package com.dropluckledger;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(DropLuckLedgerConfig.GROUP)
public interface DropLuckLedgerConfig extends Config
{
	String GROUP = "dropluckledger";

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat message for logged drops",
		description = "Shows a game message when a drop is added to your ledger, with the number of kills since the last copy",
		position = 1
	)
	default boolean chatMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "importOnLogin",
		name = "Look for history on login",
		description = "When you log in to an account that has no ledger yet, check RuneLite's saved kill counts and Loot Tracker data and offer to import them",
		position = 2
	)
	default boolean importOnLogin()
	{
		return true;
	}
}

package com.dropluckledger;

import com.dropluckledger.plugin.RuneLiteGame;
import com.dropluckledger.ui.LedgerPanel;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Collection;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/**
 * Records boss kills and drops and shows how lucky or dry the player is.  This class only connects RuneLite to
 * {@link Tracker}, which does the work.
 */
@PluginDescriptor(
	name = "Drop Luck Ledger",
	description = "Records your boss kills and drops and shows how lucky or dry you are, from the real drop tables",
	tags = {"boss", "drop", "drops", "luck", "dry", "rate", "kc", "kill", "count", "loot", "unique", "collection", "log", "pet"},
	internalName = "drop-luck-ledger"
)
public class DropLuckLedgerPlugin extends Plugin
{
	private static final String ICON_RESOURCE = "/com/dropluckledger/icon.png";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private DropLuckLedgerConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	private volatile Tracker tracker;
	private NavigationButton navButton;

	@Provides
	DropLuckLedgerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DropLuckLedgerConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		final Tracker t = new Tracker(new RuneLiteGame(client, clientThread, itemManager, configManager, chatMessageManager),
			config, getPluginDirectory(), gson, executor);
		final LedgerPanel panel = t.start();
		tracker = t;

		final BufferedImage icon = ImageUtil.loadImageResource(DropLuckLedgerPlugin.class, ICON_RESOURCE);
		navButton = NavigationButton.builder()
			.tooltip("Drop Luck Ledger")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		final Tracker t = tracker;
		tracker = null;
		if (t != null)
		{
			t.stop();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onGameStateChanged(event.getGameState());
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onChatMessage(event.getType(), event.getMessage());
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		final Tracker t = tracker;
		if (t == null)
		{
			return;
		}
		final Collection<ItemStack> items = event.getItems();
		final int[] ids = new int[items.size()];
		final int[] quantities = new int[items.size()];
		int i = 0;
		for (ItemStack stack : items)
		{
			ids[i] = stack.getId();
			quantities[i] = stack.getQuantity();
			i++;
		}
		t.onLoot(event.getType(), event.getName(), event.getAmount(), ids, quantities, event.getMetadata());
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onWidgetLoaded(event.getGroupId());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onGameTick();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onScriptPostFired(event.getScriptId());
		}
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			final Future<?> write = t.flushForShutdown();
			if (write != null)
			{
				event.waitFor(write);
			}
		}
	}
}

package com.dropluckledger;

import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.Capture;
import com.dropluckledger.capture.KcMessages;
import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.history.HistoryInput;
import com.dropluckledger.history.HistoryPlanner;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.ledger.LedgerCodec;
import com.dropluckledger.ledger.LedgerSaver;
import com.dropluckledger.plugin.DropMessages;
import com.dropluckledger.plugin.FileStore;
import com.dropluckledger.plugin.Game;
import com.dropluckledger.plugin.GameReader;
import com.dropluckledger.plugin.HistorySources;
import com.dropluckledger.plugin.ItemIcons;
import com.dropluckledger.plugin.TrackingState;
import com.dropluckledger.ui.LedgerPanel;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import java.awt.Component;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.util.Filepath;
import net.runelite.http.api.loottracker.LootRecordType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Everything the plugin does, once RuneLite has told it what happened: reads the boss data, keeps one ledger per account,
 * records kill counts and drops as they come, reads the game's own records when the player opens them, and drives the side
 * panel.  It only ever sees the game through {@link Game}; the plugin class turns RuneLite's events into calls on this class.
 */
final class Tracker
{
	private static final Logger log = LoggerFactory.getLogger(Tracker.class);

	private static final String DATA_RESOURCE = "/com/dropluckledger/data.json";
	private static final String ICON_FILE = "item-ids.json";
	private static final long SAVE_DELAY_MS = 1500;
	private static final long ICON_SAVE_PERIOD_S = 30;
	private static final long ICON_RESCAN_MS = 30L * 24 * 60 * 60 * 1000;

	private final Game game;
	private final DropLuckLedgerConfig config;
	private final Filepath dir;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	/**
	 * Everything that exists once the boss data has been read.
	 */
	static final class Core
	{
		final Data data;
		final BossIndex index;
		final Ledger ledger;
		final Capture capture;
		final HistoryPlanner planner;
		final LedgerSaver saver;
		final ItemIcons icons;
		final FileStore iconStore;

		Core(Filepath dir, Data data, Gson gson, ScheduledExecutorService executor, Game game)
		{
			this.data = data;
			this.index = new BossIndex(data);
			this.ledger = new Ledger(data);
			this.capture = new Capture(ledger, index);
			this.planner = new HistoryPlanner(ledger, index);
			this.saver = new LedgerSaver(ledger, gson, executor, SAVE_DELAY_MS);
			this.ledger.addListener(saver);
			this.icons = new ItemIcons(game);
			this.iconStore = new FileStore(dir, ICON_FILE);
		}
	}

	private volatile Core core;
	private volatile TrackingState state = TrackingState.STARTING;
	/**
	 * Counts account changes; a load that finds the number moved on gives up.
	 */
	private volatile int bindGeneration;
	private String boundKey;
	/**
	 * Held while tracking is switched on or off and while the loaded data is handed over, so a load that finishes late never
	 * leaves anything running behind a plugin that was turned off.
	 */
	private final Object lifecycle = new Object();
	private volatile ExecutorService analysis;
	private Future<?> iconSaver;
	private volatile LedgerPanel panel;

	// widgets that were opened and are read on the next game tick
	private boolean adventureLogLoaded;
	private boolean killLogLoaded;
	private String houseOwner;
	private boolean offeredHistory;
	private boolean scanChecked;

	/**
	 * @param dir      the plugin's data folder
	 * @param executor RuneLite's shared background threads
	 */
	Tracker(Game game, DropLuckLedgerConfig config, Filepath dir, Gson gson, ScheduledExecutorService executor)
	{
		this.game = game;
		this.config = config;
		this.dir = dir;
		this.gson = gson;
		this.executor = executor;
	}

	// ------------------------------------------------------------------ lifecycle

	// for the tests
	TrackingState state()
	{
		return state;
	}

	Core core()
	{
		return core;
	}

	LedgerPanel panel()
	{
		return panel;
	}

	LedgerPanel.Host host()
	{
		return new PanelHost();
	}

	/**
	 * Builds the side panel and starts reading the boss data in the background.
	 *
	 * @return the side panel, to put in RuneLite's toolbar
	 */
	LedgerPanel start()
	{
		final ExecutorService owner;
		synchronized (lifecycle)
		{
			state = TrackingState.STARTING;
			boundKey = null;
			offeredHistory = false;
			scanChecked = false;
			owner = Executors.newSingleThreadExecutor(r ->
			{
				Thread t = new Thread(r, "drop-luck-ledger-analysis");
				t.setDaemon(true);
				return t;
			});
			analysis = owner;
		}
		final LedgerPanel p = new LedgerPanel(new PanelHost(), owner);
		panel = p;
		executor.execute(() -> load(owner));
		return p;
	}

	/**
	 * Stops recording and writes what is waiting to disk (in the background).
	 */
	void stop()
	{
		final Core c;
		synchronized (lifecycle)
		{
			bindGeneration++;
			boundKey = null;
			c = core;
			core = null;
			state = TrackingState.STARTING;
			if (iconSaver != null)
			{
				iconSaver.cancel(false);
				iconSaver = null;
			}
			if (analysis != null)
			{
				analysis.shutdownNow();
				analysis = null;
			}
		}
		final LedgerPanel p = panel;
		panel = null;
		if (p != null)
		{
			p.detach();
		}
		if (c != null)
		{
			// the last changes still waiting for the saver are written on the shared background thread
			executor.execute(() -> finish(c));
		}
	}

	/**
	 * Reads the boss data, then builds everything else.  Runs on the background thread.
	 */
	private void load(ExecutorService owner)
	{
		try
		{
			Data data;
			try (InputStream in = Tracker.class.getResourceAsStream(DATA_RESOURCE))
			{
				if (in == null)
				{
					throw new IOException("boss data is missing from the plugin");
				}
				data = Data.load(gson, in);
			}
			if (owner != analysis)
			{
				return; // tracking was switched off while the data was loading
			}
			final Core c = new Core(dir, data, gson, executor, game);
			readIcons(c);
			c.capture.setListener((bossId, item, killNo) -> onDropLogged(c, bossId, item, killNo));
			synchronized (lifecycle)
			{
				if (owner != analysis)
				{
					return;
				}
				core = c;
				iconSaver = executor.scheduleWithFixedDelay(() -> saveIcons(c), ICON_SAVE_PERIOD_S, ICON_SAVE_PERIOD_S, TimeUnit.SECONDS);
				state = TrackingState.LOGGED_OUT;
			}
			SwingUtilities.invokeLater(() ->
			{
				LedgerPanel p = panel;
				if (p != null && core == c)
				{
					p.attach(c.ledger, c.index, c.icons, c.planner);
					p.stateChanged();
				}
			});
			game.invokeLater(() ->
			{
				if (core == c && game.isLoggedIn())
				{
					bindAccount();
				}
			});
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Drop Luck Ledger could not start", ex);
		}
	}

	/**
	 * Writes what is waiting and stops the saver (background thread).
	 */
	private void finish(Core c)
	{
		c.saver.setStore(null);
		c.ledger.removeListener(c.saver);
		saveIcons(c);
	}

	// ------------------------------------------------------------------ account

	void onGameStateChanged(GameState gameState)
	{
		final Core c = core;
		if (c == null)
		{
			return;
		}
		switch (gameState)
		{
			case LOGGED_IN:
				bindAccount();
				break;
			case LOGIN_SCREEN:
				requestBind(null, TrackingState.LOGGED_OUT);
				break;
			case LOADING:
			case HOPPING:
				houseOwner = null;
				break;
			case LOGGING_IN:
				c.capture.reset();
				break;
			default:
				break;
		}
	}

	/**
	 * Decides which ledger is in use from the account that is logged in and the kind of world.
	 */
	void bindAccount()
	{
		final long hash = game.accountHash();
		if (!game.isStandardWorld())
		{
			requestBind(null, TrackingState.PAUSED);
		}
		else if (hash == -1L)
		{
			requestBind(null, TrackingState.LOGGED_OUT);
		}
		else
		{
			requestBind(Long.toString(hash), TrackingState.LOADING);
		}
	}

	/**
	 * Switches to the ledger of another account (or to none).  The load happens on the background thread; events are
	 * ignored until it is done.
	 *
	 * @param key the account, or null for none
	 * @param why what to tell the player when there is none
	 */
	private void requestBind(String key, TrackingState why)
	{
		final Core c = core;
		if (c == null)
		{
			return;
		}
		if (Objects.equals(key, boundKey) && (key != null || state == why))
		{
			return;
		}
		boundKey = key;
		final int generation = ++bindGeneration;
		offeredHistory = false;
		houseOwner = null;
		adventureLogLoaded = false;
		killLogLoaded = false;
		c.capture.reset();
		if (key == null)
		{
			state = why;
			executor.execute(() ->
			{
				if (generation != bindGeneration)
				{
					return;
				}
				c.saver.setStore(null);
				c.ledger.replaceWith(new Ledger(c.data));
				stateChanged();
			});
			return;
		}
		state = TrackingState.LOADING;
		stateChanged();
		executor.execute(() ->
		{
			if (generation != bindGeneration)
			{
				return;
			}
			FileStore store = new FileStore(dir, FileStore.ledgerName(Long.parseLong(key)));
			c.saver.setStore(null);
			final boolean readable = c.saver.loadInto(store);
			if (generation != bindGeneration)
			{
				return;
			}
			c.saver.setStore(store);
			if (!readable)
			{
				message("Your saved ledger could not be read, so it was set aside and you are starting from an empty one. "
					+ "The old file is in the plugin's folder (its name ends in .unreadable).");
			}
			game.invokeLater(() ->
			{
				if (generation == bindGeneration && core == c)
				{
					c.capture.reset();
					state = TrackingState.TRACKING;
					stateChanged();
					afterBind(c);
				}
			});
		});
	}

	private void stateChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			LedgerPanel p = panel;
			if (p != null)
			{
				p.stateChanged();
			}
		});
	}

	/**
	 * Client thread, once a ledger is ready: starts the item picture scan and looks for history to offer.
	 */
	private void afterBind(Core c)
	{
		if (!scanChecked)
		{
			scanChecked = true;
			if (System.currentTimeMillis() - c.icons.scannedAt() > ICON_RESCAN_MS)
			{
				Set<String> names = new LinkedHashSet<>();
				for (Boss b : c.data.bosses)
				{
					names.addAll(Catalog.defaultTracked(b));
				}
				c.icons.startScan(names);
			}
		}
		if (!offeredHistory && config.importOnLogin() && c.ledger.activeBosses().isEmpty())
		{
			offeredHistory = true;
			planHistory(c, plan ->
			{
				LedgerPanel p = panel;
				if (p != null && !plan.isEmpty())
				{
					p.offerHistory(plan);
				}
			});
		}
	}

	// ------------------------------------------------------------------ game messages and loot

	void onChatMessage(ChatMessageType type, String message)
	{
		final Core c = core;
		if (c == null || state != TrackingState.TRACKING)
		{
			return;
		}
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.TRADE && type != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}
		final int tick = game.tickCount();
		final KcMessages.Kc kc = KcMessages.parseKillCount(message);
		if (kc != null)
		{
			c.capture.onKillCount(kc.label, kc.count, tick);
			return;
		}
		final String logged = KcMessages.collectionLogItem(message);
		if (logged != null)
		{
			c.capture.onCollectionLog(logged, tick);
		}
		if (KcMessages.isPetMessage(message))
		{
			c.capture.onPetMessage(tick);
		}
	}

	/**
	 * Loot from a kill or an event, as RuneLite's Loot Tracker reports it.
	 *
	 * @param itemIds    the ids of the items received
	 * @param quantities how many of each (same length)
	 * @param metadata   what the Loot Tracker knows about the reward (the raid level, the delve, ...), or null
	 */
	void onLoot(LootRecordType type, String name, int amount, int[] itemIds, int[] quantities, Object metadata)
	{
		final Core c = core;
		if (c == null || state != TrackingState.TRACKING)
		{
			return;
		}
		if (type != LootRecordType.NPC && type != LootRecordType.EVENT)
		{
			return;
		}
		final String bossId = c.index.loot(name);
		if (bossId == null)
		{
			return;
		}
		List<Capture.Stack> stacks = new ArrayList<>();
		for (int i = 0; i < itemIds.length; i++)
		{
			final int id = game.canonicalItemId(itemIds[i]);
			final String item = game.itemName(id);
			if (item != null)
			{
				c.icons.learn(item, id);
				stacks.add(new Capture.Stack(item, quantities[i]));
			}
		}
		c.capture.onLoot(new Capture.Loot(name, amount, stacks, hints(bossId, metadata), game.tickCount()));
	}

	/**
	 * Boss settings the game shows along with a reward: the raid level, the delve, the player's skill levels.
	 */
	Map<String, Object> hints(String bossId, Object metadata)
	{
		Map<String, Object> hints = new HashMap<>();
		switch (bossId)
		{
			case "tombs-of-amascut":
				if (metadata instanceof int[] && ((int[]) metadata).length > 0)
				{
					hints.put("raidLevel", ((int[]) metadata)[0]);
				}
				break;
			case "doom-of-mokhaiotl":
				if (metadata instanceof Integer)
				{
					hints.put("delve", metadata);
				}
				break;
			case "tempoross":
				hints.put("fishing", game.realLevel(Skill.FISHING));
				break;
			case "hespori":
				hints.put("farming", game.realLevel(Skill.FARMING));
				break;
			case "wintertodt":
				hints.put("fm200", game.experience(Skill.FIREMAKING) >= 200_000_000 ? 1 : 0);
				break;
			default:
				break;
		}
		return hints;
	}

	private void onDropLogged(Core c, String bossId, String item, int killNo)
	{
		if (!config.chatMessages())
		{
			return;
		}
		BossState s = c.ledger.copyOf(bossId);
		game.gameMessage(DropMessages.build(c.data, bossId, s, item, killNo));
	}

	// ------------------------------------------------------------------ history from the game's own screens

	/**
	 * An interface opened.
	 */
	void onWidgetLoaded(int groupId)
	{
		switch (groupId)
		{
			case InterfaceID.MENU:
			case InterfaceID.MENU_NEW:
				adventureLogLoaded = true;
				break;
			case InterfaceID.KILL_LOG:
				killLogLoaded = true;
				break;
			default:
				break;
		}
	}

	void onGameTick()
	{
		final Core c = core;
		if (c == null)
		{
			return;
		}
		if (state != TrackingState.TRACKING)
		{
			adventureLogLoaded = false;
			killLogLoaded = false;
			return;
		}
		if (c.icons.isScanning() && c.icons.scanTick(System.currentTimeMillis()))
		{
			saveIcons(c);
		}
		if (adventureLogLoaded)
		{
			adventureLogLoaded = false;
			String owner = GameReader.adventureLogOwner(game);
			if (owner != null)
			{
				houseOwner = owner;
			}
		}
		if (killLogLoaded && isMine(houseOwner))
		{
			killLogLoaded = false;
			Map<String, Integer> kills = GameReader.killLog(game);
			if (kills != null && !kills.isEmpty())
			{
				c.ledger.updateHistory(h ->
				{
					h.kc.putAll(kills);
					h.kcTime = c.ledger.now();
				});
				LedgerPanel p = panel;
				if (p != null)
				{
					SwingUtilities.invokeLater(() -> p.historyRead("Boss Kill Log: " + kills.size() + " bosses read"));
				}
			}
		}
	}

	/**
	 * A game script finished running.
	 */
	void onScriptPostFired(int scriptId)
	{
		final Core c = core;
		if (c == null || state != TrackingState.TRACKING || scriptId != ScriptID.COLLECTION_DRAW_LIST)
		{
			return;
		}
		if (!isMine(houseOwner))
		{
			return;
		}
		GameReader.LogPage page = GameReader.collectionPage(game);
		if (page == null)
		{
			return;
		}
		for (Map.Entry<String, Integer> e : page.ids.entrySet())
		{
			c.icons.learn(e.getKey(), e.getValue());
		}
		c.ledger.updateHistory(h ->
		{
			h.log.put(page.title, new LinkedHashMap<>(page.items));
			h.logTime = c.ledger.now();
		});
		LedgerPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.historyRead("Collection Log page read: " + page.title));
		}
	}

	/**
	 * True unless the open adventure log belongs to another player.
	 */
	private boolean isMine(String owner)
	{
		return owner == null || owner.equals(game.playerName());
	}

	/**
	 * Gathers everything the game and RuneLite know about the player's history and works out what it would add.  Client
	 * thread; the result is handed to the callback on the Swing thread.
	 */
	private void planHistory(Core c, Consumer<HistoryPlanner.Plan> then)
	{
		game.invoke(() ->
		{
			HistoryPlanner.Plan plan;
			try
			{
				HistoryInput in = HistorySources.collect(c.ledger, game, gson, c.index);
				plan = c.planner.plan(in);
			}
			catch (RuntimeException ex)
			{
				log.warn("Could not gather history", ex);
				return;
			}
			SwingUtilities.invokeLater(() -> then.accept(plan));
		});
	}

	// ------------------------------------------------------------------ shutdown and icons

	/**
	 * RuneLite is closing: writes everything now.
	 *
	 * @return the write, for RuneLite to wait for, or null when there is nothing to write
	 */
	Future<?> flushForShutdown()
	{
		final Core c = core;
		if (c == null)
		{
			return null;
		}
		return executor.submit(() ->
		{
			c.saver.flushNow();
			saveIcons(c);
		});
	}

	private void readIcons(Core c)
	{
		try
		{
			String text = c.iconStore.read();
			if (text == null)
			{
				return;
			}
			JsonObject root = new JsonParser().parse(text).getAsJsonObject();
			Map<String, Integer> ids = new HashMap<>();
			JsonObject o = root.getAsJsonObject("ids");
			if (o != null)
			{
				for (Map.Entry<String, JsonElement> e : o.entrySet())
				{
					ids.put(e.getKey(), e.getValue().getAsInt());
				}
			}
			long scannedAt = root.has("scannedAt") ? root.get("scannedAt").getAsLong() : 0;
			c.icons.restore(ids, scannedAt);
		}
		catch (IOException | JsonParseException | IllegalStateException | ClassCastException | NumberFormatException ex)
		{
			log.debug("Could not read the saved item pictures; they will be found again", ex);
		}
	}

	private void saveIcons(Core c)
	{
		if (!c.icons.isDirty())
		{
			return;
		}
		try
		{
			JsonObject root = new JsonObject();
			root.addProperty("v", 1);
			root.addProperty("scannedAt", c.icons.scannedAt());
			JsonObject o = new JsonObject();
			for (Map.Entry<String, Integer> e : c.icons.snapshot().entrySet())
			{
				o.addProperty(e.getKey(), e.getValue());
			}
			root.add("ids", o);
			c.iconStore.write(gson.toJson(root));
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Could not save the item pictures", ex);
		}
	}

	// ------------------------------------------------------------------ what the side panel can ask for

	private final class PanelHost implements LedgerPanel.Host
	{
		@Override
		public TrackingState state()
		{
			return state;
		}

		@Override
		public void planHistory(Consumer<HistoryPlanner.Plan> then)
		{
			Core c = core;
			if (c != null && state == TrackingState.TRACKING)
			{
				Tracker.this.planHistory(c, then);
			}
		}

		@Override
		public void exportBackup(Component parent)
		{
			final Core c = core;
			if (c == null)
			{
				return;
			}
			final Filepath file = game.chooseFileToSave(parent, "Export Drop Luck Ledger backup", "drop-luck-ledger-backup.json", "Ledger backup (*.json)", "json");
			if (file == null)
			{
				return;
			}
			final String json = LedgerCodec.toJson(gson, c.ledger);
			executor.execute(() ->
			{
				String result;
				try
				{
					FileStore.writeText(file, json);
					result = "Backup saved.";
				}
				catch (IOException ex)
				{
					log.warn("Could not write the backup", ex);
					result = "Could not save the backup: " + ex.getMessage();
				}
				message(result);
			});
		}

		@Override
		public void importBackup(Component parent, Consumer<Ledger> confirm)
		{
			final Core c = core;
			if (c == null)
			{
				return;
			}
			final Filepath file = game.chooseFileToOpen(parent, "Import a Drop Luck Ledger backup", "Ledger backup (*.json)", "json");
			if (file == null)
			{
				return;
			}
			executor.execute(() ->
			{
				try
				{
					Ledger backup = LedgerCodec.fromJson(c.data, FileStore.readText(file));
					SwingUtilities.invokeLater(() -> confirm.accept(backup));
				}
				catch (IOException | LedgerCodec.FormatException | RuntimeException ex)
				{
					log.debug("Could not read the backup", ex);
					message("That file is not a Drop Luck Ledger backup (" + ex.getMessage() + ").");
				}
			});
		}

		@Override
		public void replaceLedger(Ledger backup)
		{
			Core c = core;
			if (c != null && state == TrackingState.TRACKING)
			{
				executor.execute(() -> c.ledger.replaceWith(backup));
			}
		}
	}

	/**
	 * Shows a note at the top of the side panel.
	 */
	private void message(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			LedgerPanel p = panel;
			if (p != null)
			{
				p.showMessage(text);
			}
		});
	}
}

package com.dropluckledger.capture;

import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Param;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Knows how the game names things: which boss a kill-count message or a loot event belongs to, and which mode of the boss
 * it was.  Built from the boss data plus a short list of names that differ in game.
 */
public final class BossIndex
{
	/**
	 * A kill-count label the game prints ("Chambers of Xeric Challenge Mode") and what it says about the kill.
	 */
	public static final class KcLabel
	{
		public final String bossId;
		/**
		 * The label as spelled in the boss data; used as the key for the last count seen.
		 */
		public final String label;
		/**
		 * Boss settings the label implies (for example cm=1).
		 */
		public final Map<String, Object> patch;

		KcLabel(String bossId, String label, Map<String, Object> patch)
		{
			this.bossId = bossId;
			this.label = label;
			this.patch = patch;
		}
	}

	/**
	 * Extra kill-count labels: game wording that is not in the boss data (normalised form to boss id).
	 */
	private static final String[][] KC_ALIASES = {
		{"Barrows chest", "barrows"},
		{"Barrows chests", "barrows"},
		{"Lunar Chests", "moons-of-peril"},
		{"Fortis Colosseum", "fortis-colosseum"},
		{"Colosseum", "fortis-colosseum"},
	};

	/**
	 * Names that loot events carry for a boss, when they are not the boss name or a kill-count label.
	 */
	private static final String[][] LOOT_ALIASES = {
		{"Dusk", "grotesque-guardians"},
		{"Dawn", "grotesque-guardians"},
		{"Crystalline Hunllef", "the-gauntlet"},
		{"Corrupted Hunllef", "the-corrupted-gauntlet"},
		{"Reward pool (Tempoross)", "tempoross"},
		{"Reward cart (Wintertodt)", "wintertodt"},
		{"Unsired", "abyssal-sire"},
		{"Barrows", "barrows"},
		{"Lunar Chest", "moons-of-peril"},
		{"Fortis Colosseum", "fortis-colosseum"},
		{"Sol Heredit", "fortis-colosseum"},
		{"Vet'ion Reborn", "vetion"},
	};

	private final Data data;
	private final Map<String, KcLabel> kcByNorm = new HashMap<>();
	private final Set<String> kcAmbiguous = new HashSet<>();
	private final Map<String, String> lootByNorm = new HashMap<>();
	private final Set<String> lootAmbiguous = new HashSet<>();
	private final Map<String, List<KcLabel>> labelsOf = new LinkedHashMap<>();
	private final Map<String, List<String>> lootNamesOf = new LinkedHashMap<>();
	private final Map<String, Map<String, String>> itemsOf = new HashMap<>();

	public BossIndex(Data data)
	{
		this.data = data;
		for (Boss b : data.bosses)
		{
			List<KcLabel> labels = new ArrayList<>();
			for (String label : b.kc)
			{
				KcLabel kl = new KcLabel(b.id, label, patchFor(b, label));
				labels.add(kl);
				addKc(Names.norm(label), kl);
			}
			if (labels.isEmpty())
			{
				KcLabel kl = new KcLabel(b.id, b.name, new LinkedHashMap<>());
				labels.add(kl);
				addKc(Names.norm(b.name), kl);
			}
			labelsOf.put(b.id, Collections.unmodifiableList(labels));
			addKc(Names.norm(b.name), labels.get(0)); // the page name: the main kill count
			addKc(Names.norm(stripParens(b.name)), labels.get(0));

			LinkedHashSet<String> names = new LinkedHashSet<>();
			names.add(b.name);
			names.add(stripParens(b.name));
			names.addAll(b.kc);
			lootNamesOf.put(b.id, new ArrayList<>(names));
			for (String n : names)
			{
				addLoot(Names.norm(n), b.id);
			}
		}
		for (String[] a : KC_ALIASES)
		{
			Boss b = data.boss(a[1]);
			if (b != null)
			{
				addKc(Names.norm(a[0]), labelsOf.get(b.id).get(0));
			}
		}
		for (String[] a : LOOT_ALIASES)
		{
			if (data.boss(a[1]) != null)
			{
				addLoot(Names.norm(a[0]), a[1]);
				List<String> names = lootNamesOf.get(a[1]);
				if (!names.contains(a[0]))
				{
					names.add(a[0]);
				}
			}
		}
	}

	private void addKc(String norm, KcLabel kl)
	{
		if (norm.isEmpty() || kcAmbiguous.contains(norm))
		{
			return;
		}
		KcLabel old = kcByNorm.get(norm);
		if (old == null)
		{
			kcByNorm.put(norm, kl);
		}
		else if (!old.bossId.equals(kl.bossId))
		{
			kcByNorm.remove(norm);
			kcAmbiguous.add(norm);
		}
	}

	private void addLoot(String norm, String bossId)
	{
		if (norm.isEmpty() || lootAmbiguous.contains(norm))
		{
			return;
		}
		String old = lootByNorm.get(norm);
		if (old == null)
		{
			lootByNorm.put(norm, bossId);
		}
		else if (!old.equals(bossId))
		{
			lootByNorm.remove(norm);
			lootAmbiguous.add(norm);
		}
	}

	private static String stripParens(String s)
	{
		int i = s.indexOf('(');
		return i > 0 ? s.substring(0, i).trim() : s;
	}

	private static Param param(Boss b, String name)
	{
		for (Param p : b.params)
		{
			if (p.name.equals(name))
			{
				return p;
			}
		}
		return null;
	}

	/**
	 * The boss settings a kill-count label implies: awakened or not, challenge mode or not, Theatre of Blood mode.
	 */
	public static Map<String, Object> patchOf(Boss b, String label)
	{
		return patchFor(b, label);
	}

	static Map<String, Object> patchFor(Boss b, String label)
	{
		Map<String, Object> p = new LinkedHashMap<>();
		String l = label.toLowerCase(java.util.Locale.ROOT);
		Param aw = param(b, "awakened");
		if (aw != null && "bool".equals(aw.type))
		{
			p.put("awakened", l.contains("awakened") ? 1 : 0);
		}
		Param cm = param(b, "cm");
		if (cm != null && "bool".equals(cm.type))
		{
			p.put("cm", l.contains("challenge mode") ? 1 : 0);
		}
		Param mode = param(b, "mode");
		if (mode != null && "select".equals(mode.type) && mode.options != null)
		{
			String v = l.contains("hard mode") ? "hard" : l.contains("entry mode") ? "entry" : "normal";
			if (mode.options.contains(v))
			{
				p.put("mode", v);
			}
		}
		return p;
	}

	// ------------------------------------------------------------------ lookups

	/**
	 * The kill-count label for the text the game prints between "Your" and "kill count" (null = not a tracked boss).
	 */
	public KcLabel kc(String gameLabel)
	{
		String n = Names.norm(gameLabel);
		KcLabel kl = kcByNorm.get(n);
		if (kl != null)
		{
			return kl;
		}
		// "Awakened The Leviathan", "The Leviathan (Awakened)" and similar spellings of the awakened versions
		String lower = gameLabel == null ? "" : gameLabel.toLowerCase(java.util.Locale.ROOT);
		if (lower.contains("awakened"))
		{
			String rest = Names.norm(lower.replace("awakened", ""));
			KcLabel base = kcByNorm.get(rest);
			if (base != null && param(data.boss(base.bossId), "awakened") != null)
			{
				Map<String, Object> patch = new LinkedHashMap<>(base.patch);
				patch.put("awakened", 1);
				return new KcLabel(base.bossId, "Awakened " + base.label, patch);
			}
		}
		return null;
	}

	/**
	 * The boss a loot event name belongs to (null = not a boss we track).
	 */
	public String loot(String lootName)
	{
		return lootByNorm.get(Names.norm(lootName));
	}

	/**
	 * Every kill-count label of a boss, in the order of the boss data (the first one is the main mode).
	 */
	public List<KcLabel> labels(String bossId)
	{
		List<KcLabel> l = labelsOf.get(bossId);
		return l == null ? Collections.emptyList() : l;
	}

	/**
	 * Normalised names that two bosses both claim (the lookups return nothing for them).
	 */
	public Set<String> ambiguousKc()
	{
		return Collections.unmodifiableSet(kcAmbiguous);
	}

	public Set<String> ambiguousLoot()
	{
		return Collections.unmodifiableSet(lootAmbiguous);
	}

	/**
	 * The boss's own name for an item the game names (exact match first, then ignoring case and punctuation).  Null when
	 * the boss has no such item.
	 */
	public String item(String bossId, String gameName)
	{
		if (gameName == null)
		{
			return null;
		}
		Boss b = data.boss(bossId);
		if (b == null)
		{
			return null;
		}
		if (b.meta().containsKey(gameName))
		{
			return gameName;
		}
		Map<String, String> flat;
		synchronized (itemsOf)
		{
			flat = itemsOf.get(bossId);
			if (flat == null)
			{
				flat = new HashMap<>();
				for (String n : b.meta().keySet())
				{
					flat.putIfAbsent(Names.flat(n), n);
				}
				itemsOf.put(bossId, flat);
			}
		}
		return flat.get(Names.flat(gameName));
	}
}

package com.dropluckledger.capture;

import com.dropluckledger.capture.BossIndex.KcLabel;
import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Param;
import com.dropluckledger.engine.Engine;
import com.dropluckledger.ledger.Drop;
import com.dropluckledger.ledger.Ledger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Turns what the game reports (kill-count messages, loot, collection log and pet messages) into ledger entries.
 * <p>
 * The game tells the plugin the same kill in two ways, in either order: the chat line "Your X kill count is: N" and the
 * loot event.  The chat line is the better source for the kill number, so a loot event that arrives first is counted as
 * a provisional kill and corrected when the chat line follows.  Everything here runs on the game thread; the ledger takes
 * care of its own locking.
 */
public final class Capture
{
	private static final Logger log = LoggerFactory.getLogger(Capture.class);

	/**
	 * How long (in game ticks, 0.6 s each) a kill-count message waits for its loot.
	 */
	static final int SHORT_WINDOW = 100;
	/**
	 * Same for raids, minigames and skilling bosses, where the reward is claimed some time after the kill count shows.
	 */
	static final int LONG_WINDOW = 3000;
	/**
	 * How close (in ticks) a pet message must be to the kill it belongs to.
	 */
	static final int PET_WINDOW = 30;
	private static final int PROV_DROPS_KEPT = 20;
	/**
	 * A tick far enough in the past that nothing is near it (and subtracting it cannot overflow).
	 */
	private static final int NEVER = -1_000_000_000;

	/**
	 * Called for every drop that was written to the ledger.
	 */
	public interface Listener
	{
		void dropLogged(String bossId, String item, int killNo);
	}

	/**
	 * One item stack of a loot event, named the way the game names it.
	 */
	public static final class Stack
	{
		public final String name;
		public final int qty;

		public Stack(String name, int qty)
		{
			this.name = name;
			this.qty = qty;
		}
	}

	/**
	 * A loot event.
	 */
	public static final class Loot
	{
		public final String name;
		public final int amount;
		public final List<Stack> items;
		/**
		 * Boss settings the game revealed with the loot (raid level, delve level, skill levels), by setting name.
		 */
		public final Map<String, Object> hints;
		public final int tick;

		public Loot(String name, int amount, List<Stack> items, Map<String, Object> hints, int tick)
		{
			this.name = name;
			this.amount = amount;
			this.items = items;
			this.hints = hints == null ? Collections.emptyMap() : hints;
			this.tick = tick;
		}
	}

	private static final class Pending
	{
		final int killNo;
		final int tick;

		Pending(int killNo, int tick)
		{
			this.killNo = killNo;
			this.tick = tick;
		}
	}

	private static final class LastKill
	{
		final String bossId;
		final int killNo;
		final int tick;

		LastKill(String bossId, int killNo, int tick)
		{
			this.bossId = bossId;
			this.killNo = killNo;
			this.tick = tick;
		}
	}

	private final Ledger ledger;
	private final Data data;
	private final BossIndex index;
	private final Map<String, List<String>> logIndex;
	private final Map<String, Pending> pending = new HashMap<>();
	private final Set<String> secondChance = new HashSet<>();
	private LastKill lastKill;
	private int petSeenTick = NEVER;
	private Listener listener;

	public Capture(Ledger ledger, BossIndex index)
	{
		this.ledger = ledger;
		this.data = ledger.data();
		this.index = index;
		this.logIndex = Catalog.logIndex(data);
	}

	public synchronized void setListener(Listener l)
	{
		this.listener = l;
	}

	/**
	 * Forget the kills waiting for their loot (login, world hop).
	 */
	public synchronized void reset()
	{
		pending.clear();
		secondChance.clear();
		lastKill = null;
		petSeenTick = NEVER;
	}

	private static boolean longWindow(Boss b)
	{
		String c = b.cat == null ? "" : b.cat;
		return c.equals("Raid") || c.equals("Minigame") || c.equals("Minigame boss") || c.equals("Skilling boss");
	}

	// ------------------------------------------------------------------ kill-count messages

	/**
	 * A "Your X kill count is: N" message.
	 *
	 * @param label the activity as the game wrote it
	 * @param n     the count it showed
	 */
	public synchronized void onKillCount(String label, int n, int tick)
	{
		KcLabel kl = index.kc(label);
		if (kl == null || n <= 0)
		{
			log.debug("Kill count for '{}' is not a boss in the ledger", label);
			return;
		}
		final String id = kl.bossId;
		final Boolean[] counted = {false};
		final int[] kill = {0};
		ledger.update(id, s ->
		{
			Map<String, Integer> labels = s.labels();
			Integer prev = labels.get(kl.label);
			int cur = s.kc;
			int prov = s.provisional();
			int newKc;
			if (prev == null)
			{
				// first count seen for this label: believe the game's number, but a message always means at least one new kill
				int target = s.labelSum(kl.label) + n;
				newKc = Math.max(prov > 0 ? cur : cur + 1, target);
			}
			else
			{
				if (n <= prev)
				{
					labels.put(kl.label, n); // the game's count went down or repeated: just follow it
					return null;
				}
				newKc = cur + (n - prev) - prov;
			}
			newKc = Math.max(newKc, s.maxDropKc());
			int shift = newKc - cur;
			if (prov > 0 && shift != 0 && s.provDrops != null)
			{
				for (Drop d : s.drops)
				{
					if (s.provDrops.contains(d.id) && d.kc != null)
					{
						d.kc = Math.max(1, d.kc + shift);
					}
				}
			}
			labels.put(kl.label, n);
			int gap = newKc - cur;
			s.kc = newKc;
			s.prov = null;
			s.provDrops = null;
			// kills the plugin did not see (first count, missed kills) are assumed to be in the same mode as this one
			int from = prov == 0 && gap > 1 ? cur + 1 : newKc;
			Ledger.applyParamsLocked(s, from, kl.patch, Engine.defaultParams(data.boss(id)));
			kill[0] = newKc;
			counted[0] = true;
			if (prov == 0)
			{
				pending.put(id, new Pending(newKc, tick));
			}
			return null;
		});
		if (counted[0])
		{
			killSeen(id, kill[0], tick);
		}
	}

	// ------------------------------------------------------------------ loot

	/**
	 * Loot from a boss.  Items the player tracks are written to the ledger with the kill number.
	 */
	public void onLoot(Loot e)
	{
		final String id = index.loot(e.name);
		if (id == null)
		{
			return;
		}
		final Boss boss = data.boss(id);
		final int kills = Math.max(1, e.amount);
		final int[] kill = {0};
		List<String> logged;
		synchronized (this)
		{
			logged = ledger.update(id, s ->
			{
				Pending p = pending.remove(id);
				int killNo;
				boolean provisional;
				if (p != null && e.tick >= p.tick && e.tick - p.tick <= (longWindow(boss) ? LONG_WINDOW : SHORT_WINDOW))
				{
					s.kc += kills - 1;
					killNo = s.kc;
					provisional = false;
				}
				else
				{
					s.kc += kills;
					s.prov = s.provisional() + kills;
					killNo = s.kc;
					provisional = true;
				}
				Map<String, Object> patch = hintPatch(boss, e.hints);
				Ledger.applyParamsLocked(s, killNo, patch, Engine.defaultParams(boss));
				Set<String> tracked = new HashSet<>(ledger.trackedNames(id));
				List<String> out = new ArrayList<>();
				for (Stack st : e.items)
				{
					String item = index.item(id, st.name);
					if (item == null || !tracked.contains(item))
					{
						continue;
					}
					if (secondChance.remove(id + '|' + item + '|' + killNo))
					{
						continue; // the collection log message already put this copy in
					}
					Drop d = ledger.addDropLocked(id, s, item, killNo, st.qty, snapFor(id, item), Drop.SRC_LIVE);
					if (provisional)
					{
						if (s.provDrops == null)
						{
							s.provDrops = new ArrayList<>();
						}
						s.provDrops.add(d.id);
						while (s.provDrops.size() > PROV_DROPS_KEPT)
						{
							s.provDrops.remove(0);
						}
					}
					out.add(item);
				}
				kill[0] = killNo;
				return out;
			});
			for (String item : logged)
			{
				notifyLogged(id, item, kill[0]);
			}
			killSeen(id, kill[0], e.tick);
		}
	}

	/**
	 * The settings the game revealed with a loot event, restricted to the ones this boss has.
	 */
	static Map<String, Object> hintPatch(Boss boss, Map<String, Object> hints)
	{
		Map<String, Object> out = new LinkedHashMap<>();
		if (hints == null || hints.isEmpty())
		{
			return out;
		}
		for (Param p : boss.params)
		{
			Object v = hints.get(p.name);
			if (v == null)
			{
				continue;
			}
			if ("bool".equals(p.type))
			{
				out.put(p.name, truthy(v) ? 1 : 0);
			}
			else if ("int".equals(p.type) && v instanceof Number)
			{
				long r = Math.round(((Number) v).doubleValue());
				if (p.min != null)
				{
					r = Math.max(r, Math.round(p.min));
				}
				if (p.max != null)
				{
					r = Math.min(r, Math.round(p.max));
				}
				out.put(p.name, (int) r);
			}
			else if ("select".equals(p.type) && v instanceof String && p.options != null && p.options.contains(v))
			{
				out.put(p.name, v);
			}
		}
		return out;
	}

	private static boolean truthy(Object v)
	{
		if (v instanceof Boolean)
		{
			return (Boolean) v;
		}
		if (v instanceof Number)
		{
			return ((Number) v).doubleValue() != 0;
		}
		return v != null;
	}

	/**
	 * For an item that several bosses drop: the other bosses' kill counts right now.
	 */
	private Map<String, Integer> snapFor(String bossId, String item)
	{
		List<String> ids = logIndex.get(item);
		if (ids == null || ids.size() < 2)
		{
			return null;
		}
		Map<String, Integer> snap = new LinkedHashMap<>();
		for (String other : ids)
		{
			if (!other.equals(bossId))
			{
				int k = ledger.kc(other);
				if (k > 0)
				{
					snap.put(other, k);
				}
			}
		}
		return snap.isEmpty() ? null : snap;
	}

	private void notifyLogged(String bossId, String item, int killNo)
	{
		Listener l = listener;
		if (l != null)
		{
			try
			{
				l.dropLogged(bossId, item, killNo);
			}
			catch (RuntimeException ex)
			{
				log.debug("Drop listener failed", ex);
			}
		}
	}

	// ------------------------------------------------------------------ pets and collection log

	/**
	 * A "New item added to your collection log: X" message.  Used for pets, which do not appear in loot events, and as a
	 * second chance for tracked items of the boss that was just killed.
	 */
	public synchronized void onCollectionLog(String itemName, int tick)
	{
		if (itemName == null || lastKill == null || tick - lastKill.tick > PET_WINDOW)
		{
			// the message may come first; remember it only for pets
			return;
		}
		recordIfTracked(lastKill.bossId, lastKill.killNo, itemName);
	}

	/**
	 * A "funny feeling" pet message (it does not say which pet).  Counts when the boss just killed has exactly one pet.
	 */
	public synchronized void onPetMessage(int tick)
	{
		if (lastKill != null && tick - lastKill.tick <= PET_WINDOW)
		{
			recordIfTracked(lastKill.bossId, lastKill.killNo, null);
		}
		else
		{
			petSeenTick = tick;
		}
	}

	private void killSeen(String bossId, int killNo, int tick)
	{
		lastKill = new LastKill(bossId, killNo, tick);
		if (tick - petSeenTick <= PET_WINDOW && tick >= petSeenTick)
		{
			petSeenTick = NEVER;
			recordIfTracked(bossId, killNo, null);
		}
	}

	/**
	 * Logs the item (or the boss's only pet when itemName is null) at the kill, unless that copy is already there.
	 */
	private void recordIfTracked(String bossId, int killNo, String itemName)
	{
		Boss boss = data.boss(bossId);
		if (boss == null)
		{
			return;
		}
		List<String> logged = ledger.update(bossId, s ->
		{
			List<String> tracked = ledger.trackedNames(bossId);
			String item = null;
			if (itemName != null)
			{
				item = index.item(bossId, itemName);
				if (item == null || !tracked.contains(item))
				{
					return Collections.<String>emptyList();
				}
			}
			else
			{
				for (String n : tracked)
				{
					if (isPet(boss, n))
					{
						if (item != null)
						{
							return Collections.<String>emptyList(); // more than one pet: cannot tell which
						}
						item = n;
					}
				}
				if (item == null)
				{
					return Collections.<String>emptyList();
				}
			}
			for (Drop d : s.drops)
			{
				if (d.item.equals(item) && d.kc != null && d.kc == killNo)
				{
					return Collections.<String>emptyList();
				}
			}
			ledger.addDropLocked(bossId, s, item, killNo, 1, snapFor(bossId, item), Drop.SRC_LIVE);
			if (secondChance.size() > 200)
			{
				secondChance.clear();
			}
			secondChance.add(bossId + '|' + item + '|' + killNo);
			return Collections.singletonList(item);
		});
		for (String item : logged)
		{
			notifyLogged(bossId, item, killNo);
		}
	}

	private static boolean isPet(Boss b, String item)
	{
		Engine.ItemMeta m = b.meta().get(item);
		return m != null && m.isPet();
	}
}

package com.dropluckledger.capture;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Recognises the game messages the plugin cares about.  The patterns follow the ones RuneLite's own Chat Commands plugin uses
 * for kill counts, so they match the same wording.
 */
public final class KcMessages
{
	private KcMessages()
	{
	}

	private static final Pattern KILLCOUNT = Pattern.compile("Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");
	private static final Pattern COLLECTION_LOG = Pattern.compile("New item added to your collection log: (.*)");
	private static final String[] PET = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};

	/**
	 * A kill-count message: the text the game used for the activity and the count it shows.
	 */
	public static final class Kc
	{
		public final String label;
		public final int count;

		Kc(String label, int count)
		{
			this.label = label;
			this.count = count;
		}
	}

	/**
	 * @return the label and count, or null when the message is not a kill-count message
	 */
	public static Kc parseKillCount(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = KILLCOUNT.matcher(message);
		if (!m.find())
		{
			return null;
		}
		String pre = m.group("pre");
		String post = m.group("post");
		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return null;
		}
		String label = m.group("boss").replace(":", "");
		int n;
		try
		{
			n = Integer.parseInt(m.group("kc").replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
		return new Kc(label, n);
	}

	/**
	 * @return the item name of a "New item added to your collection log" message, or null
	 */
	public static String collectionLogItem(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = COLLECTION_LOG.matcher(stripTags(message));
		return m.find() ? m.group(1).trim() : null;
	}

	public static boolean isPetMessage(String message)
	{
		if (message == null)
		{
			return false;
		}
		String plain = stripTags(message);
		for (String p : PET)
		{
			if (plain.contains(p))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The message without the colour tags the game puts in it.
	 */
	public static String stripTags(String message)
	{
		return message.replaceAll("<[^>]*>", "");
	}
}

package com.dropluckledger.capture;

import java.util.Locale;

/**
 * Name matching helpers: game text and the boss data spell the same thing slightly differently
 * ("The Nightmare" / "Nightmare", "Theatre of Blood: Hard Mode" / "Theatre of Blood Hard Mode").
 */
public final class Names
{
	private Names()
	{
	}

	/**
	 * Lower case, letters and digits only, a leading "the" dropped.
	 */
	public static String norm(String s)
	{
		if (s == null)
		{
			return "";
		}
		String t = flat(s.replace("&", "and"));
		if (t.startsWith("the") && t.length() > 3)
		{
			t = t.substring(3);
		}
		return t;
	}

	/**
	 * Lower case, letters and digits only.
	 */
	public static String flat(String s)
	{
		if (s == null)
		{
			return "";
		}
		StringBuilder b = new StringBuilder(s.length());
		for (int i = 0; i < s.length(); i++)
		{
			char c = Character.toLowerCase(s.charAt(i));
			if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
			{
				b.append(c);
			}
		}
		return b.toString().toLowerCase(Locale.ROOT);
	}
}

package com.dropluckledger.engine;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Engine.ItemMeta;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Catalogue helpers shared by the panel and the capture code: which items a boss tracks by default, what kind of item each is,
 * which bosses list the same collection-log item.  Port of the equivalent helpers in the web app.
 */
public final class Catalog
{
	private Catalog()
	{
	}

	public static final List<String> CAT_ORDER = Arrays.asList("Raid", "Raid-style boss", "Desert Treasure II", "God Wars Dungeon", "Varlamore",
		"Royal Titans", "Slayer", "Dragons", "Wilderness", "Dagannoth Kings", "Minigame", "Minigame boss", "Skilling boss", "Standalone", "Misc",
		"Minor boss", "Clue boss");

	/**
	 * Bosses in display order (category order, then name).
	 */
	public static List<Boss> ordered(Data d)
	{
		List<Boss> l = new ArrayList<>(d.bosses);
		l.sort(Comparator.<Boss>comparingInt(b -> CAT_ORDER.indexOf(b.cat)).thenComparing(b -> b.name, String.CASE_INSENSITIVE_ORDER));
		return l;
	}

	/**
	 * The items shown by default: the collection-log items, the uniques and the pets that are not hidden; uniques first, then pets.
	 */
	public static List<String> defaultTracked(Boss b)
	{
		Map<String, ItemMeta> m = b.meta();
		Set<String> log = b.logSet();
		List<String> names = new ArrayList<>();
		for (Map.Entry<String, ItemMeta> e : m.entrySet())
		{
			ItemMeta im = e.getValue();
			if (!im.hidden && (log.contains(e.getKey()) || im.isUnique() || im.isPet()))
			{
				names.add(e.getKey());
			}
		}
		// stable sort by rank (JavaScript's sort is stable too)
		names.sort(Comparator.comparingInt(n -> rank(m.get(n))));
		return names;
	}

	private static int rank(ItemMeta m)
	{
		return m.isUnique() ? 0 : m.isPet() ? 1 : 2;
	}

	/**
	 * "unique", "pet" or "other".
	 */
	public static String kindOf(Boss b, String name)
	{
		ItemMeta m = b.meta().get(name);
		if (m == null)
		{
			return "other";
		}
		return m.isPet() ? "pet" : m.isUnique() ? "unique" : "other";
	}

	/**
	 * Item name to the ids of the bosses that list it in their collection log (in the order of {@link #ordered}).
	 */
	public static Map<String, List<String>> logIndex(Data d)
	{
		Map<String, List<String>> idx = new LinkedHashMap<>();
		for (Boss b : ordered(d))
		{
			for (String n : b.logSet())
			{
				idx.computeIfAbsent(n, k -> new ArrayList<>()).add(b.id);
			}
		}
		return idx;
	}

	/**
	 * The "any unique" selection: the tracked uniques that are in the collection log, split into those that share the unique table
	 * and those rolled separately (noany).
	 */
	public static final class AnyNames
	{
		public final List<String> names = new ArrayList<>();
		public final List<String> sep = new ArrayList<>();
	}

	public static AnyNames anyNames(Boss b, List<String> tracked)
	{
		Map<String, ItemMeta> m = b.meta();
		Set<String> log = b.logSet();
		AnyNames out = new AnyNames();
		for (String n : tracked)
		{
			ItemMeta im = m.get(n);
			if (im == null || !im.isUnique() || im.hidden || !log.contains(n))
			{
				continue;
			}
			if (im.noany)
			{
				out.sep.add(n);
			}
			else
			{
				out.names.add(n);
			}
		}
		return out;
	}
}

package com.dropluckledger.engine;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The boss drop data (boss.json compiled from the .ds sources) and the compiled form of its expressions.
 * Fields without "transient" are read straight from the JSON; the transient ones are filled in by {@link #prepare()}.
 */
public final class Data
{
	public List<Boss> bosses = new ArrayList<>();
	public List<Shared> shared = new ArrayList<>();

	public transient Map<String, Boss> boss = new LinkedHashMap<>();
	public transient Map<String, Shared> sharedById = new HashMap<>();

	/**
	 * Reads and prepares the data from a stream (UTF-8 JSON).
	 */
	public static Data load(Gson gson, InputStream in) throws IOException
	{
		try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			Data d = gson.fromJson(r, Data.class);
			if (d == null)
			{
				throw new IOException("empty boss data");
			}
			d.prepare();
			return d;
		}
	}

	public Boss boss(String id)
	{
		return boss.get(id);
	}

	/**
	 * Compiles every expression once.
	 */
	public void prepare()
	{
		boss = new LinkedHashMap<>();
		sharedById = new HashMap<>();
		if (bosses == null)
		{
			bosses = new ArrayList<>();
		}
		if (shared == null)
		{
			shared = new ArrayList<>();
		}
		for (Shared s : shared)
		{
			for (Table t : s.tables)
			{
				t.prepare();
			}
			sharedById.put(s.id, s);
		}
		for (Boss b : bosses)
		{
			b.data = this;
			b.prepare();
			boss.put(b.id, b);
		}
	}

	// ------------------------------------------------------------------ model classes

	public static final class Shared
	{
		public String id;
		public String name;
		public List<Table> tables = new ArrayList<>();
	}

	public static final class Param
	{
		public String name;
		public String type; // bool | int | select
		public String label;
		@SerializedName("default")
		public Object def;
		public Double min;
		public Double max;
		public List<String> options;
	}

	public static final class LogItem
	{
		public String name;
		public boolean found;
	}

	public static final class Derive
	{
		public String name;
		public String expr;
	}

	public static final class Derived
	{
		public final String name;
		public final Expr f;

		Derived(String name, Expr f)
		{
			this.name = name;
			this.f = f;
		}
	}

	public static final class RollVar
	{
		public final String name;
		public final double start;

		RollVar(String name, double start)
		{
			this.name = name;
			this.start = start;
		}
	}

	public static final class Boss
	{
		public String id;
		public String name;
		public String cat;
		public String wiki;
		public List<String> kc = new ArrayList<>();
		public String samples;
		public String rolls;
		public List<String> notes = new ArrayList<>();
		public List<String> always = new ArrayList<>();
		public List<Param> params = new ArrayList<>();
		public List<Table> tables = new ArrayList<>();
		public List<Row> tert = new ArrayList<>();
		public List<Row> pets = new ArrayList<>();
		public List<Derive> derive = new ArrayList<>();
		public List<LogItem> logItems = new ArrayList<>();
		public String rollvar;
		public String simnote;

		public transient Data data;
		public transient Expr rollsFn;
		public transient RollVar rv;
		public transient List<Derived> derived = new ArrayList<>();
		// lazily computed, shared between threads
		transient Luck.Dep depCache;
		transient Map<String, Engine.ItemMeta> metaCache;
		transient java.util.Set<String> logCache;

		void prepare()
		{
			notes = nn(notes);
			always = nn(always);
			params = nn(params);
			tables = nn(tables);
			tert = nn(tert);
			pets = nn(pets);
			derive = nn(derive);
			kc = nn(kc);
			logItems = nn(logItems);
			rollsFn = rolls != null && !rolls.isEmpty() ? Expr.parse(rolls) : null;
			rv = null;
			if (rollvar != null && !rollvar.isEmpty())
			{
				String[] p = rollvar.trim().split("\\s+");
				rv = new RollVar(p[0], p.length > 1 ? Double.parseDouble(p[1]) : 0);
			}
			derived = new ArrayList<>();
			for (Derive d : derive)
			{
				derived.add(new Derived(d.name, Expr.parse(d.expr)));
			}
			for (Table t : tables)
			{
				t.prepare();
			}
			for (Row r : tert)
			{
				r.prepare();
			}
			for (Row r : pets)
			{
				r.prepare();
			}
		}

		/**
		 * The first collection-log style label the game prints in its kill-count message, or the boss name.
		 */
		public String mainKcLabel()
		{
			return kc.isEmpty() ? name : kc.get(0);
		}

		/**
		 * Every row of every table, sub-table, tertiary and pet row (not the shared tables reached through gates).
		 */
		public List<Row> allRows()
		{
			List<Row> out = new ArrayList<>();
			for (Table t : tables)
			{
				out.addAll(t.items);
				for (Sub s : t.subs)
				{
					out.addAll(s.items);
				}
			}
			out.addAll(tert);
			out.addAll(pets);
			return out;
		}

		/**
		 * Names of the collection-log items of this boss (rows flagged log in the data).
		 */
		public synchronized java.util.Set<String> logSet()
		{
			if (logCache == null)
			{
				java.util.Set<String> s = new java.util.LinkedHashSet<>();
				for (Row r : allRows())
				{
					if (r.log)
					{
						s.add(r.name);
					}
				}
				logCache = s;
			}
			return logCache;
		}

		public synchronized Luck.Dep dep()
		{
			if (depCache == null)
			{
				depCache = Luck.scanBoss(this);
			}
			return depCache;
		}

		public synchronized Map<String, Engine.ItemMeta> meta()
		{
			if (metaCache == null)
			{
				metaCache = Engine.itemMeta(this);
			}
			return metaCache;
		}
	}

	public static final class Table
	{
		public String id;
		public String label;
		public boolean pre;
		public boolean par;
		public String alt;
		public List<Row> items = new ArrayList<>();
		public List<Gate> gates = new ArrayList<>();
		public List<Sub> subs = new ArrayList<>();
		public Map<String, String> opts = new HashMap<>();

		public transient Expr ifFn;
		public transient Expr gateFn;
		public transient Expr multFn;
		public transient Expr rollsFn;
		public transient Double cancels;
		public transient Double abs;

		void prepare()
		{
			items = nn(items);
			gates = nn(gates);
			subs = nn(subs);
			if (opts == null)
			{
				opts = new HashMap<>();
			}
			ifFn = opts.containsKey("if") && !opts.get("if").isEmpty() ? Expr.cond(opts.get("if")) : null;
			gateFn = has(opts, "gate") ? Expr.parse(opts.get("gate")) : null;
			multFn = has(opts, "mult") ? Expr.parse(opts.get("mult")) : null;
			rollsFn = opts.containsKey("rolls") ? Expr.parse(opts.get("rolls")) : null;
			cancels = Row.parseCancels(opts.get("cancels"));
			abs = has(opts, "abs") ? Expr.rate(opts.get("abs")).eval(new Env()) : null;
			for (Row r : items)
			{
				r.prepare();
			}
			for (Sub s : subs)
			{
				s.prepare();
			}
		}

		public String opt(String k)
		{
			return opts.get(k);
		}
	}

	public static final class Gate
	{
		public String table;
		public String rate;
		public double p;
		public Map<String, String> opts = new HashMap<>();

		public boolean opt(String k)
		{
			return opts != null && has(opts, k);
		}
	}

	public static final class Sub
	{
		public String id;
		public double p;
		public List<Row> items = new ArrayList<>();
		public Map<String, String> opts = new HashMap<>();

		public transient Expr ifFn;

		void prepare()
		{
			items = nn(items);
			if (opts == null)
			{
				opts = new HashMap<>();
			}
			ifFn = has(opts, "if") ? Expr.cond(opts.get("if")) : null;
			for (Row r : items)
			{
				r.prepare();
			}
		}
	}

	public static final class VarClause
	{
		public final List<String> conds;
		public final Expr rate;

		VarClause(List<String> conds, Expr rate)
		{
			this.conds = conds;
			this.rate = rate;
		}
	}

	public static final class Seq
	{
		public final String slot;
		public final int n;
		public final int[] ns;
		public final int last;

		Seq(String slot, int[] ns)
		{
			this.slot = slot;
			this.ns = ns;
			this.n = ns[0];
			int m = ns[0];
			for (int x : ns)
			{
				m = Math.max(m, x);
			}
			this.last = m;
		}
	}

	public static final class Row
	{
		public String flag = "";
		public String name;
		public String qty;
		public String rate;
		public Double p;
		public Map<String, String> attrs = new HashMap<>();
		public String key;
		public boolean log;

		public transient Expr ifFn;
		public transient Expr expr;
		public transient List<VarClause> var;
		public transient Double cancels;
		public transient Seq seq;
		public transient double pity;

		private static final Pattern SEQ = Pattern.compile("^([^:]+):(\\d+(?:,\\d+)*)$");

		void prepare()
		{
			if (attrs == null)
			{
				attrs = new HashMap<>();
			}
			if (flag == null)
			{
				flag = "";
			}
			ifFn = has(attrs, "if") ? Expr.cond(attrs.get("if")) : null;
			expr = has(attrs, "expr") ? Expr.parse(attrs.get("expr")) : null;
			var = has(attrs, "var") ? parseVar(attrs.get("var")) : null;
			cancels = parseCancels(attrs.get("cancels"));
			seq = null;
			if (has(attrs, "seq"))
			{
				Matcher m = SEQ.matcher(attrs.get("seq"));
				if (!m.matches())
				{
					throw new IllegalArgumentException("bad seq=" + attrs.get("seq"));
				}
				String[] parts = m.group(2).split(",");
				int[] ns = new int[parts.length];
				for (int i = 0; i < parts.length; i++)
				{
					ns[i] = Integer.parseInt(parts[i]);
				}
				seq = new Seq(m.group(1), ns);
			}
			pity = has(attrs, "pity") ? Expr.parseFloat(attrs.get("pity")) : 0;
		}

		public String attr(String k)
		{
			return attrs.get(k);
		}

		/**
		 * JavaScript truthiness of an attribute string: set and non-empty.
		 */
		public boolean flagged(String k)
		{
			return has(attrs, k);
		}

		static Double parseCancels(String v)
		{
			if (v == null || v.isEmpty())
			{
				return null;
			}
			if (v.equals("main") || v.equals("all"))
			{
				return Double.POSITIVE_INFINITY;
			}
			if (v.equals("main-roll"))
			{
				return 1.0;
			}
			Matcher m = Pattern.compile("^main:(\\d+)$").matcher(v);
			if (m.matches())
			{
				return Double.parseDouble(m.group(1));
			}
			throw new IllegalArgumentException("bad cancels=" + v);
		}

		private static List<VarClause> parseVar(String src)
		{
			List<VarClause> out = new ArrayList<>();
			for (String e : Expr.splitTop(src, ','))
			{
				int i = e.indexOf(':');
				List<String> conds = new ArrayList<>();
				for (String c : e.substring(0, i).trim().split("\\+"))
				{
					String t = c.trim();
					if (!t.isEmpty())
					{
						conds.add(t);
					}
				}
				out.add(new VarClause(conds, Expr.rate(e.substring(i + 1))));
			}
			return out;
		}
	}

	// ------------------------------------------------------------------ helpers
	private static boolean has(Map<String, String> m, String k)
	{
		String v = m == null ? null : m.get(k);
		return v != null && !v.isEmpty();
	}

	private static <T> List<T> nn(List<T> l)
	{
		return l == null ? new ArrayList<>() : l;
	}
}

package com.dropluckledger.engine;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Gate;
import com.dropluckledger.engine.Data.Param;
import com.dropluckledger.engine.Data.Row;
import com.dropluckledger.engine.Data.Seq;
import com.dropluckledger.engine.Data.Shared;
import com.dropluckledger.engine.Data.Sub;
import com.dropluckledger.engine.Data.Table;
import com.dropluckledger.engine.Data.VarClause;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Per-kill drop probabilities of a boss.  This is a line-by-line port of the web app's engine.js
 * (the part that computes chances; the drop simulator is intentionally not part of the plugin).
 * See SPEC.md of the web app for the meaning of the table options.
 */
public final class Engine
{
	private Engine()
	{
	}

	/**
	 * What the account has so far, used by rows whose chance depends on it (pity timers, no-duplicate groups, owned()).
	 */
	public interface Ctx
	{
		int owned(Row row);

		double since(Row row);
	}

	// ------------------------------------------------------------------ environment
	public static Map<String, Object> defaultParams(Boss boss)
	{
		Map<String, Object> o = new LinkedHashMap<>();
		for (Param p : boss.params)
		{
			o.put(p.name, p.def);
		}
		return o;
	}

	private static boolean jsTruthy(Object v)
	{
		if (v == null)
		{
			return false;
		}
		if (v instanceof Boolean)
		{
			return (Boolean) v;
		}
		if (v instanceof Number)
		{
			double d = ((Number) v).doubleValue();
			return d != 0 && !Double.isNaN(d);
		}
		if (v instanceof CharSequence)
		{
			return ((CharSequence) v).length() > 0;
		}
		return true;
	}

	private static double jsNumber(Object v)
	{
		if (v == null)
		{
			return 0;
		}
		if (v instanceof Boolean)
		{
			return (Boolean) v ? 1 : 0;
		}
		if (v instanceof Number)
		{
			return ((Number) v).doubleValue();
		}
		String s = v.toString().trim();
		if (s.isEmpty())
		{
			return 0;
		}
		try
		{
			return Double.parseDouble(s);
		}
		catch (NumberFormatException e)
		{
			return Double.NaN;
		}
	}

	/**
	 * Builds the variables an expression can read for one boss, one set of boss settings and a kill count.
	 *
	 * @param values  boss settings by name (missing ones use the data's default)
	 * @param globals account-wide switches (rowi = ring of wealth, lq = Legends' Quest)
	 */
	public static Env makeEnv(Boss boss, Map<String, Object> values, Map<String, Double> globals, double kc)
	{
		Env env = new Env();
		env.put("rowi", 0);
		env.put("lq", 1);
		env.put("kc", kc);
		env.put("owned", 0);
		env.put("ri", 0);
		if (globals != null)
		{
			for (Map.Entry<String, Double> e : globals.entrySet())
			{
				env.put(e.getKey(), e.getValue());
			}
		}
		for (Param p : boss.params)
		{
			Object v = values != null && values.containsKey(p.name) ? values.get(p.name) : p.def;
			if ("bool".equals(p.type))
			{
				env.put(p.name, jsTruthy(v) ? 1 : 0);
			}
			else if ("int".equals(p.type))
			{
				env.put(p.name, jsNumber(v));
			}
			else if ("select".equals(p.type))
			{
				String sv = v instanceof String ? (String) v : null;
				env.put(p.name, sv == null ? -1 : p.options.indexOf(sv));
				for (String o : p.options)
				{
					env.put(o, o.equals(sv) ? 1 : 0);
				}
			}
		}
		for (Data.Derived d : boss.derived)
		{
			env.put(d.name, d.f.eval(env));
		}
		return env;
	}

	// ------------------------------------------------------------------ row probabilities
	/**
	 * Absolute probability per attempt of a row; null for "rest" rows (whatever is left over) and unknown rates.
	 */
	public static Double rowBase(Row row, Env env, Ctx ctx)
	{
		if (row.ifFn != null && !Expr.truthy(row.ifFn.eval(env)))
		{
			return 0.0;
		}
		if (row.expr != null)
		{
			env.put("owned", ctx != null ? ctx.owned(row) : 0);
			double v = row.expr.eval(env);
			env.put("owned", 0);
			return Math.max(0, v);
		}
		if (row.var != null)
		{
			VarClause best = null;
			for (VarClause v : row.var)
			{
				boolean all = true;
				for (String c : v.conds)
				{
					boolean ok = c.charAt(0) == '!' ? !env.truthy(c.substring(1)) : env.truthy(c);
					if (!ok)
					{
						all = false;
						break;
					}
				}
				if (all && (best == null || v.conds.size() > best.conds.size()))
				{
					best = v;
				}
			}
			if (best != null)
			{
				return Math.max(0, best.rate.eval(env));
			}
		}
		if (row.flagged("pity") && ctx != null)
		{
			if (ctx.since(row) >= row.pity - 1)
			{
				return 1.0;
			}
		}
		if (row.p == null)
		{
			return null;
		}
		return row.p;
	}

	/**
	 * Independent attempts for tertiaries and pets (attribute trials=expr).
	 */
	private static Double withTrials(Row row, Double p, Env env)
	{
		String t = row.attrs.get("trials");
		if (t == null || t.isEmpty() || p == null)
		{
			return p;
		}
		double n = Expr.parse(t).eval(env);
		return 1 - Math.pow(1 - p, n);
	}

	private static int cnt(Ctx ctx, Row row)
	{
		return ctx != null ? ctx.owned(row) : 0;
	}

	private static boolean truthy(Double d)
	{
		return d != null && d != 0 && !Double.isNaN(d);
	}

	// ------------------------------------------------------------------ table expansion
	static final class Out
	{
		final String name;
		final double pm;
		final Row row;

		Out(String name, double pm, Row row)
		{
			this.name = name;
			this.pm = pm;
			this.row = row;
		}
	}

	public static final class Member
	{
		public final String name;
		public double pm;
		public final Row row;
		public String xor;
		public Integer seqN;
		public int[] seqNs;

		Member(String name, double pm, Row row)
		{
			this.name = name;
			this.pm = pm;
			this.row = row;
		}
	}

	public static final class Entry
	{
		public Double p;
		public Double k;
		public final List<Member> members = new ArrayList<>();
		public int row = -1;
		public String nodup;
		public String slot;
		public boolean bundle;
		public String shared;
	}

	private static Shared sharedLookup(Data data, String id)
	{
		Shared s = data.sharedById.get(id);
		if (s == null)
		{
			throw new IllegalStateException("unknown shared table " + id);
		}
		return s;
	}

	private static double nz(Double d)
	{
		return d == null ? 0 : d;
	}

	static void expandShared(Data data, Shared s, Env env, Ctx ctx, double mass, List<Out> out)
	{
		Table t = s.tables.get(0);
		List<Row> rows = new ArrayList<>();
		for (Row r : t.items)
		{
			if (!(env.truthy("rowi") && r.flagged("rowremove")))
			{
				rows.add(r);
			}
		}
		Double[] shares = new Double[rows.size()];
		for (int i = 0; i < rows.size(); i++)
		{
			Row r = rows.get(i);
			shares[i] = r.flag.equals("+") ? Double.valueOf(0) : rowBase(r, env, ctx);
		}
		int restIdx = -1;
		double sum = 0;
		boolean hasAbs = t.abs != null && t.abs != 0 && !Double.isNaN(t.abs);
		for (int i = 0; i < rows.size(); i++)
		{
			if (shares[i] == null)
			{
				restIdx = i;
			}
			else
			{
				if (hasAbs)
				{
					shares[i] = shares[i] / t.abs;
				}
				sum += shares[i];
			}
		}
		for (Gate g : t.gates)
		{
			sum += g.p;
		}
		if (restIdx >= 0)
		{
			shares[restIdx] = Math.max(0, 1 - sum);
			sum += shares[restIdx];
		}
		double f = sum > 0 ? 1 / sum : 0;
		for (int i = 0; i < rows.size(); i++)
		{
			Row r = rows.get(i);
			if (r.flag.equals("+") || !truthy(shares[i]))
			{
				continue;
			}
			out.add(new Out(r.name, mass * shares[i] * f, r));
		}
		for (Gate g : t.gates)
		{
			double m = mass * g.p * f;
			if (g.opt("lq") && !env.truthy("lq"))
			{
				out.add(new Out("Nature talisman", m, null));
				continue;
			}
			expandShared(data, sharedLookup(data, g.table), env, ctx, m, out);
		}
	}

	private static String nonEmpty(String s)
	{
		return s == null || s.isEmpty() ? null : s;
	}

	/**
	 * The mutually exclusive outcomes of one table for one attempt.
	 */
	static List<Entry> expandTable(Data data, Table t, Env env, Ctx ctx, boolean isBase)
	{
		List<Row> rows = t.items;
		int n = rows.size();
		List<Integer> leaders = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			if (!rows.get(i).flag.equals("+"))
			{
				leaders.add(i);
			}
		}
		Double[] base = new Double[n];
		for (int i = 0; i < n; i++)
		{
			base[i] = rowBase(rows.get(i), env, ctx);
		}
		// sequence slots: the first row (lowest n) carries the probability, the others are members of the same entry
		Map<String, Integer> slotLead = new HashMap<>();
		for (int i : leaders)
		{
			Seq s = rows.get(i).seq;
			if (s != null && (!slotLead.containsKey(s.slot) || s.n < rows.get(slotLead.get(s.slot)).seq.n))
			{
				slotLead.put(s.slot, i);
			}
		}
		List<Entry> entries = new ArrayList<>();
		Map<String, Entry> slotEntry = new HashMap<>();
		for (int i : leaders)
		{
			Row r = rows.get(i);
			Seq s = r.seq;
			if (s != null && slotLead.get(s.slot) != i)
			{
				continue;
			}
			Entry e = new Entry();
			e.p = base[i];
			e.k = r.cancels;
			e.row = i;
			e.nodup = nonEmpty(r.attrs.get("nodup"));
			if (s != null)
			{
				e.slot = s.slot;
				slotEntry.put(s.slot, e);
			}
			entries.add(e);
			e.members.add(new Member(r.name, nz(base[i]), r));
			for (int j = i + 1; j < n && rows.get(j).flag.equals("+"); j++)
			{
				e.members.add(new Member(rows.get(j).name, nz(base[j]), rows.get(j)));
			}
		}
		for (int i : leaders)
		{
			Seq s = rows.get(i).seq;
			if (s != null && slotLead.get(s.slot) != i)
			{
				Entry e = slotEntry.get(s.slot);
				Member m = new Member(rows.get(i).name, nz(e.p), rows.get(i));
				m.seqN = s.n;
				m.seqNs = s.ns;
				e.members.add(m);
			}
		}
		for (Entry e : entries)
		{
			if (e.slot != null)
			{
				Member m0 = e.members.get(0);
				m0.seqN = m0.row.seq.n;
				m0.seqNs = m0.row.seq.ns;
				for (Member m : e.members)
				{
					m.pm = nz(e.p);
				}
			}
		}
		// no-duplicate groups: only the copies you hold the fewest of can drop; the group's total chance is kept
		Map<String, List<Entry>> groups = new LinkedHashMap<>();
		for (Entry e : entries)
		{
			if (e.nodup != null && e.p != null)
			{
				groups.computeIfAbsent(e.nodup, k -> new ArrayList<>()).add(e);
			}
		}
		for (List<Entry> es : groups.values())
		{
			int[] counts = new int[es.size()];
			int mn = Integer.MAX_VALUE;
			double tot = 0;
			for (int i = 0; i < es.size(); i++)
			{
				counts[i] = cnt(ctx, rows.get(es.get(i).row));
				mn = Math.min(mn, counts[i]);
				tot += es.get(i).p;
			}
			double se = 0;
			for (int i = 0; i < es.size(); i++)
			{
				if (counts[i] == mn)
				{
					se += es.get(i).p;
				}
			}
			for (int i = 0; i < es.size(); i++)
			{
				Entry e = es.get(i);
				double np = counts[i] == mn && se > 0 ? e.p * tot / se : 0;
				for (Member m : e.members)
				{
					m.pm = np;
				}
				e.p = np;
			}
		}
		// gated shared tables and sub-tables (absolute masses)
		List<Entry> extra = new ArrayList<>();
		for (Gate g : t.gates)
		{
			List<Out> out = new ArrayList<>();
			expandShared(data, sharedLookup(data, g.table), env, ctx, g.p, out);
			for (Out o : out)
			{
				Entry e = new Entry();
				e.p = o.pm;
				e.k = null;
				e.members.add(new Member(o.name, o.pm, o.row));
				e.shared = g.table;
				extra.add(e);
			}
		}
		Set<String> seenAlt = new HashSet<>();
		for (Sub sb : t.subs)
		{
			String alt = nonEmpty(sb.opts.get("alt"));
			if (sb.ifFn != null && !Expr.truthy(sb.ifFn.eval(env)))
			{
				continue;
			}
			if (alt != null)
			{
				if (seenAlt.contains(alt))
				{
					continue;
				}
				seenAlt.add(alt);
			}
			boolean sbBundle = nonEmpty(sb.opts.get("bundle")) != null;
			Double[] sp = new Double[sb.items.size()];
			for (int i = 0; i < sp.length; i++)
			{
				sp[i] = rowBase(sb.items.get(i), env, ctx);
			}
			if (sbBundle)
			{
				Entry e = new Entry();
				e.p = sb.p;
				e.k = null;
				e.bundle = true;
				for (int i = 0; i < sp.length; i++)
				{
					Row r = sb.items.get(i);
					Member m = new Member(r.name, Math.min(nz(sp[i]), sb.p), r);
					m.xor = nonEmpty(r.attrs.get("xor"));
					e.members.add(m);
				}
				extra.add(e);
			}
			else
			{
				Entry lead = null;
				for (int i = 0; i < sp.length; i++)
				{
					Row r = sb.items.get(i);
					if (r.flag.equals("+") && lead != null)
					{
						lead.members.add(new Member(r.name, nz(sp[i]), r));
						continue;
					}
					lead = new Entry();
					lead.p = nz(sp[i]);
					lead.k = r.cancels;
					lead.members.add(new Member(r.name, nz(sp[i]), r));
					extra.add(lead);
				}
			}
		}
		// totals
		double entriesSum = 0;
		for (Entry e : entries)
		{
			entriesSum += nz(e.p);
		}
		double extraSum = 0;
		for (Entry e : extra)
		{
			extraSum += e.p;
		}
		double total = entriesSum + extraSum;
		if (t.gateFn != null)
		{
			double g = Math.min(1, Math.max(0, t.gateFn.eval(env)));
			double s = entriesSum;
			double sc = s > 0 ? g / s : 0;
			for (Entry e : entries)
			{
				e.p = nz(e.p) * sc;
				for (Member m : e.members)
				{
					m.pm = m.pm * sc;
				}
			}
		}
		else
		{
			List<Entry> restE = new ArrayList<>();
			for (Entry e : entries)
			{
				if (e.p == null)
				{
					restE.add(e);
				}
			}
			if (!restE.isEmpty())
			{
				double r = Math.max(0, 1 - total);
				for (Entry e : restE)
				{
					e.p = r / restE.size();
					for (Member m : e.members)
					{
						m.pm = e.p;
					}
				}
				total += r;
			}
			// base tables always sum to 1 (wiki rounding); any table that exceeds 1 is scaled down so the maths agree
			String normalize = t.opts.get("normalize");
			if ((normalize != null && !normalize.isEmpty()) || isBase || total > 1)
			{
				double sc = total > 0 ? 1 / total : 1;
				for (Entry e : entries)
				{
					e.p = e.p * sc;
					for (Member m : e.members)
					{
						m.pm *= sc;
					}
				}
				for (Entry e : extra)
				{
					e.p = e.p * sc;
					for (Member m : e.members)
					{
						m.pm *= sc;
					}
				}
			}
		}
		List<Entry> all = new ArrayList<>(entries);
		all.addAll(extra);
		if (t.multFn != null)
		{
			double mu = t.multFn.eval(env);
			for (Entry e : all)
			{
				e.p = e.p * mu;
				for (Member m : e.members)
				{
					m.pm *= mu;
				}
			}
		}
		// item-level cancels default to the table level
		for (Entry e : all)
		{
			if (e.k == null)
			{
				e.k = t.cancels;
			}
		}
		List<Entry> res = new ArrayList<>();
		for (Entry e : all)
		{
			boolean named = false;
			for (Member m : e.members)
			{
				if (m.name != null && !m.name.isEmpty())
				{
					named = true;
					break;
				}
			}
			if (e.p > 0 || named)
			{
				res.add(e);
			}
		}
		return res;
	}

	// ------------------------------------------------------------------ kill plan
	static final class ChainTable
	{
		Table t;
		boolean par;
		List<Entry> entries;
		Expr nFn;
		boolean isBase;
	}

	static final class Chain
	{
		List<ChainTable> tables;
		ChainTable base;
	}

	static final class Plan
	{
		boolean indexMode;
		double[][] rd; // pairs [rolls, weight]
		Chain chain;
		List<Chain> chains;
		Boss boss;
	}

	private static Chain buildChain(Boss boss, Env env, Ctx ctx)
	{
		List<ChainTable> chain = new ArrayList<>();
		for (Table t : boss.tables)
		{
			String follow = t.opts.get("follow");
			if (follow != null && !follow.isEmpty())
			{
				continue;
			}
			if (t.ifFn != null && !Expr.truthy(t.ifFn.eval(env)))
			{
				continue;
			}
			ChainTable ct = new ChainTable();
			ct.t = t;
			ct.par = t.par;
			ct.nFn = t.rollsFn;
			chain.add(ct);
		}
		ChainTable base = null;
		for (ChainTable ct : chain)
		{
			if (!ct.par && !ct.t.pre)
			{
				base = ct;
			}
		}
		for (ChainTable ct : chain)
		{
			ct.isBase = ct == base;
			ct.entries = expandTable(boss.data, ct.t, env, ctx, ct.isBase);
		}
		Chain c = new Chain();
		c.tables = new ArrayList<>();
		for (ChainTable ct : chain)
		{
			if (!ct.isBase)
			{
				c.tables.add(ct);
			}
		}
		c.base = base;
		return c;
	}

	private static double[][] rollsDist(Boss boss, Env env)
	{
		double v = boss.rollsFn != null ? boss.rollsFn.eval(env) : 1;
		double lo = Math.max(0, Math.floor(v + 1e-12));
		double f = Math.max(0, v - lo);
		if (f > 1e-9)
		{
			return new double[][] {{lo, 1 - f}, {lo + 1, f}};
		}
		return new double[][] {{lo, 1}};
	}

	static Plan plan(Boss boss, Env env, Ctx ctx)
	{
		Plan pl = new Plan();
		pl.boss = boss;
		pl.rd = rollsDist(boss, env);
		if (boss.rv != null)
		{
			double maxR = 0;
			for (double[] x : pl.rd)
			{
				maxR = Math.max(maxR, x[0]);
			}
			pl.indexMode = true;
			pl.chains = new ArrayList<>();
			for (int r = 0; r < maxR; r++)
			{
				env.put(boss.rv.name, boss.rv.start + r);
				env.put("ri", r + 1);
				pl.chains.add(buildChain(boss, env, ctx));
			}
			return pl;
		}
		pl.indexMode = false;
		pl.chain = buildChain(boss, env, ctx);
		return pl;
	}

	private static int baseRolls(Chain chain, Env env, int rolls)
	{
		if (chain.base == null)
		{
			return 0;
		}
		Table t = chain.base.t;
		if (t.rollsFn != null)
		{
			return (int) Math.max(0, Math.floor(t.rollsFn.eval(env) + 1e-12));
		}
		return rolls;
	}

	private static int nAttempts(ChainTable t, Env env, int rolls)
	{
		if (t.nFn != null)
		{
			return (int) Math.max(0, Math.floor(t.nFn.eval(env) + 1e-12));
		}
		return t.par ? 1 : rolls;
	}

	private static double kEff(Entry e, ChainTable t)
	{
		return e.k != null ? e.k : (t.par ? 0 : 1);
	}

	/**
	 * Probability of receiving NONE of the named items in one kill with R rolls.
	 */
	static double survChain(Chain chain, Env env, int rolls, Set<String> names, Integer m0Force)
	{
		int m0 = m0Force != null ? m0Force : baseRolls(chain, env, rolls);
		double[] vec = new double[m0 + 1];
		vec[m0] = 1;
		for (ChainTable t : chain.tables)
		{
			TreeMap<Integer, Double> mass = new TreeMap<>();
			double tot = 0;
			for (Entry e : t.entries)
			{
				double a = 0;
				for (Member m : e.members)
				{
					if (names.contains(m.name))
					{
						a = Math.max(a, m.pm);
					}
				}
				a = Math.min(a, e.p);
				tot += e.p;
				double k = kEff(e, t);
				int kk = Double.isInfinite(k) ? 1_000_000_000 : (int) k;
				if (e.p - a > 0)
				{
					mass.merge(kk, e.p - a, Double::sum);
				}
			}
			double miss = Math.max(0, 1 - tot);
			int n = nAttempts(t, env, rolls);
			double[] nv = new double[m0 + 1];
			for (int mm = 0; mm <= m0; mm++)
			{
				double w = vec[mm];
				if (!Expr.truthy(w))
				{
					continue;
				}
				if (!t.par && mm == 0)
				{
					nv[0] += w;
					continue;
				}
				double[] local = new double[mm + 1];
				local[mm] = w;
				int ne = t.par ? n : Math.min(n, mm);
				for (int a = 0; a < ne; a++)
				{
					double[] nx = new double[mm + 1];
					for (int m = 0; m <= mm; m++)
					{
						double x = local[m];
						if (!Expr.truthy(x))
						{
							continue;
						}
						if (!t.par && m == 0)
						{
							nx[0] += x;
							continue;
						}
						nx[m] += x * miss;
						for (Map.Entry<Integer, Double> me : mass.entrySet())
						{
							nx[Math.max(0, m - me.getKey())] += x * me.getValue();
						}
					}
					local = nx;
				}
				for (int m = 0; m <= mm; m++)
				{
					nv[m] += local[m];
				}
			}
			vec = nv;
		}
		if (chain.base != null)
		{
			double q = 0;
			for (Entry e : chain.base.entries)
			{
				double a = 0;
				for (Member m : e.members)
				{
					if (names.contains(m.name))
					{
						a = Math.max(a, m.pm);
					}
				}
				q += Math.min(a, e.p);
			}
			double s = 0;
			double keep = Math.max(0, 1 - q);
			for (int mm = 0; mm <= m0; mm++)
			{
				s += vec[mm] * Math.pow(keep, mm);
			}
			return s;
		}
		double s = 0;
		for (double x : vec)
		{
			s += x;
		}
		return s;
	}

	static double survPlan(Plan pl, Env env, Set<String> names)
	{
		double tot = 0;
		for (double[] rw : pl.rd)
		{
			int rolls = (int) rw[0];
			double w = rw[1];
			double s;
			if (!pl.indexMode)
			{
				s = survChain(pl.chain, env, rolls, names, null);
			}
			else
			{
				s = 1;
				for (int r = 0; r < rolls; r++)
				{
					env.put(pl.boss.rv.name, pl.boss.rv.start + r);
					env.put("ri", r + 1);
					s *= survChain(pl.chains.get(r), env, 1, names, 1);
				}
			}
			tot += w * s;
		}
		return tot;
	}

	private static Set<String> planNames(Plan pl)
	{
		Set<String> set = new LinkedHashSet<>();
		List<Chain> chains = new ArrayList<>();
		if (!pl.indexMode)
		{
			chains.add(pl.chain);
		}
		else
		{
			chains.addAll(pl.chains);
		}
		for (Chain c : chains)
		{
			List<ChainTable> all = new ArrayList<>(c.tables);
			if (c.base != null)
			{
				all.add(c.base);
			}
			for (ChainTable t : all)
			{
				for (Entry e : t.entries)
				{
					for (Member m : e.members)
					{
						set.add(m.name);
					}
				}
			}
		}
		return set;
	}

	// ------------------------------------------------------------------ per-kill item probabilities
	public static final class SeqInfo
	{
		public final String slot;
		public final int n;
		public final int len;

		SeqInfo(String slot, int n, int len)
		{
			this.slot = slot;
			this.n = n;
			this.len = len;
		}
	}

	public static final class ItemProb
	{
		public double p;
		public final List<String> kinds = new ArrayList<>();
		public final List<Row> rows = new ArrayList<>();
		public SeqInfo seq;
	}

	private static void put(Map<String, ItemProb> out, String name, double p, String kind, Row row)
	{
		ItemProb o = out.computeIfAbsent(name, k -> new ItemProb());
		o.p = 1 - (1 - o.p) * (1 - Math.min(1, Math.max(0, p)));
		if (!o.kinds.contains(kind))
		{
			o.kinds.add(kind);
		}
		if (row != null)
		{
			o.rows.add(row);
		}
	}

	/**
	 * Per-kill probability of each item (restricted to onlyNames when given).
	 */
	public static Map<String, ItemProb> itemProbs(Boss boss, Env env, Ctx ctx, Set<String> onlyNames)
	{
		Map<String, ItemProb> out = new LinkedHashMap<>();
		Plan pl = plan(boss, env, ctx);
		for (String n : planNames(pl))
		{
			if (onlyNames != null && !onlyNames.contains(n))
			{
				continue;
			}
			put(out, n, 1 - survPlan(pl, env, java.util.Collections.singleton(n)), "table", null);
		}
		// row metadata: sequence lengths
		Map<String, Integer> slotLen = new HashMap<>();
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				if (r.seq != null)
				{
					slotLen.merge(r.seq.slot, r.seq.last, Math::max);
				}
			}
		}
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				if (r.seq != null && out.containsKey(r.name))
				{
					out.get(r.name).seq = new SeqInfo(r.seq.slot, r.seq.n, slotLen.get(r.seq.slot));
				}
			}
		}
		// follow tables (e.g. Abyssal Sire: items rolled when the Unsired is offered)
		for (Table t : boss.tables)
		{
			String src = nonEmpty(t.opts.get("follow"));
			if (src == null || (t.ifFn != null && !Expr.truthy(t.ifFn.eval(env))))
			{
				continue;
			}
			double pSrc = out.containsKey(src) ? out.get(src).p : 0;
			List<Row> rows = new ArrayList<>();
			for (Row r : t.items)
			{
				if (!r.flag.equals("+"))
				{
					rows.add(r);
				}
			}
			Map<String, List<Row>> groups = new LinkedHashMap<>();
			for (Row r : rows)
			{
				String g = nonEmpty(r.attrs.get("nodup"));
				if (g != null)
				{
					groups.computeIfAbsent(g, k -> new ArrayList<>()).add(r);
				}
			}
			IdentityHashMap<Row, Double> adj = new IdentityHashMap<>();
			for (List<Row> rs : groups.values())
			{
				int[] cs = new int[rs.size()];
				int mn = Integer.MAX_VALUE;
				double tot = 0;
				for (int i = 0; i < rs.size(); i++)
				{
					cs[i] = cnt(ctx, rs.get(i));
					mn = Math.min(mn, cs[i]);
					tot += nz(rs.get(i).p);
				}
				double se = 0;
				for (int i = 0; i < rs.size(); i++)
				{
					if (cs[i] == mn)
					{
						se += nz(rs.get(i).p);
					}
				}
				for (int i = 0; i < rs.size(); i++)
				{
					adj.put(rs.get(i), cs[i] == mn && se > 0 ? nz(rs.get(i).p) * tot / se : 0.0);
				}
			}
			for (Row r : rows)
			{
				if (onlyNames != null && !onlyNames.contains(r.name))
				{
					continue;
				}
				Double sh = adj.containsKey(r) ? adj.get(r) : rowBase(r, env, ctx);
				if (truthy(sh))
				{
					put(out, r.name, pSrc * sh, "follow", r);
				}
			}
		}
		// tertiaries and pets
		for (Row r : boss.tert)
		{
			if (onlyNames != null && !onlyNames.contains(r.name))
			{
				continue;
			}
			Double p = withTrials(r, rowBase(r, env, ctx), env);
			if (truthy(p))
			{
				put(out, r.name, p, "tert", r);
			}
		}
		for (Row r : boss.pets)
		{
			if (onlyNames != null && !onlyNames.contains(r.name))
			{
				continue;
			}
			Double p = withTrials(r, rowBase(r, env, ctx), env);
			if (truthy(p))
			{
				put(out, r.name, p, "pet", r);
			}
		}
		return out;
	}

	/**
	 * Items that can only drop from a follow table, mapped to the item(s) that trigger that table
	 * (Abyssal Sire: Unsired -> Font of Consumption).
	 */
	public static Map<String, List<String>> followMap(Boss boss)
	{
		Map<String, List<String>> src = new LinkedHashMap<>();
		Set<String> other = new HashSet<>();
		for (Table t : boss.tables)
		{
			String f = nonEmpty(t.opts.get("follow"));
			for (Row r : t.items)
			{
				if (f != null)
				{
					src.computeIfAbsent(r.name, k -> new ArrayList<>()).add(f);
				}
				else
				{
					other.add(r.name);
				}
			}
		}
		Map<String, List<String>> out = new LinkedHashMap<>();
		for (Map.Entry<String, List<String>> e : src.entrySet())
		{
			if (!other.contains(e.getKey()))
			{
				out.put(e.getKey(), e.getValue());
			}
		}
		return out;
	}

	/**
	 * P(at least one of targets in one kill).  Items off the kill's tables exclude or otherwise depend on each other, so they are
	 * combined inside one pass (exact); tertiaries, pets and follow-up rolls are independent events and are multiplied in.
	 * sources = names other rolls depend on (follow-table sources) that must be evaluated but are not targets.
	 */
	public static double anyProb(Boss boss, Env env, Ctx ctx, Set<String> targets, Collection<String> sources)
	{
		Set<String> need = new LinkedHashSet<>(targets);
		if (sources != null)
		{
			need.addAll(sources);
		}
		Map<String, ItemProb> all = itemProbs(boss, env, ctx, need);
		Set<String> tbl = new LinkedHashSet<>();
		double q = 1;
		Map<String, List<String>> src = new HashMap<>();
		for (Table t : boss.tables)
		{
			String f = nonEmpty(t.opts.get("follow"));
			if (f != null)
			{
				for (Row r : t.items)
				{
					src.computeIfAbsent(r.name, k -> new ArrayList<>()).add(f);
				}
			}
		}
		for (String n : targets)
		{
			ItemProb o = all.get(n);
			if (o == null)
			{
				continue;
			}
			if (o.kinds.size() == 1 && o.kinds.get(0).equals("table"))
			{
				tbl.add(n);
				continue;
			}
			if (o.kinds.size() == 1 && o.kinds.get(0).equals("follow"))
			{
				boolean viaTarget = false;
				List<String> fs = src.get(n);
				if (fs != null)
				{
					for (String f : fs)
					{
						if (targets.contains(f))
						{
							viaTarget = true;
							break;
						}
					}
				}
				if (viaTarget)
				{
					continue; // only rolled after a source that is itself in the set
				}
			}
			q *= 1 - o.p;
		}
		if (!tbl.isEmpty())
		{
			q *= survPlan(plan(boss, env, ctx), env, tbl);
		}
		return 1 - q;
	}

	// ------------------------------------------------------------------ item catalogue (static metadata)
	public static final class ItemMeta
	{
		public final String name;
		public final List<String> flags = new ArrayList<>();
		public String pool;
		public boolean hidden;
		public String group;
		public SeqInfo seq;
		public final List<String> where = new ArrayList<>();
		public boolean noany;
		public int pity;
		public String note;

		ItemMeta(String name)
		{
			this.name = name;
		}

		public boolean isUnique()
		{
			return flags.contains("U");
		}

		public boolean isPet()
		{
			return flags.contains("P");
		}
	}

	public static Map<String, ItemMeta> itemMeta(Boss boss)
	{
		Map<String, ItemMeta> meta = new LinkedHashMap<>();
		Map<String, Integer> slotLen = new HashMap<>();
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				if (r.seq != null)
				{
					slotLen.merge(r.seq.slot, r.seq.last, Math::max);
				}
			}
		}
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				doRow(meta, slotLen, r, t.id);
			}
			for (Sub sb : t.subs)
			{
				for (Row r : sb.items)
				{
					doRow(meta, slotLen, r, t.id + ":" + sb.id);
				}
			}
			for (Gate g : t.gates)
			{
				List<Out> out = new ArrayList<>();
				Env env = makeEnv(boss, defaultParams(boss), new HashMap<>(), 0);
				env.put("rowi", 0);
				expandShared(boss.data, sharedLookup(boss.data, g.table), env, null, 1, out);
				for (Out o : out)
				{
					ItemMeta m = meta.computeIfAbsent(o.name, ItemMeta::new);
					if (!m.where.contains(g.table))
					{
						m.where.add(g.table);
					}
				}
			}
		}
		for (Row r : boss.tert)
		{
			doRow(meta, slotLen, r, "tertiary");
		}
		for (Row r : boss.pets)
		{
			ItemMeta m = meta.computeIfAbsent(r.name, ItemMeta::new);
			if (!m.flags.contains("P"))
			{
				m.flags.add("P");
			}
			m.where.add("pet");
			if (r.flagged("note"))
			{
				m.note = r.attr("note");
			}
		}
		return meta;
	}

	private static void doRow(Map<String, ItemMeta> meta, Map<String, Integer> slotLen, Row r, String where)
	{
		ItemMeta m = meta.computeIfAbsent(r.name, ItemMeta::new);
		if (r.flag != null && !r.flag.isEmpty() && !m.flags.contains(r.flag))
		{
			m.flags.add(r.flag);
		}
		if (r.flagged("pool"))
		{
			m.pool = r.attr("pool");
		}
		if (r.flagged("hidden"))
		{
			m.hidden = true;
		}
		if (r.flagged("group"))
		{
			m.group = r.attr("group");
		}
		if (r.flagged("noany"))
		{
			m.noany = true;
		}
		if (r.seq != null)
		{
			m.seq = new SeqInfo(r.seq.slot, r.seq.n, slotLen.get(r.seq.slot));
		}
		if (r.flagged("pity"))
		{
			m.pity = (int) Expr.parseFloat(r.attr("pity"));
		}
		if (r.flagged("note"))
		{
			m.note = r.attr("note");
		}
		if (!m.where.contains(where))
		{
			m.where.add(where);
		}
	}
}

