package com.dropluckledger.engine;

import java.util.HashMap;

/**
 * Variables visible to the expressions of the drop data (kill count, boss settings, ...).
 * A variable that was never set is an error when an expression reads it, but reads as "false"
 * when it is only tested for truth (this mirrors the JavaScript engine the maths was written in).
 */
public final class Env
{
	private final HashMap<String, Double> vars = new HashMap<>();

	public void put(String name, double value)
	{
		vars.put(name, value);
	}

	public Double get(String name)
	{
		return vars.get(name);
	}

	public boolean has(String name)
	{
		return vars.containsKey(name);
	}

	/**
	 * True when the variable exists and is neither 0 nor NaN.
	 */
	public boolean truthy(String name)
	{
		Double v = vars.get(name);
		return v != null && v != 0 && !Double.isNaN(v);
	}

	/**
	 * JavaScript truthiness of a number.
	 */
	public static boolean truthy(double v)
	{
		return v != 0 && !Double.isNaN(v);
	}
}

package com.dropluckledger.engine;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The small expression language used by the drop data ("1/181.1", "if(kc>200, 1/50, 1/100)", ...).
 * Port of parseExpr() from the web app's engine; the semantics are identical (numbers only,
 * 0/NaN are false, comparison with a 1e-9 tolerance for == and !=).
 */
public final class Expr
{
	/**
	 * A compiled node.
	 */
	@FunctionalInterface
	public interface Node
	{
		double eval(Env env);
	}

	private static final Map<String, Expr> CACHE = new ConcurrentHashMap<>();

	private final Node fn;
	private final Set<String> idents;
	private final String src;

	private Expr(Node fn, Set<String> idents, String src)
	{
		this.fn = fn;
		this.idents = idents;
		this.src = src;
	}

	public double eval(Env env)
	{
		return fn.eval(env);
	}

	/**
	 * Names of the variables the expression reads.
	 */
	public Set<String> idents()
	{
		return idents;
	}

	/**
	 * The source text ("" for compound conditions).
	 */
	public String src()
	{
		return src;
	}

	public static boolean truthy(double v)
	{
		return v != 0 && !Double.isNaN(v);
	}

	/**
	 * An expression that is the same number everywhere (the word "always").
	 */
	public static Expr constant(double v)
	{
		return new Expr(env -> v, new HashSet<>(), "");
	}

	// ------------------------------------------------------------------ tokenizer
	private static final class Tok
	{
		final char kind; // 'n' number, 'i' identifier, 'o' operator
		final String text;
		final double num;

		Tok(char kind, String text, double num)
		{
			this.kind = kind;
			this.text = text;
			this.num = num;
		}
	}

	/**
	 * JavaScript's parseFloat on a string made of digits and dots: the longest valid prefix.
	 */
	static double parseFloat(String s)
	{
		int i = 0;
		int n = s.length();
		while (i < n && Character.isDigit(s.charAt(i)))
		{
			i++;
		}
		int end = i;
		if (i < n && s.charAt(i) == '.')
		{
			i++;
			while (i < n && Character.isDigit(s.charAt(i)))
			{
				i++;
			}
			end = i;
		}
		String t = s.substring(0, end);
		if (t.isEmpty() || t.equals("."))
		{
			return Double.NaN;
		}
		return Double.parseDouble(t);
	}

	private static List<Tok> tokenize(String s)
	{
		List<Tok> t = new ArrayList<>();
		int i = 0;
		int n = s.length();
		while (i < n)
		{
			char c = s.charAt(i);
			if (Character.isWhitespace(c))
			{
				i++;
				continue;
			}
			if ((c >= '0' && c <= '9') || c == '.')
			{
				int j = i;
				while (j < n && ((s.charAt(j) >= '0' && s.charAt(j) <= '9') || s.charAt(j) == '.'))
				{
					j++;
				}
				t.add(new Tok('n', s.substring(i, j), parseFloat(s.substring(i, j))));
				i = j;
				continue;
			}
			if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_')
			{
				int j = i;
				while (j < n && ((s.charAt(j) >= 'A' && s.charAt(j) <= 'Z') || (s.charAt(j) >= 'a' && s.charAt(j) <= 'z')
					|| (s.charAt(j) >= '0' && s.charAt(j) <= '9') || s.charAt(j) == '_'))
				{
					j++;
				}
				t.add(new Tok('i', s.substring(i, j), 0));
				i = j;
				continue;
			}
			if (i + 1 < n)
			{
				String two = s.substring(i, i + 2);
				if (two.equals("<=") || two.equals(">=") || two.equals("==") || two.equals("!=") || two.equals("&&") || two.equals("||"))
				{
					t.add(new Tok('o', two, 0));
					i += 2;
					continue;
				}
			}
			if ("+-*/(),<>!".indexOf(c) >= 0)
			{
				t.add(new Tok('o', String.valueOf(c), 0));
				i++;
				continue;
			}
			throw new IllegalArgumentException("bad character \"" + c + "\" in expression: " + s);
		}
		return t;
	}

	// ------------------------------------------------------------------ functions
	private static double call(String name, double[] a, String src)
	{
		switch (name)
		{
			case "min":
			{
				double r = Double.POSITIVE_INFINITY;
				for (double x : a)
				{
					r = Math.min(r, x);
				}
				return r;
			}
			case "max":
			{
				double r = Double.NEGATIVE_INFINITY;
				for (double x : a)
				{
					r = Math.max(r, x);
				}
				return r;
			}
			case "clamp":
				return Math.min(Math.max(arg(a, 0), arg(a, 1)), arg(a, 2));
			case "floor":
				return Math.floor(arg(a, 0));
			case "ceil":
				return Math.ceil(arg(a, 0));
			case "round":
				return Math.floor(arg(a, 0) + 0.5);
			case "abs":
				return Math.abs(arg(a, 0));
			case "pow":
				return Math.pow(arg(a, 0), arg(a, 1));
			case "if":
				return truthy(arg(a, 0)) ? arg(a, 1) : arg(a, 2);
			case "interp":
			{
				// interp(x, x1,y1, x2,y2, ...) piecewise linear
				int np = a.length - 1;
				if (np < 4 || np % 2 != 0)
				{
					throw new IllegalArgumentException("interp needs x1,y1,x2,y2,...");
				}
				double x = a[0];
				if (x <= a[1])
				{
					return a[2];
				}
				for (int i = 3; i < a.length; i += 2)
				{
					if (x <= a[i])
					{
						double x0 = a[i - 2], y0 = a[i - 1], x1 = a[i], y1 = a[i + 1];
						return y0 + (y1 - y0) * (x - x0) / (x1 - x0);
					}
				}
				return a[a.length - 1];
			}
			case "step":
			{
				double x = a[0];
				double r = 0;
				for (int i = 1; i + 1 < a.length; i += 2)
				{
					if (x >= a[i])
					{
						r = a[i + 1];
					}
				}
				return r;
			}
			default:
				throw new IllegalArgumentException("unknown function " + name + " in " + src);
		}
	}

	private static double arg(double[] a, int i)
	{
		return i < a.length ? a[i] : Double.NaN; // a missing argument is undefined in the original
	}

	private static boolean knownFunction(String name)
	{
		switch (name)
		{
			case "min":
			case "max":
			case "clamp":
			case "floor":
			case "ceil":
			case "round":
			case "abs":
			case "pow":
			case "if":
			case "interp":
			case "step":
				return true;
			default:
				return false;
		}
	}

	// ------------------------------------------------------------------ parser
	/**
	 * Parses (and caches) an expression.
	 */
	public static Expr parse(String src)
	{
		Expr hit = CACHE.get(src);
		if (hit != null)
		{
			return hit;
		}
		Expr e = new Parser(src).run();
		CACHE.put(src, e);
		return e;
	}

	/**
	 * A condition list "a,b" meaning a AND b (each part is an expression), as used by the if= attribute.
	 */
	public static Expr cond(String src)
	{
		List<String> parts = splitTop(src, ',');
		List<Expr> es = new ArrayList<>();
		Set<String> ids = new LinkedHashSet<>();
		for (String p : parts)
		{
			Expr e = parse(p);
			es.add(e);
			ids.addAll(e.idents);
		}
		return new Expr(env ->
		{
			for (Expr p : es)
			{
				if (!truthy(p.eval(env)))
				{
					return 0;
				}
			}
			return 1;
		}, ids, "");
	}

	/**
	 * A rate such as "1/181.1", "3.5/25", "~0.02" or "Always".
	 */
	public static Expr rate(String s)
	{
		String t = s.trim().replace(",", "");
		if (t.startsWith("~"))
		{
			t = t.substring(1);
		}
		if (t.equalsIgnoreCase("always"))
		{
			return constant(1);
		}
		return parse(t);
	}

	/**
	 * Splits at top-level separators (not inside parentheses), trimmed, empties dropped.
	 */
	public static List<String> splitTop(String s, char sep)
	{
		List<String> out = new ArrayList<>();
		int d = 0;
		StringBuilder cur = new StringBuilder();
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			if (c == '(')
			{
				d++;
			}
			if (c == ')')
			{
				d--;
			}
			if (c == sep && d == 0)
			{
				out.add(cur.toString());
				cur.setLength(0);
			}
			else
			{
				cur.append(c);
			}
		}
		out.add(cur.toString());
		List<String> res = new ArrayList<>();
		for (String x : out)
		{
			String tr = x.trim();
			if (!tr.isEmpty())
			{
				res.add(tr);
			}
		}
		return res;
	}

	private static final class Parser
	{
		private final String src;
		private final List<Tok> tk;
		private int pos;
		private final Set<String> idents = new LinkedHashSet<>();

		Parser(String src)
		{
			this.src = src;
			this.tk = tokenize(src);
		}

		Expr run()
		{
			Node n = orE();
			if (pos < tk.size())
			{
				throw new IllegalArgumentException("trailing tokens in expression: " + src);
			}
			return new Expr(n, idents, src);
		}

		private Tok peek()
		{
			return pos < tk.size() ? tk.get(pos) : null;
		}

		private Tok eat()
		{
			return pos < tk.size() ? tk.get(pos++) : null;
		}

		private boolean isOp(String v)
		{
			Tok p = peek();
			return p != null && p.kind == 'o' && p.text.equals(v);
		}

		private Node primary()
		{
			Tok x = eat();
			if (x == null)
			{
				throw new IllegalArgumentException("unexpected end of expression: " + src);
			}
			if (x.kind == 'n')
			{
				final double v = x.num;
				return env -> v;
			}
			if (x.kind == 'i')
			{
				if (isOp("("))
				{
					eat();
					List<Node> args = new ArrayList<>();
					if (!isOp(")"))
					{
						for (;;)
						{
							args.add(orE());
							if (isOp(","))
							{
								eat();
								continue;
							}
							break;
						}
					}
					if (!isOp(")"))
					{
						throw new IllegalArgumentException("missing ) in " + src);
					}
					eat();
					final String fname = x.text;
					if (!knownFunction(fname))
					{
						throw new IllegalArgumentException("unknown function " + fname + " in " + src);
					}
					final Node[] an = args.toArray(new Node[0]);
					final String s = src;
					return env ->
					{
						double[] a = new double[an.length];
						for (int i = 0; i < an.length; i++)
						{
							a[i] = an[i].eval(env); // all arguments are evaluated, as in the original
						}
						return call(fname, a, s);
					};
				}
				final String name = x.text;
				idents.add(name);
				final String s = src;
				return env ->
				{
					Double v = env.get(name);
					if (v == null)
					{
						throw new IllegalStateException("undefined variable \"" + name + "\" in expression: " + s);
					}
					return v;
				};
			}
			if (x.kind == 'o' && x.text.equals("("))
			{
				Node e = orE();
				if (!isOp(")"))
				{
					throw new IllegalArgumentException("missing ) in " + src);
				}
				eat();
				return e;
			}
			throw new IllegalArgumentException("unexpected token " + x.text + " in " + src);
		}

		private Node unary()
		{
			if (isOp("-"))
			{
				eat();
				final Node e = unary();
				return env -> -e.eval(env);
			}
			if (isOp("!"))
			{
				eat();
				final Node e = unary();
				return env -> truthy(e.eval(env)) ? 0 : 1;
			}
			return primary();
		}

		private Node mul()
		{
			Node l = unary();
			while (isOp("*") || isOp("/"))
			{
				final String o = eat().text;
				final Node r = unary();
				final Node a = l;
				l = o.equals("*") ? env -> a.eval(env) * r.eval(env) : env -> a.eval(env) / r.eval(env);
			}
			return l;
		}

		private Node add()
		{
			Node l = mul();
			while (isOp("+") || isOp("-"))
			{
				final String o = eat().text;
				final Node r = mul();
				final Node a = l;
				l = o.equals("+") ? env -> a.eval(env) + r.eval(env) : env -> a.eval(env) - r.eval(env);
			}
			return l;
		}

		private Node cmp()
		{
			Node l = add();
			for (;;)
			{
				Tok p = peek();
				if (p == null || p.kind != 'o')
				{
					break;
				}
				String o = p.text;
				if (!(o.equals("<") || o.equals(">") || o.equals("<=") || o.equals(">=") || o.equals("==") || o.equals("!=")))
				{
					break;
				}
				eat();
				final Node r = add();
				final Node a = l;
				final String op = o;
				l = env ->
				{
					double x = a.eval(env);
					double y = r.eval(env);
					boolean res;
					switch (op)
					{
						case "<":
							res = x < y;
							break;
						case ">":
							res = x > y;
							break;
						case "<=":
							res = x <= y;
							break;
						case ">=":
							res = x >= y;
							break;
						case "==":
							res = Math.abs(x - y) < 1e-9;
							break;
						default:
							res = Math.abs(x - y) >= 1e-9;
							break;
					}
					return res ? 1 : 0;
				};
			}
			return l;
		}

		private Node andE()
		{
			Node l = cmp();
			while (isOp("&&"))
			{
				eat();
				final Node r = cmp();
				final Node a = l;
				l = env -> (truthy(a.eval(env)) && truthy(r.eval(env))) ? 1 : 0;
			}
			return l;
		}

		private Node orE()
		{
			Node l = andE();
			while (isOp("||"))
			{
				eat();
				final Node r = andE();
				final Node a = l;
				l = env -> (truthy(a.eval(env)) || truthy(r.eval(env))) ? 1 : 0;
			}
			return l;
		}
	}
}

package com.dropluckledger.engine;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Row;
import com.dropluckledger.engine.Data.Sub;
import com.dropluckledger.engine.Data.Table;
import com.dropluckledger.engine.Data.VarClause;
import com.dropluckledger.engine.Engine.ItemMeta;
import com.dropluckledger.engine.Engine.SeqInfo;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The luck maths: how likely was your drop record, how long a dry streak you are on, what comes next.
 * Port of luck.js.  A "run list" is [(p, n)]: n consecutive kills that each had probability p of producing the item.
 */
public final class Luck
{
	private Luck()
	{
	}

	// ------------------------------------------------------------------ run lists and the Poisson-binomial count
	public static final class Run
	{
		public double p;
		public long n;

		public Run(double p, long n)
		{
			this.p = p;
			this.n = n;
		}
	}

	/**
	 * pmf[0..m] of Binomial(n, p), exact for j &lt;= m.
	 */
	static double[] binomPmf(double n, double p, int m)
	{
		double[] out = new double[m + 1];
		if (p <= 0)
		{
			out[0] = 1;
			return out;
		}
		if (p >= 1)
		{
			if (n <= m)
			{
				out[(int) n] = 1;
			}
			return out;
		}
		double lq = Math.log1p(-p);
		double lp = Math.log(p);
		double lg = n * lq;
		out[0] = Math.exp(lg);
		for (int j = 1; j <= m && j <= n; j++)
		{
			lg += Math.log((n - j + 1) / j) + lp - lq;
			out[j] = Math.exp(lg);
		}
		return out;
	}

	/**
	 * P(X = j) for j = 0..m, where X is the number of hits over the runs.
	 */
	public static double[] countDist(List<Run> runs, int m)
	{
		double[] dist = new double[m + 1];
		dist[0] = 1;
		for (Run r : runs)
		{
			if (r.n <= 0 || r.p <= 0)
			{
				continue;
			}
			double[] pm = binomPmf(r.n, r.p, m);
			double[] nd = new double[m + 1];
			for (int i = 0; i <= m; i++)
			{
				double a = dist[i];
				if (!Expr.truthy(a))
				{
					continue;
				}
				for (int j = 0; i + j <= m; j++)
				{
					nd[i + j] += a * pm[j];
				}
			}
			dist = nd;
		}
		return dist;
	}

	public static double logSurv(List<Run> runs)
	{
		double s = 0;
		for (Run r : runs)
		{
			if (r.p >= 1 && r.n > 0)
			{
				return Double.NEGATIVE_INFINITY;
			}
			if (r.n > 0 && r.p > 0)
			{
				s += r.n * Math.log1p(-r.p);
			}
		}
		return s;
	}

	/**
	 * P(X &gt;= need).
	 */
	public static double atLeast(int need, List<Run> runs)
	{
		if (need <= 0)
		{
			return 1;
		}
		if (need == 1)
		{
			return -Math.expm1(logSurv(runs));
		}
		if (need > 3000)
		{
			// normal approximation for very large counts
			double mu = 0;
			double v = 0;
			for (Run r : runs)
			{
				mu += r.n * r.p;
				v += r.n * r.p * (1 - r.p);
			}
			double z = (need - 0.5 - mu) / Math.sqrt(Math.max(v, 1e-12));
			return 0.5 * erfc(z / Math.sqrt(2));
		}
		double[] d = countDist(runs, need - 1);
		double s = 0;
		for (double x : d)
		{
			s += x;
		}
		return Math.max(0, 1 - s);
	}

	private static double erfc(double x)
	{
		// Abramowitz-Stegun 7.1.26 (enough for the rare large-count approximation)
		double s = x < 0 ? -1 : 1;
		x = Math.abs(x);
		double t = 1 / (1 + 0.3275911 * x);
		double y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x);
		return s > 0 ? 1 - y : 1 + y;
	}

	public static double sumP(List<Run> runs)
	{
		double s = 0;
		for (Run r : runs)
		{
			s += r.p * r.n;
		}
		return s;
	}

	public static long countKills(List<Run> runs)
	{
		long s = 0;
		for (Run r : runs)
		{
			s += r.n;
		}
		return s;
	}

	/**
	 * Concatenates run lists and compresses neighbours with the same chance.
	 */
	public static List<Run> mergeRuns(List<List<Run>> lists)
	{
		List<Run> out = new ArrayList<>();
		for (List<Run> l : lists)
		{
			for (Run r : l)
			{
				if (r.n <= 0)
				{
					continue;
				}
				Run last = out.isEmpty() ? null : out.get(out.size() - 1);
				if (last != null && Math.abs(last.p - r.p) < 1e-15)
				{
					last.n += r.n;
				}
				else
				{
					out.add(new Run(r.p, r.n));
				}
			}
		}
		return out;
	}

	// ------------------------------------------------------------------ boss dependency scan
	/**
	 * What in a boss's data depends on the account: kill count ramps, owned copies, pity timers, follow tables.
	 */
	public static final class Dep
	{
		public boolean kcDep;
		public int cap = 1000;
		public final Set<String> ownedNames = new LinkedHashSet<>();
		public final Map<String, Integer> pity = new LinkedHashMap<>();
		public final List<String> follows = new ArrayList<>();
		public final Map<String, Set<String>> nodupGroups = new LinkedHashMap<>();
	}

	private static final Pattern NUM = Pattern.compile("(\\d+(?:\\.\\d+)?)");

	static Dep scanBoss(Boss boss)
	{
		Dep dep = new Dep();
		List<Double> lits = new ArrayList<>();
		class See
		{
			void expr(Expr fn, String rowName)
			{
				if (fn == null)
				{
					return;
				}
				Set<String> ids = fn.idents();
				if (ids.contains("kc"))
				{
					dep.kcDep = true;
					Matcher m = NUM.matcher(fn.src() == null ? "" : fn.src());
					while (m.find())
					{
						lits.add(Double.parseDouble(m.group(1)));
					}
				}
				if (ids.contains("owned") && rowName != null)
				{
					dep.ownedNames.add(rowName);
				}
			}

			void row(Row r)
			{
				expr(r.expr, r.name);
				expr(r.ifFn, null);
				if (r.var != null)
				{
					for (VarClause v : r.var)
					{
						expr(v.rate, r.name);
					}
				}
				if (r.pity != 0 && !Double.isNaN(r.pity))
				{
					dep.pity.put(r.name, (int) r.pity);
				}
				String g = r.attrs.get("nodup");
				if (g != null && !g.isEmpty())
				{
					dep.nodupGroups.computeIfAbsent(g, k -> new LinkedHashSet<>()).add(r.name);
				}
			}
		}
		See see = new See();
		for (Table t : boss.tables)
		{
			see.expr(t.ifFn, null);
			see.expr(t.gateFn, null);
			see.expr(t.multFn, null);
			see.expr(t.rollsFn, null);
			String f = t.opts.get("follow");
			if (f != null && !f.isEmpty())
			{
				dep.follows.add(f);
			}
			for (Row r : t.items)
			{
				see.row(r);
			}
			for (Sub sb : t.subs)
			{
				for (Row r : sb.items)
				{
					see.row(r);
				}
			}
		}
		for (Row r : boss.tert)
		{
			see.row(r);
		}
		for (Row r : boss.pets)
		{
			see.row(r);
		}
		for (Data.Derived d : boss.derived)
		{
			see.expr(d.f, null);
		}
		see.expr(boss.rollsFn, null);
		for (Set<String> set : dep.nodupGroups.values())
		{
			dep.ownedNames.addAll(set);
		}
		if (dep.kcDep)
		{
			double m = 0;
			for (double x : lits)
			{
				if (x >= 2 && x <= 5000)
				{
					m = Math.max(m, x);
				}
			}
			dep.cap = m != 0 ? (int) Math.min(2000, Math.ceil(m) + 2) : 1000;
		}
		return dep;
	}

	// ------------------------------------------------------------------ per-boss model
	/**
	 * One logged drop.  kc is the kill number it came on, or null when that is unknown.
	 */
	public static final class DropRec
	{
		public final String item;
		public final Integer kc;

		public DropRec(String item, Integer kc)
		{
			this.item = item;
			this.kc = kc;
		}
	}

	/**
	 * Boss settings that apply from a kill number on.
	 */
	public static final class Seg
	{
		public final int from;
		public final Map<String, Object> params;

		public Seg(int from, Map<String, Object> params)
		{
			this.from = from;
			this.params = params;
		}
	}

	/**
	 * The state of one boss the maths needs.
	 */
	public static final class BossRecord
	{
		public int kc;
		public List<Seg> segs = new ArrayList<>();
		public List<DropRec> drops = new ArrayList<>();
	}

	static final class Held
	{
		final List<Integer> ks = new ArrayList<>();
		int unk;
		int total;
	}

	private static int lowerBound(List<Integer> a, int x)
	{
		int lo = 0;
		int hi = a.size();
		while (lo < hi)
		{
			int m = (lo + hi) >>> 1;
			if (a.get(m) < x)
			{
				lo = m + 1;
			}
			else
			{
				hi = m;
			}
		}
		return lo;
	}

	/**
	 * The chances of one boss for one account state.  Not thread safe (it memoises); build one per computation.
	 */
	public static final class Model
	{
		public final Boss boss;
		public final int K;
		final Dep dep;
		final List<Seg> segs;
		final List<Map<String, Object>> segEnv = new ArrayList<>();
		final Map<String, Held> byName = new HashMap<>();
		final Map<String, Double> globals;
		private final Map<String, Double> memo = new HashMap<>();

		Model(Boss boss, BossRecord st, Map<String, Double> globals)
		{
			this.boss = boss;
			this.dep = boss.dep();
			this.globals = globals == null ? new HashMap<>() : globals;
			this.K = Math.max(0, st.kc);
			List<Seg> ss = new ArrayList<>(st.segs);
			if (ss.isEmpty())
			{
				ss.add(new Seg(1, Engine.defaultParams(boss)));
			}
			ss.sort((a, b) -> Integer.compare(a.from, b.from));
			this.segs = ss;
			for (Seg s : ss)
			{
				Map<String, Object> m = Engine.defaultParams(boss);
				if (s.params != null)
				{
					m.putAll(s.params);
				}
				segEnv.add(m);
			}
			for (DropRec d : st.drops)
			{
				Held o = byName.computeIfAbsent(d.item, k -> new Held());
				o.total++;
				if (d.kc == null)
				{
					o.unk++;
				}
				else
				{
					o.ks.add(d.kc);
				}
			}
			for (Held h : byName.values())
			{
				Collections.sort(h.ks);
			}
		}

		private int segIdx(int k)
		{
			int i = 0;
			for (int j = 0; j < segs.size(); j++)
			{
				if (segs.get(j).from <= k)
				{
					i = j;
				}
			}
			return i;
		}

		int ownedAt(String name, int k)
		{
			Held o = byName.get(name);
			if (o == null)
			{
				return 0;
			}
			return lowerBound(o.ks, k) + (k > K ? o.unk : 0);
		}

		int lastBefore(String name, int k)
		{
			Held o = byName.get(name);
			if (o == null)
			{
				return 0;
			}
			int i = lowerBound(o.ks, k);
			return i > 0 ? o.ks.get(i - 1) : 0;
		}

		private Set<String> names1(String name)
		{
			Set<String> s = new LinkedHashSet<>(dep.follows);
			s.add(name);
			return s;
		}

		/**
		 * Chance per kill number k of receiving the item (names.size()==1 and !multi) or at least one of the items (multi).
		 */
		private double pAtImpl(List<String> names, boolean multi, final int k, final Integer ownedOverride)
		{
			int si = segIdx(k);
			int kcE = dep.kcDep ? Math.min(k - 1, dep.cap) : 0;
			StringBuilder sig = new StringBuilder();
			if (ownedOverride == null)
			{
				if (!dep.ownedNames.isEmpty())
				{
					boolean first = true;
					for (String n : dep.ownedNames)
					{
						if (!first)
						{
							sig.append(',');
						}
						first = false;
						sig.append(ownedAt(n, k));
					}
				}
			}
			else
			{
				sig.append("ov").append(ownedOverride);
			}
			StringBuilder since = new StringBuilder();
			if (!dep.pity.isEmpty())
			{
				boolean first = true;
				for (Map.Entry<String, Integer> e : dep.pity.entrySet())
				{
					if (!first)
					{
						since.append(',');
					}
					first = false;
					since.append(Math.min(e.getValue(), k - 1 - lastBefore(e.getKey(), k)));
				}
			}
			StringBuilder key = new StringBuilder();
			if (multi)
			{
				key.append("M:").append(String.join("\u0001", names));
			}
			else
			{
				key.append(names.get(0));
			}
			key.append('|').append(si).append('|').append(kcE).append('|').append(sig).append('|').append(since);
			String ks = key.toString();
			Double hit = memo.get(ks);
			if (hit != null)
			{
				return hit;
			}
			Env env = Engine.makeEnv(boss, segEnv.get(si), globals, kcE);
			Engine.Ctx ctx = new Engine.Ctx()
			{
				@Override
				public int owned(Row row)
				{
					return ownedOverride != null ? ownedOverride : ownedAt(row.name, k);
				}

				@Override
				public double since(Row row)
				{
					return (k - 1) - lastBefore(row.name, k);
				}
			};
			double v;
			if (multi)
			{
				v = Engine.anyProb(boss, env, ctx, new LinkedHashSet<>(names), dep.follows);
			}
			else
			{
				Map<String, Engine.ItemProb> out = Engine.itemProbs(boss, env, ctx, names1(names.get(0)));
				Engine.ItemProb ip = out.get(names.get(0));
				v = ip != null ? ip.p : 0;
			}
			memo.put(ks, v);
			return v;
		}

		public double pAt(String name, int k)
		{
			return pAtImpl(Collections.singletonList(name), false, k, null);
		}

		/**
		 * As pAt but pretending the account owns exactly ownedOverride copies.
		 */
		public double pAt(String name, int k, int ownedOverride)
		{
			return pAtImpl(Collections.singletonList(name), false, k, ownedOverride);
		}

		public double pAtAny(List<String> names, int k)
		{
			return pAtImpl(names, true, k, null);
		}

		public double pNext(String name)
		{
			return pAt(name, K + 1);
		}

		public int copies(String name)
		{
			Held o = byName.get(name);
			return o != null ? o.total : 0;
		}

		public List<Integer> known(String name)
		{
			Held o = byName.get(name);
			return o != null ? o.ks : Collections.<Integer>emptyList();
		}

		public int unknown(String name)
		{
			Held o = byName.get(name);
			return o != null ? o.unk : 0;
		}

		public List<Run> runsFor(String name, int from, int to)
		{
			return runsImpl(Collections.singletonList(name), false, from, to);
		}

		public List<Run> runsForAny(List<String> names, int from, int to)
		{
			return runsImpl(names, true, from, to);
		}

		/**
		 * Run list for kills from..to (inclusive, 1-indexed).
		 */
		private List<Run> runsImpl(List<String> names, boolean multi, int from, int to)
		{
			List<Run> out = new ArrayList<>();
			if (to < from)
			{
				return out;
			}
			TreeSet<Integer> pts = new TreeSet<>();
			pts.add(from);
			for (Seg s : segs)
			{
				if (s.from > from && s.from <= to)
				{
					pts.add(s.from);
				}
			}
			if (dep.kcDep)
			{
				for (int k = from + 1; k <= Math.min(to, dep.cap + 2); k++)
				{
					pts.add(k);
				}
			}
			if (!dep.ownedNames.isEmpty())
			{
				for (String n : dep.ownedNames)
				{
					Held o = byName.get(n);
					if (o != null)
					{
						for (int d : o.ks)
						{
							if (d + 1 > from && d + 1 <= to)
							{
								pts.add(d + 1);
							}
						}
					}
				}
				if (K + 1 > from && K + 1 <= to)
				{
					pts.add(K + 1);
				}
			}
			for (String nm : names)
			{
				Integer pv = dep.pity.get(nm);
				if (pv == null)
				{
					continue;
				}
				Held o = byName.get(nm);
				List<Integer> ds = new ArrayList<>();
				ds.add(0);
				if (o != null)
				{
					ds.addAll(o.ks);
				}
				for (int d : ds)
				{
					int[] xs = {d + 1, d + pv};
					for (int x : xs)
					{
						if (x > from && x <= to)
						{
							pts.add(x);
						}
					}
				}
			}
			Integer[] arr = pts.toArray(new Integer[0]);
			for (int i = 0; i < arr.length; i++)
			{
				int s = arr[i];
				int e = i + 1 < arr.length ? arr[i + 1] - 1 : to;
				double p = pAtImpl(names, multi, s, null);
				Run last = out.isEmpty() ? null : out.get(out.size() - 1);
				if (last != null && Math.abs(last.p - p) < 1e-15)
				{
					last.n += e - s + 1;
				}
				else
				{
					out.add(new Run(p, e - s + 1));
				}
			}
			return out;
		}
	}

	public static Model makeModel(Boss boss, BossRecord st, Map<String, Double> globals)
	{
		return new Model(boss, st, globals);
	}

	// ------------------------------------------------------------------ item analysis
	static List<Row> slotMembers(Boss boss, String slot)
	{
		List<Row> out = new ArrayList<>();
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				if (r.seq != null && r.seq.slot.equals(slot))
				{
					out.add(r);
				}
			}
		}
		return out;
	}

	/**
	 * How many times the slot has hit.  Normally the sum of the copies of its members.  A member received on hit n of L implies all the
	 * earlier hits happened (a vestige is the 3rd vestige roll even if the two gold rings were never logged), so never infer fewer than
	 * L x (copies of the last member).
	 */
	static int slotHits(Model m, Boss boss, String slot)
	{
		List<Row> mem = slotMembers(boss, slot);
		if (mem.isEmpty())
		{
			return 0;
		}
		int len = 0;
		for (Row r : mem)
		{
			len = Math.max(len, r.seq.last);
		}
		int sum = 0;
		int fin = 0;
		for (Row r : mem)
		{
			int c = m.copies(r.name);
			sum += c;
			if (r.seq.last == len)
			{
				fin += c;
			}
		}
		return Math.max(sum, len * fin);
	}

	public static final class Label
	{
		public final String key;
		public final String text;

		Label(String key, String text)
		{
			this.key = key;
			this.text = text;
		}
	}

	public static Label luckLabel(Double pct)
	{
		if (pct == null || Double.isNaN(pct))
		{
			return new Label("na", "—");
		}
		if (pct < 0.05)
		{
			return new Label("vdry", "Very dry");
		}
		if (pct < 0.20)
		{
			return new Label("dry", "Dry");
		}
		if (pct < 0.40)
		{
			return new Label("below", "Slightly dry");
		}
		if (pct < 0.60)
		{
			return new Label("avg", "On rate");
		}
		if (pct < 0.80)
		{
			return new Label("above", "Slightly lucky");
		}
		if (pct < 0.95)
		{
			return new Label("lucky", "Lucky");
		}
		return new Label("vlucky", "Very lucky");
	}

	/**
	 * Kills needed from now (memoryless) for the chance of at least d hits to reach c; Infinity if unreachable.
	 */
	public static double killsTo(Model m, String name, int d, double c, int startK)
	{
		java.util.function.IntToDoubleFunction test = n -> atLeast(d, m.runsFor(name, startK + 1, startK + n));
		if (m.pAt(name, startK + 1) <= 0 && test.applyAsDouble(1) <= 0)
		{
			return Double.POSITIVE_INFINITY;
		}
		int hi = 1;
		while (test.applyAsDouble(hi) < c)
		{
			hi *= 2;
			if (hi > 20_000_000)
			{
				return Double.POSITIVE_INFINITY;
			}
		}
		int lo = hi / 2; // test(lo) < c (or lo = 0)
		while (hi - lo > 1)
		{
			int mid = (lo + hi) >> 1;
			if (test.applyAsDouble(mid) >= c)
			{
				hi = mid;
			}
			else
			{
				lo = mid;
			}
		}
		return hi;
	}

	/**
	 * The analysis of one item in one boss.
	 */
	public static final class ItemAnalysis
	{
		public String name;
		public int K;
		public SeqInfo seq;
		public int pity;
		public int O;
		public int unknown;
		public Integer hits;
		public boolean once;
		public double pNext;
		public boolean collected;
		public int need;
		public Double expected;
		public Double pct;
		public Double exceed;
		public Double cum;
		/**
		 * P(at least one more copy than the player has, from all their kills): how likely it is that the next copy would have come by
		 * now.  The kills made beyond the drop rate carry over to the next copy, so a drop does not send this back to zero.  Equal to
		 * {@link #cum} while the player has none; null before the first kill and for a drop that is already collected.
		 */
		public Double another;
		public Label label;
		public int streakFrom;
		public int streak;
		public double meter;
		/**
		 * False when the player has copies but none with a kill number, so nobody knows how long ago the last one was:
		 * {@link #streak} and {@link #meter} then count from the first kill and say nothing true.
		 */
		public boolean streakKnown = true;
		public final Map<Integer, Double> fwd = new LinkedHashMap<>();
		public Map<Double, Double> kto;
		public int window;
	}

	public static ItemAnalysis analyse(Model m, String name, int window)
	{
		final Boss boss = m.boss;
		final int K = m.K;
		final int win = window > 0 ? window : 50;
		ItemMeta meta = boss.meta().get(name);
		final SeqInfo seq = meta != null ? meta.seq : null;
		ItemAnalysis out = new ItemAnalysis();
		out.name = name;
		out.K = K;
		out.seq = seq;
		out.pity = meta != null ? meta.pity : 0;
		// copies and slot hits
		int O = m.copies(name);
		int unk = m.unknown(name);
		Integer H = null;
		List<String> members = null;
		List<Integer> knownAll = m.known(name);
		if (seq != null)
		{
			members = new ArrayList<>();
			for (Row r : slotMembers(boss, seq.slot))
			{
				members.add(r.name);
			}
			H = slotHits(m, boss, seq.slot);
			knownAll = new ArrayList<>();
			unk = 0;
			for (String n : members)
			{
				knownAll.addAll(m.known(n));
				unk += m.unknown(n);
			}
			Collections.sort(knownAll);
		}
		out.O = O;
		out.unknown = unk;
		out.hits = H;
		// dynamic "once" detection: probability with the item owned
		double pOwned = m.pAt(name, K + 1, 1);
		double pUn = m.pAt(name, K + 1, 0);
		out.once = pUn > 0 && pOwned == 0 && seq == null;
		out.pNext = m.pNext(name);
		out.collected = out.once && O > 0;
		// number of hits needed for the next copy
		int d = 1;
		if (seq != null)
		{
			int l0 = seq.len;
			d = (((seq.n - 1 - H) % l0) + l0) % l0 + 1;
		}
		out.need = d;
		final int dd = d;
		// career
		int lastKnown = knownAll.isEmpty() ? 0 : knownAll.get(knownAll.size() - 1);
		final String runName = seq != null ? members.get(0) : name;
		final List<Run> allRuns = K > 0 ? m.runsFor(runName, 1, K) : new ArrayList<Run>();
		out.expected = null;
		out.pct = null;
		if (K > 0)
		{
			java.util.function.IntToDoubleFunction needHits = mm -> mm <= 0 ? 0 : (seq != null ? seq.n + (mm - 1) * seq.len : mm);
			java.util.function.IntToDoubleFunction ge = mm -> mm <= 0 ? 1 : atLeast((int) needHits.applyAsDouble(mm), allRuns);
			if (out.once && O > 0)
			{
				List<Integer> kn = m.known(name);
				if (!kn.isEmpty())
				{
					int k1 = kn.get(0);
					List<Run> r1 = m.runsFor(name, 1, k1 - 1);
					double pk = m.pAt(name, k1, 0);
					double sv = Math.exp(logSurv(r1));
					out.pct = sv * (1 - pk) + 0.5 * sv * pk; // P(T>k1) + 1/2 P(T=k1): first-passage mid-p
				}
				out.expected = sumP(allRuns);
			}
			else
			{
				out.pct = 1 - 0.5 * (ge.applyAsDouble(O) + ge.applyAsDouble(O + 1));
				out.another = ge.applyAsDouble(O + 1);
				if (seq != null)
				{
					double e = 0;
					for (int mm = 1; mm <= O + 12; mm++)
					{
						e += ge.applyAsDouble(mm);
					}
					out.expected = e;
				}
				else
				{
					out.expected = sumP(allRuns);
				}
			}
			out.exceed = ge.applyAsDouble(O); // P(at least as many as you have)
			out.cum = ge.applyAsDouble(1); // P(at least one over all your kills, whenever your drops came): never resets
		}
		out.label = luckLabel(out.pct);
		// progress meter: kills since the last receipt (hit of the slot for sequence items)
		out.streakFrom = lastKnown;
		out.streak = Math.max(0, K - lastKnown);
		out.streakKnown = !knownAll.isEmpty() || unk == 0;
		if (out.collected)
		{
			out.meter = 1;
		}
		else
		{
			List<Run> sr = out.streak > 0 ? m.runsFor(runName, lastKnown + 1, K) : new ArrayList<Run>();
			out.meter = out.streak > 0 ? atLeast(dd, sr) : 0;
		}
		// forward looking
		if (!out.collected)
		{
			int[] ns = {win, 10, 100, 500, 1000};
			for (int n : ns)
			{
				if (!out.fwd.containsKey(n))
				{
					out.fwd.put(n, atLeast(dd, m.runsFor(runName, K + 1, K + n)));
				}
			}
			out.kto = new LinkedHashMap<>();
			for (double c : new double[] {0.5, 0.9, 0.99})
			{
				out.kto.put(c, killsTo(m, runName, dd, c, K));
			}
		}
		out.window = win;
		return out;
	}

	// ------------------------------------------------------------------ "any unique" synthetic item
	public static final class AnyUnique
	{
		public int O;
		public double expected;
		public double pct;
		public Label label;
		public double meter;
		public double cum;
		/**
		 * P(at least one more of these than the player has, from all their kills); see {@link ItemAnalysis#another}.
		 */
		public double another;
		public int streak;
		/**
		 * False when the player has uniques but none with a kill number (see {@link ItemAnalysis#streakKnown}).
		 */
		public boolean streakKnown = true;
		public final Map<Integer, Double> fwd = new LinkedHashMap<>();
		public int window;
		public double pNext;
		public int events;
	}

	/**
	 * One event per kill: "at least one of these items drops".  Computed inside the drop-table maths so items that cannot drop together
	 * (one table roll gives one item) are not treated as independent.  A sequence slot (the vestige) is one event for all its members.
	 */
	public static AnyUnique anyUnique(Model m, List<String> names, int window)
	{
		final Boss boss = m.boss;
		final int K = m.K;
		final int win = window > 0 ? window : 50;
		Map<String, ItemMeta> meta = boss.meta();
		Set<String> seen = new LinkedHashSet<>();
		List<String> evs = new ArrayList<>();
		// an item that only drops from a follow table (Sire's Font of Consumption, rolled once per Unsired) is part of its source's event
		Map<String, List<String>> fm = Engine.followMap(boss);
		Set<String> nset = new LinkedHashSet<>(names);
		Map<String, List<String>> kids = new HashMap<>();
		for (String n : names)
		{
			List<String> fs = fm.get(n);
			if (fs != null)
			{
				for (String f : fs)
				{
					if (nset.contains(f))
					{
						kids.computeIfAbsent(f, k -> new ArrayList<>()).add(n);
					}
				}
			}
		}
		for (String n : names)
		{
			ItemMeta mt = meta.get(n);
			if (mt == null || isKid(fm, nset, n))
			{
				continue;
			}
			if (mt.seq != null)
			{
				if (seen.contains(mt.seq.slot))
				{
					continue;
				}
				seen.add(mt.seq.slot);
			}
			evs.add(n);
		}
		if (evs.isEmpty() || K <= 0)
		{
			return null;
		}
		// O = kills that gave at least one of these items: copies on the same kill count once, copies with no kill number count one each,
		// and a slot's unlogged earlier hits are filled in
		int lastKnown = 0;
		int unk = 0;
		int extra = 0;
		Set<String> slots = new LinkedHashSet<>();
		Set<Integer> kcs = new LinkedHashSet<>();
		for (String n : names)
		{
			ItemMeta mt = meta.get(n);
			if (mt == null)
			{
				continue;
			}
			if (mt.seq != null)
			{
				if (slots.contains(mt.seq.slot))
				{
					continue;
				}
				slots.add(mt.seq.slot);
				int sumc = 0;
				for (Row r : slotMembers(boss, mt.seq.slot))
				{
					lastKnown = noteKnown(m, r.name, kcs, lastKnown);
					unk += m.unknown(r.name);
					sumc += m.copies(r.name);
				}
				extra += Math.max(0, slotHits(m, boss, mt.seq.slot) - sumc);
			}
			else
			{
				lastKnown = noteKnown(m, n, kcs, lastKnown);
				if (isKid(fm, nset, n))
				{
					continue;
				}
				int u = m.unknown(n);
				List<String> ks = kids.get(n);
				if (ks != null)
				{
					int t = 0;
					for (String k : ks)
					{
						t += m.unknown(k); // each Unsired gives one follow-table roll
					}
					u = Math.max(u, t);
				}
				unk += u;
			}
		}
		AnyUnique out = new AnyUnique();
		out.O = kcs.size() + unk + extra;
		List<Run> runsAll = m.runsForAny(evs, 1, K);
		out.pct = 1 - 0.5 * (atLeast(out.O, runsAll) + atLeast(out.O + 1, runsAll));
		List<Run> sr = K - lastKnown > 0 ? m.runsForAny(evs, lastKnown + 1, K) : new ArrayList<Run>();
		out.meter = K - lastKnown > 0 ? atLeast(1, sr) : 0;
		out.cum = atLeast(1, runsAll);
		out.another = atLeast(out.O + 1, runsAll);
		int[] ns = {win, 10, 100, 500};
		for (int n : ns)
		{
			out.fwd.put(n, atLeast(1, m.runsForAny(evs, K + 1, K + n)));
		}
		out.pNext = m.pAtAny(evs, K + 1);
		out.expected = sumP(runsAll);
		out.label = luckLabel(out.pct);
		out.streak = K - lastKnown;
		out.streakKnown = !kcs.isEmpty() || unk == 0;
		out.window = win;
		out.events = evs.size();
		return out;
	}

	private static boolean isKid(Map<String, List<String>> fm, Set<String> nset, String n)
	{
		List<String> fs = fm.get(n);
		if (fs == null)
		{
			return false;
		}
		for (String f : fs)
		{
			if (nset.contains(f))
			{
				return true;
			}
		}
		return false;
	}

	private static int noteKnown(Model m, String n, Set<Integer> kcs, int lastKnown)
	{
		List<Integer> ks = m.known(n);
		kcs.addAll(ks);
		if (!ks.isEmpty())
		{
			return Math.max(lastKnown, ks.get(ks.size() - 1));
		}
		return lastKnown;
	}

	// ------------------------------------------------------------------ pooled item (several bosses drop it)
	public static final class PoolMember
	{
		public final Model m;
		public final int snapKc;

		public PoolMember(Model m, int snapKc)
		{
			this.m = m;
			this.snapKc = snapKc;
		}
	}

	public static final class PoolPer
	{
		public String id;
		public String name;
		public int K;
		public int streak;
		public int copies;
	}

	public static final class Pool
	{
		public String name;
		public int O;
		public double expected;
		public double pct;
		public Label label;
		public double meter;
		public double cum;
		/**
		 * P(at least one more copy than the player has, over all these bosses' kills); see {@link ItemAnalysis#another}.
		 */
		public double another;
		public long streak;
		/**
		 * False when the player has copies but none with a kill number (see {@link ItemAnalysis#streakKnown}).
		 */
		public boolean streakKnown = true;
		public long kills;
		public final List<PoolPer> per = new ArrayList<>();
		public int window;
	}

	public static Pool analysePool(List<PoolMember> members, String name, int window)
	{
		final int win = window > 0 ? window : 50;
		int O = 0;
		int unknown = 0;
		boolean anyKnown = false;
		double expected = 0;
		List<List<Run>> runsAll = new ArrayList<>();
		List<List<Run>> sr = new ArrayList<>();
		List<PoolPer> per = new ArrayList<>();
		for (PoolMember pm : members)
		{
			Model m = pm.m;
			int K = m.K;
			O += m.copies(name);
			unknown += m.unknown(name);
			anyKnown |= !m.known(name).isEmpty();
			List<Run> ra = K > 0 ? m.runsFor(name, 1, K) : new ArrayList<Run>();
			runsAll.add(ra);
			expected += sumP(ra);
			int from = Math.min(K, Math.max(0, pm.snapKc));
			List<Run> rs = K - from > 0 ? m.runsFor(name, from + 1, K) : new ArrayList<Run>();
			sr.add(rs);
			PoolPer pp = new PoolPer();
			pp.id = m.boss.id;
			pp.name = m.boss.name;
			pp.K = K;
			pp.streak = K - from;
			pp.copies = m.copies(name);
			per.add(pp);
		}
		List<Run> all = mergeRuns(runsAll);
		List<Run> st = mergeRuns(sr);
		long kills = countKills(all);
		if (kills == 0)
		{
			return null;
		}
		Pool out = new Pool();
		out.name = name;
		out.O = O;
		out.expected = expected;
		out.pct = 1 - 0.5 * (atLeast(O, all) + atLeast(O + 1, all));
		out.label = luckLabel(out.pct);
		out.meter = atLeast(1, st);
		out.cum = atLeast(1, all);
		out.another = atLeast(O + 1, all);
		out.streak = countKills(st);
		out.streakKnown = anyKnown || unknown == 0;
		out.kills = kills;
		out.per.addAll(per);
		out.window = win;
		return out;
	}

	/**
	 * Convenience for tests: the chance list as plain strings.
	 */
	static String describe(List<Run> runs)
	{
		return Arrays.toString(runs.stream().map(r -> r.n + "x" + r.p).toArray());
	}
}

package com.dropluckledger.history;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Everything gathered from the game's own records, before it is matched against the ledger.
 */
public final class HistoryInput
{
	/**
	 * Copies of an item the player owns.
	 */
	public static final class Owned
	{
		/**
		 * The boss, when the source says exactly which one (the loot tracker does); otherwise null.
		 */
		public final String bossId;
		/**
		 * Collection log page the item was seen on, when the source has pages; otherwise null.
		 */
		public final String page;
		public final String item;
		public final int count;

		Owned(String bossId, String page, String item, int count)
		{
			this.bossId = bossId;
			this.page = page;
			this.item = item;
			this.count = count;
		}
	}

	/**
	 * Activity name as the game or hiscores print it, to the kill count (the largest if several sources have one).
	 */
	public final Map<String, Integer> kc = new LinkedHashMap<>();
	public final List<Owned> owned = new ArrayList<>();
	/**
	 * Where the data came from, for display.
	 */
	public final Set<String> sources = new LinkedHashSet<>();

	public void addKc(String name, int n, String source)
	{
		if (name == null || n <= 0)
		{
			return;
		}
		kc.merge(name, n, Math::max);
		sources.add(source);
	}

	public void addOwned(String bossId, String page, String item, int count, String source)
	{
		if (item == null || count <= 0)
		{
			return;
		}
		owned.add(new Owned(bossId, page, item, count));
		sources.add(source);
	}

	public boolean isEmpty()
	{
		return kc.isEmpty() && owned.isEmpty();
	}
}

package com.dropluckledger.history;

import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.BossIndex.KcLabel;
import com.dropluckledger.capture.Names;
import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Engine;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.ledger.Period;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Works out what the game's records add to the ledger, and applies it.
 * <p>
 * No game record says which kill an old drop came on, so history can only bring in kill counts and "owned copies"
 * (items with an unknown kill number).  Running it twice, or after the plugin has seen the same drops live, adds nothing
 * twice: copies already in the ledger are subtracted, and kill counts only ever go up.
 */
public final class HistoryPlanner
{
	/**
	 * Same cap as the web app: more copies than this is almost certainly a mistake in the source.  A boss with more kills than
	 * this allows as many copies as it has kills.
	 */
	public static final int MAX_COPIES = 200;

	/**
	 * A kill count to set.
	 */
	public static final class KcRow
	{
		public final String bossId;
		public final String name;
		public final int cur;
		public final int to;
		/**
		 * Kill-count label (as in the boss data) to the count the source had.
		 */
		public final Map<String, Integer> labels;
		public boolean on;

		KcRow(String bossId, String name, int cur, int to, Map<String, Integer> labels)
		{
			this.bossId = bossId;
			this.name = name;
			this.cur = cur;
			this.to = to;
			this.labels = labels;
			this.on = to > cur;
		}
	}

	/**
	 * Copies (drops) of one item to add.
	 */
	public static final class ItemRow
	{
		public final String bossId;
		public final String bossName;
		public final String item;
		/**
		 * How many drops the source stands for.
		 */
		public final int want;
		public final int have;
		public final int add;
		/**
		 * Copies an earlier import added with no kill number that the source does not support, because they counted every item of a
		 * stack as a drop.  Only set for rows worked out from a quantity.
		 */
		public final int remove;
		/**
		 * The most drops of this item the ledger takes for the boss.
		 */
		final int cap;
		/**
		 * Several bosses drop this item and the source did not say which: it went to the one with the most kills.
		 */
		public final boolean assumed;
		/**
		 * How many of the item the source said were received, when that is not the number of drops (a stackable item such as bolt
		 * racks arrives several at a time, so {@link #want} is worked out from this); 0 when {@link #want} is exactly what the
		 * source said.
		 */
		public final int quantity;
		public boolean on;

		ItemRow(String bossId, String bossName, String item, int want, int have, int imported, int cap, boolean assumed, int quantity)
		{
			this.bossId = bossId;
			this.bossName = bossName;
			this.item = item;
			this.want = want;
			this.have = have;
			this.cap = cap;
			this.add = Math.max(0, Math.min(want, cap) - have);
			this.remove = quantity > 0 ? Math.min(imported, Math.max(0, have - Math.min(want, cap))) : 0;
			this.assumed = assumed;
			this.quantity = quantity;
			this.on = add > 0 || remove > 0;
		}

		/**
		 * True when {@link #want} is an estimate from a received quantity rather than a count of drops.
		 */
		public boolean estimated()
		{
			return quantity > 0;
		}
	}

	public static final class Plan
	{
		public final List<KcRow> kc = new ArrayList<>();
		public final List<ItemRow> items = new ArrayList<>();
		/**
		 * Kill-count entries that are not a boss in the ledger ("name count").
		 */
		public final List<String> kcSkipped = new ArrayList<>();
		/**
		 * Item names that are not tracked.
		 */
		public final List<String> itemsMissing = new ArrayList<>();
		public int itemsTotal;
		public final Set<String> sources = new LinkedHashSet<>();

		public int kcToApply()
		{
			int n = 0;
			for (KcRow r : kc)
			{
				if (r.on)
				{
					n++;
				}
			}
			return n;
		}

		public int itemRowsToApply()
		{
			int n = 0;
			for (ItemRow r : items)
			{
				if (r.on && (r.add > 0 || r.remove > 0))
				{
					n++;
				}
			}
			return n;
		}

		public int copiesToAdd()
		{
			int n = 0;
			for (ItemRow r : items)
			{
				if (r.on)
				{
					n += r.add;
				}
			}
			return n;
		}

		/**
		 * Copies of an earlier import that the rows ticked would take back.
		 */
		public int copiesToRemove()
		{
			int n = 0;
			for (ItemRow r : items)
			{
				if (r.on)
				{
					n += r.remove;
				}
			}
			return n;
		}

		public boolean isEmpty()
		{
			return kcToApply() == 0 && copiesToAdd() == 0 && copiesToRemove() == 0;
		}
	}

	private final Ledger ledger;
	private final Data data;
	private final BossIndex index;
	private final Map<String, List<String>> logIndex;
	private final Map<String, String> itemKey = new HashMap<>();

	public HistoryPlanner(Ledger ledger, BossIndex index)
	{
		this.ledger = ledger;
		this.data = ledger.data();
		this.index = index;
		this.logIndex = Catalog.logIndex(data);
		for (String n : logIndex.keySet())
		{
			itemKey.putIfAbsent(Names.flat(n), n);
		}
	}

	public Plan plan(HistoryInput in)
	{
		Plan plan = new Plan();
		plan.sources.addAll(in.sources);

		// ---- kill counts: one row per boss, summing its modes
		Map<String, Map<String, Integer>> byBoss = new LinkedHashMap<>();
		for (Map.Entry<String, Integer> e : in.kc.entrySet())
		{
			KcLabel kl = index.kc(e.getKey());
			if (kl == null)
			{
				plan.kcSkipped.add(e.getKey() + " " + e.getValue());
				continue;
			}
			byBoss.computeIfAbsent(kl.bossId, k -> new LinkedHashMap<>()).merge(kl.label, e.getValue(), Math::max);
		}
		Map<String, Integer> kcTo = new HashMap<>();
		for (Map.Entry<String, Map<String, Integer>> e : byBoss.entrySet())
		{
			int sum = 0;
			for (int v : e.getValue().values())
			{
				sum += v;
			}
			kcTo.put(e.getKey(), sum);
			plan.kc.add(new KcRow(e.getKey(), data.boss(e.getKey()).name, ledger.kc(e.getKey()), sum, e.getValue()));
		}
		plan.kc.sort(Comparator.<KcRow>comparingInt(r -> -r.to).thenComparing(r -> r.name));

		// ---- owned copies
		Map<String, Integer> exact = new HashMap<>(); // bossId|item -> drops the source named a boss for
		Map<String, Integer> quantities = new HashMap<>(); // bossId|item -> the received quantity behind it, when that is not the drops
		Map<String, Integer> exactTotal = new HashMap<>(); // item -> the same over all bosses
		class Page
		{
			int n;
			final List<String> pages = new ArrayList<>();
		}
		Map<String, Page> perItem = new LinkedHashMap<>();
		LinkedHashSet<String> missing = new LinkedHashSet<>();
		for (HistoryInput.Owned o : in.owned)
		{
			plan.itemsTotal++;
			if (o.bossId != null)
			{
				Boss b = data.boss(o.bossId);
				String item = b == null ? null : index.item(o.bossId, o.item);
				if (item == null || !Catalog.defaultTracked(b).contains(item))
				{
					missing.add(o.item);
					continue;
				}
				int drops = Quantities.drops(b, item, o.count);
				String key = o.bossId + '|' + item;
				if (drops >= exact.getOrDefault(key, 0))
				{
					exact.put(key, drops);
					if (drops != o.count)
					{
						quantities.put(key, o.count);
					}
					else
					{
						quantities.remove(key);
					}
				}
				continue;
			}
			String item = itemKey.get(Names.flat(o.item));
			if (item == null)
			{
				missing.add(o.item);
				continue;
			}
			Page p = perItem.computeIfAbsent(item, k -> new Page());
			p.n = Math.max(p.n, o.count); // a received quantity, not yet drops
			if (o.page != null)
			{
				p.pages.add(Names.norm(o.page));
			}
		}
		for (Map.Entry<String, Integer> e : exact.entrySet())
		{
			exactTotal.merge(e.getKey().substring(e.getKey().indexOf('|') + 1), e.getValue(), Integer::sum);
		}
		Map<String, int[]> want = new LinkedHashMap<>(); // bossId|item -> {copies, assumed}
		for (Map.Entry<String, Integer> e : exact.entrySet())
		{
			want.put(e.getKey(), new int[]{e.getValue(), 0});
		}
		for (Map.Entry<String, Page> e : perItem.entrySet())
		{
			String item = e.getKey();
			Page p = e.getValue();
			List<String> cands = logIndex.get(item);
			String id;
			boolean assumed = false;
			if (cands.size() == 1)
			{
				id = cands.get(0);
			}
			else
			{
				List<String> byPage = new ArrayList<>();
				for (String c : cands)
				{
					String bn = Names.norm(data.boss(c).name);
					for (String pg : p.pages)
					{
						if (pg.contains(bn) && !byPage.contains(c))
						{
							byPage.add(c);
						}
					}
				}
				if (byPage.size() == 1)
				{
					id = byPage.get(0);
				}
				else
				{
					List<String> sorted = new ArrayList<>(cands);
					sorted.sort(Comparator.<String>comparingInt(c -> -(kcTo.containsKey(c) ? kcTo.get(c) : ledger.kc(c))));
					id = sorted.get(0);
					assumed = true;
				}
			}
			int drops = Quantities.drops(data.boss(id), item, p.n);
			int n = drops - exactTotal.getOrDefault(item, 0);
			if (n <= 0)
			{
				continue;
			}
			String key = id + '|' + item;
			if (drops != p.n)
			{
				quantities.merge(key, p.n, Integer::sum);
			}
			int[] cur = want.get(key);
			if (cur == null)
			{
				want.put(key, new int[]{n, assumed ? 1 : 0});
			}
			else
			{
				cur[0] += n;
				cur[1] = assumed ? 1 : cur[1];
			}
		}
		for (Map.Entry<String, int[]> e : want.entrySet())
		{
			String id = e.getKey().substring(0, e.getKey().indexOf('|'));
			String item = e.getKey().substring(e.getKey().indexOf('|') + 1);
			BossState st = ledger.copyOf(id);
			plan.items.add(new ItemRow(id, data.boss(id).name, item, e.getValue()[0], st.copies(item), st.importedUnknown(item), copyCap(id, kcTo),
				e.getValue()[1] != 0, quantities.getOrDefault(e.getKey(), 0)));
		}
		plan.items.sort(Comparator.<ItemRow, String>comparing(r -> r.bossName, String.CASE_INSENSITIVE_ORDER).thenComparing(r -> r.item));
		plan.itemsMissing.addAll(missing);
		return plan;
	}

	/**
	 * The most copies of an item the ledger takes for a boss: {@link #MAX_COPIES}, or the number of kills when there are more.
	 */
	private int copyCap(String bossId, Map<String, Integer> kcTo)
	{
		Integer planned = kcTo.get(bossId);
		return Math.max(MAX_COPIES, Math.max(planned == null ? 0 : planned, ledger.kc(bossId)));
	}

	/**
	 * Applies the rows that are switched on.
	 *
	 * @return {kill counts set, copies added, copies taken back}
	 */
	public int[] apply(Plan plan)
	{
		int kcSet = 0;
		int copies = 0;
		int removed = 0;
		for (KcRow r : plan.kc)
		{
			if (!r.on)
			{
				continue;
			}
			final Boss boss = data.boss(r.bossId);
			ledger.update(r.bossId, s ->
			{
				boolean fresh = s.kc == 0 && s.drops.isEmpty() && s.segs.size() == 1;
				if (fresh)
				{
					layOutModes(s, boss, r);
				}
				for (Map.Entry<String, Integer> e : r.labels.entrySet())
				{
					s.labels().merge(e.getKey(), e.getValue(), Math::max);
				}
				s.kc = Math.max(s.kc, Math.max(r.to, s.maxDropKc()));
				s.prov = null;
				s.provDrops = null;
				return null;
			});
			kcSet++;
		}
		for (ItemRow r : plan.items)
		{
			if (r.on && (r.add > 0 || r.remove > 0))
			{
				// re-check against the ledger as it is now, in case something changed since the plan was made
				BossState st = ledger.copyOf(r.bossId);
				int have = st.copies(r.item);
				int target = Math.min(r.want, r.cap);
				copies += ledger.addOwned(r.bossId, r.item, Math.max(0, target - have));
				if (r.remove > 0)
				{
					removed += ledger.removeOwned(r.bossId, r.item, Math.min(st.importedUnknown(r.item), Math.max(0, have - target)));
				}
			}
		}
		return new int[]{kcSet, copies, removed};
	}

	/**
	 * For a boss with no kills yet: the settings of its kill-count labels become periods.  With several labels (normal and
	 * challenge mode, awakened and normal ...) the kills of each label form one block of kills with that label's settings,
	 * in the order of the boss data.  The real order is unknown, but the totals per mode are right.
	 */
	private static void layOutModes(BossState s, Boss boss, KcRow r)
	{
		Map<String, Object> defaults = Engine.defaultParams(boss);
		if (r.labels.size() < 2)
		{
			Map<String, Object> patch = BossIndex.patchOf(boss, r.labels.keySet().iterator().next());
			if (!patch.isEmpty())
			{
				Ledger.applyParamsLocked(s, 1, patch, defaults);
			}
			return;
		}
		List<Period> periods = new ArrayList<>();
		int from = 1;
		for (String label : boss.kc)
		{
			Integer n = r.labels.get(label);
			if (n == null)
			{
				continue;
			}
			Map<String, Object> params = new LinkedHashMap<>(s.segs.get(0).params);
			params.putAll(BossIndex.patchOf(boss, label));
			if (periods.isEmpty() || !samePeriod(periods.get(periods.size() - 1).params, params, defaults))
			{
				periods.add(new Period(from, params));
			}
			from += n;
		}
		if (!periods.isEmpty())
		{
			s.segs = periods;
		}
	}

	private static boolean samePeriod(Map<String, Object> a, Map<String, Object> b, Map<String, Object> defaults)
	{
		Set<String> keys = new LinkedHashSet<>(a.keySet());
		keys.addAll(b.keySet());
		for (String k : keys)
		{
			Object x = a.containsKey(k) ? a.get(k) : defaults.get(k);
			Object y = b.containsKey(k) ? b.get(k) : defaults.get(k);
			if (x instanceof Number && y instanceof Number)
			{
				if (((Number) x).doubleValue() != ((Number) y).doubleValue())
				{
					return false;
				}
			}
			else if (!String.valueOf(x).equals(String.valueOf(y)))
			{
				return false;
			}
		}
		return true;
	}
}

package com.dropluckledger.history;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Row;

/**
 * Turns "how many of an item the game says you have" into "how many times it dropped".
 * <p>
 * Stackable items drop several at a time (a Barrows chest gives 35-40 bolt racks, an Amoxliatl kill 2-20 frozen tears), but
 * the Loot Tracker and the Collection Log only keep the running total.  Counting that total as separate drops would make
 * the player look absurdly lucky, so it is divided by the usual amount per drop.  The result is an estimate; for items that
 * always drop one at a time it is exact.
 */
public final class Quantities
{
	private Quantities()
	{
	}

	/**
	 * The usual number of the item in one drop from the boss: the average of the amounts on its drop table, weighted by how
	 * likely each row is; 1 when the table gives no amount.
	 */
	public static double perDrop(Boss boss, String item)
	{
		double sum = 0;
		double weights = 0;
		boolean allHaveRates = true;
		for (Row r : boss.allRows())
		{
			if (item.equals(r.name) && parse(r.qty) != null && !(r.p != null && r.p > 0))
			{
				allHaveRates = false;
			}
		}
		for (Row r : boss.allRows())
		{
			Double q = item.equals(r.name) ? parse(r.qty) : null;
			if (q == null)
			{
				continue;
			}
			double w = allHaveRates ? r.p : 1;
			sum += q * w;
			weights += w;
		}
		return weights > 0 ? Math.max(1, sum / weights) : 1;
	}

	/**
	 * How many drops a received total stands for.
	 *
	 * @param total how many of the item the game says were received
	 */
	public static int drops(Boss boss, String item, int total)
	{
		if (total <= 0)
		{
			return 0;
		}
		double each = perDrop(boss, item);
		if (each < 1.05)
		{
			return total;
		}
		return (int) Math.max(1, Math.round(total / each));
	}

	/**
	 * The amount a drop-table cell stands for: "3" is 3, "35-40" is 37.5, "11;17" (without and with a perfect kill) is 11, the
	 * trailing "n" of a noted item and the thousands separators are ignored.  Null when there is no amount.
	 */
	static Double parse(String qty)
	{
		if (qty == null)
		{
			return null;
		}
		String s = qty.trim().replace(",", "");
		int semicolon = s.indexOf(';');
		if (semicolon >= 0)
		{
			s = s.substring(0, semicolon);
		}
		s = s.replaceAll("[^0-9-]", "");
		if (s.isEmpty() || s.startsWith("-"))
		{
			return null;
		}
		try
		{
			int dash = s.indexOf('-');
			if (dash < 0)
			{
				return Double.valueOf(Long.parseLong(s));
			}
			double lo = Long.parseLong(s.substring(0, dash));
			double hi = Long.parseLong(s.substring(dash + 1));
			return (lo + hi) / 2;
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.dropluckledger.ledger;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Everything the ledger knows about one boss.  The first six fields are the same as the web app's backup format,
 * the rest belong to the plugin (they are ignored by the web app).
 */
public final class BossState
{
	public int kc;
	public List<Period> segs = new ArrayList<>();
	public List<Drop> drops = new ArrayList<>();
	public List<String> track = new ArrayList<>();
	public List<String> hide = new ArrayList<>();
	public long u;

	/**
	 * Plugin only: the last kill count the game showed for each kill-count label of the boss (for example the normal and
	 * the challenge mode count of a raid).  The ledger kill count is their sum plus any kills added by hand.
	 */
	public Map<String, Integer> labelKc;
	/**
	 * Plugin only: kills counted from a loot event before the game's kill-count message for them arrived.
	 */
	public Integer prov;
	/**
	 * Plugin only: ids of the drops recorded on those kills.
	 */
	public List<String> provDrops;

	public BossState()
	{
		segs.add(new Period(1, new LinkedHashMap<>()));
	}

	public int maxDropKc()
	{
		int m = 0;
		for (Drop d : drops)
		{
			if (d.kc != null && d.kc > m)
			{
				m = d.kc;
			}
		}
		return m;
	}

	public int copies(String item)
	{
		int n = 0;
		for (Drop d : drops)
		{
			if (d.item.equals(item))
			{
				n++;
			}
		}
		return n;
	}

	/**
	 * Copies of an item that came from a history import and have no kill number.
	 */
	public int importedUnknown(String item)
	{
		int n = 0;
		for (Drop d : drops)
		{
			if (d.item.equals(item) && d.kc == null && Drop.SRC_IMPORT.equals(d.src))
			{
				n++;
			}
		}
		return n;
	}

	public int provisional()
	{
		return prov == null ? 0 : prov;
	}

	public Map<String, Integer> labels()
	{
		if (labelKc == null)
		{
			labelKc = new LinkedHashMap<>();
		}
		return labelKc;
	}

	public int labelSum(String except)
	{
		int s = 0;
		if (labelKc != null)
		{
			for (Map.Entry<String, Integer> e : labelKc.entrySet())
			{
				if (!e.getKey().equals(except))
				{
					s += e.getValue();
				}
			}
		}
		return s;
	}

	public Period lastPeriod()
	{
		return segs.get(segs.size() - 1);
	}

	/**
	 * The settings in force at a kill number (the latest period starting at or before it).
	 */
	public Map<String, Object> paramsAt(int killNo)
	{
		Period best = segs.get(0);
		for (Period p : segs)
		{
			if (p.from <= killNo && p.from >= best.from)
			{
				best = p;
			}
		}
		return best.params;
	}

	public BossState copy()
	{
		BossState b = new BossState();
		b.kc = kc;
		b.segs = new ArrayList<>();
		for (Period p : segs)
		{
			b.segs.add(p.copy());
		}
		b.drops = new ArrayList<>();
		for (Drop d : drops)
		{
			b.drops.add(d.copy());
		}
		b.track = new ArrayList<>(track);
		b.hide = new ArrayList<>(hide);
		b.u = u;
		b.labelKc = labelKc == null ? null : new LinkedHashMap<>(labelKc);
		b.prov = prov;
		b.provDrops = provDrops == null ? null : new ArrayList<>(provDrops);
		return b;
	}
}

package com.dropluckledger.ledger;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One copy of an item the player received.
 */
public final class Drop
{
	/**
	 * Came from the collection log or loot tracker history: the kill number is unknown.
	 */
	public static final String SRC_IMPORT = "import";
	/**
	 * Seen in game while the plugin was running.
	 */
	public static final String SRC_LIVE = "live";
	/**
	 * Typed in by the player.
	 */
	public static final String SRC_MANUAL = "manual";

	public String id;
	public String item;
	/**
	 * Ledger kill number it came on, null when unknown.
	 */
	public Integer kc;
	public int qty = 1;
	/**
	 * Epoch milliseconds when it was recorded.
	 */
	public long t;
	/**
	 * For items several bosses drop: the other bosses' kill counts when this one dropped.
	 */
	public Map<String, Integer> snap;
	public String src;

	public Drop copy()
	{
		Drop d = new Drop();
		d.id = id;
		d.item = item;
		d.kc = kc;
		d.qty = qty;
		d.t = t;
		d.snap = snap == null ? null : new LinkedHashMap<>(snap);
		d.src = src;
		return d;
	}
}

package com.dropluckledger.ledger;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * What the plugin has read from the game's own records (Boss Kill Log, collection log, hiscores) and not yet turned into
 * ledger entries.  Kept in the ledger file so a page read one day is still there the next.
 */
public final class HistoryStage
{
	/**
	 * Activity name as the game or hiscores show it, to the kill count.
	 */
	public final Map<String, Integer> kc = new LinkedHashMap<>();
	/**
	 * Collection log page title, to item name, to number of copies.
	 */
	public final Map<String, Map<String, Integer>> log = new LinkedHashMap<>();
	public long kcTime;
	public long logTime;

	public boolean isEmpty()
	{
		return kc.isEmpty() && log.isEmpty();
	}

	public HistoryStage copy()
	{
		HistoryStage h = new HistoryStage();
		h.kc.putAll(kc);
		for (Map.Entry<String, Map<String, Integer>> e : log.entrySet())
		{
			h.log.put(e.getKey(), new LinkedHashMap<>(e.getValue()));
		}
		h.kcTime = kcTime;
		h.logTime = logTime;
		return h;
	}
}

package com.dropluckledger.ledger;

import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Luck;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Function;
import java.util.function.LongSupplier;

/**
 * The player's kill counts, drops and boss settings.  All access goes through this class, which is safe to use from any
 * thread: every change happens under one lock, and readers get copies.
 */
public final class Ledger
{
	/**
	 * Told after every change.  Called on the thread that made the change, outside the lock; keep it quick.
	 */
	public interface Listener
	{
		/**
		 * @param bossId the boss that changed, or null when the change is not about one boss (settings, restore)
		 */
		void changed(String bossId);
	}

	private final Data data;
	private final LongSupplier clock;
	private final Map<String, BossState> bosses = new LinkedHashMap<>();
	private final Map<String, Long> revisions = new HashMap<>();
	private final CopyOnWriteArrayList<Listener> listeners = new CopyOnWriteArrayList<>();
	private final Random rnd = new Random();
	private Prefs prefs = new Prefs();
	private HistoryStage history = new HistoryStage();
	private long revision;

	public Ledger(Data data)
	{
		this(data, System::currentTimeMillis);
	}

	public Ledger(Data data, LongSupplier clock)
	{
		this.data = data;
		this.clock = clock;
	}

	public Data data()
	{
		return data;
	}

	public long now()
	{
		return clock.getAsLong();
	}

	public void addListener(Listener l)
	{
		listeners.add(l);
	}

	public void removeListener(Listener l)
	{
		listeners.remove(l);
	}

	private void fire(String bossId)
	{
		for (Listener l : listeners)
		{
			l.changed(bossId);
		}
	}

	private void touch(String id)
	{
		revision++;
		if (id != null)
		{
			revisions.merge(id, 1L, Long::sum);
			BossState b = bosses.get(id);
			if (b != null)
			{
				b.u = now();
			}
		}
	}

	/**
	 * Changes every time anything changes.
	 */
	public synchronized long revision()
	{
		return revision;
	}

	/**
	 * Changes every time the given boss changes (or the settings that affect all bosses).
	 */
	public synchronized long revision(String id)
	{
		return revisions.getOrDefault(id, 0L) + globalRev;
	}

	private long globalRev;

	// ------------------------------------------------------------------ reading

	public synchronized boolean hasBoss(String id)
	{
		return bosses.containsKey(id);
	}

	public synchronized boolean hasData(String id)
	{
		BossState b = bosses.get(id);
		return b != null && (b.kc > 0 || !b.drops.isEmpty());
	}

	/**
	 * Ids of the bosses with a kill count or a drop.
	 */
	public synchronized List<String> activeBosses()
	{
		List<String> out = new ArrayList<>();
		for (Boss b : Catalog.ordered(data))
		{
			if (hasData(b.id))
			{
				out.add(b.id);
			}
		}
		return out;
	}

	/**
	 * A copy of the boss state (a blank one when the boss has none yet).
	 */
	public synchronized BossState copyOf(String id)
	{
		BossState b = bosses.get(id);
		return b == null ? new BossState() : b.copy();
	}

	public synchronized int kc(String id)
	{
		BossState b = bosses.get(id);
		return b == null ? 0 : b.kc;
	}

	/**
	 * The state in the form the luck maths takes.
	 */
	public synchronized Luck.BossRecord record(String id)
	{
		BossState s = bosses.get(id);
		Luck.BossRecord r = new Luck.BossRecord();
		if (s == null)
		{
			return r;
		}
		r.kc = s.kc;
		for (Period p : s.segs)
		{
			r.segs.add(new Luck.Seg(p.from, new LinkedHashMap<>(p.params)));
		}
		for (Drop d : s.drops)
		{
			r.drops.add(new Luck.DropRec(d.item, d.kc));
		}
		return r;
	}

	public synchronized Map<String, Double> globals()
	{
		Map<String, Double> g = new HashMap<>();
		g.put("rowi", prefs.rowi != 0 ? 1.0 : 0.0);
		g.put("lq", prefs.lq != 0 ? 1.0 : 0.0);
		return g;
	}

	public synchronized Prefs prefs()
	{
		return prefs.copy();
	}

	/**
	 * A copy of what has been read from the game's own records so far.
	 */
	public synchronized HistoryStage history()
	{
		return history.copy();
	}

	/**
	 * Changes the staged history (the ledger itself is not touched).
	 */
	public void updateHistory(java.util.function.Consumer<HistoryStage> fn)
	{
		synchronized (this)
		{
			fn.accept(history);
			touch(null);
		}
		fire(null);
	}

	/**
	 * The settings in force for the next kill (the last period, over the boss defaults).
	 */
	public synchronized Map<String, Object> currentParams(String id)
	{
		Boss boss = data.boss(id);
		Map<String, Object> out = com.dropluckledger.engine.Engine.defaultParams(boss);
		BossState s = bosses.get(id);
		if (s != null)
		{
			out.putAll(s.lastPeriod().params);
		}
		return out;
	}

	/**
	 * Items shown for the boss: the default ones the player has not hidden, then any they added.
	 */
	public synchronized List<String> trackedNames(String id)
	{
		Boss boss = data.boss(id);
		if (boss == null)
		{
			return Collections.emptyList();
		}
		BossState s = bosses.get(id);
		Set<String> hide = s == null ? Collections.emptySet() : new LinkedHashSet<>(s.hide);
		List<String> out = new ArrayList<>();
		for (String n : Catalog.defaultTracked(boss))
		{
			if (!hide.contains(n))
			{
				out.add(n);
			}
		}
		if (s != null)
		{
			for (String n : s.track)
			{
				if (!out.contains(n) && boss.meta().containsKey(n))
				{
					out.add(n);
				}
			}
		}
		return out;
	}

	/**
	 * Changes one boss under the lock and tells the listeners.  The boss is created when it does not exist yet.
	 */
	public <T> T update(String id, Function<BossState, T> fn)
	{
		T out;
		synchronized (this)
		{
			BossState s = bosses.computeIfAbsent(id, k -> blank());
			out = fn.apply(s);
			touch(id);
		}
		fire(id);
		return out;
	}

	private BossState blank()
	{
		BossState b = new BossState();
		b.u = now();
		return b;
	}

	// ------------------------------------------------------------------ changes made by the player or by history

	public void setKc(String id, int kc)
	{
		update(id, s ->
		{
			s.kc = Math.max(s.maxDropKc(), Math.max(0, kc));
			s.prov = null;
			s.provDrops = null;
			return null;
		});
	}

	public void addKc(String id, int n)
	{
		update(id, s ->
		{
			s.kc = Math.max(s.maxDropKc(), Math.max(0, s.kc + n));
			return null;
		});
	}

	/**
	 * Logs a drop (the player's own entry, or one seen in game).
	 */
	public Drop logDrop(String id, String item, Integer kc, int qty, Map<String, Integer> snap, String src)
	{
		return update(id, s -> addDropLocked(id, s, item, kc, qty, snap, src));
	}

	/**
	 * Adds a drop to a boss the caller already holds through {@link #update}.
	 */
	public Drop addDropLocked(String id, BossState s, String item, Integer kc, int qty, Map<String, Integer> snap, String src)
	{
		Drop d = new Drop();
		d.id = newId();
		d.item = item;
		d.kc = kc == null ? null : Math.max(1, kc);
		d.qty = Math.max(1, qty);
		d.t = now();
		d.src = src;
		d.snap = snap == null || snap.isEmpty() ? null : new LinkedHashMap<>(snap);
		s.drops.add(d);
		if (d.kc != null && d.kc > s.kc)
		{
			s.kc = d.kc;
		}
		s.hide.remove(item);
		Boss boss = data.boss(id);
		if (boss != null && !Catalog.defaultTracked(boss).contains(item) && !s.track.contains(item))
		{
			s.track.add(item);
		}
		return d;
	}

	/**
	 * Changes a logged drop.  Returns false when there is no such drop.
	 */
	public boolean editDrop(String id, String dropId, String item, Integer kc, int qty, Map<String, Integer> snap)
	{
		return update(id, s ->
		{
			for (Drop d : s.drops)
			{
				if (d.id.equals(dropId))
				{
					d.item = item;
					d.kc = kc == null ? null : Math.max(1, kc);
					d.qty = Math.max(1, qty);
					d.snap = snap == null || snap.isEmpty() ? null : new LinkedHashMap<>(snap);
					if (d.src != null && !Drop.SRC_LIVE.equals(d.src))
					{
						d.src = Drop.SRC_MANUAL;
					}
					if (d.kc != null && d.kc > s.kc)
					{
						s.kc = d.kc;
					}
					s.hide.remove(item);
					Boss boss = data.boss(id);
					if (boss != null && !Catalog.defaultTracked(boss).contains(item) && !s.track.contains(item))
					{
						s.track.add(item);
					}
					return true;
				}
			}
			return false;
		});
	}

	public boolean deleteDrop(String id, String dropId)
	{
		return update(id, s ->
		{
			if (s.provDrops != null)
			{
				s.provDrops.remove(dropId);
			}
			return s.drops.removeIf(d -> d.id.equals(dropId));
		});
	}

	/**
	 * Changes a boss setting.  With newKillsOnly the change starts at the next kill; before that the earlier kills keep
	 * the old value (the web app calls this "new kills only").
	 */
	public void setParam(String id, String name, Object value, boolean newKillsOnly)
	{
		update(id, s ->
		{
			if (newKillsOnly && s.kc > 0)
			{
				int from = s.kc + 1;
				Period seg = null;
				for (Period p : s.segs)
				{
					if (p.from == from)
					{
						seg = p;
					}
				}
				if (seg == null)
				{
					Period prev = null;
					for (Period p : s.segs)
					{
						if (p.from < from)
						{
							prev = p;
						}
					}
					seg = new Period(from, prev == null ? null : prev.params);
					s.segs.add(seg);
					s.segs.sort((a, b) -> Integer.compare(a.from, b.from));
				}
				for (Period p : s.segs)
				{
					if (p.from >= from)
					{
						p.params.put(name, value);
					}
				}
			}
			else
			{
				for (Period p : s.segs)
				{
					p.params.put(name, value);
				}
			}
			return null;
		});
	}

	/**
	 * Merges all periods into one that has the latest settings.
	 */
	public void collapsePeriods(String id)
	{
		update(id, s ->
		{
			Period last = s.lastPeriod();
			s.segs = new ArrayList<>();
			s.segs.add(new Period(1, last.params));
			return null;
		});
	}

	/**
	 * Makes sure the settings that apply to the kill with this number include the given values (used when the game tells
	 * the plugin which mode the kill was in), for callers that already hold the boss under {@link #update}.  A new period
	 * starts at the kill when the settings differ.  Does nothing when a later period exists (the player has set things up
	 * by hand).
	 *
	 * @param defaults the boss's default settings, which apply where a period does not say (may be null)
	 */
	public static boolean applyParamsLocked(BossState s, int killNo, Map<String, Object> patch, Map<String, Object> defaults)
	{
		Period last = s.lastPeriod();
		if (last.from > killNo)
		{
			return false;
		}
		boolean differs = false;
		for (Map.Entry<String, Object> e : patch.entrySet())
		{
			Object cur = last.params.containsKey(e.getKey()) ? last.params.get(e.getKey()) : defaults == null ? null : defaults.get(e.getKey());
			if (!sameValue(cur, e.getValue()))
			{
				differs = true;
			}
		}
		if (!differs)
		{
			return false;
		}
		if (last.from == killNo)
		{
			last.params.putAll(patch);
			return true;
		}
		Period p = new Period(killNo, last.params);
		p.params.putAll(patch);
		s.segs.add(p);
		return true;
	}

	/**
	 * Equality for setting values that may be a number, a boolean or a string; a missing value counts as "off" / 0.
	 */
	static boolean sameValue(Object a, Object b)
	{
		if (a == null)
		{
			a = 0;
		}
		if (b == null)
		{
			b = 0;
		}
		if (a instanceof String || b instanceof String)
		{
			return a.toString().equals(b.toString());
		}
		return num(a) == num(b);
	}

	private static double num(Object o)
	{
		if (o instanceof Boolean)
		{
			return (Boolean) o ? 1 : 0;
		}
		return ((Number) o).doubleValue();
	}

	public void setTracked(String id, String name, boolean on)
	{
		update(id, s ->
		{
			Boss boss = data.boss(id);
			boolean def = boss != null && Catalog.defaultTracked(boss).contains(name);
			if (on)
			{
				s.hide.remove(name);
				if (!def && !s.track.contains(name))
				{
					s.track.add(name);
				}
			}
			else
			{
				s.track.remove(name);
				if (def && !s.hide.contains(name))
				{
					s.hide.add(name);
				}
			}
			return null;
		});
	}

	/**
	 * Adds copies of an item the player owns without a known kill number (history).  Returns how many were added.
	 */
	public int addOwned(String id, String item, int n)
	{
		if (n <= 0)
		{
			return 0;
		}
		update(id, s ->
		{
			for (int i = 0; i < n; i++)
			{
				Drop d = new Drop();
				d.id = newId();
				d.item = item;
				d.qty = 1;
				d.t = now();
				d.src = Drop.SRC_IMPORT;
				s.drops.add(d);
			}
			s.hide.remove(item);
			Boss boss = data.boss(id);
			if (boss != null && !Catalog.defaultTracked(boss).contains(item) && !s.track.contains(item))
			{
				s.track.add(item);
			}
			return null;
		});
		return n;
	}

	/**
	 * Takes back copies that a history import added with no kill number (it counted every item of a stack as a drop, say).  Only
	 * those copies are touched, never one that was logged live or by hand.
	 *
	 * @return how many were removed
	 */
	public int removeOwned(String id, String item, int n)
	{
		if (n <= 0)
		{
			return 0;
		}
		final int[] removed = {0};
		update(id, s ->
		{
			for (java.util.Iterator<Drop> it = s.drops.iterator(); it.hasNext() && removed[0] < n; )
			{
				Drop d = it.next();
				if (d.item.equals(item) && d.kc == null && Drop.SRC_IMPORT.equals(d.src))
				{
					it.remove();
					removed[0]++;
				}
			}
			return null;
		});
		return removed[0];
	}

	public void updatePrefs(java.util.function.Consumer<Prefs> fn)
	{
		synchronized (this)
		{
			fn.accept(prefs);
			prefs.window = Math.max(1, Math.min(5000, prefs.window));
			globalRev++;
			touch(null);
		}
		fire(null);
	}

	/**
	 * Remembers what the side panel shows so that it comes back the same.  It is saved with the ledger; no figure depends on it.
	 */
	public void setView(String sel, String tab, String scope)
	{
		synchronized (this)
		{
			if (prefs.sel.equals(sel) && prefs.tab.equals(tab) && prefs.scope.equals(scope))
			{
				return;
			}
			prefs.sel = sel;
			prefs.tab = tab;
			prefs.scope = scope;
			revision++;
		}
		fire(null);
	}

	/**
	 * Adds what another ledger (a backup) has.  A boss this ledger knows nothing about comes over whole.  For the others the
	 * drops with ids not yet here are added, the kill count becomes the larger of the two, and the extra tracked items come over.
	 *
	 * @return the number of drops added
	 */
	public int mergeFrom(Ledger other)
	{
		Map<String, BossState> theirs = new LinkedHashMap<>();
		synchronized (other)
		{
			for (Map.Entry<String, BossState> e : other.bosses.entrySet())
			{
				theirs.put(e.getKey(), e.getValue().copy());
			}
		}
		int added = 0;
		synchronized (this)
		{
			for (Map.Entry<String, BossState> e : theirs.entrySet())
			{
				String id = e.getKey();
				BossState inc = e.getValue();
				BossState cur = bosses.get(id);
				if (cur == null)
				{
					bosses.put(id, inc);
					added += inc.drops.size();
				}
				else
				{
					Set<String> have = new HashSet<>();
					for (Drop d : cur.drops)
					{
						have.add(d.id);
					}
					for (Drop d : inc.drops)
					{
						if (have.add(d.id))
						{
							cur.drops.add(d);
							added++;
						}
					}
					cur.kc = Math.max(cur.kc, Math.max(inc.kc, cur.maxDropKc()));
					for (String n : inc.track)
					{
						if (!cur.track.contains(n))
						{
							cur.track.add(n);
						}
					}
				}
				touch(id);
			}
		}
		fire(null);
		return added;
	}

	/**
	 * Replaces everything with the content of another ledger (restore).
	 */
	public void replaceWith(Ledger other)
	{
		synchronized (this)
		{
			Map<String, BossState> theirs;
			Prefs p;
			synchronized (other)
			{
				theirs = new LinkedHashMap<>();
				for (Map.Entry<String, BossState> e : other.bosses.entrySet())
				{
					theirs.put(e.getKey(), e.getValue().copy());
				}
				p = other.prefs.copy();
			}
			HistoryStage h;
			synchronized (other)
			{
				h = other.history.copy();
			}
			bosses.clear();
			bosses.putAll(theirs);
			prefs = p;
			history = h;
			globalRev++;
			touch(null);
		}
		fire(null);
	}

	/**
	 * Adds the state of one boss from outside (restore of a single boss); replaces what is there.
	 */
	void putBoss(String id, BossState s)
	{
		synchronized (this)
		{
			bosses.put(id, s);
			revision++;
			revisions.merge(id, 1L, Long::sum);
		}
	}

	void putHistory(HistoryStage h)
	{
		synchronized (this)
		{
			this.history = h;
		}
	}

	synchronized HistoryStage rawHistory()
	{
		return history;
	}

	void putPrefs(Prefs p)
	{
		synchronized (this)
		{
			this.prefs = p;
			globalRev++;
		}
	}

	synchronized Map<String, BossState> rawBosses()
	{
		return bosses;
	}

	synchronized Prefs rawPrefs()
	{
		return prefs;
	}

	public String newId()
	{
		StringBuilder b = new StringBuilder();
		for (int i = 0; i < 8; i++)
		{
			b.append(Character.forDigit(rnd.nextInt(36), 36));
		}
		return b.toString();
	}
}

package com.dropluckledger.ledger;

import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Param;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Reads and writes the ledger as JSON.  The format is the web app's backup format ("drop-luck-ledger", version 1) with a few
 * extra plugin-only fields that the web app ignores, so a backup can be moved either way.
 */
public final class LedgerCodec
{
	public static final String APP = "drop-luck-ledger";

	private LedgerCodec()
	{
	}

	/**
	 * Thrown for text that is not a ledger backup.
	 */
	public static final class FormatException extends Exception
	{
		private static final long serialVersionUID = 1L;

		public FormatException(String msg)
		{
			super(msg);
		}
	}

	// ------------------------------------------------------------------ writing

	public static String toJson(Gson gson, Ledger ledger)
	{
		return gson.toJson(toTree(ledger));
	}

	static JsonObject toTree(Ledger ledger)
	{
		JsonObject root = new JsonObject();
		root.addProperty("app", APP);
		root.addProperty("v", 1);
		root.addProperty("saved", Instant.ofEpochMilli(ledger.now()).toString());
		synchronized (ledger)
		{
			Prefs p = ledger.rawPrefs();
			JsonObject po = new JsonObject();
			po.addProperty("window", p.window);
			po.addProperty("rowi", p.rowi);
			po.addProperty("lq", p.lq);
			po.addProperty("theme", p.theme);
			po.addProperty("scope", p.scope);
			po.addProperty("sel", p.sel);
			po.addProperty("tab", p.tab);
			po.addProperty("images", p.images);
			root.add("prefs", po);
			JsonObject bo = new JsonObject();
			for (Map.Entry<String, BossState> e : ledger.rawBosses().entrySet())
			{
				bo.add(e.getKey(), bossTree(e.getValue()));
			}
			root.add("bosses", bo);
			HistoryStage h = ledger.rawHistory();
			if (!h.isEmpty())
			{
				JsonObject ho = new JsonObject();
				JsonObject kc = new JsonObject();
				for (Map.Entry<String, Integer> e : h.kc.entrySet())
				{
					kc.addProperty(e.getKey(), e.getValue());
				}
				ho.add("kc", kc);
				JsonObject log = new JsonObject();
				for (Map.Entry<String, Map<String, Integer>> e : h.log.entrySet())
				{
					JsonObject page = new JsonObject();
					for (Map.Entry<String, Integer> it : e.getValue().entrySet())
					{
						page.addProperty(it.getKey(), it.getValue());
					}
					log.add(e.getKey(), page);
				}
				ho.add("log", log);
				ho.addProperty("kcTime", h.kcTime);
				ho.addProperty("logTime", h.logTime);
				root.add("history", ho);
			}
		}
		return root;
	}

	static JsonObject bossTree(BossState b)
	{
		JsonObject o = new JsonObject();
		o.addProperty("kc", b.kc);
		JsonArray segs = new JsonArray();
		for (Period p : b.segs)
		{
			JsonObject s = new JsonObject();
			s.addProperty("from", p.from);
			JsonObject params = new JsonObject();
			for (Map.Entry<String, Object> e : p.params.entrySet())
			{
				Object v = e.getValue();
				if (v instanceof Boolean)
				{
					params.addProperty(e.getKey(), (Boolean) v ? 1 : 0);
				}
				else if (v instanceof Number)
				{
					params.addProperty(e.getKey(), (Number) v);
				}
				else if (v != null)
				{
					params.addProperty(e.getKey(), v.toString());
				}
			}
			s.add("params", params);
			segs.add(s);
		}
		o.add("segs", segs);
		JsonArray drops = new JsonArray();
		for (Drop d : b.drops)
		{
			JsonObject j = new JsonObject();
			j.addProperty("id", d.id);
			j.addProperty("item", d.item);
			if (d.kc != null)
			{
				j.addProperty("kc", d.kc);
			}
			j.addProperty("qty", d.qty);
			j.addProperty("t", d.t);
			if (d.snap != null && !d.snap.isEmpty())
			{
				JsonObject sn = new JsonObject();
				for (Map.Entry<String, Integer> e : d.snap.entrySet())
				{
					sn.addProperty(e.getKey(), e.getValue());
				}
				j.add("snap", sn);
			}
			if (d.src != null)
			{
				j.addProperty("src", d.src);
			}
			drops.add(j);
		}
		o.add("drops", drops);
		o.add("track", strings(b.track));
		o.add("hide", strings(b.hide));
		o.addProperty("u", b.u);
		if (b.labelKc != null && !b.labelKc.isEmpty())
		{
			JsonObject lk = new JsonObject();
			for (Map.Entry<String, Integer> e : b.labelKc.entrySet())
			{
				lk.addProperty(e.getKey(), e.getValue());
			}
			o.add("labelKc", lk);
		}
		if (b.prov != null && b.prov > 0)
		{
			o.addProperty("prov", b.prov);
		}
		if (b.provDrops != null && !b.provDrops.isEmpty())
		{
			o.add("provDrops", strings(b.provDrops));
		}
		return o;
	}

	private static JsonArray strings(List<String> l)
	{
		JsonArray a = new JsonArray();
		for (String s : l)
		{
			a.add(s);
		}
		return a;
	}

	// ------------------------------------------------------------------ reading

	/**
	 * Reads a backup.  Unknown bosses and settings are dropped, damaged entries are repaired or skipped.
	 */
	public static Ledger fromJson(Data data, String json) throws FormatException
	{
		return fromJson(data, json, null);
	}

	public static Ledger fromJson(Data data, String json, java.util.function.LongSupplier clock) throws FormatException
	{
		JsonObject root;
		try
		{
			JsonElement e = new JsonParser().parse(json == null ? "" : json.trim());
			if (!e.isJsonObject())
			{
				throw new FormatException("This is not a Drop Luck Ledger backup.");
			}
			root = e.getAsJsonObject();
		}
		catch (com.google.gson.JsonParseException | IllegalStateException ex)
		{
			throw new FormatException("This is not a Drop Luck Ledger backup (the file could not be read).");
		}
		if (!root.has("app") || !root.get("app").isJsonPrimitive() || !APP.equals(root.get("app").getAsString()))
		{
			throw new FormatException("This is not a Drop Luck Ledger backup.");
		}
		Ledger l = clock == null ? new Ledger(data) : new Ledger(data, clock);
		Prefs prefs = new Prefs();
		if (root.has("prefs") && root.get("prefs").isJsonObject())
		{
			JsonObject po = root.getAsJsonObject("prefs");
			prefs.window = clamp(po.get("window"), 1, 5000, prefs.window);
			prefs.rowi = flag(po.get("rowi"), 0);
			prefs.lq = flag(po.get("lq"), 1);
			prefs.images = flag(po.get("images"), 1);
			prefs.theme = text(po.get("theme"), "");
			prefs.scope = "new".equals(text(po.get("scope"), "all")) ? "new" : "all";
			String sel = text(po.get("sel"), "");
			prefs.sel = data.boss(sel) != null ? sel : "";
			prefs.tab = text(po.get("tab"), "tracker");
		}
		l.putPrefs(prefs);
		if (root.has("bosses") && root.get("bosses").isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("bosses").entrySet())
			{
				Boss boss = data.boss(e.getKey());
				if (boss == null || !e.getValue().isJsonObject())
				{
					continue;
				}
				l.putBoss(e.getKey(), sanitizeBoss(l, boss, e.getValue().getAsJsonObject()));
			}
		}
		HistoryStage hs = new HistoryStage();
		if (root.has("history") && root.get("history").isJsonObject())
		{
			JsonObject ho = root.getAsJsonObject("history");
			if (ho.has("kc") && ho.get("kc").isJsonObject())
			{
				for (Map.Entry<String, JsonElement> e : ho.getAsJsonObject("kc").entrySet())
				{
					int v = clamp(e.getValue(), 0, 100_000_000, 0);
					if (v > 0)
					{
						hs.kc.put(e.getKey(), v);
					}
				}
			}
			if (ho.has("log") && ho.get("log").isJsonObject())
			{
				for (Map.Entry<String, JsonElement> e : ho.getAsJsonObject("log").entrySet())
				{
					if (!e.getValue().isJsonObject())
					{
						continue;
					}
					Map<String, Integer> page = new LinkedHashMap<>();
					for (Map.Entry<String, JsonElement> it : e.getValue().getAsJsonObject().entrySet())
					{
						int v = clamp(it.getValue(), 0, 1_000_000, 0);
						if (v > 0)
						{
							page.put(it.getKey(), v);
						}
					}
					hs.log.put(e.getKey(), page);
				}
			}
			hs.kcTime = lng(ho.get("kcTime"), 0);
			hs.logTime = lng(ho.get("logTime"), 0);
		}
		l.putHistory(hs);
		return l;
	}

	private static BossState sanitizeBoss(Ledger l, Boss boss, JsonObject x)
	{
		BossState b = new BossState();
		b.kc = clamp(x.get("kc"), 0, 100_000_000, 0);
		b.u = lng(x.get("u"), l.now());
		List<Period> segs = new ArrayList<>();
		if (x.has("segs") && x.get("segs").isJsonArray())
		{
			for (JsonElement se : x.getAsJsonArray("segs"))
			{
				if (!se.isJsonObject())
				{
					continue;
				}
				JsonObject so = se.getAsJsonObject();
				Period p = new Period();
				p.from = Math.max(1, clamp(so.get("from"), 1, 1_000_000_000, 1));
				if (so.has("params") && so.get("params").isJsonObject())
				{
					for (Map.Entry<String, JsonElement> pe : so.getAsJsonObject("params").entrySet())
					{
						Param def = null;
						for (Param pd : boss.params)
						{
							if (pd.name.equals(pe.getKey()))
							{
								def = pd;
							}
						}
						if (def != null)
						{
							Object v = coerce(def, pe.getValue());
							if (v != null)
							{
								p.params.put(pe.getKey(), v);
							}
						}
					}
				}
				segs.add(p);
			}
		}
		if (!segs.isEmpty())
		{
			segs.sort(Comparator.comparingInt(p -> p.from));
			if (segs.get(0).from != 1)
			{
				segs.add(0, new Period(1, new LinkedHashMap<>()));
			}
			b.segs = segs;
		}
		if (x.has("drops") && x.get("drops").isJsonArray())
		{
			for (JsonElement de : x.getAsJsonArray("drops"))
			{
				if (!de.isJsonObject())
				{
					continue;
				}
				JsonObject d = de.getAsJsonObject();
				if (!d.has("item") || !d.get("item").isJsonPrimitive() || !d.get("item").getAsJsonPrimitive().isString())
				{
					continue;
				}
				Drop r = new Drop();
				r.id = text(d.get("id"), "");
				if (r.id.isEmpty())
				{
					r.id = l.newId();
				}
				r.item = d.get("item").getAsString();
				r.kc = d.has("kc") && !d.get("kc").isJsonNull() ? Integer.valueOf(clamp(d.get("kc"), 1, 1_000_000_000, 1)) : null;
				r.qty = clamp(d.get("qty"), 1, 1_000_000_000, 1);
				r.t = lng(d.get("t"), 0);
				if (d.has("snap") && d.get("snap").isJsonObject())
				{
					Map<String, Integer> sn = new LinkedHashMap<>();
					for (Map.Entry<String, JsonElement> se : d.getAsJsonObject("snap").entrySet())
					{
						sn.put(se.getKey(), clamp(se.getValue(), 0, 1_000_000_000, 0));
					}
					r.snap = sn.isEmpty() ? null : sn;
				}
				String src = text(d.get("src"), "");
				r.src = Drop.SRC_IMPORT.equals(src) || Drop.SRC_LIVE.equals(src) || Drop.SRC_MANUAL.equals(src) ? src : null;
				b.drops.add(r);
			}
		}
		b.track = stringList(x.get("track"));
		b.hide = stringList(x.get("hide"));
		if (x.has("labelKc") && x.get("labelKc").isJsonObject())
		{
			Map<String, Integer> lk = new LinkedHashMap<>();
			for (Map.Entry<String, JsonElement> le : x.getAsJsonObject("labelKc").entrySet())
			{
				lk.put(le.getKey(), clamp(le.getValue(), 0, 100_000_000, 0));
			}
			b.labelKc = lk.isEmpty() ? null : lk;
		}
		int prov = clamp(x.get("prov"), 0, 1_000_000, 0);
		b.prov = prov > 0 ? prov : null;
		List<String> pd = stringList(x.get("provDrops"));
		b.provDrops = pd.isEmpty() ? null : pd;
		b.kc = Math.max(b.kc, b.maxDropKc());
		return b;
	}

	/**
	 * A setting value in the form the maths takes: 1 or 0 for yes/no, an integer, or the chosen option.
	 */
	private static Object coerce(Param p, JsonElement v)
	{
		if (v == null || v.isJsonNull() || !v.isJsonPrimitive())
		{
			return null;
		}
		JsonPrimitive pr = v.getAsJsonPrimitive();
		if ("bool".equals(p.type))
		{
			if (pr.isBoolean())
			{
				return pr.getAsBoolean() ? 1 : 0;
			}
			return flag(pr, 0);
		}
		if ("int".equals(p.type))
		{
			double d = number(pr, Double.NaN);
			if (Double.isNaN(d))
			{
				return null;
			}
			long r = Math.round(d);
			if (p.min != null)
			{
				r = Math.max(r, Math.round(p.min));
			}
			if (p.max != null)
			{
				r = Math.min(r, Math.round(p.max));
			}
			return (int) r;
		}
		String s = pr.getAsString();
		return p.options != null && p.options.contains(s) ? s : null;
	}

	private static List<String> stringList(JsonElement e)
	{
		List<String> out = new ArrayList<>();
		if (e != null && e.isJsonArray())
		{
			for (JsonElement s : e.getAsJsonArray())
			{
				if (s.isJsonPrimitive() && s.getAsJsonPrimitive().isString())
				{
					out.add(s.getAsString());
				}
			}
		}
		return out;
	}

	private static String text(JsonElement e, String def)
	{
		return e != null && e.isJsonPrimitive() ? e.getAsString() : def;
	}

	private static double number(JsonElement e, double def)
	{
		if (e == null || !e.isJsonPrimitive())
		{
			return def;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		if (p.isNumber())
		{
			return p.getAsDouble();
		}
		if (p.isBoolean())
		{
			return p.getAsBoolean() ? 1 : 0;
		}
		try
		{
			return Double.parseDouble(p.getAsString().trim());
		}
		catch (NumberFormatException ex)
		{
			return def;
		}
	}

	private static int clamp(JsonElement e, int lo, int hi, int def)
	{
		double d = number(e, Double.NaN);
		if (Double.isNaN(d) || Double.isInfinite(d))
		{
			return def;
		}
		long r = Math.round(d);
		return (int) Math.max(lo, Math.min(hi, r));
	}

	private static long lng(JsonElement e, long def)
	{
		double d = number(e, Double.NaN);
		return Double.isNaN(d) || Double.isInfinite(d) ? def : (long) d;
	}

	/**
	 * 1 for true / 1 / "1" / "true", 0 for false / 0, the default for anything else.
	 */
	private static int flag(JsonElement e, int def)
	{
		if (e == null || !e.isJsonPrimitive())
		{
			return def;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		if (p.isBoolean())
		{
			return p.getAsBoolean() ? 1 : 0;
		}
		if (p.isNumber())
		{
			return p.getAsDouble() != 0 ? 1 : 0;
		}
		String s = p.getAsString().trim();
		if (s.equalsIgnoreCase("true") || s.equals("1"))
		{
			return 1;
		}
		if (s.equalsIgnoreCase("false") || s.equals("0") || s.isEmpty())
		{
			return 0;
		}
		return def;
	}
}

package com.dropluckledger.ledger;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Keeps a {@link LedgerStore} up to date: changes are written a moment after the last one, on a background thread.
 */
public final class LedgerSaver implements Ledger.Listener
{
	private static final Logger log = LoggerFactory.getLogger(LedgerSaver.class);

	private final Ledger ledger;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final long delayMs;
	private LedgerStore store;
	private Future<?> pending;
	private boolean dirty;
	private boolean failedOnce;

	public LedgerSaver(Ledger ledger, Gson gson, ScheduledExecutorService executor, long delayMs)
	{
		this.ledger = ledger;
		this.gson = gson;
		this.executor = executor;
		this.delayMs = delayMs;
	}

	/**
	 * Where to save from now on (null = nowhere, for example while logged out).  Anything not written yet goes to the
	 * previous place first, so to switch accounts call setStore(null), load the other account into the ledger, then
	 * setStore(its store).
	 */
	public synchronized void setStore(LedgerStore next)
	{
		flushNow();
		store = next;
		dirty = false;
	}

	@Override
	public synchronized void changed(String bossId)
	{
		if (store == null)
		{
			return;
		}
		dirty = true;
		if (pending != null)
		{
			pending.cancel(false);
		}
		pending = executor.schedule(this::flushNow, delayMs, TimeUnit.MILLISECONDS);
	}

	/**
	 * Writes now if there is anything to write.  Safe to call from any thread.
	 */
	public synchronized void flushNow()
	{
		if (pending != null)
		{
			pending.cancel(false);
			pending = null;
		}
		if (store == null || !dirty)
		{
			return;
		}
		try
		{
			store.write(LedgerCodec.toJson(gson, ledger));
			dirty = false;
			failedOnce = false;
		}
		catch (IOException | RuntimeException ex)
		{
			if (!failedOnce)
			{
				log.warn("Could not save the drop ledger", ex);
				failedOnce = true;
			}
			// keep it dirty; the next change tries again
		}
	}

	public synchronized void cancel()
	{
		if (pending != null)
		{
			pending.cancel(false);
			pending = null;
		}
	}

	/**
	 * Reads the saved ledger into the live one.  A missing file leaves the ledger empty.
	 *
	 * @return false when a file existed but could not be read (the ledger is left empty and nothing is overwritten
	 * until the player changes something)
	 */
	public synchronized boolean loadInto(LedgerStore from)
	{
		try
		{
			String text = from.read();
			if (text == null || text.trim().isEmpty())
			{
				ledger.replaceWith(new Ledger(ledger.data()));
				return true;
			}
			ledger.replaceWith(LedgerCodec.fromJson(ledger.data(), text));
			return true;
		}
		catch (IOException | LedgerCodec.FormatException | RuntimeException ex)
		{
			log.warn("Could not read the saved drop ledger", ex);
			try
			{
				from.quarantine();
			}
			catch (IOException | RuntimeException ex2)
			{
				log.warn("Could not set the unreadable ledger file aside", ex2);
			}
			ledger.replaceWith(new Ledger(ledger.data()));
			return false;
		}
	}
}

package com.dropluckledger.ledger;

import java.io.IOException;

/**
 * Where one account's ledger file lives.
 */
public interface LedgerStore
{
	/**
	 * @return the saved text, or null when nothing has been saved yet
	 */
	String read() throws IOException;

	/**
	 * Replaces the saved text.  Must not leave a half-written file behind if it fails.
	 */
	void write(String json) throws IOException;

	/**
	 * Called when the saved text could not be understood: keep it somewhere (for example by renaming the file) so the next
	 * save does not destroy it.
	 */
	default void quarantine() throws IOException
	{
	}
}

package com.dropluckledger.ledger;

import java.util.LinkedHashMap;
