package com.dropluckledger.plugin;

import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Drop;
import java.text.NumberFormat;
import java.util.Locale;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;

/**
 * The game message shown when a drop has been added to the ledger.
 */
public final class DropMessages
{
	private DropMessages()
	{
	}

	/**
	 * "Logged Dragonbone necklace at Vorkath kill 1,234 (412 kills since the last one)."
	 *
	 * @param state the boss as it is after the drop was added
	 * @return the message in RuneLite's chat format
	 */
	public static String build(Data data, String bossId, BossState state, String item, int killNo)
	{
		Boss boss = data.boss(bossId);
		String bossName = boss == null ? bossId : boss.name;
		return new ChatMessageBuilder()
			.append(ChatColorType.NORMAL)
			.append("Logged ")
			.append(ChatColorType.HIGHLIGHT)
			.append(item)
			.append(ChatColorType.NORMAL)
			.append(" at ")
			.append(ChatColorType.HIGHLIGHT)
			.append(bossName)
			.append(ChatColorType.NORMAL)
			.append(" kill " + number(killNo) + detail(state, item, killNo) + ".")
			.build();
	}

	/**
	 * What to say about the streak: kills since the last copy, or that this is the first one.  Nothing when copies of unknown
	 * kill number (imported from history) make that unclear.
	 */
	static String detail(BossState state, String item, int killNo)
	{
		int previous = 0;
		int unknown = 0;
		int others = 0;
		for (Drop d : state.drops)
		{
			if (!d.item.equals(item))
			{
				continue;
			}
			if (d.kc == null)
			{
				unknown++;
			}
			else if (d.kc < killNo)
			{
				previous = Math.max(previous, d.kc);
				others++;
			}
			else if (d.kc > killNo)
			{
				return "";
			}
		}
		if (unknown > 0)
		{
			return "";
		}
		if (others == 0)
		{
			return killNo > 1 ? " (the first one, after " + number(killNo - 1) + " kills)" : "";
		}
		int since = killNo - previous;
		return " (" + number(since) + (since == 1 ? " kill" : " kills") + " since the last one)";
	}

	private static String number(int n)
	{
		return NumberFormat.getIntegerInstance(Locale.US).format(n);
	}
}

package com.dropluckledger.plugin;

import com.dropluckledger.ledger.LedgerStore;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import net.runelite.client.util.Filepath;

/**
 * One text file in the plugin's data folder.  Every path goes through RuneLite's {@link Filepath}, so the plugin cannot write
 * anywhere else.  Writes go to a temporary file first and are moved over the real one, so a crash never leaves half a file.
 */
public final class FileStore implements LedgerStore
{
	/**
	 * A ledger file bigger than this is not read (it is not a ledger).
	 */
	static final long MAX_BYTES = 64L * 1024 * 1024;

	private final Filepath dir;
	private final String name;
	private boolean backedUp;

	/**
	 * @param dir  the folder (created on the first write)
	 * @param name the file name inside it, one path segment
	 */
	public FileStore(Filepath dir, String name)
	{
		this.dir = dir;
		this.name = name;
	}

	/**
	 * File name of an account's ledger.
	 */
	public static String ledgerName(long accountHash)
	{
		return "ledger-" + accountHash + ".json";
	}

	@Override
	public String read() throws IOException
	{
		Filepath file = dir.joinSegment(name);
		if (!file.isFile())
		{
			return null;
		}
		return readText(file);
	}

	/**
	 * Reads a whole UTF-8 text file.
	 */
	public static String readText(Filepath file) throws IOException
	{
		if (file.size() > MAX_BYTES)
		{
			throw new IOException("The file is too large to be a ledger backup");
		}
		try (InputStream in = file.openInputStream())
		{
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
	}

	/**
	 * Writes a whole UTF-8 text file (used for backups the player chose the location of).
	 */
	public static void writeText(Filepath file, String text) throws IOException
	{
		file.write(text, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
	}

	@Override
	public synchronized void write(String json) throws IOException
	{
		dir.createDirectories();
		Filepath target = dir.joinSegment(name);
		Filepath temp = dir.joinSegment(name + ".tmp");
		writeText(temp, json);
		if (!backedUp && target.isFile())
		{
			// the file as the last session left it: kept once, in case this session does something the player regrets
			target.copyTo(dir.joinSegment(name + ".bak"), StandardCopyOption.REPLACE_EXISTING);
			backedUp = true;
		}
		try
		{
			temp.moveTo(target, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException ex)
		{
			temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	@Override
	public synchronized void quarantine() throws IOException
	{
		Filepath file = dir.joinSegment(name);
		if (file.isFile())
		{
			file.moveTo(dir.joinSegment(name + ".unreadable-" + System.currentTimeMillis()), StandardCopyOption.REPLACE_EXISTING);
		}
	}
}

package com.dropluckledger.plugin;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Skill;
import net.runelite.client.util.Filepath;

/**
 * Everything the plugin asks of the running game and of RuneLite's services, in one place.
 * <p>
 * {@link RuneLiteGame} is the only class that talks to the real client; the rest of the plugin (and its tests) sees only this
 * interface.  Call the methods on the client thread unless a method says otherwise.
 */
public interface Game
{
	// ------------------------------------------------------------------ the player

	/**
	 * The hash that identifies the logged in account, or -1 when nobody is logged in.
	 */
	long accountHash();

	/**
	 * True while a character is logged in.
	 */
	boolean isLoggedIn();

	/**
	 * True on a normal world.  False on the worlds that keep a save of their own (Leagues, Deadman, ...).
	 */
	boolean isStandardWorld();

	/**
	 * The logged in character's name, or null.
	 */
	String playerName();

	/**
	 * The number of game ticks since the client started; messages and loot of one kill share a tick or are a tick apart.
	 */
	int tickCount();

	/**
	 * The player's unboosted level in a skill.
	 */
	int realLevel(Skill skill);

	/**
	 * The player's experience in a skill.
	 */
	int experience(Skill skill);

	// ------------------------------------------------------------------ the game's screens

	/**
	 * A piece of the game's interface, as far as the plugin reads it.
	 */
	interface Node
	{
		/**
		 * The text shown, or null.
		 */
		String text();

		/**
		 * The pieces inside this one (entries may be null), or null when there is no list.
		 */
		List<Node> children();

		/**
		 * The piece at a position inside this one, or null.
		 */
		Node child(int index);

		/**
		 * The item shown, or -1 (or 0) when none.
		 */
		int itemId();

		int itemQuantity();

		/**
		 * 0 for fully drawn, up to 255 for invisible; the collection log fades the items the player does not have.
		 */
		int opacity();
	}

	/**
	 * The interface component with an id from {@code InterfaceID}, or null when it is not on screen.
	 */
	Node widget(int componentId);

	// ------------------------------------------------------------------ items

	/**
	 * What the game knows about an item.
	 */
	final class ItemInfo
	{
		/**
		 * The game's name for it ("null" for ids that are not items).
		 */
		public final String name;
		/**
		 * True for the noted (bank note) copy of another item.
		 */
		public final boolean noted;
		/**
		 * True for the bank placeholder of another item.
		 */
		public final boolean placeholder;

		public ItemInfo(String name, boolean noted, boolean placeholder)
		{
			this.name = name;
			this.noted = noted;
			this.placeholder = placeholder;
		}
	}

	/**
	 * An item found by searching for a name.
	 */
	final class ItemRef
	{
		public final int id;
		public final String name;

		public ItemRef(int id, String name)
		{
			this.id = id;
			this.name = name;
		}
	}

	/**
	 * What the game knows about an item id, or null when it has nothing for that id.
	 */
	ItemInfo item(int id);

	/**
	 * The game's name for an item, or null when the id is not an item.
	 */
	default String itemName(int id)
	{
		ItemInfo info = item(id);
		return info == null || info.name == null || info.name.isEmpty() || info.name.equals("null") ? null : info.name;
	}

	/**
	 * The id of the plain item behind a noted copy or a placeholder (other ids come back as they are).
	 */
	int canonicalItemId(int id);

	/**
	 * Tradeable items whose names contain the text.
	 */
	List<ItemRef> searchItems(String text);

	/**
	 * The item's picture.  The game fills it in a moment after returning it, and calls {@code whenLoaded} then.
	 * Can be called from any thread.
	 *
	 * @return null when there is no picture
	 */
	BufferedImage itemImage(int id, Runnable whenLoaded);

	// ------------------------------------------------------------------ what other RuneLite plugins saved

	/**
	 * Keys that start with a prefix, among the settings other plugins saved for the logged in profile (empty when there
	 * is no profile).  Can be called from any thread.
	 */
	List<String> savedKeys(String group, String keyPrefix);

	/**
	 * A whole number saved for the logged in profile, or null.  Can be called from any thread.
	 */
	Integer savedInt(String group, String key);

	/**
	 * A text saved for the logged in profile, or null.  Can be called from any thread.
	 */
	String savedText(String group, String key);

	// ------------------------------------------------------------------ chat, threads and files

	/**
	 * Puts a line in the player's chat box (RuneLite colour tags allowed).
	 */
	void gameMessage(String runeLiteFormattedMessage);

	/**
	 * Runs something on the client thread: at once when already there, otherwise as soon as the client thread is free.
	 * Can be called from any thread.
	 */
	void invoke(Runnable task);

	/**
	 * Runs something on the client thread, never at once.  Can be called from any thread.
	 */
	void invokeLater(Runnable task);

	/**
	 * Asks the player where to save a file.  Call on the Swing thread.
	 *
	 * @return the chosen file, or null when the player cancels
	 */
	Filepath chooseFileToSave(Component parent, String title, String fileName, String description, String extension);

	/**
	 * Asks the player which file to open.  Call on the Swing thread.
	 *
	 * @return the chosen file, or null when the player cancels
	 */
	Filepath chooseFileToOpen(Component parent, String title, String description, String extension);
}

package com.dropluckledger.plugin;

import com.dropluckledger.capture.KcMessages;
import com.dropluckledger.plugin.Game.Node;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.InterfaceID;

/**
 * Reads the game's own records off the screen when the player opens them: the Boss Kill Log and the pages of the collection
 * log.  Only reads widgets; the caller decides what to do with the result.  Call on the client thread.
 */
public final class GameReader
{
	private static final Pattern ADVENTURE_LOG_TITLE = Pattern.compile("The Exploits of (.+)");

	private GameReader()
	{
	}

	/**
	 * One page of the collection log: its title and the copies of each item the player has.
	 */
	public static final class LogPage
	{
		public final String title;
		/**
		 * Item name to the number of copies the player has (only items the player has).
		 */
		public final Map<String, Integer> items;
		/**
		 * Item name to item id for every item on the page, including the ones the player does not have yet.
		 */
		public final Map<String, Integer> ids;

		LogPage(String title, Map<String, Integer> items, Map<String, Integer> ids)
		{
			this.title = title;
			this.items = items;
			this.ids = ids;
		}
	}

	/**
	 * The Boss Kill Log as shown on screen: boss name to kill count.
	 *
	 * @return null when the Boss Kill Log is not on screen (or not filled in yet)
	 */
	public static Map<String, Integer> killLog(Game game)
	{
		Node title = game.widget(InterfaceID.KillLog.INTERFACE_TITLE);
		Node names = game.widget(InterfaceID.KillLog.NAME);
		Node kills = game.widget(InterfaceID.KillLog.KILL);
		if (title == null || names == null || kills == null || !"Boss Kill Log".equals(title.text()))
		{
			return null;
		}
		List<Node> nameRows = names.children();
		List<Node> killRows = kills.children();
		if (nameRows == null || killRows == null)
		{
			return null;
		}
		Map<String, Integer> out = new LinkedHashMap<>();
		for (int i = 0; i < Math.min(nameRows.size(), killRows.size()); i++)
		{
			Node name = nameRows.get(i);
			Node kill = killRows.get(i);
			if (name == null || kill == null || name.text() == null || kill.text() == null)
			{
				continue;
			}
			String boss = KcMessages.stripTags(name.text()).replace(":", "").trim();
			String count = KcMessages.stripTags(kill.text()).replace(",", "").trim();
			try
			{
				int n = Integer.parseInt(count);
				if (!boss.isEmpty() && n > 0)
				{
					out.put(boss, n);
				}
			}
			catch (NumberFormatException ex)
			{
				// a heading or an empty row
			}
		}
		return out;
	}

	/**
	 * The collection log page on screen: the items the player has, with how many.
	 *
	 * @return null when no page is on screen
	 */
	public static LogPage collectionPage(Game game)
	{
		Node header = game.widget(InterfaceID.Collection.HEADER_TEXT);
		if (header == null || header.children() == null)
		{
			return null;
		}
		Node titleNode = header.child(0);
		if (titleNode == null || titleNode.text() == null)
		{
			return null;
		}
		String title = KcMessages.stripTags(titleNode.text()).trim();
		Node list = game.widget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (title.isEmpty() || list == null || list.children() == null)
		{
			return null;
		}
		Map<String, Integer> items = new LinkedHashMap<>();
		Map<String, Integer> ids = new LinkedHashMap<>();
		for (Node child : list.children())
		{
			if (child == null || child.itemId() <= 0)
			{
				continue;
			}
			String name = game.itemName(child.itemId());
			if (name == null)
			{
				continue;
			}
			ids.putIfAbsent(name, child.itemId());
			// items the player does not have are drawn faded (opacity above zero)
			if (child.opacity() == 0)
			{
				items.merge(name, Math.max(1, child.itemQuantity()), Integer::sum);
			}
		}
		return new LogPage(title, items, ids);
	}

	/**
	 * Whose adventure log is open: the name after "The Exploits of".  The Boss Kill Log opens from the adventure log, and in
	 * a player-owned house it can be another player's.
	 *
	 * @return null when no adventure log is open
	 */
	public static String adventureLogOwner(Game game)
	{
		String owner = ownerIn(game, InterfaceID.MenuNew.TITLE);
		return owner != null ? owner : ownerIn(game, InterfaceID.Menu.LJ_LAYER2);
	}

	private static String ownerIn(Game game, int componentId)
	{
		Node container = game.widget(componentId);
		if (container == null)
		{
			return null;
		}
		String own = owner(container.text());
		if (own != null)
		{
			return own;
		}
		List<Node> children = container.children();
		if (children == null)
		{
			return null;
		}
		for (Node child : children)
		{
			if (child == null)
			{
				continue;
			}
			String found = owner(child.text());
			if (found != null)
			{
				return found;
			}
		}
		return null;
	}

	static String owner(String text)
	{
		if (text == null)
		{
			return null;
		}
		Matcher m = ADVENTURE_LOG_TITLE.matcher(KcMessages.stripTags(text));
		return m.find() ? m.group(1).trim() : null;
	}
}

package com.dropluckledger.plugin;

import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.BossIndex.KcLabel;
import com.dropluckledger.history.HistoryInput;
import com.dropluckledger.ledger.HistoryStage;
import com.dropluckledger.ledger.Ledger;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.List;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Collects what the game and RuneLite already know about the player's history, for {@link com.dropluckledger.history.HistoryPlanner}:
 * <ul>
 * <li>the kill counts RuneLite's Chat Commands plugin saved from every kill-count message it has seen,</li>
 * <li>the totals the Loot Tracker plugin saved (items per boss, over the last year, if "Remember loot" is on),</li>
 * <li>whatever the player has opened on screen: the Boss Kill Log and collection log pages (kept in the ledger).</li>
 * </ul>
 * None of these says which kill a drop came on, so history only ever brings in kill counts and owned copies.
 */
public final class HistorySources
{
	public static final String SRC_KC = "RuneLite kill counts";
	public static final String SRC_LOOT = "Loot Tracker";
	public static final String SRC_KILL_LOG = "Boss Kill Log";
	public static final String SRC_COLLECTION = "Collection Log";

	private static final String KILLCOUNT_GROUP = "killcount";
	private static final String LOOT_TRACKER_GROUP = "loottracker";
	private static final String LOOT_PREFIX = "drops_";

	private static final Logger log = LoggerFactory.getLogger(HistorySources.class);

	private HistorySources()
	{
	}

	/**
	 * One saved Loot Tracker total (the part of its format the plugin needs; the rest is ignored).
	 */
	private static final class Aggregate
	{
		String type;
		String name;
		int kills;
		int[] drops;
	}

	/**
	 * Everything available now.  Call on the client thread (item names are looked up in the game).
	 */
	public static HistoryInput collect(Ledger ledger, Game game, Gson gson, BossIndex index)
	{
		HistoryInput in = new HistoryInput();
		readStage(ledger.history(), in);
		readRuneLite(game, gson, index, in);
		return in;
	}

	/**
	 * What has been read off the screen so far.
	 */
	static void readStage(HistoryStage stage, HistoryInput in)
	{
		for (Map.Entry<String, Integer> e : stage.kc.entrySet())
		{
			in.addKc(e.getKey(), e.getValue(), SRC_KILL_LOG);
		}
		for (Map.Entry<String, Map<String, Integer>> page : stage.log.entrySet())
		{
			for (Map.Entry<String, Integer> item : page.getValue().entrySet())
			{
				in.addOwned(null, page.getKey(), item.getKey(), item.getValue(), SRC_COLLECTION);
			}
		}
	}

	/**
	 * What RuneLite's other plugins saved for the profile that is logged in.
	 */
	static void readRuneLite(Game game, Gson gson, BossIndex index, HistoryInput in)
	{
		for (String key : game.savedKeys(KILLCOUNT_GROUP, ""))
		{
			Integer n = game.savedInt(KILLCOUNT_GROUP, key);
			if (n != null && n > 0)
			{
				in.addKc(key, n, SRC_KC);
			}
		}
		for (String key : game.savedKeys(LOOT_TRACKER_GROUP, LOOT_PREFIX))
		{
			Aggregate a = parse(gson, game.savedText(LOOT_TRACKER_GROUP, key));
			if (a == null || a.name == null || a.drops == null || !("NPC".equals(a.type) || "EVENT".equals(a.type)))
			{
				continue;
			}
			String bossId = index.loot(a.name);
			if (bossId == null)
			{
				continue;
			}
			if (a.kills > 0)
			{
				KcLabel label = index.kc(a.name);
				List<KcLabel> labels = index.labels(bossId);
				String name = label != null && label.bossId.equals(bossId) ? a.name : labels.isEmpty() ? null : labels.get(0).label;
				if (name != null)
				{
					in.addKc(name, a.kills, SRC_LOOT);
				}
			}
			for (int i = 0; i + 1 < a.drops.length; i += 2)
			{
				String item = game.itemName(a.drops[i]);
				if (item != null)
				{
					in.addOwned(bossId, null, item, a.drops[i + 1], SRC_LOOT);
				}
			}
		}
	}

	private static Aggregate parse(Gson gson, String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, Aggregate.class);
		}
		catch (JsonParseException ex)
		{
			log.debug("Skipping a Loot Tracker record that could not be read", ex);
			return null;
		}
	}
}

package com.dropluckledger.plugin;

import com.dropluckledger.capture.Names;
import com.dropluckledger.plugin.Game.ItemInfo;
import com.dropluckledger.plugin.Game.ItemRef;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Finds the game's item picture for an item name.
 * <p>
 * Ids come from three places: items seen in loot and on collection log pages, a search of the tradeable items, and (for
 * what is left, mostly pets) a slow scan of the game's item list that runs a few ids per game tick.  What was found is kept
 * between sessions.
 */
public final class ItemIcons
{
	/**
	 * Item ids looked at per game tick by the scan; small enough not to be felt.
	 */
	static final int SCAN_PER_TICK = 100;
	/**
	 * Above the highest item id the game has.
	 */
	static final int SCAN_LIMIT = 40000;

	private final Game game;
	/**
	 * Flattened item name to item id.
	 */
	private final Map<String, Integer> ids = new ConcurrentHashMap<>();
	private final Set<String> searched = ConcurrentHashMap.newKeySet();
	private volatile boolean dirty;

	private Set<String> wanted = Collections.emptySet();
	private int scanNext = -1;
	private long scannedAt;

	public ItemIcons(Game game)
	{
		this.game = game;
	}

	// ------------------------------------------------------------------ what is known

	/**
	 * Remembers the id of an item seen in the game.
	 */
	public void learn(String name, int id)
	{
		if (name == null || id <= 0)
		{
			return;
		}
		String key = Names.flat(name);
		if (!key.isEmpty() && ids.putIfAbsent(key, id) == null)
		{
			dirty = true;
		}
	}

	/**
	 * The item id for a name, or 0 when it is not known.
	 */
	public int id(String name)
	{
		String key = Names.flat(name);
		Integer known = ids.get(key);
		if (known != null)
		{
			return known;
		}
		if (key.isEmpty() || !searched.add(key))
		{
			return 0;
		}
		int best = 0;
		for (ItemRef p : game.searchItems(name))
		{
			if (p.name.equalsIgnoreCase(name.trim()) && (best == 0 || p.id < best))
			{
				best = p.id;
			}
		}
		if (best > 0)
		{
			ids.put(key, best);
			dirty = true;
		}
		return best;
	}

	/**
	 * The item's picture (filled in by the game a moment after it is returned, when {@code whenLoaded} is called), or null
	 * when the id is not known.
	 */
	public BufferedImage image(String name, Runnable whenLoaded)
	{
		int id = id(name);
		return id > 0 ? game.itemImage(id, whenLoaded) : null;
	}

	// ------------------------------------------------------------------ saved between sessions

	/**
	 * True when something was learned since the last {@link #snapshot()}.
	 */
	public boolean isDirty()
	{
		return dirty;
	}

	/**
	 * What to save: flattened name to id, in name order.
	 */
	public synchronized Map<String, Integer> snapshot()
	{
		dirty = false;
		return new TreeMap<>(ids);
	}

	public synchronized long scannedAt()
	{
		return scannedAt;
	}

	public synchronized void restore(Map<String, Integer> saved, long scannedAtMillis)
	{
		for (Map.Entry<String, Integer> e : saved.entrySet())
		{
			if (e.getKey() != null && e.getValue() != null && e.getValue() > 0)
			{
				ids.putIfAbsent(e.getKey(), e.getValue());
			}
		}
		this.scannedAt = scannedAtMillis;
	}

	// ------------------------------------------------------------------ scan

	/**
	 * Starts looking through the game's items for the given names.  Does nothing when a scan is running.
	 *
	 * @param names the item names the ledger knows
	 */
	public synchronized void startScan(Iterable<String> names)
	{
		if (scanNext >= 0)
		{
			return;
		}
		Set<String> want = new HashSet<>();
		for (String n : names)
		{
			String key = Names.flat(n);
			if (!key.isEmpty() && !ids.containsKey(key))
			{
				want.add(key);
			}
		}
		if (want.isEmpty())
		{
			return;
		}
		wanted = want;
		scanNext = 1;
	}

	public synchronized boolean isScanning()
	{
		return scanNext >= 0;
	}

	/**
	 * Looks at the next few item ids.  Call on the client thread, once per game tick.
	 *
	 * @param now the time in milliseconds, kept as the time of the last finished scan
	 * @return true when the scan finished with this call
	 */
	public synchronized boolean scanTick(long now)
	{
		if (scanNext < 0)
		{
			return false;
		}
		int end = Math.min(SCAN_LIMIT, scanNext + SCAN_PER_TICK);
		for (int id = scanNext; id < end && !wanted.isEmpty(); id++)
		{
			ItemInfo c = game.item(id);
			if (c == null || c.name == null || c.noted || c.placeholder)
			{
				continue;
			}
			String key = Names.flat(c.name);
			if (wanted.remove(key))
			{
				if (ids.putIfAbsent(key, id) == null)
				{
					dirty = true;
				}
			}
		}
		scanNext = end;
		if (end >= SCAN_LIMIT || wanted.isEmpty())
		{
			scanNext = -1;
			wanted = Collections.emptySet();
			scannedAt = now;
			dirty = true;
			return true;
		}
		return false;
	}
}

package com.dropluckledger.plugin;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.Filepath;
import net.runelite.http.api.item.ItemPrice;

/**
 * {@link Game} over the real client and RuneLite's services.  This and the plugin class are the only places that use them;
 * everything here is a one-line hand-over.
 */
public final class RuneLiteGame implements Game
{
	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final ConfigManager configManager;
	private final ChatMessageManager chatMessageManager;

	public RuneLiteGame(Client client, ClientThread clientThread, ItemManager itemManager, ConfigManager configManager, ChatMessageManager chatMessageManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.configManager = configManager;
		this.chatMessageManager = chatMessageManager;
	}

	// ------------------------------------------------------------------ the player

	@Override
	public long accountHash()
	{
		return client.getAccountHash();
	}

	@Override
	public boolean isLoggedIn()
	{
		return client.getGameState() == GameState.LOGGED_IN;
	}

	@Override
	public boolean isStandardWorld()
	{
		return RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.STANDARD;
	}

	@Override
	public String playerName()
	{
		Player player = client.getLocalPlayer();
		return player == null ? null : player.getName();
	}

	@Override
	public int tickCount()
	{
		return client.getTickCount();
	}

	@Override
	public int realLevel(Skill skill)
	{
		return client.getRealSkillLevel(skill);
	}

	@Override
	public int experience(Skill skill)
	{
		return client.getSkillExperience(skill);
	}

	// ------------------------------------------------------------------ the game's screens

	@Override
	public Node widget(int componentId)
	{
		return wrap(client.getWidget(componentId));
	}

	private static Node wrap(Widget widget)
	{
		return widget == null ? null : new WidgetNode(widget);
	}

	private static final class WidgetNode implements Node
	{
		private final Widget widget;

		WidgetNode(Widget widget)
		{
			this.widget = widget;
		}

		@Override
		public String text()
		{
			return widget.getText();
		}

		@Override
		public List<Node> children()
		{
			Widget[] children = widget.getChildren();
			if (children == null)
			{
				return null;
			}
			List<Node> out = new ArrayList<>(children.length);
			for (Widget child : children)
			{
				out.add(wrap(child));
			}
			return out;
		}

		@Override
		public Node child(int index)
		{
			return wrap(widget.getChild(index));
		}

		@Override
		public int itemId()
		{
			return widget.getItemId();
		}

		@Override
		public int itemQuantity()
		{
			return widget.getItemQuantity();
		}

		@Override
		public int opacity()
		{
			return widget.getOpacity();
		}
	}

	// ------------------------------------------------------------------ items

	@Override
	public ItemInfo item(int id)
	{
		try
		{
			ItemComposition c = itemManager.getItemComposition(id);
			return c == null ? null : new ItemInfo(c.getName(), c.getNote() != -1, c.getPlaceholderTemplateId() != -1);
		}
		catch (RuntimeException ex)
		{
			// ids the game has no item for
			return null;
		}
	}

	@Override
	public int canonicalItemId(int id)
	{
		return itemManager.canonicalize(id);
	}

	@Override
	public List<ItemRef> searchItems(String text)
	{
		List<ItemRef> out = new ArrayList<>();
		for (ItemPrice found : itemManager.search(text))
		{
			out.add(new ItemRef(found.getId(), found.getName()));
		}
		return out;
	}

	@Override
	public BufferedImage itemImage(int id, Runnable whenLoaded)
	{
		AsyncBufferedImage image = itemManager.getImage(id);
		if (image != null)
		{
			image.onLoaded(whenLoaded);
		}
		return image;
	}

	// ------------------------------------------------------------------ what other RuneLite plugins saved

	@Override
	public List<String> savedKeys(String group, String keyPrefix)
	{
		String profile = configManager.getRSProfileKey();
		return profile == null ? Collections.emptyList() : configManager.getRSProfileConfigurationKeys(group, profile, keyPrefix);
	}

	@Override
	public Integer savedInt(String group, String key)
	{
		return configManager.getRSProfileConfiguration(group, key, int.class);
	}

	@Override
	public String savedText(String group, String key)
	{
		return configManager.getRSProfileConfiguration(group, key);
	}

	// ------------------------------------------------------------------ chat, threads and files

	@Override
	public void gameMessage(String runeLiteFormattedMessage)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(runeLiteFormattedMessage)
			.build());
	}

	@Override
	public void invoke(Runnable task)
	{
		clientThread.invoke(task);
	}

	@Override
	public void invokeLater(Runnable task)
	{
		clientThread.invokeLater(task);
	}

	@Override
	public Filepath chooseFileToSave(Component parent, String title, String fileName, String description, String extension)
	{
		List<Filepath> files = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle(title)
			.setFileName(fileName)
			.addExtensionFilter(description, extension)
			.setDefaultExtension(extension)
			.showDialog(parent);
		return files == null || files.isEmpty() ? null : files.get(0);
	}

	@Override
	public Filepath chooseFileToOpen(Component parent, String title, String description, String extension)
	{
		List<Filepath> files = new Filepath.Chooser()
			.setIsOpen()
			.setAcceptsFiles()
			.setDialogTitle(title)
			.addExtensionFilter(description, extension)
			.showDialog(parent);
		return files == null || files.isEmpty() ? null : files.get(0);
	}
}

package com.dropluckledger.plugin;

/**
 * Whether the plugin is recording at the moment, and if not why not (shown at the top of the side panel).
 */
public enum TrackingState
{
	/**
	 * The boss data is still being read.
	 */
	STARTING("Loading the boss data..."),
	/**
	 * Nobody is logged in, so there is no ledger to show.
	 */
	LOGGED_OUT("Log in to see and record your ledger."),
	/**
	 * Logged in on a world that has its own separate save (a Leagues, Deadman, tournament or beta world).
	 */
	PAUSED("Paused: this kind of world has its own save, so it is not recorded in your ledger."),
	/**
	 * Logged in and the ledger is being read from disk.
	 */
	LOADING("Loading your ledger..."),
	/**
	 * Recording.
	 */
	TRACKING("");

	private final String message;

	TrackingState(String message)
	{
		this.message = message;
	}

	/**
	 * What to tell the player; empty while recording.
	 */
	public String message()
	{
		return message;
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Env;
import com.dropluckledger.engine.Engine;
import com.dropluckledger.engine.Engine.ItemMeta;
import com.dropluckledger.engine.Luck;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Drop;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.plugin.ItemIcons;
import java.text.Collator;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Works out what the panel shows from the ledger.  The luck maths can take a moment, so this is meant to run on a
 * background thread; one call at a time (the maths keeps working state that must not be shared).  Results are kept
 * for as long as the part of the ledger they came from has not changed.
 */
final class Analyzer
{
	private static final Logger log = LoggerFactory.getLogger(Analyzer.class);

	private static final int MODELS = 24;
	private static final int ANALYSES = 1500;
	private static final int EXTRAS = 600;
	/**
	 * Stands for "worked out, and there is nothing to show".
	 */
	private static final Object NONE = new Object();
	/**
	 * The rankings on the overview.
	 */
	static final int DRY = 5;
	static final int HOT = 5;
	/**
	 * Luck percentiles that count as dry (below the first) and lucky (from the second), the same lines as the labels.
	 */
	private static final double DRY_BELOW = 0.40;
	private static final double HOT_FROM = 0.60;
	/**
	 * Points on the chart.
	 */
	private static final int CHART_STEPS = 60;

	private final Ledger ledger;
	private final Data data;
	private final ItemIcons icons;
	private final Map<String, List<String>> logIndex;
	private final Map<String, Luck.Model> models = lru(MODELS);
	private final Map<String, Luck.ItemAnalysis> analyses = lru(ANALYSES);
	private final Map<String, Object> extras = lru(EXTRAS);

	Analyzer(Ledger ledger, ItemIcons icons)
	{
		this.ledger = ledger;
		this.data = ledger.data();
		this.icons = icons;
		this.logIndex = Catalog.logIndex(data);
	}

	private static <V> Map<String, V> lru(int max)
	{
		return new LinkedHashMap<String, V>(16, 0.75f, true)
		{
			private static final long serialVersionUID = 1L;

			@Override
			protected boolean removeEldestEntry(Map.Entry<String, V> eldest)
			{
				return size() > max;
			}
		};
	}

	/**
	 * Bosses whose collection log lists the item.
	 */
	List<String> bossesWith(String item)
	{
		List<String> l = logIndex.get(item);
		return l == null ? Collections.<String>emptyList() : l;
	}

	boolean shared(String item)
	{
		return bossesWith(item).size() > 1;
	}

	// ------------------------------------------------------------------ the maths, kept while nothing changes

	private Luck.Model model(String id, long rev)
	{
		String key = id + '|' + rev;
		Luck.Model m = models.get(key);
		if (m == null)
		{
			m = Luck.makeModel(data.boss(id), ledger.record(id), ledger.globals());
			models.put(key, m);
		}
		return m;
	}

	private Luck.ItemAnalysis analysis(String id, long rev, String name, int window)
	{
		String key = id + '|' + rev + '|' + name + '|' + window;
		Luck.ItemAnalysis a = analyses.get(key);
		if (a == null)
		{
			try
			{
				a = Luck.analyse(model(id, rev), name, window);
			}
			catch (RuntimeException ex)
			{
				log.warn("Could not work out {} at {}", name, id, ex);
				return null;
			}
			analyses.put(key, a);
		}
		return a;
	}

	private Views.AnyView anyUnique(String id, long rev, List<String> tracked, int window)
	{
		String key = "U|" + id + '|' + rev + '|' + window;
		Object c = extras.get(key);
		if (c != null)
		{
			return c == NONE ? null : (Views.AnyView) c;
		}
		Boss boss = data.boss(id);
		Catalog.AnyNames an = Catalog.anyNames(boss, tracked);
		Views.AnyView out = null;
		if (an.names.size() >= 2)
		{
			try
			{
				Luck.AnyUnique u = Luck.anyUnique(model(id, rev), an.names, window);
				if (u != null)
				{
					out = new Views.AnyView(u, an.names, an.sep, hasGold(boss, an.names));
				}
			}
			catch (RuntimeException ex)
			{
				log.warn("Could not work out the unique table of {}", id, ex);
			}
		}
		extras.put(key, out == null ? NONE : out);
		return out;
	}

	private static boolean hasGold(Boss boss, List<String> names)
	{
		Map<String, ItemMeta> m = boss.meta();
		for (String n : names)
		{
			ItemMeta im = m.get(n);
			if (im == null || im.seq == null)
			{
				continue;
			}
			for (ItemMeta other : m.values())
			{
				if (other.hidden && other.seq != null && other.seq.slot.equals(im.seq.slot))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * The figures for an item that several bosses drop, pooled over the bosses the player has kills at.  Null when fewer than
	 * two such bosses, or when the selected boss is not one of them.
	 */
	private Luck.Pool pool(String name, String selected, int window)
	{
		List<String> ids = new ArrayList<>();
		for (String i : bossesWith(name))
		{
			if (ledger.kc(i) > 0)
			{
				ids.add(i);
			}
		}
		if (ids.size() < 2 || !ids.contains(selected))
		{
			return null;
		}
		StringBuilder k = new StringBuilder("P|").append(name).append('|').append(window);
		Map<String, Long> revs = new LinkedHashMap<>();
		for (String i : ids)
		{
			long r = ledger.revision(i);
			revs.put(i, r);
			k.append('|').append(i).append(':').append(r);
		}
		String key = k.toString();
		Object c = extras.get(key);
		if (c != null)
		{
			return c == NONE ? null : (Luck.Pool) c;
		}
		// the most recent receipt (counted in kills) decides where each boss's streak starts
		Map<String, Integer> bestStart = null;
		int bestTotal = -1;
		for (String i : ids)
		{
			for (Drop d : ledger.copyOf(i).drops)
			{
				if (!name.equals(d.item) || d.kc == null)
				{
					continue;
				}
				Map<String, Integer> start = new LinkedHashMap<>();
				int total = 0;
				for (String j : ids)
				{
					int s = j.equals(i) ? d.kc : (d.snap != null && d.snap.get(j) != null ? d.snap.get(j) : 0);
					start.put(j, s);
					total += s;
				}
				if (bestStart == null || total > bestTotal)
				{
					bestStart = start;
					bestTotal = total;
				}
			}
		}
		List<Luck.PoolMember> members = new ArrayList<>();
		for (String i : ids)
		{
			int snap = bestStart == null ? 0 : Math.min(bestStart.getOrDefault(i, 0), ledger.kc(i));
			members.add(new Luck.PoolMember(model(i, revs.get(i)), snap));
		}
		Luck.Pool out = null;
		try
		{
			out = Luck.analysePool(members, name, window);
		}
		catch (RuntimeException ex)
		{
			log.warn("Could not pool {}", name, ex);
		}
		extras.put(key, out == null ? NONE : out);
		return out;
	}

	// ------------------------------------------------------------------ a boss page

	/**
	 * The tracker tab of a boss; null when cancelled.
	 */
	synchronized Views.BossView boss(String id, BooleanSupplier cancelled)
	{
		Boss boss = data.boss(id);
		if (boss == null)
		{
			return null;
		}
		final long rev = ledger.revision(id);
		final int window = ledger.prefs().window;
		final BossState st = ledger.copyOf(id);
		final List<String> names = ledger.trackedNames(id);
		final Map<String, ItemMeta> meta = boss.meta();
		List<Views.ItemView> items = new ArrayList<>();
		for (String n : names)
		{
			if (cancelled.getAsBoolean())
			{
				return null;
			}
			ItemMeta m = meta.get(n);
			Luck.ItemAnalysis a = analysis(id, rev, n, window);
			Luck.Pool p = a != null ? pool(n, id, window) : null;
			String kind = Catalog.kindOf(boss, n);
			items.add(new Views.ItemView(n, kind.equals("other") ? "drop" : kind, m, a, p, shared(n)));
			if (icons != null)
			{
				icons.id(n);
			}
		}
		Views.AnyView any = st.kc > 0 ? anyUnique(id, rev, names, window) : null;
		Collator collator = Collator.getInstance(Locale.ENGLISH);
		List<String> addable = new ArrayList<>();
		Set<String> shown = new HashSet<>(names);
		for (Map.Entry<String, ItemMeta> e : meta.entrySet())
		{
			if (!shown.contains(e.getKey()) && !e.getValue().hidden)
			{
				addable.add(e.getKey());
			}
		}
		addable.sort(collator);
		if (icons != null)
		{
			for (Drop d : st.drops)
			{
				icons.id(d.item);
			}
		}
		return new Views.BossView(id, rev, st.kc, window, items, any, st, addable);
	}

	// ------------------------------------------------------------------ the overview

	/**
	 * The overview page; null when cancelled.
	 */
	synchronized Views.OverviewView overview(BooleanSupplier cancelled)
	{
		final int window = ledger.prefs().window;
		final long overall = ledger.revision();
		List<String> ids = ledger.activeBosses();
		List<Views.Rank> rows = new ArrayList<>();
		Set<String> ranked = new HashSet<>();
		List<Views.BossRow> bosses = new ArrayList<>();
		for (String id : ids)
		{
			if (cancelled.getAsBoolean())
			{
				return null;
			}
			Boss boss = data.boss(id);
			long rev = ledger.revision(id);
			BossState st = ledger.copyOf(id);
			List<String> names = ledger.trackedNames(id);
			if (st.kc > 0)
			{
				for (String n : names)
				{
					Luck.ItemAnalysis a = analysis(id, rev, n, window);
					if (a == null || a.collected || !(a.pNext > 0))
					{
						continue;
					}
					// an item several bosses drop is one line, with the luck of all of them together
					Luck.Pool p = shared(n) ? pool(n, id, window) : null;
					if (p != null)
					{
						if (ranked.add(n) && !Double.isNaN(p.pct))
						{
							rows.add(rankOf(p));
						}
					}
					else if (a.pct != null && a.expected != null && a.another != null)
					{
						rows.add(new Views.Rank(id, boss.name, n, a.O, a.expected, a.pct, a.another, a.label, false));
					}
					if (icons != null)
					{
						icons.id(n);
					}
				}
			}
			Set<String> have = new HashSet<>();
			for (Drop d : st.drops)
			{
				have.add(d.item);
			}
			int got = 0;
			Set<String> logNames = boss.logSet();
			for (String n : logNames)
			{
				if (have.contains(n))
				{
					got++;
				}
			}
			Views.AnyView any = st.kc > 0 ? anyUnique(id, rev, names, window) : null;
			bosses.add(new Views.BossRow(id, boss.name, st.kc, got, logNames.size(), any == null ? null : any.u, st.u));
		}
		List<Views.Rank> dry = new ArrayList<>();
		List<Views.Rank> lucky = new ArrayList<>();
		for (Views.Rank r : rows)
		{
			if (r.expected >= 0.5 && r.pct < DRY_BELOW)
			{
				dry.add(r);
			}
			if (r.got > 0 && r.pct >= HOT_FROM)
			{
				lucky.add(r);
			}
		}
		dry.sort(Comparator.comparingDouble((Views.Rank r) -> r.pct));
		lucky.sort(Comparator.comparingDouble((Views.Rank r) -> r.pct).reversed());
		bosses.sort(Comparator.comparingLong((Views.BossRow b) -> b.updated).reversed().thenComparing(b -> b.name, String.CASE_INSENSITIVE_ORDER));
		List<Luck.Pool> pooled = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		for (String id : ids)
		{
			if (cancelled.getAsBoolean())
			{
				return null;
			}
			for (String n : ledger.trackedNames(id))
			{
				if (!shared(n) || !seen.add(n))
				{
					continue;
				}
				Luck.Pool p = pool(n, id, window);
				if (p != null)
				{
					pooled.add(p);
				}
			}
		}
		pooled.sort(Comparator.comparingDouble((Luck.Pool p) -> p.pct));
		return new Views.OverviewView(overall, ids.size(), top(dry, DRY), top(lucky, HOT), bosses, pooled);
	}

	/**
	 * A ranking line for an item pooled over several bosses; it opens the boss the player has the most kills at.
	 */
	private static Views.Rank rankOf(Luck.Pool p)
	{
		Luck.PoolPer main = p.per.get(0);
		for (Luck.PoolPer x : p.per)
		{
			if (x.K > main.K)
			{
				main = x;
			}
		}
		String where = main.name + (p.per.size() > 1 ? " +" + (p.per.size() - 1) + " more" : "");
		return new Views.Rank(main.id, where, p.name, p.O, p.expected, p.pct, p.another, p.label, true);
	}

	private static <T> List<T> top(List<T> l, int n)
	{
		return new ArrayList<>(l.subList(0, Math.min(n, l.size())));
	}

	// ------------------------------------------------------------------ the drop table

	synchronized Views.TableView table(String id)
	{
		Boss boss = data.boss(id);
		if (boss == null)
		{
			return null;
		}
		Map<String, Object> vals = ledger.currentParams(id);
		Env env = Engine.makeEnv(boss, vals, ledger.globals(), Math.max(0, ledger.kc(id)));
		Map<String, Engine.ItemProb> probs = Engine.itemProbs(boss, env, null, null);
		Map<String, Views.RowInfo> info = Views.rowInfo(boss);
		Map<String, ItemMeta> meta = boss.meta();
		Set<String> logNames = boss.logSet();
		List<Views.TableRow> rows = new ArrayList<>();
		for (Map.Entry<String, Engine.ItemProb> e : probs.entrySet())
		{
			String n = e.getKey();
			Views.RowInfo ri = info.get(n);
			ItemMeta m = meta.get(n);
			boolean notable = m != null && (m.isUnique() || m.isPet()) || logNames.contains(n);
			rows.add(new Views.TableRow(n, e.getValue().p, ri == null ? "" : ri.qty, ri == null ? new ArrayList<String>() : ri.rates,
				ri == null ? new ArrayList<String>() : ri.where, logNames.contains(n), notable));
			if (icons != null)
			{
				icons.id(n);
			}
		}
		rows.sort(Comparator.comparingDouble((Views.TableRow r) -> r.p).reversed());
		return new Views.TableView(id, boss.always, rows);
	}

	// ------------------------------------------------------------------ the chart

	/**
	 * The curve behind an item card: the chance of getting it within a number of kills after the last copy.
	 */
	synchronized Views.ChartData chart(String id, String item)
	{
		Boss boss = data.boss(id);
		if (boss == null)
		{
			return null;
		}
		final long rev = ledger.revision(id);
		final int window = ledger.prefs().window;
		Luck.ItemAnalysis a = analysis(id, rev, item, window);
		if (a == null)
		{
			return null;
		}
		Luck.Model m = model(id, rev);
		String nm = a.seq != null ? slotFirst(boss, a.seq.slot) : item;
		if (nm == null)
		{
			nm = item;
		}
		final int d = a.need;
		final int from = a.streakFrom;
		double xmax = Math.max(30, a.streak * 1.3);
		if (a.kto != null)
		{
			Double k99 = a.kto.get(0.99);
			if (k99 != null && !Double.isInfinite(k99) && !Double.isNaN(k99))
			{
				xmax = Math.max(xmax, a.streak + k99);
			}
		}
		xmax = Math.min(xmax, 3e6);
		double[] xs = new double[CHART_STEPS + 1];
		double[] ys = new double[CHART_STEPS + 1];
		for (int i = 0; i <= CHART_STEPS; i++)
		{
			int x = (int) Math.round(xmax * i / CHART_STEPS);
			xs[i] = x;
			ys[i] = x == 0 ? 0 : Luck.atLeast(d, m.runsFor(nm, from + 1, from + x));
		}
		return new Views.ChartData(item, xs, ys, xmax, a.streak);
	}

	private static String slotFirst(Boss boss, String slot)
	{
		for (Data.Table t : boss.tables)
		{
			for (Data.Row r : t.items)
			{
				if (r.seq != null && r.seq.slot.equals(slot))
				{
					return r.name;
				}
			}
		}
		return null;
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.engine.Luck;
import java.awt.BorderLayout;
import java.awt.Color;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

/**
 * "Any unique": how lucky the player has been with the boss's uniques as a whole (or with its unique table, where the boss rolls
 * the rest separately).  One compact row like an item card; the details are in the tooltip.
 */
@SuppressWarnings("serial")
final class AnyCard extends Column
{
	private final Meter meter = new Meter(5);

	AnyCard(Views.AnyView any)
	{
		super(3, true);
		setBackground(Look.CARD);
		setBorder(javax.swing.BorderFactory.createCompoundBorder(javax.swing.BorderFactory.createLineBorder(Look.GOLD, 1), Look.pad(4, 6, 4, 6)));
		final Luck.AnyUnique u = any.u;
		final boolean table = any.isTable();
		final boolean known = !Double.isNaN(u.pct) && u.label != null && !"na".equals(u.label.key);
		final Color color = known ? Look.luck(u.label.key) : Look.MUTED;
		final Color barColor = Look.chance(u.another);

		JPanel top = new JPanel(new BorderLayout(6, 0));
		top.setOpaque(false);
		JLabel name = Look.wrapped("<b>" + (table ? "Unique table" : "Any unique") + "</b> " + Look.dim(any.names.size() + " items"), Look.CARD_TEXT - 60,
			Look.body(), Look.TEXT);
		top.add(name, BorderLayout.CENTER);
		JLabel pc = Look.label(Fmt.pct(u.another), Look.bold().deriveFont(Look.bold().getSize2D() + 2f), barColor);
		pc.setHorizontalAlignment(SwingConstants.RIGHT);
		top.add(pc, BorderLayout.EAST);
		add(top);

		meter.set(u.another, barColor);
		add(meter);

		JPanel sub = new JPanel(new BorderLayout(4, 0));
		sub.setOpaque(false);
		sub.add(Look.label(Fmt.rate(u.pNext) + " · " + u.O + " vs " + Fmt.expected(u.expected) + " expected", Look.small(), Look.MUTED), BorderLayout.CENTER);
		if (known)
		{
			sub.add(Look.label(u.label.text, Look.small(), color), BorderLayout.EAST);
		}
		add(sub);
		setToolTipText(tip(any, table, known));
	}

	private static String tip(Views.AnyView any, boolean table, boolean known)
	{
		Luck.AnyUnique u = any.u;
		StringBuilder b = new StringBuilder("<b>").append(table ? "Unique table" : "Any unique").append("</b><br>").append(Look.esc(describe(any, table)));
		b.append("<br><b>").append(Fmt.pct(u.another)).append("</b> chance of ").append(u.O > 0 ? "another " + (table ? "table hit" : "unique") : "one")
			.append(" by now, from all your kills. ").append(Look.dim("Kills past the rate carry over to the next one."));
		b.append("<br>Per kill: ").append(Look.esc(Fmt.rate(u.pNext)));
		b.append("<br>").append(table ? "Table hits" : "Uniques").append(": ").append(u.O).append(" vs ").append(Fmt.expected(u.expected)).append(" expected");
		if (known)
		{
			b.append("<br>Luck: ").append(Look.colored("<b>" + Look.esc(u.label.text) + "</b>", Look.luck(u.label.key))).append(" · luckier than ")
				.append(Fmt.pct(u.pct)).append(" of players with the same kills");
		}
		b.append("<br>Chance of 1+ in all your kills: ").append(Fmt.pct(u.cum));
		b.append("<br>Next ").append(u.window).append(" kills: ").append(Fmt.pct(u.fwd.get(u.window)));
		if (u.streakKnown)
		{
			b.append("<br>Dry streak: ").append(Fmt.num(u.streak)).append(" kills since your last (").append(Fmt.pct(u.meter)).append(" would have had another)");
		}
		else
		{
			b.append("<br>Dry streak: not known, because your last ").append(table ? "table hit" : "unique").append(" has no kill number.");
		}
		return Look.tip(b.toString());
	}

	private static String describe(Views.AnyView any, boolean table)
	{
		List<String> shown = any.names.subList(0, Math.min(6, any.names.size()));
		String list = String.join(", ", shown) + (any.names.size() > 6 ? "…" : "");
		if (table)
		{
			return "Chance of hitting the unique table: " + list + ". "
				+ (any.gold ? "The vestige slot counts on every one of its rolls (the first two drop gold rings, the third the vestige). " : "")
				+ String.join(", ", any.separate) + (any.separate.size() > 1 ? " are" : " is") + " rolled separately and has its own card.";
		}
		return "At least one of: " + list + ".";
	}
}

