package com.dropluckledger.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/**
 * The curve of the chance of getting a drop within a number of kills after the last one, with a line where the player is now.
 */
@SuppressWarnings("serial")
final class CurveChart extends JComponent
{
	private static final int LEFT = 30;
	private static final int RIGHT = 6;
	private static final int TOP = 8;
	private static final int BOTTOM = 16;

	private Views.ChartData data;

	CurveChart()
	{
		setOpaque(false);
		setFont(Look.small());
		setPreferredSize(new Dimension(Look.CARD_TEXT, 110));
	}

	void set(Views.ChartData d)
	{
		this.data = d;
		repaint();
	}

	boolean hasData()
	{
		return data != null;
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		Views.ChartData d = data;
		if (d == null)
		{
			return;
		}
		Graphics2D g = (Graphics2D) g0.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setFont(getFont());
			FontMetrics fm = g.getFontMetrics();
			int w = getWidth();
			int h = getHeight();
			int pw = w - LEFT - RIGHT;
			int ph = h - TOP - BOTTOM;
			// horizontal guides
			double[] marks = {0, 0.5, 0.9, 1};
			for (double y : marks)
			{
				int py = TOP + (int) Math.round(ph * (1 - y));
				g.setColor(y == 0 || y == 1 ? Look.LINE : new Color(255, 255, 255, 40));
				if (y != 0 && y != 1)
				{
					g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[] {2f, 3f}, 0f));
				}
				else
				{
					g.setStroke(new BasicStroke(1f));
				}
				g.drawLine(LEFT, py, w - RIGHT, py);
				if (y < 1)
				{
					g.setColor(Look.MUTED);
					String t = Math.round(y * 100) + "%";
					g.drawString(t, LEFT - 3 - fm.stringWidth(t), py + fm.getAscent() / 2 - 1);
				}
			}
			g.setStroke(new BasicStroke(1f));
			// distances along the bottom
			for (int i = 0; i <= 2; i++)
			{
				double x = d.xmax * i / 2;
				String t = Fmt.num(x);
				int px = LEFT + (int) Math.round(pw * i / 2.0);
				int tx = i == 0 ? px : i == 2 ? px - fm.stringWidth(t) : px - fm.stringWidth(t) / 2;
				g.setColor(Look.MUTED);
				g.drawString(t, tx, h - 3);
			}
			// the curve
			if (d.x.length > 1 && d.xmax > 0)
			{
				Path2D.Double line = new Path2D.Double();
				Path2D.Double area = new Path2D.Double();
				for (int i = 0; i < d.x.length; i++)
				{
					double px = LEFT + pw * d.x[i] / d.xmax;
					double py = TOP + ph * (1 - d.y[i]);
					if (i == 0)
					{
						line.moveTo(px, py);
						area.moveTo(px, TOP + ph);
						area.lineTo(px, py);
					}
					else
					{
						line.lineTo(px, py);
						area.lineTo(px, py);
					}
				}
				area.lineTo(LEFT + pw, TOP + ph);
				area.closePath();
				g.setColor(new Color(Look.BLUE.getRed(), Look.BLUE.getGreen(), Look.BLUE.getBlue(), 45));
				g.fill(area);
				g.setColor(Look.BLUE);
				g.setStroke(new BasicStroke(1.6f));
				g.draw(line);
			}
			// where the player is
			if (d.xmax > 0)
			{
				int px = LEFT + (int) Math.round(pw * Math.min(1.0, d.you / d.xmax));
				g.setColor(Look.EMBER);
				g.setStroke(new BasicStroke(1.5f));
				g.drawLine(px, TOP, px, TOP + ph);
				String t = "you: " + Fmt.num(d.you);
				int tx = Math.min(px + 4, w - RIGHT - fm.stringWidth(t));
				g.drawString(t, Math.max(LEFT, tx), TOP + fm.getAscent());
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.dropluckledger.ui;

import java.awt.Component;
import javax.swing.JComponent;
import javax.swing.JOptionPane;

/**
 * The questions the panel asks in windows of their own.  A separate type so that the panel can be tried without a screen.
 */
interface Dialogs
{
	/**
	 * Shows a form with an OK and a Cancel button.
	 *
	 * @return true when OK was chosen
	 */
	boolean form(Component parent, String title, JComponent form, String ok);

	/**
	 * A question with a yes and a no.
	 */
	boolean confirm(Component parent, String title, String message, String yes);

	/**
	 * A question with several answers.
	 *
	 * @return the index of the chosen option, or -1 when the window was closed
	 */
	int choose(Component parent, String title, String message, String... options);

	/**
	 * A note with an OK button.
	 */
	void note(Component parent, String title, String message);

	/**
	 * The real windows.
	 */
	final class Swing implements Dialogs
	{
		@Override
		public boolean form(Component parent, String title, JComponent form, String ok)
		{
			Object[] options = {ok, "Cancel"};
			int r = JOptionPane.showOptionDialog(parent, form, title, JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null, options, options[0]);
			return r == 0;
		}

		@Override
		public boolean confirm(Component parent, String title, String message, String yes)
		{
			Object[] options = {yes, "Cancel"};
			int r = JOptionPane.showOptionDialog(parent, message, title, JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]);
			return r == 0;
		}

		@Override
		public int choose(Component parent, String title, String message, String... options)
		{
			return JOptionPane.showOptionDialog(parent, message, title, JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE, null, options, options[0]);
		}

		@Override
		public void note(Component parent, String title, String message)
		{
			JOptionPane.showMessageDialog(parent, message, title, JOptionPane.INFORMATION_MESSAGE);
		}
	}
}

package com.dropluckledger.ui;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Locale;

/**
 * Number formatting for the panel.  It prints exactly what the web app prints for the same number.
 */
final class Fmt
{
	private static final String[] SUFFIX = {"th", "st", "nd", "rd"};

	private Fmt()
	{
	}

	/**
	 * Like JavaScript's toFixed: the exact value of the number, rounded half up.
	 */
	static String fixed(double x, int digits)
	{
		return new BigDecimal(x).setScale(digits, RoundingMode.HALF_UP).toPlainString();
	}

	/**
	 * A whole number with thousands separators ("1,234"); the infinity sign for an endless wait.
	 */
	static String num(double n)
	{
		if (Double.isNaN(n))
		{
			return "NaN";
		}
		if (Double.isInfinite(n))
		{
			return n > 0 ? "∞" : "-∞";
		}
		return String.format(Locale.US, "%,d", Math.round(n));
	}

	/**
	 * A chance as a percentage: "0%", "<0.1%", "4.5%", "38%", "99.6%", ">99.9%"; a dash when there is none.
	 */
	static String pct(Double p)
	{
		if (p == null || Double.isNaN(p))
		{
			return "—";
		}
		if (p <= 0)
		{
			return "0%";
		}
		if (p < 0.001)
		{
			return "<0.1%";
		}
		if (p > 0.9995)
		{
			return ">99.9%";
		}
		if (p < 0.1 || p > 0.99)
		{
			return fixed(p * 100, 1) + "%";
		}
		return Math.round(p * 100) + "%";
	}

	/**
	 * A per-kill chance as "1/128", "every kill" or a dash.
	 */
	static String rate(double p)
	{
		if (!(p > 0))
		{
			return "—";
		}
		double x = 1 / p;
		if (x < 1.05)
		{
			return "every kill";
		}
		if (x < 10)
		{
			return "1/" + fixed(x, 2).replaceAll("\\.?0+$", "");
		}
		if (x < 100)
		{
			return "1/" + fixed(x, 1).replaceAll("\\.0$", "");
		}
		return "1/" + num(x);
	}

	/**
	 * "1st", "22nd", "99th": a percentile, kept between 1 and 99.
	 */
	static String ord(double n)
	{
		int v = (int) Math.min(99, Math.max(1, Math.round(n)));
		int m = v % 100;
		int k = m - 20;
		String s;
		if (k >= 0 && k % 10 >= 1 && k % 10 <= 3)
		{
			s = SUFFIX[k % 10];
		}
		else if (m >= 1 && m <= 3)
		{
			s = SUFFIX[m];
		}
		else
		{
			s = SUFFIX[0];
		}
		return v + s;
	}

	/**
	 * A count of expected copies: two decimals under 10, one above.
	 */
	static String expected(double e)
	{
		return e < 10 ? fixed(e, 2) : fixed(e, 1);
	}
}

package com.dropluckledger.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.util.function.Consumer;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

/**
 * A heading that opens and closes the part under it.
 */
@SuppressWarnings("serial")
final class Fold extends Column
{
	private final JButton head;
	private final JComponent body;
	private final JComponent always;
	private final Consumer<Boolean> onToggle;
	private boolean open;

	Fold(String title, boolean open, Consumer<Boolean> onToggle, JComponent body)
	{
		this(title, open, onToggle, null, body);
	}

	/**
	 * @param always a part shown under the heading while the fold is closed, such as a summary of what is inside (may be null)
	 */
	Fold(String title, boolean open, Consumer<Boolean> onToggle, JComponent always, JComponent body)
	{
		super(4);
		this.onToggle = onToggle;
		this.body = body;
		this.always = always;
		head = new JButton(title);
		head.setFont(Look.body());
		head.setForeground(Look.TEXT);
		head.setBorderPainted(false);
		head.setContentAreaFilled(false);
		head.setFocusPainted(false);
		head.setHorizontalAlignment(SwingConstants.LEFT);
		head.setMargin(new java.awt.Insets(1, 0, 1, 0));
		head.setIconTextGap(6);
		head.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		head.addActionListener(e -> set(!this.open, true));
		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(head, BorderLayout.CENTER);
		add(top);
		if (always != null)
		{
			add(always);
		}
		add(body);
		set(open, false);
	}

	private void set(boolean open, boolean notify)
	{
		this.open = open;
		head.setIcon(Glyph.of(open ? Glyph.Kind.DOWN : Glyph.Kind.RIGHT));
		body.setVisible(open);
		if (always != null)
		{
			always.setVisible(!open);
		}
		revalidate();
		repaint();
		if (notify && onToggle != null)
		{
			onToggle.accept(open);
		}
	}

	boolean isOpen()
	{
		return open;
	}

	Component header()
	{
		return head;
	}
}

package com.dropluckledger.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/**
 * Small drawn symbols, so that nothing depends on which characters a font has.
 */
final class Glyph implements Icon
{
	enum Kind
	{
		RIGHT, DOWN, LEFT, CROSS
	}

	private final Kind kind;
	private final Color color;
	private final int size;

	private Glyph(Kind kind, Color color, int size)
	{
		this.kind = kind;
		this.color = color;
		this.size = size;
	}

	static Glyph of(Kind kind, Color color)
	{
		return new Glyph(kind, color, 10);
	}

	static Glyph of(Kind kind)
	{
		return new Glyph(kind, Look.MUTED, 10);
	}

	Kind kind()
	{
		return kind;
	}

	@Override
	public void paintIcon(Component c, Graphics g0, int x, int y)
	{
		Graphics2D g = (Graphics2D) g0.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.translate(x, y);
			g.setColor(color);
			double s = size;
			Path2D.Double p = new Path2D.Double();
			switch (kind)
			{
				case RIGHT:
					p.moveTo(s * 0.3, s * 0.15);
					p.lineTo(s * 0.8, s * 0.5);
					p.lineTo(s * 0.3, s * 0.85);
					p.closePath();
					g.fill(p);
					break;
				case DOWN:
					p.moveTo(s * 0.15, s * 0.3);
					p.lineTo(s * 0.85, s * 0.3);
					p.lineTo(s * 0.5, s * 0.8);
					p.closePath();
					g.fill(p);
					break;
				case LEFT:
					g.setStroke(new java.awt.BasicStroke(1.8f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));
					p.moveTo(s * 0.65, s * 0.15);
					p.lineTo(s * 0.3, s * 0.5);
					p.lineTo(s * 0.65, s * 0.85);
					g.draw(p);
					break;
				case CROSS:
				default:
					g.setStroke(new java.awt.BasicStroke(1.6f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));
					g.drawLine((int) (s * 0.25), (int) (s * 0.25), (int) (s * 0.75), (int) (s * 0.75));
					g.drawLine((int) (s * 0.75), (int) (s * 0.25), (int) (s * 0.25), (int) (s * 0.75));
					break;
			}
		}
		finally
		{
			g.dispose();
		}
	}

	@Override
	public int getIconWidth()
	{
		return size;
	}

	@Override
	public int getIconHeight()
	{
		return size;
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.history.HistoryPlanner;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTable;
import javax.swing.table.AbstractTableModel;

/**
 * Shows what the game's records would add to the ledger, with a tick for each line, before anything is added.
 */
@SuppressWarnings("serial")
final class HistoryForm extends JPanel
{
	private final HistoryPlanner.Plan plan;
	private final JLabel summary = new JLabel();
	private final KcModel kcModel;
	private final ItemModel itemModel;
	private final JTable kcTable;
	private final JTable itemTable;

	HistoryForm(HistoryPlanner.Plan plan)
	{
		super(new BorderLayout(0, 6));
		this.plan = plan;
		setPreferredSize(new Dimension(560, 440));

		JPanel top = new JPanel();
		top.setLayout(new javax.swing.BoxLayout(top, javax.swing.BoxLayout.Y_AXIS));
		JLabel from = new JLabel(Look.html(520, "Read from: " + Look.esc(String.join(", ", plan.sources))
			+ ".<br>The game does not record which kill each old drop came on, so items come in without a kill number. They count towards "
			+ "your luck right away (the kills you have made against the copies you own); no dry streak is shown for an item until you edit that drop "
			+ "and add its kill number. Items that drop in stacks (bolt racks, frozen tears) are turned into an estimated number of drops, marked ~."));
		from.setFont(Look.small());
		top.add(from);
		add(top, BorderLayout.NORTH);

		kcModel = new KcModel(plan.kc);
		kcTable = table(kcModel, new int[] {24, 190, 80, 80, 140});
		itemModel = new ItemModel(plan.items);
		itemTable = table(itemModel, new int[] {24, 140, 90, 130, 55, 45});

		JPanel center = new JPanel();
		center.setLayout(new javax.swing.BoxLayout(center, javax.swing.BoxLayout.Y_AXIS));
		center.add(heading("Kill counts", kcModel, plan.kc.size()));
		center.add(new JScrollPane(kcTable));
		center.add(javax.swing.Box.createVerticalStrut(8));
		center.add(heading("Items you own", itemModel, plan.items.size()));
		center.add(new JScrollPane(itemTable));
		add(center, BorderLayout.CENTER);

		JPanel bottom = new JPanel();
		bottom.setLayout(new javax.swing.BoxLayout(bottom, javax.swing.BoxLayout.Y_AXIS));
		summary.setFont(Look.body());
		bottom.add(summary);
		String left = leftOut(plan);
		if (!left.isEmpty())
		{
			JLabel l = new JLabel(Look.html(520, left));
			l.setFont(Look.small());
			bottom.add(l);
		}
		add(bottom, BorderLayout.SOUTH);
		refreshSummary();
	}

	private static String leftOut(HistoryPlanner.Plan p)
	{
		StringBuilder b = new StringBuilder();
		if (!p.kcSkipped.isEmpty())
		{
			b.append("Not used: ").append(Look.esc(String.join(" · ", p.kcSkipped.subList(0, Math.min(25, p.kcSkipped.size())))));
			if (p.kcSkipped.size() > 25)
			{
				b.append(" …");
			}
			b.append(" (other activities, other modes of a boss, or bosses not in the ledger).<br>");
		}
		if (!p.itemsMissing.isEmpty())
		{
			b.append("Collection log items that are not tracked here: ").append(Look.esc(String.join(" · ", p.itemsMissing.subList(0, Math.min(25, p.itemsMissing.size())))));
			if (p.itemsMissing.size() > 25)
			{
				b.append(" …");
			}
		}
		return b.toString();
	}

	private JTable table(AbstractTableModel m, int[] widths)
	{
		JTable t = new JTable(m);
		t.setFillsViewportHeight(true);
		t.setRowHeight(t.getRowHeight() + 2);
		t.setPreferredScrollableViewportSize(new Dimension(520, 120));
		for (int i = 0; i < widths.length; i++)
		{
			t.getColumnModel().getColumn(i).setPreferredWidth(widths[i]);
		}
		t.getColumnModel().getColumn(0).setMaxWidth(30);
		m.addTableModelListener(e -> refreshSummary());
		return t;
	}

	private JPanel heading(String title, AbstractTableModel model, int rows)
	{
		JPanel p = new JPanel(new BorderLayout());
		JLabel l = new JLabel(title + " (" + rows + ")");
		l.setFont(Look.bold());
		p.add(l, BorderLayout.WEST);
		JCheckBox all = new JCheckBox("Tick all");
		all.setFont(Look.small());
		all.setSelected(true);
		all.addActionListener(e ->
		{
			if (model instanceof KcModel)
			{
				((KcModel) model).setAll(all.isSelected());
			}
			else
			{
				((ItemModel) model).setAll(all.isSelected());
			}
		});
		p.add(all, BorderLayout.EAST);
		p.setMaximumSize(new Dimension(Short.MAX_VALUE, p.getPreferredSize().height));
		return p;
	}

	private void refreshSummary()
	{
		int k = plan.kcToApply();
		int rows = plan.itemRowsToApply();
		int c = plan.copiesToAdd();
		int back = plan.copiesToRemove();
		List<String> parts = new ArrayList<>();
		if (k > 0)
		{
			parts.add(k + " kill count" + (k == 1 ? "" : "s"));
		}
		if (c > 0)
		{
			parts.add(c + " owned item" + (c == 1 ? "" : "s") + " (" + rows + " line" + (rows == 1 ? "" : "s") + ")");
		}
		String text = parts.isEmpty() ? "" : "Will add: " + String.join(" and ", parts);
		if (back > 0)
		{
			text += (text.isEmpty() ? "" : ". ") + "Will take back " + back + " item" + (back == 1 ? "" : "s") + " an earlier import counted too many times";
		}
		summary.setText(text.isEmpty() ? "Nothing is ticked." : text);
	}

	HistoryPlanner.Plan plan()
	{
		return plan;
	}

	JLabel summaryLabel()
	{
		return summary;
	}

	/**
	 * Sets the tick of a kill count line (for tests).
	 */
	void tickKc(int row, boolean on)
	{
		kcModel.setValueAt(on, row, 0);
	}

	void tickItem(int row, boolean on)
	{
		itemModel.setValueAt(on, row, 0);
	}

	// ------------------------------------------------------------------ the two lists

	@SuppressWarnings("serial")
	private static final class KcModel extends AbstractTableModel
	{
		private static final String[] COLUMNS = {"", "Boss", "In game", "In ledger", "Result"};
		private final List<HistoryPlanner.KcRow> rows;

		KcModel(List<HistoryPlanner.KcRow> rows)
		{
			this.rows = rows;
		}

		void setAll(boolean on)
		{
			for (HistoryPlanner.KcRow r : rows)
			{
				r.on = on && r.to > r.cur;
			}
			fireTableDataChanged();
		}

		@Override
		public int getRowCount()
		{
			return rows.size();
		}

		@Override
		public int getColumnCount()
		{
			return COLUMNS.length;
		}

		@Override
		public String getColumnName(int c)
		{
			return COLUMNS[c];
		}

		@Override
		public Class<?> getColumnClass(int c)
		{
			return c == 0 ? Boolean.class : String.class;
		}

		@Override
		public boolean isCellEditable(int r, int c)
		{
			return c == 0 && rows.get(r).to > rows.get(r).cur;
		}

		@Override
		public Object getValueAt(int r, int c)
		{
			HistoryPlanner.KcRow row = rows.get(r);
			switch (c)
			{
				case 0:
					return row.on;
				case 1:
					return row.name;
				case 2:
					return Fmt.num(row.to);
				case 3:
					return Fmt.num(row.cur);
				default:
					return row.to > row.cur ? "sets the kill count" : row.to == row.cur ? "already the same" : "your ledger is ahead, kept";
			}
		}

		@Override
		public void setValueAt(Object v, int r, int c)
		{
			if (c == 0)
			{
				rows.get(r).on = (Boolean) v;
				fireTableCellUpdated(r, c);
			}
		}
	}

	@SuppressWarnings("serial")
	private static final class ItemModel extends AbstractTableModel
	{
		private static final String[] COLUMNS = {"", "Item", "Boss", "Owned", "In ledger", "Adds"};
		private final List<HistoryPlanner.ItemRow> rows;

		ItemModel(List<HistoryPlanner.ItemRow> rows)
		{
			this.rows = rows;
		}

		void setAll(boolean on)
		{
			for (HistoryPlanner.ItemRow r : rows)
			{
				r.on = on && (r.add > 0 || r.remove > 0);
			}
			fireTableDataChanged();
		}

		@Override
		public int getRowCount()
		{
			return rows.size();
		}

		@Override
		public int getColumnCount()
		{
			return COLUMNS.length;
		}

		@Override
		public String getColumnName(int c)
		{
			return COLUMNS[c];
		}

		@Override
		public Class<?> getColumnClass(int c)
		{
			return c == 0 ? Boolean.class : String.class;
		}

		@Override
		public boolean isCellEditable(int r, int c)
		{
			return c == 0 && (rows.get(r).add > 0 || rows.get(r).remove > 0);
		}

		@Override
		public Object getValueAt(int r, int c)
		{
			HistoryPlanner.ItemRow row = rows.get(r);
			switch (c)
			{
				case 0:
					return row.on;
				case 1:
					return row.item;
				case 2:
					return row.bossName + (row.assumed ? " (assumed)" : "");
				case 3:
					return row.estimated() ? "~" + Fmt.num(row.want) + " (" + Fmt.num(row.quantity) + " items)" : Fmt.num(row.want);
				case 4:
					return Fmt.num(row.have);
				default:
					return row.add > 0 ? "+" + Fmt.num(row.add) : row.remove > 0 ? "-" + Fmt.num(row.remove) : "—";
			}
		}

		@Override
		public void setValueAt(Object v, int r, int c)
		{
			if (c == 0)
			{
				rows.get(r).on = (Boolean) v;
				fireTableCellUpdated(r, c);
			}
		}
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.engine.Luck;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

/**
 * One tracked item, on a single compact row.  The percentage and the bar are the chance that a player would have had the next copy by
 * now, counting every kill made: 85% for someone who is dry, and after a drop it falls to the chance of one more, not to zero, because
 * the kills beyond the drop rate carry over.  The word (Dry, On rate, Lucky) says how the player's copies compare with what is likely.
 * Everything else is in the tooltip, and a click opens the figures, the chart and the buttons.
 */
@SuppressWarnings("serial")
final class ItemCard extends Column
{
	/**
	 * What the card's buttons and clicks do.
	 */
	interface Actions
	{
		void log(String item);

		void hide(String item);

		void toggle(String item);

		boolean isOpen(String item);

		void chart(String item, Consumer<Views.ChartData> into);
	}

	/**
	 * The luck figures the card leads with: the pooled ones when several bosses drop the item, so that the same item reads the
	 * same on each of those bosses' pages.
	 */
	private static final class Figures
	{
		final Double pct;
		final Luck.Label label;
		final int got;
		final Double expected;
		final boolean pooled;
		private final double poolChance;
		private final Double anotherChance;

		Figures(Views.ItemView v)
		{
			poolChance = v.pool != null ? v.pool.another : 0;
			anotherChance = v.pool != null ? null : v.a.another;
			if (v.pool != null)
			{
				pct = v.pool.pct;
				label = v.pool.label;
				got = v.pool.O;
				expected = v.pool.expected;
				pooled = true;
			}
			else
			{
				pct = v.a.pct;
				label = v.a.label;
				got = v.a.O;
				expected = v.a.expected;
				pooled = false;
			}
		}

		boolean known()
		{
			return pct != null && !Double.isNaN(pct) && label != null && !"na".equals(label.key);
		}

		/**
		 * The chance that the next copy would have come by now (the first one, while there is none).
		 */
		double chance()
		{
			Double c = pooled ? Double.valueOf(poolChance) : anotherChance;
			return c == null ? Double.NaN : c;
		}
	}

	private final Views.ItemView view;
	private final Actions actions;
	private final CurveChart chart = new CurveChart();
	private final Meter meter = new Meter(5);
	private final JButton logButton;
	private final JButton hideButton;

	ItemCard(Ctx ctx, Views.ItemView v, Actions actions)
	{
		super(3, true);
		this.view = v;
		this.actions = actions;
		setBackground(Look.CARD);
		setBorder(Look.card());
		final Luck.ItemAnalysis a = v.a;
		final boolean open = actions.isOpen(v.name);
		logButton = Look.button("Log drop");
		logButton.addActionListener(e -> actions.log(v.name));
		hideButton = Look.button("Hide");
		hideButton.setToolTipText("Stop tracking this item");
		hideButton.addActionListener(e -> actions.hide(v.name));

		if (a == null)
		{
			add(top(ctx, v, null, null, Look.CARD_TEXT));
			add(Look.wrapped("Could not work this out.", Look.CARD_TEXT, Look.small(), Look.MUTED));
			if (open)
			{
				add(footer());
			}
			Look.clickable(this, () -> actions.toggle(v.name));
			return;
		}

		final Figures f = new Figures(v);
		final boolean done = a.collected;
		final double chance = f.chance();
		final boolean has = a.K > 0 && !Double.isNaN(chance);
		final Color color = done ? Look.GOOD : has ? Look.chance(chance) : Look.MUTED;
		final String headline = done ? "Done" : has ? Fmt.pct(chance) : "—";
		add(top(ctx, v, headline, color, Look.CARD_TEXT));
		meter.set(done ? 1 : has ? chance : 0, color);
		add(meter);
		add(sub(v, f, done, color));

		if (open)
		{
			if (a.K > 0)
			{
				add(Look.kv(Look.CARD_TEXT, facts(v, f, done)));
			}
			if (v.pool != null)
			{
				add(pooled(v.pool));
			}
			String extras = extrasOf(v);
			if (!extras.isEmpty())
			{
				add(Look.wrapped(Look.esc(extras), Look.CARD_TEXT, Look.small(), Look.MUTED));
			}
			if (v.meta != null && v.meta.note != null && !v.meta.note.isEmpty())
			{
				add(Look.wrapped(Look.esc(v.meta.note), Look.CARD_TEXT, Look.small(), Look.MUTED));
			}
			if (a.K > 0 && !done && v.pool == null && a.streakKnown)
			{
				add(Look.wrapped("Chance of getting it within a number of kills after your last one", Look.CARD_TEXT, Look.small(), Look.MUTED));
				add(chart);
				actions.chart(v.name, chart::set);
			}
			else if (a.K > 0 && !done && !streakKnown(v))
			{
				add(Look.wrapped("Your last copy has no kill number, so the dry streak and its chart are left out. Edit the drop in the history to add one.",
					Look.CARD_TEXT, Look.small(), Look.MUTED));
			}
			add(footer());
		}
		setToolTipText(tip(v, f, done));
		Look.clickable(this, () -> actions.toggle(v.name));
	}

	// ------------------------------------------------------------------ the row

	/**
	 * The icon, the name and, on the right, the headline.
	 */
	private JPanel top(Ctx ctx, Views.ItemView v, String headline, Color color, int width)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		java.awt.Font big = Look.bold().deriveFont(Look.bold().getSize2D() + 2f);
		final int headWidth = headline == null ? 0 : getFontMetrics(big).stringWidth(headline) + 4;
		int tw = width - headWidth - (ctx.pictures() ? 36 + 6 : 0) - 6;
		if (ctx.pictures())
		{
			JLabel icon = new JLabel();
			ItemIcon.set(icon, ctx.icons(), v.name, true, 30, 28);
			icon.setVerticalAlignment(SwingConstants.CENTER);
			row.add(icon, BorderLayout.WEST);
		}
		Luck.ItemAnalysis a = v.a;
		String title = Look.esc(v.name) + (a != null && a.O > 0 ? " " + Look.colored("×" + a.O, Look.GOOD) : "");
		JLabel name = Look.wrapped("<b>" + title + "</b>", tw, Look.body(), Look.TEXT);
		name.setVerticalAlignment(SwingConstants.CENTER);
		row.add(name, BorderLayout.CENTER);
		if (headline != null)
		{
			JLabel pc = Look.label(headline, big, color);
			pc.setHorizontalAlignment(SwingConstants.RIGHT);
			row.add(pc, BorderLayout.EAST);
		}
		return row;
	}

	/**
	 * The muted line under the bar: the rate and what has been received against what to expect, with the word for the luck.
	 */
	private static JPanel sub(Views.ItemView v, Figures f, boolean done, Color color)
	{
		Luck.ItemAnalysis a = v.a;
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		String left;
		if (done)
		{
			left = "Collected · no longer rolls";
		}
		else if (a.K == 0)
		{
			left = "Add your kill count";
		}
		else
		{
			String rate = a.pNext > 0 ? Fmt.rate(a.pNext) : "not droppable";
			if (f.pooled)
			{
				left = "pooled · " + f.got + " vs " + (f.expected == null ? "—" : Fmt.expected(f.expected)) + " expected";
			}
			else
			{
				left = rate + " · " + f.got + " vs " + (f.expected == null ? "—" : Fmt.expected(f.expected)) + " expected";
			}
		}
		JLabel l = Look.label(left, Look.small(), Look.MUTED);
		row.add(l, BorderLayout.CENTER);
		if (!done && a.K > 0 && f.known())
		{
			row.add(Look.label(f.label.text, Look.small(), Look.luck(f.label.key)), BorderLayout.EAST);
		}
		return row;
	}

	private JPanel footer()
	{
		JPanel p = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		p.setOpaque(false);
		p.add(logButton);
		p.add(hideButton);
		return p;
	}

	// ------------------------------------------------------------------ the words

	/**
	 * Whether anyone can say how long ago the last copy was.  For an item pooled over several bosses that is the pool's streak.
	 */
	private static boolean streakKnown(Views.ItemView v)
	{
		return v.pool != null ? v.pool.streakKnown : v.a.streakKnown;
	}

	private static String tagsOf(Views.ItemView v)
	{
		String extras = extrasOf(v);
		return extras.isEmpty() ? v.kind : v.kind + " · " + extras;
	}

	/**
	 * What is special about the item, beyond being a unique, a pet or a drop.
	 */
	private static String extrasOf(Views.ItemView v)
	{
		List<String> t = new ArrayList<>();
		if (v.meta != null && v.meta.seq != null)
		{
			t.add("hit " + v.meta.seq.n + " of " + v.meta.seq.len);
		}
		if (v.meta != null && v.meta.pity > 0)
		{
			t.add("pity " + v.meta.pity);
		}
		if (v.shared)
		{
			t.add("shared by several bosses");
		}
		return String.join(" · ", t);
	}

	private static String rateOf(Luck.ItemAnalysis a)
	{
		String rate = a.pNext > 0 ? Fmt.rate(a.pNext) : a.once && a.O > 0 ? "once only" : "not droppable with these settings";
		return a.seq != null ? rate + " · slot hits so far " + a.hits : rate;
	}

	/**
	 * Everything about the item, for hovering.
	 */
	private static String tip(Views.ItemView v, Figures f, boolean done)
	{
		Luck.ItemAnalysis a = v.a;
		StringBuilder b = new StringBuilder("<b>").append(Look.esc(v.name)).append("</b> ").append(Look.dim(Look.esc(tagsOf(v))));
		if (done)
		{
			b.append("<br>Collected: this drop no longer rolls.");
			return Look.tip(b.toString());
		}
		if (a.K == 0)
		{
			b.append("<br>Set your kill count to see how lucky you are.");
			return Look.tip(b.toString());
		}
		b.append("<br><b>").append(Fmt.pct(f.chance())).append("</b> chance of ").append(f.got > 0 ? "copy " + (f.got + 1) : "one")
			.append(" by now, from all your kills at the drop rate. ").append(Look.dim("Kills past the rate carry over to the next one."));
		b.append("<br>Per kill here: ").append(Look.esc(rateOf(a)));
		if (v.pool != null)
		{
			b.append(" ").append(Look.dim("(each boss has its own rate; the luck below joins them all)"));
			b.append("<br>Across ").append(v.pool.per.size()).append(" bosses (").append(Look.esc(perBoss(v.pool))).append("): got ").append(f.got).append(" vs ")
				.append(f.expected == null ? "—" : Fmt.expected(f.expected)).append(" expected");
		}
		else
		{
			b.append("<br>Received ").append(f.got).append(" vs ").append(f.expected == null ? "—" : Fmt.expected(f.expected)).append(" expected over ")
				.append(Fmt.num(a.K)).append(" kills");
		}
		if (f.known())
		{
			b.append("<br>Luck: ").append(Look.colored("<b>" + Look.esc(f.label.text) + "</b>", Look.luck(f.label.key))).append(" · luckier than ")
				.append(Fmt.pct(f.pct)).append(" of players with the same kills");
		}
		Double cum = v.pool != null ? (Double) v.pool.cum : a.cum;
		if (cum != null)
		{
			b.append("<br>Chance of 1+ in all those kills: ").append(Fmt.pct(cum));
		}
		b.append("<br>").append(streakLine(v));
		b.append("<br>").append(Look.dim("Click for more"));
		return Look.tip(b.toString());
	}

	private static String streakLine(Views.ItemView v)
	{
		Luck.ItemAnalysis a = v.a;
		if (v.pool != null)
		{
			Luck.Pool p = v.pool;
			return p.streakKnown
				? "Dry streak over all these bosses: " + Fmt.num(p.streak) + " kills since your last (" + Fmt.pct(p.meter) + " would have had another)"
				: "Dry streak: not known, because your last copy has no kill number.";
		}
		if (!a.streakKnown)
		{
			return "Dry streak: not known, because your last copy has no kill number.";
		}
		if (a.O > 0 && a.streakFrom > 0)
		{
			return "Dry streak: " + Fmt.num(a.streak) + " kills since your last, at kill " + Fmt.num(a.streakFrom) + " (" + Fmt.pct(a.meter) + " would have had another)";
		}
		return "Dry streak: " + Fmt.num(a.streak) + " kills without one (" + Fmt.pct(a.meter) + " would have had one)";
	}

	private static String perBoss(Luck.Pool p)
	{
		List<String> parts = new ArrayList<>();
		for (Luck.PoolPer x : p.per)
		{
			parts.add(x.name + " " + Fmt.num(x.K));
		}
		return String.join(" · ", parts);
	}

	private static List<String[]> facts(Views.ItemView v, Figures f, boolean done)
	{
		Luck.ItemAnalysis a = v.a;
		List<String[]> rows = new ArrayList<>();
		rows.add(new String[] {"Per kill here", Look.esc(rateOf(a))});
		rows.add(new String[] {"Received vs expected", a.O + " vs " + (a.expected == null ? "—" : Fmt.expected(a.expected))});
		if (!done && !Double.isNaN(f.chance()))
		{
			rows.add(new String[] {f.got > 0 ? "Chance of copy " + (f.got + 1) : "Chance of one", Look.esc(Fmt.pct(f.chance()))});
		}
		if (f.known())
		{
			rows.add(new String[] {"Luck", Look.colored(Look.esc(f.label.text), Look.luck(f.label.key))});
			rows.add(new String[] {"Luckier than", Look.esc(Fmt.pct(f.pct)) + " of players"});
		}
		if (!done && a.cum != null)
		{
			rows.add(new String[] {"1+ in all kills", Look.esc(Fmt.pct(a.cum))});
		}
		if (!done)
		{
			boolean pooled = v.pool != null;
			if (streakKnown(v))
			{
				long streak = pooled ? v.pool.streak : a.streak;
				double odds = pooled ? v.pool.meter : a.meter;
				boolean again = pooled ? v.pool.O > 0 : a.O > 0;
				rows.add(new String[] {pooled ? "Dry streak, all bosses" : "Dry streak", Fmt.num(streak) + " kills"});
				rows.add(new String[] {again ? "Odds of another by now" : "Odds of one by now", Look.esc(Fmt.pct(odds))});
			}
			Double fwd = a.fwd.get(a.window);
			rows.add(new String[] {"Next " + a.window + " kills", Look.esc(Fmt.pct(fwd))});
			if (a.kto != null)
			{
				Double half = a.kto.get(0.5);
				Double most = a.kto.get(0.9);
				rows.add(new String[] {"50% / 90% in", Fmt.num(half == null ? Double.POSITIVE_INFINITY : half) + " / "
					+ Fmt.num(most == null ? Double.POSITIVE_INFINITY : most) + " kills"});
			}
		}
		return rows;
	}

	private static JLabel pooled(Luck.Pool p)
	{
		String m = "<b>Pooled across " + p.per.size() + " bosses</b><br>" + Look.esc(perBoss(p)) + "<br>" + p.O + " received vs " + Fmt.expected(p.expected)
			+ " expected · " + Look.colored(Look.esc(p.label.text), Look.luck(p.label.key)) + ", luckier than " + Fmt.pct(p.pct) + " of players";
		return Look.wrapped(m, Look.CARD_TEXT, Look.small(), Look.TEXT);
	}

