/**
 * Colours, fonts and small builders shared by the panel's parts.
 */
final class Look
{
	/**
	 * Width for wrapped text straight on the page.  The side panel is 242 pixels wide (225 and the 17 RuneLite keeps for a scrollbar);
	 * the page has 6 pixels of padding on each side and, when it is long, a scrollbar of 7, which leaves 223 for the content.
	 */
	static final int PAGE_TEXT = 218;
	/**
	 * Width for wrapped text inside a card (the card's border and padding, 16 pixels, taken off the content width).
	 */
	static final int CARD_TEXT = 202;

	/**
	 * Width for the wrapped text of a tooltip.
	 */
	static final int TIP = 236;

	static final Color BG = ColorScheme.DARK_GRAY_COLOR;
	static final Color CARD = ColorScheme.DARKER_GRAY_COLOR;
	static final Color CARD_HOVER = ColorScheme.DARKER_GRAY_HOVER_COLOR;
	static final Color LINE = ColorScheme.MEDIUM_GRAY_COLOR;
	static final Color TEXT = new Color(0xe6, 0xe6, 0xe6);
	static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	static final Color ACCENT = ColorScheme.BRAND_ORANGE;

	static final Color BLUE = new Color(0x6a, 0xa5, 0xd6);
	static final Color GOLD = new Color(0xe0, 0xae, 0x2c);
	static final Color EMBER = new Color(0xe8, 0x79, 0x4f);
	static final Color GOOD = new Color(0x5e, 0xc1, 0x84);
	static final Color WARN = new Color(0xe3, 0xa2, 0x4d);
	static final Color BAD = new Color(0xee, 0x84, 0x66);

	private Look()
	{
	}

	static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	static Font bold()
	{
		return FontManager.getRunescapeBoldFont();
	}

	/**
	 * The colour of a "chance by now" bar: blue while it is still likely you would not have had it, gold past even odds, ember past
	 * nine in ten (well overdue).
	 */
	static Color chance(double c)
	{
		return c < 0.5 ? BLUE : c < 0.9 ? GOLD : EMBER;
	}

	/**
	 * The colour of a luck label ("vdry", "dry", "below", "avg", "above", "lucky", "vlucky", "na").
	 */
	static Color luck(String key)
	{
		switch (key)
		{
			case "vdry":
			case "dry":
				return BAD;
			case "below":
				return WARN;
			case "above":
			case "lucky":
			case "vlucky":
				return GOOD;
			case "avg":
				return TEXT;
			default:
				return MUTED;
		}
	}

	static String esc(String s)
	{
		if (s == null)
		{
			return "";
		}
		StringBuilder b = new StringBuilder(s.length() + 8);
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			switch (c)
			{
				case '&':
					b.append("&amp;");
					break;
				case '<':
					b.append("&lt;");
					break;
				case '>':
					b.append("&gt;");
					break;
				case '"':
					b.append("&quot;");
					break;
				default:
					b.append(c);
			}
		}
		return b.toString();
	}

	/**
	 * "#rrggbb" for use in label markup.
	 */
	static String hex(Color c)
	{
		return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	static JLabel label(String text, Font font, Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(font);
		l.setForeground(color);
		return l;
	}

	/**
	 * Label markup that wraps at the given width in pixels.  The width is given as an attribute because Swing reads a CSS width in
	 * "px" as 1.3 pixels each.
	 */
	static String html(int width, String markup)
	{
		return "<html><body width='" + width + "'>" + markup + "</body></html>";
	}

	/**
	 * Tooltip markup: wraps at {@link #TIP} pixels.
	 */
	static String tip(String markup)
	{
		return html(TIP, markup);
	}

	/**
	 * Markup for a muted piece of text inside a label of another colour.
	 */
	static String dim(String escapedText)
	{
		return colored(escapedText, MUTED);
	}

	/**
	 * A label whose text (already escaped markup) wraps at the given width.
	 */
	static JLabel wrapped(String markup, int width, Font font, Color color)
	{
		JLabel l = new JLabel(html(width, markup));
		l.setFont(font);
		l.setForeground(color);
		l.setVerticalAlignment(SwingConstants.TOP);
		return l;
	}

	/**
	 * A list of labelled values: the label on the left, the value (markup) on the right.
	 */
	static JLabel kv(int width, java.util.List<String[]> rows)
	{
		StringBuilder b = new StringBuilder("<table cellpadding='1' cellspacing='0' width='").append(width).append("'>");
		for (String[] r : rows)
		{
			b.append("<tr><td valign='top'><font color='").append(hex(MUTED)).append("'>").append(esc(r[0]).replace(" ", "&nbsp;")).append("</font></td>")
				.append("<td align='right' valign='top'>").append(r[1]).append("</td></tr>");
		}
		b.append("</table>");
		JLabel l = new JLabel(html(width, b.toString()));
		l.setFont(small());
		l.setForeground(TEXT);
		l.setVerticalAlignment(SwingConstants.TOP);
		return l;
	}

	/**
	 * Markup that colours a piece of text.
	 */
	static String colored(String escapedText, Color c)
	{
		return "<font color='" + hex(c) + "'>" + escapedText + "</font>";
	}

	static JLabel muted(String text)
	{
		return label(text, small(), MUTED);
	}

	static Border pad(int top, int left, int bottom, int right)
	{
		return BorderFactory.createEmptyBorder(top, left, bottom, right);
	}

	static Border card()
	{
		return BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR, 1), pad(4, 6, 4, 6));
	}

	/**
	 * A text-only button that looks like a link.
	 */
	static JButton link(String text)
	{
		JButton b = new JButton(text);
		b.setFont(small());
		b.setForeground(ACCENT);
		b.setBorderPainted(false);
		b.setContentAreaFilled(false);
		b.setFocusPainted(false);
		b.setOpaque(false);
		b.setMargin(new java.awt.Insets(0, 0, 0, 0));
		b.setBorder(pad(1, 0, 1, 0));
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		b.setHorizontalAlignment(SwingConstants.LEFT);
		return b;
	}

	/**
	 * A small ordinary button.
	 */
	static JButton button(String text)
	{
		JButton b = new JButton(text);
		b.setFont(small());
		b.setFocusPainted(false);
		b.setMargin(new java.awt.Insets(2, 6, 2, 6));
		return b;
	}

	/**
	 * Makes a panel react to the mouse like a button.
	 */
	static void clickable(JComponent c, Runnable action)
	{
		c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		c.addMouseListener(new MouseAdapter()
		{
			private Color normal;

			@Override
			public void mouseClicked(MouseEvent e)
			{
				action.run();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				normal = c.getBackground();
				c.setBackground(CARD_HOVER);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (normal != null)
				{
					c.setBackground(normal);
				}
			}
		});
	}
}

package com.dropluckledger.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * A thin bar showing a chance from 0 to 100%, with optional marks (the card's luck bar has one at 50%, "exactly on rate").
 */
@SuppressWarnings("serial")
final class Meter extends JComponent
{
	private double value;
	private Color color = Look.BLUE;
	private final double[] marks;

	/**
	 * @param marks where to draw thin lines across the bar, as fractions of its length
	 */
	Meter(int height, double... marks)
	{
		this.marks = marks;
		setOpaque(false);
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
	}

	void set(double v, Color c)
	{
		this.value = Double.isNaN(v) ? 0 : Math.max(0, Math.min(1, v));
		this.color = c;
		repaint();
	}

	double value()
	{
		return value;
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		Graphics2D g = (Graphics2D) g0.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			g.setColor(Look.LINE);
			g.fillRoundRect(0, 0, w, h, h, h);
			if (value > 0)
			{
				int fill = Math.max(h, (int) Math.round(w * value));
				g.setColor(color);
				g.fillRoundRect(0, 0, fill, h, h, h);
			}
			g.setColor(new Color(0, 0, 0, 140));
			for (double m : marks)
			{
				g.fillRect((int) Math.round(w * m), 0, 1, h);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Luck;
import com.dropluckledger.ledger.Ledger;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/**
 * The first page: where the player's luck stands across every boss, and the way into each boss.
 */
@SuppressWarnings("serial")
final class OverviewPage extends Column
{
	private final Ctx ctx;
	private final Ledger ledger;
	private final Jobs.Slot<Views.OverviewView> job;
	private final JTextField search = new JTextField();
	private final Column results = new Column(8);
	private final Map<String, Boolean> openGroups = new LinkedHashMap<>();
	private boolean openHelp;
	private Views.OverviewView view;

	OverviewPage(Ctx ctx)
	{
		super(8);
		this.ctx = ctx;
		this.ledger = ctx.ledger();
		this.job = ctx.jobs().slot();
		search.setFont(Look.small());
		search.setToolTipText("Find a boss, or an item a boss drops");
		search.putClientProperty("JTextField.placeholderText", "Find a boss or an item");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				build();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				build();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				build();
			}
		});
		add(Look.label("Your drop luck", Look.bold(), Look.TEXT));
		add(search);
		add(results);
		build();
		refresh();
	}

	/**
	 * The ledger changed: work the figures out again.
	 */
	void refresh()
	{
		job.run(c -> ctx.analyzer().overview(c), v ->
		{
			view = v;
			build();
		});
	}

	JTextField searchField()
	{
		return search;
	}

	Views.OverviewView lastView()
	{
		return view;
	}

	// ------------------------------------------------------------------ building

	private void build()
	{
		List<Component> parts = new ArrayList<>();
		String q = search.getText().trim().toLowerCase();
		if (!q.isEmpty())
		{
			parts.addAll(found(q));
			Swap.into(results, parts);
			return;
		}
		if (view == null)
		{
			parts.add(Look.wrapped("Working it out…", Look.PAGE_TEXT, Look.small(), Look.MUTED));
		}
		else if (view.tracked == 0)
		{
			parts.add(empty());
		}
		else
		{
			parts.add(Look.muted(view.tracked + " boss" + (view.tracked == 1 ? "" : "es") + " tracked · " + ctx.ledger().data().bosses.size() + " available"));
			parts.add(ranking("Driest so far", "The items you are furthest behind on. The percentage is the chance, from all your kills, that you would "
				+ "have the next copy by now, so a high figure means you are overdue. Hover a line for the figures; click to open the boss.", view.driest, "Nothing is this dry yet."));
			parts.add(ranking("Running hot", "The items you have been luckiest with. The percentage is the chance, from all your kills, that you would "
				+ "have the next copy by now, so a low figure means you are well ahead. Hover a line for the figures; click to open the boss.", view.hottest, "Nothing is running hot yet."));
			parts.add(myBosses(view));
			if (!view.pooled.isEmpty())
			{
				parts.add(shared(view));
			}
		}
		parts.add(allBosses());
		parts.add(help());
		Swap.into(results, parts);
	}

	private JComponent empty()
	{
		Column c = new Column(6);
		c.add(Look.wrapped("Nothing tracked yet. Kills and drops you get in game are recorded automatically from now on. "
			+ "To bring in what you already have, add your game history, or pick a boss below and set its kill count.", Look.PAGE_TEXT, Look.small(), Look.MUTED));
		JButton b = Look.button("Add my game history…");
		b.setToolTipText("Reads your kill counts and collection log from the game and shows you what it would add");
		b.addActionListener(e -> ctx.reviewHistory());
		c.add(b);
		return c;
	}

	/**
	 * A heading whose explanation is in a tooltip, so it takes no room on the page.
	 */
	private JComponent heading(String title, String help)
	{
		JPanel p = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		p.setOpaque(false);
		p.add(Look.label(title, Look.bold(), Look.TEXT));
		if (help != null)
		{
			JLabel q = Look.label("(?)", Look.small(), Look.MUTED);
			q.setToolTipText(Look.tip(Look.esc(help)));
			p.setToolTipText(Look.tip(Look.esc(help)));
			p.add(q);
		}
		return p;
	}

	private JComponent ranking(String title, String help, List<Views.Rank> rows, String none)
	{
		Column c = new Column(3);
		c.add(heading(title, help));
		if (rows.isEmpty())
		{
			c.add(Look.muted(none));
			return c;
		}
		for (Views.Rank r : rows)
		{
			c.add(rankRow(r));
		}
		return c;
	}

	private JComponent rankRow(Views.Rank r)
	{
		Color color = Look.luck(r.label.key);
		Color bar = Look.chance(r.chance);
		JPanel row = new JPanel(new BorderLayout(6, 2));
		row.setBackground(Look.CARD);
		row.setBorder(Look.pad(3, 6, 3, 6));
		JLabel name = new JLabel(Look.html(126, Look.esc(r.item) + "<br>" + Look.dim(Look.esc(r.where))));
		name.setFont(Look.small());
		name.setForeground(Look.TEXT);
		ItemIcon.set(name, ctx.icons(), r.item, ctx.pictures(), 24, 22);
		row.add(name, BorderLayout.CENTER);
		row.add(figure(Fmt.pct(r.chance), bar, r.label.text, color), BorderLayout.EAST);
		Meter m = new Meter(3);
		m.set(r.chance, bar);
		row.add(m, BorderLayout.SOUTH);
		row.setToolTipText(Look.tip("<b>" + Look.esc(r.item) + "</b> " + Look.dim(Look.esc(r.where)) + "<br>" + (r.pooled ? "All these bosses together: " : "")
			+ r.got + " received vs " + Fmt.expected(r.expected) + " expected<br><b>" + Fmt.pct(r.chance) + "</b> chance of "
			+ (r.got > 0 ? "copy " + (r.got + 1) : "one") + " by now<br>" + Look.colored("<b>" + Look.esc(r.label.text) + "</b>", color)
			+ " · luckier than " + Fmt.pct(r.pct) + " of players with the same kills<br>" + Look.dim("Click to open")));
		Look.clickable(row, () -> ctx.openBoss(r.bossId));
		return row;
	}

	/**
	 * The figure at the right of a line: the chance on top and the luck word under it.
	 */
	private static JComponent figure(String chance, Color chanceColor, String word, Color wordColor)
	{
		JPanel p = new JPanel();
		p.setOpaque(false);
		p.setLayout(new javax.swing.BoxLayout(p, javax.swing.BoxLayout.Y_AXIS));
		JLabel top = Look.label(chance, Look.body(), chanceColor);
		top.setAlignmentX(Component.RIGHT_ALIGNMENT);
		p.add(top);
		JLabel bottom = Look.label(word, Look.small(), wordColor);
		bottom.setAlignmentX(Component.RIGHT_ALIGNMENT);
		p.add(bottom);
		return p;
	}

	private JComponent myBosses(Views.OverviewView v)
	{
		Column c = new Column(3);
		c.add(heading("My bosses", null));
		for (Views.BossRow b : v.bosses)
		{
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setBackground(Look.CARD);
			row.setBorder(Look.pad(3, 6, 3, 6));
			StringBuilder t = new StringBuilder("<b>").append(Look.esc(b.name)).append("</b>");
			StringBuilder second = new StringBuilder();
			if (b.any != null && b.any.label != null && !"na".equals(b.any.label.key))
			{
				second.append(Look.colored(Look.esc(b.any.label.text), Look.luck(b.any.label.key))).append(Look.dim(" " + b.any.O + " of " + Fmt.expected(b.any.expected)));
			}
			if (b.total > 0)
			{
				second.append(second.length() > 0 ? Look.dim(" · ") : "").append(Look.dim("log " + b.got + "/" + b.total));
			}
			if (second.length() > 0)
			{
				t.append("<br>").append(second);
			}
			JLabel l = new JLabel(Look.html(150, t.toString()));
			l.setFont(Look.small());
			l.setForeground(Look.TEXT);
			row.add(l, BorderLayout.CENTER);
			row.add(Look.label(Fmt.num(b.kc), Look.body(), Look.TEXT), BorderLayout.EAST);
			StringBuilder tip = new StringBuilder("<b>").append(Look.esc(b.name)).append("</b> · ").append(Fmt.num(b.kc)).append(" kills");
			if (b.any != null)
			{
				tip.append("<br>Uniques together: ").append(b.any.O).append(" received vs ").append(Fmt.expected(b.any.expected)).append(" expected<br><b>")
					.append(Fmt.pct(b.any.another)).append("</b> chance of ").append(b.any.O > 0 ? "another" : "one").append(" by now");
				if (!"na".equals(b.any.label.key))
				{
					tip.append(" · ").append(Look.colored("<b>" + Look.esc(b.any.label.text) + "</b>", Look.luck(b.any.label.key))).append(" (luckier than ")
						.append(Fmt.pct(b.any.pct)).append(" of players)");
				}
			}
			if (b.total > 0)
			{
				tip.append("<br>Collection log items: ").append(b.got).append(" of ").append(b.total);
			}
			row.setToolTipText(Look.tip(tip.toString()));
			Look.clickable(row, () -> ctx.openBoss(b.id));
			c.add(row);
		}
		return c;
	}

	private JComponent shared(Views.OverviewView v)
	{
		Column c = new Column(3);
		c.add(heading("Shared drops", "Items several of your bosses can drop. Each boss has its own rate, so these combine all of those bosses' kills into one luck figure."));
		for (Luck.Pool p : v.pooled)
		{
			Luck.PoolPer main = p.per.get(0);
			StringBuilder per = new StringBuilder();
			for (Luck.PoolPer x : p.per)
			{
				if (x.K > main.K)
				{
					main = x;
				}
				if (per.length() > 0)
				{
					per.append(" · ");
				}
				per.append(x.name).append(' ').append(Fmt.num(x.K));
			}
			final String openId = main.id;
			boolean known = !Double.isNaN(p.pct) && !"na".equals(p.label.key);
			Color color = known ? Look.luck(p.label.key) : Look.MUTED;
			JPanel row = new JPanel(new BorderLayout(6, 2));
			row.setBackground(Look.CARD);
			row.setBorder(Look.pad(3, 6, 3, 6));
			JLabel name = new JLabel(Look.html(126, "<b>" + Look.esc(p.name) + "</b><br>" + Look.dim(p.per.size() + " bosses · " + p.O + " vs " + Fmt.expected(p.expected))));
			name.setFont(Look.small());
			name.setForeground(Look.TEXT);
			ItemIcon.set(name, ctx.icons(), p.name, ctx.pictures(), 24, 22);
			row.add(name, BorderLayout.CENTER);
			Color bar = known ? Look.chance(p.another) : Look.MUTED;
			row.add(figure(known ? Fmt.pct(p.another) : "—", bar, known ? p.label.text : "no kills", color), BorderLayout.EAST);
			Meter m = new Meter(3);
			m.set(known ? p.another : 0, bar);
			row.add(m, BorderLayout.SOUTH);
			row.setToolTipText(Look.tip("<b>" + Look.esc(p.name) + "</b><br>" + Look.esc(per.toString()) + " kills<br>" + p.O + " received vs " + Fmt.expected(p.expected)
				+ " expected" + (known ? "<br><b>" + Fmt.pct(p.another) + "</b> chance of " + (p.O > 0 ? "another" : "one") + " by now<br>"
				+ Look.colored("<b>" + Look.esc(p.label.text) + "</b>", color) + " · luckier than " + Fmt.pct(p.pct) + " of players" : "")
				+ "<br>" + Look.dim("Click to open")));
			Look.clickable(row, () -> ctx.openBoss(openId));
			c.add(row);
		}
		return c;
	}

	private JComponent allBosses()
	{
		Column c = new Column(4);
		c.add(heading("All bosses", null));
		Map<String, List<Boss>> byCat = new LinkedHashMap<>();
		for (Boss b : Catalog.ordered(ledger.data()))
		{
			byCat.computeIfAbsent(b.cat, k -> new ArrayList<>()).add(b);
		}
		for (Map.Entry<String, List<Boss>> e : byCat.entrySet())
		{
			Column list = new Column(2);
			for (Boss b : e.getValue())
			{
				list.add(bossButton(b));
			}
			String cat = e.getKey();
			c.add(new Fold(cat + " (" + e.getValue().size() + ")", Boolean.TRUE.equals(openGroups.get(cat)), open -> openGroups.put(cat, open), list));
		}
		return c;
	}

	private JComponent bossButton(Boss b)
	{
		int kc = ledger.kc(b.id);
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(Look.CARD);
		row.setBorder(Look.pad(3, 6, 3, 6));
		row.add(Look.label(b.name, Look.small(), Look.TEXT), BorderLayout.CENTER);
		if (kc > 0)
		{
			row.add(Look.label(Fmt.num(kc), Look.small(), Look.MUTED), BorderLayout.EAST);
		}
		Look.clickable(row, () -> ctx.openBoss(b.id));
		return row;
	}

	private List<Component> found(String q)
	{
		List<Component> out = new ArrayList<>();
		List<Component> hits = new ArrayList<>();
		for (Boss b : Catalog.ordered(ledger.data()))
		{
			boolean match = b.name.toLowerCase().contains(q);
			for (String k : b.kc)
			{
				match |= k.toLowerCase().contains(q);
			}
			String viaItem = null;
			if (!match)
			{
				for (String n : b.meta().keySet())
				{
					if (n.toLowerCase().contains(q))
					{
						viaItem = n;
						break;
					}
				}
			}
			if (match || viaItem != null)
			{
				JComponent row = bossButton(b);
				if (viaItem != null)
				{
					Column c = new Column(0);
					c.add(row);
					c.add(Look.wrapped("drops " + Look.esc(viaItem), Look.PAGE_TEXT, Look.small(), Look.MUTED));
					hits.add(c);
				}
				else
				{
					hits.add(row);
				}
			}
		}
		if (hits.isEmpty())
		{
			out.add(Look.wrapped("No boss or item matches \"" + Look.esc(search.getText().trim()) + "\".", Look.PAGE_TEXT, Look.small(), Look.MUTED));
		}
		else
		{
			Column c = new Column(3);
			for (Component h : hits)
			{
				c.add(h);
			}
			out.add(c);
		}
		return out;
	}

	private JComponent help()
	{
		Column body = new Column(6);
		int w = Look.PAGE_TEXT - 4;
		body.add(Look.wrapped("<b>The percentage and the bar</b> are the chance, from all the kills you have made and the drop rate, that a player would have "
			+ "the next copy by now. With none of an item that is the chance of getting one: 85% means you are overdue, and the bar fills as you go dry. "
			+ "When a drop lands the bar falls to the chance of one more, not to zero, because the kills you made beyond the rate count towards the next copy. "
			+ "<b>The word and colour</b> (Dry, On rate, Lucky…) say how your count of copies compares with the kills you have made. "
			+ "Items shared by several bosses (like Virtus) use all those bosses together, so they read the same everywhere even though each boss has its own rate.",
			w, Look.small(), Look.TEXT));
		body.add(Look.wrapped("<b>Click an item</b> to see the figures behind it: the chance of at least one in all your kills, the dry streak since your last copy, "
			+ "the next " + ledger.prefs().window + " kills, and a chart. <b>Dry streak</b> is how long you have gone since your last copy; it says nothing about your next kill, "
			+ "which has the same chance whenever your last drop came (apart from drops with pity or ramping rates).", w, Look.small(), Look.TEXT));
		body.add(Look.wrapped("<b>Settings that change a rate</b> (task, Combat Achievements, team size, raid level…) live under Boss settings. "
			+ "Use \"new kills only\" if a setting changed part-way through your kills.", w, Look.small(), Look.TEXT));
		body.add(Look.wrapped("<b>Importing.</b> No source records which kill each past drop came on. Your game history brings in kill counts and the items you own; "
			+ "those count towards your luck, but they have no kill number, so no dry streak is shown until you add one. Items that drop in stacks (bolt racks, frozen tears) "
			+ "are turned into an estimated number of drops.", w, Look.small(), Look.TEXT));
		body.add(Look.wrapped("<b>Accuracy.</b> Rates come from the OSRS Wiki drop tables, checked twice. Each boss page lists anything that could not be captured.",
			w, Look.small(), Look.TEXT));
		return new Fold("How to read the numbers", openHelp, open -> openHelp = open, body);
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Ledger;
import java.awt.BorderLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;

/**
 * "Items I already own": how many copies the player has of each unique, so that the luck figures count them.  The copies
 * are added without a kill number.
 */
@SuppressWarnings("serial")
final class OwnedForm extends Column
{
	private static final int WIDTH = 280;

	private final Ledger ledger;
	private final String bossId;
	private final Map<String, JSpinner> spinners = new LinkedHashMap<>();
	private final Map<String, Integer> have = new LinkedHashMap<>();

	OwnedForm(Ctx ctx, String bossId)
	{
		super(4);
		this.ledger = ctx.ledger();
		this.bossId = bossId;
		Boss boss = ledger.data().boss(bossId);
		BossState st = ledger.copyOf(bossId);
		add(Look.wrapped("Enter how many copies you have received so far. They are added without a kill number (use Edit in the drop history if you remember it)."
			+ " This only adds; delete a drop from the history to remove one.", WIDTH, Look.small(), Look.MUTED));
		List<String> names = new ArrayList<>();
		for (String n : ledger.trackedNames(bossId))
		{
			if (!Catalog.kindOf(boss, n).equals("other") || boss.logSet().contains(n))
			{
				names.add(n);
			}
		}
		for (String n : names)
		{
			int h = st.copies(n);
			have.put(n, h);
			JSpinner s = new JSpinner(new SpinnerNumberModel(h, 0, 999, 1));
			spinners.put(n, s);
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setOpaque(false);
			JLabel label = new JLabel(n);
			label.setFont(Look.small());
			ItemIcon.set(label, ctx.icons(), n, ctx.pictures(), 24, 22);
			row.add(label, BorderLayout.CENTER);
			s.setPreferredSize(new java.awt.Dimension(64, s.getPreferredSize().height));
			row.add(s, BorderLayout.EAST);
			add(row);
		}
		setPreferredSize(new java.awt.Dimension(WIDTH, getPreferredSize().height));
	}

	/**
	 * Adds the copies the player entered.
	 *
	 * @return how many copies were added
	 */
	int save()
	{
		int added = 0;
		for (Map.Entry<String, JSpinner> e : spinners.entrySet())
		{
			int want = (Integer) e.getValue().getValue();
			int h = have.get(e.getKey());
			if (want > h)
			{
				added += ledger.addOwned(bossId, e.getKey(), want - h);
			}
		}
		return added;
	}

	Map<String, JSpinner> spinners()
	{
		return spinners;
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.ledger.Prefs;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;

/**
 * Settings that change the figures, the game history, backups.
 */
@SuppressWarnings("serial")
final class SettingsPage extends Column
{
	private final Ctx ctx;
	private final Ledger ledger;
	private final JSpinner window = new JSpinner(new SpinnerNumberModel(50, 1, 5000, 1));
	private final JCheckBox rowi = check("Wearing a ring of wealth (i)");
	private final JCheckBox lq = check("Legends' Quest completed");
	private final JCheckBox images = check("Show item pictures");
	private boolean updating;

	SettingsPage(Ctx ctx)
	{
		super(8);
		this.ctx = ctx;
		this.ledger = ctx.ledger();

		add(Look.label("Settings", Look.bold(), Look.TEXT));

		Column figures = new Column(4);
		figures.add(Look.wrapped("<b>Luck window</b><br>How many upcoming kills the \"next kills\" figures look at.", Look.PAGE_TEXT, Look.small(), Look.TEXT));
		figures.add(window);
		figures.add(rowi);
		figures.add(lq);
		figures.add(images);
		add(figures);

		Column history = new Column(4);
		history.add(Look.wrapped("<b>Game history</b><br>Reads your kill counts and collection log from the game and shows you what it would add before it adds anything. "
			+ "Open your Boss Kill Log (Adventure Log) and your Collection Log pages in game first, so the plugin can read them.", Look.PAGE_TEXT, Look.small(), Look.TEXT));
		JButton h = Look.button("Add my game history…");
		h.addActionListener(e -> ctx.reviewHistory());
		history.add(h);
		add(history);

		Column backup = new Column(4);
		backup.add(Look.wrapped("<b>Backup</b><br>A backup is a file you can keep, move to another computer, or open in the Drop Luck Ledger web page.", Look.PAGE_TEXT, Look.small(), Look.TEXT));
		JPanel row = new JPanel(new java.awt.GridLayout(1, 2, 4, 0));
		row.setOpaque(false);
		JButton export = Look.button("Export…");
		export.addActionListener(e -> ctx.host().exportBackup(ctx.window()));
		JButton in = Look.button("Import…");
		in.addActionListener(e -> ctx.host().importBackup(ctx.window(), this::chooseImport));
		row.add(export);
		row.add(in);
		backup.add(row);
		add(backup);

		Column erase = new Column(4);
		erase.add(Look.wrapped("<b>Start over</b><br>Removes every kill count and drop from this account's ledger.", Look.PAGE_TEXT, Look.small(), Look.TEXT));
		JButton wipe = Look.button("Erase everything…");
		wipe.setForeground(Look.BAD);
		wipe.addActionListener(e -> wipe());
		erase.add(wipe);
		add(erase);

		add(Look.wrapped("Everything stays on this computer. The plugin makes no network requests; boss data was taken from the OSRS Wiki when the plugin was built.",
			Look.PAGE_TEXT, Look.small(), Look.MUTED));

		window.addChangeListener(e ->
		{
			if (!updating)
			{
				int v = (Integer) window.getValue();
				ledger.updatePrefs(p -> p.window = v);
			}
		});
		rowi.addActionListener(e ->
		{
			if (!updating)
			{
				boolean on = rowi.isSelected();
				ledger.updatePrefs(p -> p.rowi = on ? 1 : 0);
			}
		});
		lq.addActionListener(e ->
		{
			if (!updating)
			{
				boolean on = lq.isSelected();
				ledger.updatePrefs(p -> p.lq = on ? 1 : 0);
			}
		});
		images.addActionListener(e ->
		{
			if (!updating)
			{
				boolean on = images.isSelected();
				ledger.updatePrefs(p -> p.images = on ? 1 : 0);
			}
		});
		sync();
	}

	private static JCheckBox check(String text)
	{
		JCheckBox c = new JCheckBox(text);
		c.setFont(Look.small());
		c.setOpaque(false);
		return c;
	}

	/**
	 * Makes the controls show the ledger's settings.
	 */
	void sync()
	{
		Prefs p = ledger.prefs();
		updating = true;
		try
		{
			window.setValue(p.window);
			rowi.setSelected(p.rowi != 0);
			lq.setSelected(p.lq != 0);
			images.setSelected(p.images != 0);
		}
		finally
		{
			updating = false;
		}
	}

	/**
	 * A backup was chosen: ask how to bring it in.
	 */
	private void chooseImport(Ledger backup)
	{
		int bosses = backup.activeBosses().size();
		int drops = 0;
		for (String id : backup.activeBosses())
		{
			drops += backup.copyOf(id).drops.size();
		}
		String what = "This backup has " + bosses + " boss" + (bosses == 1 ? "" : "es") + " and " + drops + " drop" + (drops == 1 ? "" : "s") + ".\n\n"
			+ "Merge adds what is missing from your ledger and keeps everything you have.\nReplace swaps your whole ledger for the backup.";
		int choice = ctx.dialogs().choose(ctx.window(), "Import a backup", what, "Merge into my ledger", "Replace my ledger", "Cancel");
		if (choice == 0)
		{
			int added = ledger.mergeFrom(backup);
			ctx.notice("Backup merged: " + added + " drop" + (added == 1 ? "" : "s") + " added");
		}
		else if (choice == 1)
		{
			if (ctx.dialogs().confirm(ctx.window(), "Replace my ledger", "Replace your whole ledger with the backup? What you have now is lost unless you export it first.", "Replace"))
			{
				ctx.host().replaceLedger(backup);
				ctx.notice("Backup restored");
			}
		}
	}

	private void wipe()
	{
		if (!ctx.dialogs().confirm(ctx.window(), "Erase everything",
			"This removes every kill count and drop from your ledger. Export a backup first if you might want them back.", "Erase everything"))
		{
			return;
		}
		Ledger fresh = new Ledger(ledger.data());
		Prefs keep = ledger.prefs();
		fresh.updatePrefs(p ->
		{
			p.window = keep.window;
			p.rowi = keep.rowi;
			p.lq = keep.lq;
			p.images = keep.images;
		});
		ctx.host().replaceLedger(fresh);
		ctx.notice("Ledger erased");
	}

	// ---- for tests

	JSpinner windowSpinner()
	{
		return window;
	}

	JCheckBox ringBox()
	{
		return rowi;
	}

	JCheckBox questBox()
	{
		return lq;
	}

	JCheckBox picturesBox()
	{
		return images;
	}
}

package com.dropluckledger.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Point;
import java.util.List;
import javax.swing.JViewport;
import javax.swing.SwingUtilities;

/**
 * Replaces what a container shows without making the scroll pane jump.
 */
final class Swap
{
	private Swap()
	{
	}

	/**
	 * Puts new parts into a container and keeps the scroll position where it was (as far as the new height allows).
	 */
	static void into(Container holder, List<? extends Component> parts)
	{
		final JViewport port = (JViewport) SwingUtilities.getAncestorOfClass(JViewport.class, holder);
		final Point where = port == null ? null : port.getViewPosition();
		holder.removeAll();
		for (Component c : parts)
		{
			holder.add(c);
		}
		holder.revalidate();
		holder.repaint();
		if (port != null && where != null && where.y > 0)
		{
			SwingUtilities.invokeLater(() ->
			{
				Dimension view = port.getViewSize();
				int max = Math.max(0, view.height - port.getExtentSize().height);
				port.setViewPosition(new Point(0, Math.min(where.y, max)));
			});
		}
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Row;
import com.dropluckledger.engine.Engine;
import com.dropluckledger.engine.Luck;
import com.dropluckledger.ledger.BossState;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * What the panel shows, worked out away from the Swing thread and handed over finished.  Nothing here changes after it is built.
 */
final class Views
{
	private Views()
	{
	}

	/**
	 * One tracked item of a boss with its luck figures.
	 */
	static final class ItemView
	{
		final String name;
		/**
		 * "unique", "pet" or "drop".
		 */
		final String kind;
		final Engine.ItemMeta meta;
		/**
		 * Null when the figures could not be worked out.
		 */
		final Luck.ItemAnalysis a;
		/**
		 * The figures pooled over every boss that drops the item; null unless the player has kills at two or more of them.
		 */
		final Luck.Pool pool;
		/**
		 * Several bosses list this item in their collection log.
		 */
		final boolean shared;

		ItemView(String name, String kind, Engine.ItemMeta meta, Luck.ItemAnalysis a, Luck.Pool pool, boolean shared)
		{
			this.name = name;
			this.kind = kind;
			this.meta = meta;
			this.a = a;
			this.pool = pool;
			this.shared = shared;
		}
	}

	/**
	 * The "any unique" (or "unique table") card.
	 */
	static final class AnyView
	{
		final Luck.AnyUnique u;
		final List<String> names;
		final List<String> separate;
		/**
		 * A slot whose early hits give a non-unique item (the gold rings).
		 */
		final boolean gold;

		AnyView(Luck.AnyUnique u, List<String> names, List<String> separate, boolean gold)
		{
			this.u = u;
			this.names = Collections.unmodifiableList(new ArrayList<>(names));
			this.separate = Collections.unmodifiableList(new ArrayList<>(separate));
			this.gold = gold;
		}

		/**
		 * The boss rolls its other uniques separately, so this card is the unique table itself.
		 */
		boolean isTable()
		{
			return !separate.isEmpty();
		}
	}

	/**
	 * A boss page's tracker tab.
	 */
	static final class BossView
	{
		final String id;
		final long rev;
		final int kc;
		final int window;
		final List<ItemView> items;
		final AnyView any;
		final BossState state;
		/**
		 * Items on the drop table that are not shown yet, in name order.
		 */
		final List<String> addable;

		BossView(String id, long rev, int kc, int window, List<ItemView> items, AnyView any, BossState state, List<String> addable)
		{
			this.id = id;
			this.rev = rev;
			this.kc = kc;
			this.window = window;
			this.items = Collections.unmodifiableList(items);
			this.any = any;
			this.state = state;
			this.addable = Collections.unmodifiableList(addable);
		}
	}

	/**
	 * A line of the overview's rankings: one item, or one item pooled over the bosses that drop it.
	 */
	static final class Rank
	{
		/**
		 * The boss to open when the line is clicked.
		 */
		final String bossId;
		/**
		 * Where it drops: the boss, or "Duke Sucellus +3 more" when pooled.
		 */
		final String where;
		final String item;
		final int got;
		final double expected;
		final double pct;
		/**
		 * The chance, from all the player's kills, of having at least one more copy than they do by now.
		 */
		final double chance;
		final Luck.Label label;
		final boolean pooled;

		Rank(String bossId, String where, String item, int got, double expected, double pct, double chance, Luck.Label label, boolean pooled)
		{
			this.bossId = bossId;
			this.where = where;
			this.item = item;
			this.got = got;
			this.expected = expected;
			this.pct = pct;
			this.chance = chance;
			this.label = label;
			this.pooled = pooled;
		}
	}

	/**
	 * A line of the overview's list of the player's bosses.
	 */
	static final class BossRow
	{
		final String id;
		final String name;
		final int kc;
		final int got;
		final int total;
		final Luck.AnyUnique any;
		final long updated;

		BossRow(String id, String name, int kc, int got, int total, Luck.AnyUnique any, long updated)
		{
			this.id = id;
			this.name = name;
			this.kc = kc;
			this.got = got;
			this.total = total;
			this.any = any;
			this.updated = updated;
		}
	}

	static final class OverviewView
	{
		final long rev;
		final int tracked;
		final List<Rank> driest;
		final List<Rank> hottest;
		final List<BossRow> bosses;
		final List<Luck.Pool> pooled;

		OverviewView(long rev, int tracked, List<Rank> driest, List<Rank> hottest, List<BossRow> bosses, List<Luck.Pool> pooled)
		{
			this.rev = rev;
			this.tracked = tracked;
			this.driest = driest;
			this.hottest = hottest;
			this.bosses = bosses;
			this.pooled = pooled;
		}
	}

	static final class TableRow
	{
		final String name;
		final double p;
		final String qty;
		final List<String> printed;
		final List<String> where;
		final boolean log;
		final boolean notable;

		TableRow(String name, double p, String qty, List<String> printed, List<String> where, boolean log, boolean notable)
		{
			this.name = name;
			this.p = p;
			this.qty = qty;
			this.printed = printed;
			this.where = where;
			this.log = log;
			this.notable = notable;
		}
	}

	static final class TableView
	{
		final String bossId;
		final List<String> always;
		final List<TableRow> rows;

		TableView(String bossId, List<String> always, List<TableRow> rows)
		{
			this.bossId = bossId;
			this.always = always;
			this.rows = rows;
		}
	}

	/**
	 * The curve of "chance of getting it within this many kills of your last one".
	 */
	static final class ChartData
	{
		final String item;
		final double[] x;
		final double[] y;
		final double xmax;
		final int you;

		ChartData(String item, double[] x, double[] y, double xmax, int you)
		{
			this.item = item;
			this.x = x;
			this.y = y;
			this.xmax = xmax;
			this.you = you;
		}
	}

	/**
	 * How completely the wiki data for a boss was captured.
	 */
	static final class Confidence
	{
		final String level;
		final List<String> unknown;
		final List<String> inferred;
		final List<String> gaps;

		Confidence(String level, List<String> unknown, List<String> inferred, List<String> gaps)
		{
			this.level = level;
			this.unknown = unknown;
			this.inferred = inferred;
			this.gaps = gaps;
		}
	}

	private static final Pattern GAP = Pattern.compile("KNOWN GAP|NOT captured|not modelled|NOT modelled|CAVEAT|unconfirmed|not on page", Pattern.CASE_INSENSITIVE);

	static Confidence confidence(Boss b)
	{
		List<String> unknown = new ArrayList<>();
		List<String> inferred = new ArrayList<>();
		for (Row r : b.allRows())
		{
			if ("unknown".equals(r.rate))
			{
				unknown.add(r.name);
			}
			if (r.flagged("inferred"))
			{
				inferred.add(r.name);
			}
		}
		List<String> gaps = new ArrayList<>();
		for (String n : b.notes)
		{
			if (GAP.matcher(n).find())
			{
				gaps.add(n);
			}
		}
		String level = "high";
		if (!unknown.isEmpty() || !inferred.isEmpty() || !gaps.isEmpty())
		{
			level = "medium";
		}
		if (inferred.size() > 5 || unknown.size() > 1)
		{
			level = "medium-low";
		}
		return new Confidence(level, unknown, inferred, gaps);
	}

	/**
	 * Item name to everything the drop table says about it, for the "as printed on the wiki" column.
	 */
	static final class RowInfo
	{
		String qty = "";
		final List<String> rates = new ArrayList<>();
		final List<String> where = new ArrayList<>();
	}

	static Map<String, RowInfo> rowInfo(Boss b)
	{
		Map<String, RowInfo> info = new java.util.LinkedHashMap<>();
		for (com.dropluckledger.engine.Data.Table t : b.tables)
		{
			String label = t.label != null && !t.label.isEmpty() ? t.label : t.id;
			for (Row r : t.items)
			{
				addInfo(info, r, label);
			}
			for (com.dropluckledger.engine.Data.Sub s : t.subs)
			{
				for (Row r : s.items)
				{
					addInfo(info, r, label + " › " + s.id);
				}
			}
		}
		for (Row r : b.tert)
		{
			addInfo(info, r, "Tertiary");
		}
		for (Row r : b.pets)
		{
			addInfo(info, r, "Pet");
		}
		if (b.data != null)
		{
			for (com.dropluckledger.engine.Data.Shared s : b.data.shared)
			{
				for (com.dropluckledger.engine.Data.Table t : s.tables)
				{
					for (Row r : t.items)
					{
						if (!info.containsKey(r.name))
						{
							RowInfo i = new RowInfo();
							i.qty = r.qty == null ? "" : r.qty;
							info.put(r.name, i);
						}
					}
				}
			}
		}
		return info;
	}

	private static void addInfo(Map<String, RowInfo> info, Row r, String where)
	{
		RowInfo i = info.computeIfAbsent(r.name, k ->
		{
			RowInfo n = new RowInfo();
			n.qty = r.qty == null ? "" : r.qty;
			return n;
		});
		if (r.rate != null && !r.rate.isEmpty() && !i.rates.contains(r.rate) && i.rates.size() < 3)
		{
			i.rates.add(r.rate);
		}
		if (where != null && !where.isEmpty() && !i.where.contains(where))
		{
			i.where.add(where);
		}
	}
}

