		logout();
		String json = text(ledgerFile(111));
		assertTrue(json, json.contains("\"drop-luck-ledger\""));
		assertTrue(json, json.contains("Dragonbone necklace"));
		assertTrue(json, json.contains("\"kc\":50"));
	}

