	@Test
	public void modesComeFromTheLabel()
	{
		KcLabel cox = kc("Your completed Chambers of Xeric count is: <col=ff0000>51</col>.");
		assertEquals("chambers-of-xeric", cox.bossId);
		assertEquals(0, cox.patch.get("cm"));
