package com.dropluckledger.engine;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Engine.ItemProb;
import com.dropluckledger.engine.Luck.AnyUnique;
import com.dropluckledger.engine.Luck.BossRecord;
import com.dropluckledger.engine.Luck.DropRec;
import com.dropluckledger.engine.Luck.ItemAnalysis;
import com.dropluckledger.engine.Luck.Model;
import com.dropluckledger.engine.Luck.Pool;
import com.dropluckledger.engine.Luck.PoolMember;
import com.dropluckledger.engine.Luck.Seg;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Checks the Java engine against vectors produced by the JavaScript engine it was ported from
 * (src/test/resources/parity.json, generated by tools/gen_parity.js of the web app).
 */
public class ParityTest
{
	private static Data data;
	private static JsonObject ref;
	private static final List<String> problems = new ArrayList<>();
	private static int checks;

	@BeforeClass
	public static void load() throws Exception
	{
		try (InputStream in = ParityTest.class.getResourceAsStream("/com/dropluckledger/data.json"))
		{
			data = Data.load(new Gson(), in);
		}
		try (InputStreamReader r = new InputStreamReader(ParityTest.class.getResourceAsStream("/parity.json"), StandardCharsets.UTF_8))
		{
			ref = new JsonParser().parse(r).getAsJsonObject();
		}
	}

	// ------------------------------------------------------------------ helpers
	private static double num(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return Double.NaN;
		}
		String s = e.getAsString();
		switch (s)
		{
			case "Infinity":
				return Double.POSITIVE_INFINITY;
			case "-Infinity":
				return Double.NEGATIVE_INFINITY;
			case "NaN":
				return Double.NaN;
			default:
				return e.getAsDouble();
		}
	}

	private static void same(String where, double expected, double actual)
	{
		checks++;
		if (Double.isNaN(expected) && Double.isNaN(actual))
		{
			return;
		}
		if (expected == actual)
		{
			return;
		}
		double diff = Math.abs(expected - actual);
		double scale = Math.max(Math.abs(expected), Math.abs(actual));
		if (diff <= 1e-12 || diff <= 1e-9 * scale)
		{
			return;
		}
		problems.add(where + ": expected " + expected + " got " + actual);
	}

	private static void sameNullable(String where, JsonElement expected, Double actual)
	{
		checks++;
		boolean en = expected == null || expected.isJsonNull();
		if (en != (actual == null))
		{
			problems.add(where + ": expected " + (en ? "null" : expected) + " got " + actual);
			return;
		}
		if (!en)
		{
			same(where, num(expected), actual);
		}
	}

	private static void eq(String where, Object expected, Object actual)
	{
		checks++;
		if (expected == null ? actual != null : !expected.equals(actual))
		{
			problems.add(where + ": expected " + expected + " got " + actual);
		}
	}

	private static Map<String, Object> params(JsonObject o)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> e : o.entrySet())
		{
			com.google.gson.JsonPrimitive p = e.getValue().getAsJsonPrimitive();
			m.put(e.getKey(), p.isBoolean() ? (Object) p.getAsBoolean() : p.isNumber() ? (Object) p.getAsDouble() : p.getAsString());
		}
		return m;
	}

	private static Map<String, Double> globals(JsonObject o)
	{
		Map<String, Double> m = new HashMap<>();
		for (Map.Entry<String, JsonElement> e : o.entrySet())
		{
			m.put(e.getKey(), e.getValue().getAsDouble());
		}
		return m;
	}

	private static BossRecord record(JsonObject st)
	{
		BossRecord r = new BossRecord();
		r.kc = st.get("kc").getAsInt();
		for (JsonElement se : st.getAsJsonArray("segs"))
		{
			JsonObject s = se.getAsJsonObject();
			r.segs.add(new Seg(s.get("from").getAsInt(), params(s.getAsJsonObject("params"))));
		}
		for (JsonElement de : st.getAsJsonArray("drops"))
		{
			JsonObject d = de.getAsJsonObject();
			r.drops.add(new DropRec(d.get("item").getAsString(), d.get("kc").isJsonNull() ? null : d.get("kc").getAsInt()));
		}
		return r;
	}

	private static void finish(String what)
	{
		System.out.println(what + ": " + checks + " checks, " + problems.size() + " problems");
		if (!problems.isEmpty())
		{
			int n = Math.min(problems.size(), 40);
			for (int i = 0; i < n; i++)
			{
				System.out.println("  " + problems.get(i));
			}
			Assert.fail(problems.size() + " mismatches against the JavaScript reference (first: " + problems.get(0) + ")");
		}
	}

	// ------------------------------------------------------------------ tests
	@Test
	public void catalogueMatches()
	{
		problems.clear();
		checks = 0;
		JsonObject metas = ref.getAsJsonObject("metas");
		for (Map.Entry<String, JsonElement> e : metas.entrySet())
		{
			Boss boss = data.boss(e.getKey());
			Assert.assertNotNull("boss " + e.getKey(), boss);
			JsonObject m = e.getValue().getAsJsonObject();
			List<String> tracked = new ArrayList<>();
			for (JsonElement t : m.getAsJsonArray("tracked"))
			{
				tracked.add(t.getAsString());
			}
			eq(e.getKey() + " tracked", tracked, Catalog.defaultTracked(boss));
			Map<String, Engine.ItemMeta> meta = boss.meta();
			JsonArray arr = m.getAsJsonArray("meta");
			eq(e.getKey() + " meta size", arr.size(), meta.size());
			for (JsonElement me : arr)
			{
				JsonObject o = me.getAsJsonObject();
				String n = o.get("n").getAsString();
				Engine.ItemMeta im = meta.get(n);
				if (im == null)
				{
					problems.add(e.getKey() + ": missing meta for " + n);
					continue;
				}
				List<String> flags = new ArrayList<>();
				for (JsonElement f : o.getAsJsonArray("f"))
				{
					flags.add(f.getAsString());
				}
				eq(e.getKey() + "/" + n + " flags", flags, im.flags);
				eq(e.getKey() + "/" + n + " hidden", o.get("h").getAsBoolean(), im.hidden);
				eq(e.getKey() + "/" + n + " noany", o.get("na").getAsBoolean(), im.noany);
				eq(e.getKey() + "/" + n + " pity", o.get("p").getAsInt(), im.pity);
				if (o.get("s").isJsonNull())
				{
					eq(e.getKey() + "/" + n + " seq", null, im.seq);
				}
				else
				{
					JsonObject s = o.getAsJsonObject("s");
					checks++;
					if (im.seq == null || !im.seq.slot.equals(s.get("slot").getAsString()) || im.seq.n != s.get("n").getAsInt() || im.seq.len != s.get("len").getAsInt())
					{
						problems.add(e.getKey() + "/" + n + " seq differs");
					}
				}
			}
			List<String> log = new ArrayList<>();
			for (JsonElement l : m.getAsJsonArray("log"))
			{
				log.add(l.getAsString());
			}
			eq(e.getKey() + " log set", log, new ArrayList<>(boss.logSet()));
			JsonObject follow = m.getAsJsonObject("follow");
			Map<String, List<String>> fm = Engine.followMap(boss);
			eq(e.getKey() + " follow keys", follow.keySet().size(), fm.size());
		}
		finish("catalogue");
	}

	@Test
	public void perKillChancesMatch()
	{
		problems.clear();
		checks = 0;
		for (JsonElement ce : ref.getAsJsonArray("probCases"))
		{
			JsonObject c = ce.getAsJsonObject();
			Boss boss = data.boss(c.get("boss").getAsString());
			Env env = Engine.makeEnv(boss, params(c.getAsJsonObject("params")), globals(c.getAsJsonObject("globals")), c.get("kc").getAsInt());
			Map<String, ItemProb> probs = Engine.itemProbs(boss, env, null, null);
			String tag = boss.id + " kc" + c.get("kc").getAsInt();
			for (Map.Entry<String, JsonElement> e : c.getAsJsonObject("probs").entrySet())
			{
				ItemProb ip = probs.get(e.getKey());
				if (ip == null)
				{
					problems.add(tag + ": no probability for " + e.getKey());
					continue;
				}
				JsonObject o = e.getValue().getAsJsonObject();
				same(tag + " " + e.getKey(), num(o.get("p")), ip.p);
				List<String> kinds = new ArrayList<>();
				if (o.has("k"))
				{
					for (JsonElement k : o.getAsJsonArray("k"))
					{
						kinds.add(k.getAsString());
					}
				}
				else
				{
					kinds.add("table");
				}
				eq(tag + " " + e.getKey() + " kinds", kinds, ip.kinds);
				checks++;
				if (o.has("s") != (ip.seq != null))
				{
					problems.add(tag + " " + e.getKey() + " seq presence differs");
				}
			}
		}
		finish("per-kill chances");
	}

	@Test
	public void luckAnalysisMatches()
	{
		problems.clear();
		checks = 0;
		for (JsonElement ce : ref.getAsJsonArray("cases"))
		{
			JsonObject c = ce.getAsJsonObject();
			Boss boss = data.boss(c.get("boss").getAsString());
			int window = c.get("window").getAsInt();
			BossRecord rec = record(c.getAsJsonObject("state"));
			Model m = Luck.makeModel(boss, rec, globals(c.getAsJsonObject("globals")));
			String tag0 = boss.id + " kc" + rec.kc;
			for (Map.Entry<String, JsonElement> e : c.getAsJsonObject("items").entrySet())
			{
				String tag = tag0 + " " + e.getKey();
				JsonObject o = e.getValue().getAsJsonObject();
				ItemAnalysis a = Luck.analyse(m, e.getKey(), window);
				eq(tag + " O", o.get("O").getAsInt(), a.O);
				eq(tag + " unknown", o.get("unknown").getAsInt(), a.unknown);
				eq(tag + " hits", o.get("hits").isJsonNull() ? null : o.get("hits").getAsInt(), a.hits);
				eq(tag + " once", o.get("once").getAsBoolean(), a.once);
				eq(tag + " collected", o.get("collected").getAsBoolean(), a.collected);
				eq(tag + " need", o.get("need").getAsInt(), a.need);
				same(tag + " pNext", num(o.get("pNext")), a.pNext);
				sameNullable(tag + " expected", o.get("expected"), a.expected);
				sameNullable(tag + " pct", o.get("pct"), a.pct);
				sameNullable(tag + " exceed", o.get("exceed"), a.exceed);
				sameNullable(tag + " cum", o.get("cum"), a.cum);
				eq(tag + " label", o.getAsJsonObject("label").get("key").getAsString(), a.label.key);
				eq(tag + " streakFrom", o.get("streakFrom").getAsInt(), a.streakFrom);
				eq(tag + " streak", o.get("streak").getAsInt(), a.streak);
				same(tag + " meter", num(o.get("meter")), a.meter);
				JsonObject fwd = o.getAsJsonObject("fwd");
				eq(tag + " fwd keys", fwd.keySet().size(), a.fwd.size());
				for (Map.Entry<String, JsonElement> f : fwd.entrySet())
				{
					Double got = a.fwd.get(Integer.parseInt(f.getKey()));
					if (got == null)
					{
						problems.add(tag + " fwd[" + f.getKey() + "] missing");
					}
					else
					{
						same(tag + " fwd[" + f.getKey() + "]", num(f.getValue()), got);
					}
				}
				if (o.has("kto"))
				{
					for (Map.Entry<String, JsonElement> k : o.getAsJsonObject("kto").entrySet())
					{
						double want = num(k.getValue());
						double got = a.kto.get(Double.parseDouble(k.getKey()));
						checks++;
						// a kill count found by bisection can sit on the edge of a threshold: allow one kill of slack
						if (!(want == got || (Double.isFinite(want) && Math.abs(want - got) <= 1)))
						{
							problems.add(tag + " kto[" + k.getKey() + "] expected " + want + " got " + got);
						}
					}
				}
				else
				{
					eq(tag + " kto absent", null, a.kto);
				}
			}
			AnyUnique au = null;
			List<String> an = new ArrayList<>();
			for (JsonElement n : c.getAsJsonArray("anyNames"))
			{
				an.add(n.getAsString());
			}
			if (an.size() >= 2)
			{
				au = Luck.anyUnique(m, an, window);
			}
			JsonElement any = c.get("any");
			if (any == null || any.isJsonNull())
			{
				eq(tag0 + " any", null, au);
			}
			else if (au == null)
			{
				problems.add(tag0 + " any unique missing");
			}
			else
			{
				JsonObject o = any.getAsJsonObject();
				eq(tag0 + " any O", o.get("O").getAsInt(), au.O);
				same(tag0 + " any expected", num(o.get("expected")), au.expected);
				same(tag0 + " any pct", num(o.get("pct")), au.pct);
				same(tag0 + " any meter", num(o.get("meter")), au.meter);
				same(tag0 + " any cum", num(o.get("cum")), au.cum);
				eq(tag0 + " any streak", o.get("streak").getAsInt(), au.streak);
				same(tag0 + " any pNext", num(o.get("pNext")), au.pNext);
				eq(tag0 + " any events", o.get("events").getAsInt(), au.events);
				for (Map.Entry<String, JsonElement> f : o.getAsJsonObject("fwd").entrySet())
				{
					same(tag0 + " any fwd[" + f.getKey() + "]", num(f.getValue()), au.fwd.get(Integer.parseInt(f.getKey())));
				}
			}
		}
		finish("luck analysis");
	}

	@Test
	public void pooledAnalysisMatches()
	{
		problems.clear();
		checks = 0;
		for (JsonElement pe : ref.getAsJsonArray("pools"))
		{
			JsonObject p = pe.getAsJsonObject();
			String name = p.get("name").getAsString();
			Map<String, Double> g = globals(p.getAsJsonObject("globals"));
			List<PoolMember> members = new ArrayList<>();
			for (JsonElement me : p.getAsJsonArray("members"))
			{
				JsonObject mo = me.getAsJsonObject();
				members.add(new PoolMember(Luck.makeModel(data.boss(mo.get("id").getAsString()), record(mo.getAsJsonObject("rec")), g), mo.get("snap").getAsInt()));
			}
			Pool r = Luck.analysePool(members, name, 50);
			JsonElement want = p.get("res");
			if (want == null || want.isJsonNull())
			{
				eq("pool " + name, null, r);
				continue;
			}
			JsonObject o = want.getAsJsonObject();
			if (r == null)
			{
				problems.add("pool " + name + " missing");
				continue;
			}
			eq("pool " + name + " O", o.get("O").getAsInt(), r.O);
			same("pool " + name + " expected", num(o.get("expected")), r.expected);
			same("pool " + name + " pct", num(o.get("pct")), r.pct);
			same("pool " + name + " meter", num(o.get("meter")), r.meter);
			same("pool " + name + " cum", num(o.get("cum")), r.cum);
			eq("pool " + name + " streak", o.get("streak").getAsLong(), r.streak);
			eq("pool " + name + " kills", o.get("kills").getAsLong(), r.kills);
		}
		finish("pooled analysis");
	}
}

package com.dropluckledger.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.Capture;
import com.dropluckledger.engine.Data;
import com.dropluckledger.history.HistoryPlanner.ItemRow;
import com.dropluckledger.history.HistoryPlanner.KcRow;
import com.dropluckledger.history.HistoryPlanner.Plan;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Drop;
import com.dropluckledger.ledger.Ledger;
import java.util.Arrays;
import org.junit.Before;
import org.junit.Test;

public class HistoryPlannerTest
{
	private final Data data = TestData.get();
	private final BossIndex index = new BossIndex(data);
	private Ledger ledger;
	private HistoryPlanner planner;

	@Before
	public void setUp()
	{
		ledger = new Ledger(data, () -> 5_000L);
		planner = new HistoryPlanner(ledger, index);
	}

	private static KcRow kcRow(Plan p, String id)
	{
		for (KcRow r : p.kc)
		{
			if (r.bossId.equals(id))
			{
				return r;
			}
		}
		return null;
	}

	private static ItemRow itemRow(Plan p, String id, String item)
	{
		for (ItemRow r : p.items)
		{
			if (r.bossId.equals(id) && r.item.equals(item))
			{
				return r;
			}
		}
		return null;
	}

	@Test
	public void killCountsFromTheBossKillLog()
	{
		HistoryInput in = new HistoryInput();
		in.addKc("Zulrah", 1234, "Boss Kill Log");
		in.addKc("Barrows Chests", 280, "Boss Kill Log");
		in.addKc("Corporeal Beast", 7, "Boss Kill Log");
		in.addKc("Goblin", 3, "Boss Kill Log");
		in.addKc("The Nightmare", 15, "Boss Kill Log");
		Plan plan = planner.plan(in);
		assertEquals(4, plan.kc.size());
		assertEquals(1, plan.kcSkipped.size());
		assertEquals(1234, kcRow(plan, "zulrah").to);
		assertEquals(280, kcRow(plan, "barrows").to);
		assertEquals(15, kcRow(plan, "the-nightmare").to);
		assertEquals(4, plan.kcToApply());
		int[] done = planner.apply(plan);
		assertEquals(4, done[0]);
		assertEquals(1234, ledger.kc("zulrah"));
		assertEquals(Integer.valueOf(1234), ledger.copyOf("zulrah").labelKc.get("Zulrah"));
		assertEquals(280, ledger.kc("barrows"));
		assertEquals(Integer.valueOf(280), ledger.copyOf("barrows").labelKc.get("Barrows Chest"));
	}

	@Test
	public void modesOfOneBossAreAddedUpAndLaidOutInBlocks()
	{
		HistoryInput in = new HistoryInput();
		in.addKc("Chambers of Xeric", 50, "Boss Kill Log");
		in.addKc("Chambers of Xeric Challenge Mode", 12, "Boss Kill Log");
		in.addKc("Duke Sucellus", 100, "Boss Kill Log");
		in.addKc("Awakened Duke Sucellus", 30, "Boss Kill Log");
		Plan plan = planner.plan(in);
		assertEquals(62, kcRow(plan, "chambers-of-xeric").to);
		assertEquals(130, kcRow(plan, "duke-sucellus").to);
		planner.apply(plan);
		BossState c = ledger.copyOf("chambers-of-xeric");
		assertEquals(62, c.kc);
		assertEquals(2, c.segs.size());
		assertEquals(1, c.segs.get(0).from);
		assertEquals(0, ((Number) c.paramsAt(50).get("cm")).intValue());
		assertEquals(51, c.segs.get(1).from);
		assertEquals(1, ((Number) c.paramsAt(62).get("cm")).intValue());
		BossState d = ledger.copyOf("duke-sucellus");
		assertEquals(101, d.segs.get(1).from);
		assertEquals(1, ((Number) d.paramsAt(130).get("awakened")).intValue());
		assertEquals(0, ((Number) d.paramsAt(100).get("awakened")).intValue());
	}

	@Test
	public void applyingTwiceChangesNothing()
	{
		HistoryInput in = new HistoryInput();
		in.addKc("Zulrah", 500, "Boss Kill Log");
		in.addOwned(null, "Zulrah", "Tanzanite fang", 2, "Collection log");
		in.addOwned(null, "Zulrah", "Pet snakeling", 1, "Collection log");
		planner.apply(planner.plan(in));
		assertEquals(3, ledger.copyOf("zulrah").drops.size());
		Plan again = planner.plan(in);
		assertFalse(kcRow(again, "zulrah").on);
		assertEquals(0, again.copiesToAdd());
		assertTrue(again.isEmpty());
		int[] done = planner.apply(again);
		assertEquals(0, done[0]);
		assertEquals(0, done[1]);
		assertEquals(3, ledger.copyOf("zulrah").drops.size());
	}

	@Test
	public void ownedCopiesComeInWithoutAKillNumber()
	{
		HistoryInput in = new HistoryInput();
		in.addOwned(null, "Zulrah", "tanzanite FANG", 2, "Collection log");
		in.addOwned(null, "Zulrah", "Coins", 100, "Collection log");
		Plan plan = planner.plan(in);
		ItemRow r = itemRow(plan, "zulrah", "Tanzanite fang");
		assertNotNull(r);
		assertEquals(2, r.add);
		assertFalse(r.assumed);
		assertEquals(Arrays.asList("Coins"), plan.itemsMissing);
		planner.apply(plan);
		BossState z = ledger.copyOf("zulrah");
		assertEquals(2, z.copies("Tanzanite fang"));
		for (Drop d : z.drops)
		{
			assertNull(d.kc);
			assertEquals(Drop.SRC_IMPORT, d.src);
		}
	}

	@Test
	public void copiesTheLedgerAlreadyHasAreNotAddedAgain()
	{
		Capture capture = new Capture(ledger, index);
		capture.onKillCount("Zulrah", 100, 0);
		capture.onLoot(new Capture.Loot("Zulrah", 1, Arrays.asList(new Capture.Stack("Tanzanite fang", 1)), null, 2));
		assertEquals(1, ledger.copyOf("zulrah").copies("Tanzanite fang"));
		HistoryInput in = new HistoryInput();
		in.addOwned(null, "Zulrah", "Tanzanite fang", 3, "Collection log");
		Plan plan = planner.plan(in);
		ItemRow r = itemRow(plan, "zulrah", "Tanzanite fang");
		assertEquals(3, r.want);
		assertEquals(1, r.have);
		assertEquals(2, r.add);
		planner.apply(plan);
		BossState z = ledger.copyOf("zulrah");
		assertEquals(3, z.copies("Tanzanite fang"));
		// the live copy keeps its kill number
		assertEquals(Integer.valueOf(100), z.drops.get(0).kc);
	}

	@Test
	public void lootTrackerCopiesNameTheBossAndOverrideTheCollectionLog()
	{
		HistoryInput in = new HistoryInput();
		in.addOwned("zulrah", null, "Tanzanite fang", 3, "Loot Tracker");
		in.addOwned(null, "Zulrah", "Tanzanite fang", 2, "Collection log"); // log says 2, loot tracker 3: the larger count wins
		Plan plan = planner.plan(in);
		assertEquals(1, plan.items.size());
		assertEquals(3, itemRow(plan, "zulrah", "Tanzanite fang").want);
		HistoryInput in2 = new HistoryInput();
		in2.addOwned("zulrah", null, "Tanzanite fang", 3, "Loot Tracker");
		in2.addOwned(null, "Zulrah", "Tanzanite fang", 4, "Collection log"); // one more than the loot tracker saw
		Plan plan2 = planner.plan(in2);
		assertEquals(4, itemRow(plan2, "zulrah", "Tanzanite fang").want);
	}

	@Test
	public void sharedItemsGoToTheBossTheCollectionLogPageNames()
	{
		HistoryInput in = new HistoryInput();
		in.addKc("Callisto", 400, "Boss Kill Log");
		in.addKc("Venenatis", 900, "Boss Kill Log");
		in.addOwned(null, "Venenatis and Spindel", "Dragon pickaxe", 1, "Collection log");
		in.addOwned(null, "Callisto and Artio", "Callisto cub", 1, "Collection log");
		Plan plan = planner.plan(in);
		ItemRow pick = itemRow(plan, "venenatis", "Dragon pickaxe");
		assertNotNull(pick); // the page names Venenatis and Spindel: it goes to the one with more kills, and is flagged
		assertTrue(pick.assumed);
		assertNull(itemRow(plan, "spindel", "Dragon pickaxe"));
		// the page names two bosses: it goes to the one with more kills and is flagged
		ItemRow cub = itemRow(plan, "callisto", "Callisto cub");
		ItemRow cubArtio = itemRow(plan, "artio", "Callisto cub");
		assertTrue(cub != null || cubArtio != null);
		assertTrue((cub != null ? cub : cubArtio).assumed);
	}

	@Test
	public void absurdCountsAreCapped()
	{
		HistoryInput in = new HistoryInput();
		in.addOwned(null, "Zulrah", "Magic fang", 5000, "Collection log");
		Plan plan = planner.plan(in);
		assertEquals(HistoryPlanner.MAX_COPIES, itemRow(plan, "zulrah", "Magic fang").add);
	}

	@Test
	public void aStackOfBoltRacksIsNotThreeThousandDrops()
	{
		// the Collection Log and the Loot Tracker keep the running total of the stack, not the number of chests it came from
		HistoryInput in = new HistoryInput();
		in.addKc("Barrows Chests", 1000, "Boss Kill Log");
		in.addOwned(null, "Barrows Chests", "Bolt rack", 3750, "Collection log");
		Plan plan = planner.plan(in);
		ItemRow r = itemRow(plan, "barrows", "Bolt rack");
		assertNotNull(r);
		assertEquals(100, r.want);
		assertEquals(3750, r.quantity);
		assertTrue(r.estimated());
		assertEquals(100, r.add);
		planner.apply(plan);
		assertEquals(100, ledger.copyOf("barrows").copies("Bolt rack"));
		// and the same total from the Loot Tracker, which names the boss
		HistoryInput exact = new HistoryInput();
		exact.addOwned("barrows", null, "Bolt rack", 3750, "Loot Tracker");
		ItemRow e = itemRow(planner.plan(exact), "barrows", "Bolt rack");
		assertEquals(100, e.want);
		assertEquals(3750, e.quantity);
		assertEquals(0, e.add); // already in the ledger from the first import
	}

	@Test
	public void anEarlierImportThatCountedAStackAsDropsIsCorrected()
	{
		// the first version of the importer took 3,750 bolt racks as 200 drops (its cap)
		ledger.setKc("barrows", 1000);
		ledger.logDrop("barrows", "Bolt rack", 50, 1, null, Drop.SRC_MANUAL);
		ledger.addOwned("barrows", "Bolt rack", 200);
		HistoryInput in = new HistoryInput();
		in.addOwned(null, "Barrows Chests", "Bolt rack", 3750, "Collection log");
		Plan plan = planner.plan(in);
		ItemRow r = itemRow(plan, "barrows", "Bolt rack");
		assertEquals(100, r.want);
		assertEquals(201, r.have);
		assertEquals(0, r.add);
		assertEquals(101, r.remove);
		assertTrue(r.on);
		assertEquals(101, plan.copiesToRemove());
		assertFalse(plan.isEmpty());
		int[] done = planner.apply(plan);
		assertEquals(0, done[1]);
		assertEquals(101, done[2]);
		BossState b = ledger.copyOf("barrows");
		assertEquals(100, b.copies("Bolt rack"));
		// the copy that was logged by hand, with its kill number, is still there
		assertEquals(1, b.drops.stream().filter(d -> d.kc != null && d.item.equals("Bolt rack")).count());
		// and a second run has nothing left to do
		assertTrue(planner.plan(in).isEmpty());
	}

	@Test
	public void copiesAreNeverTakenBackForItemsThatDropOneAtATime()
	{
		ledger.addOwned("zulrah", "Tanzanite fang", 5);
		HistoryInput in = new HistoryInput();
		in.addOwned(null, "Zulrah", "Tanzanite fang", 2, "Collection log");
		Plan plan = planner.plan(in);
		assertEquals(0, itemRow(plan, "zulrah", "Tanzanite fang").remove);
		assertTrue(plan.isEmpty());
		planner.apply(plan);
		assertEquals(5, ledger.copyOf("zulrah").copies("Tanzanite fang"));
	}

	@Test
	public void itemsThatDropOneAtATimeAreNotEstimated()
	{
		HistoryInput in = new HistoryInput();
		in.addOwned(null, "Zulrah", "Tanzanite fang", 2, "Collection log");
		ItemRow r = itemRow(planner.plan(in), "zulrah", "Tanzanite fang");
		assertEquals(2, r.want);
		assertEquals(0, r.quantity);
		assertFalse(r.estimated());
	}

	@Test
	public void aBossWithManyKillsTakesMoreThanTheUsualCap()
	{
		HistoryInput in = new HistoryInput();
		in.addKc("Zulrah", 1000, "Boss Kill Log");
		in.addOwned(null, "Zulrah", "Magic fang", 500, "Collection log");
		Plan plan = planner.plan(in);
		assertEquals(500, itemRow(plan, "zulrah", "Magic fang").add);
		planner.apply(plan);
		assertEquals(500, ledger.copyOf("zulrah").copies("Magic fang"));
	}

	@Test
	public void killCountNeverGoesDown()
	{
		ledger.setKc("zulrah", 2000);
		HistoryInput in = new HistoryInput();
		in.addKc("Zulrah", 1500, "Boss Kill Log");
		Plan plan = planner.plan(in);
		assertFalse(kcRow(plan, "zulrah").on);
		planner.apply(plan);
		assertEquals(2000, ledger.kc("zulrah"));
	}

	@Test
	public void importThenLiveKillsContinueFromTheImportedCount()
	{
		HistoryInput in = new HistoryInput();
		in.addKc("Zulrah", 1234, "Boss Kill Log");
		planner.apply(planner.plan(in));
		Capture capture = new Capture(ledger, index);
		capture.onKillCount("Zulrah", 1235, 10);
		capture.onLoot(new Capture.Loot("Zulrah", 1, Arrays.asList(new Capture.Stack("Magic fang", 1)), null, 12));
		BossState z = ledger.copyOf("zulrah");
		assertEquals(1235, z.kc);
		assertEquals(Integer.valueOf(1235), z.drops.get(0).kc);
	}
}

package com.dropluckledger.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.dropluckledger.TestData;
import com.dropluckledger.engine.Data;
import org.junit.Test;

public class QuantitiesTest
{
	private final Data data = TestData.get();

	@Test
	public void amountsInTheDropTableAreRead()
	{
		assertEquals(3, Quantities.parse("3"), 0);
		assertEquals(37.5, Quantities.parse("35-40"), 0);
		assertEquals(11, Quantities.parse("11;17"), 0);
		assertEquals(200, Quantities.parse("200;300n"), 0);
		assertEquals(1500, Quantities.parse("1,500;2,250"), 0);
		assertNull(Quantities.parse("-"));
		assertNull(Quantities.parse(""));
		assertNull(Quantities.parse(null));
	}

	@Test
	public void aStackOfBoltRacksIsAboutOneHundredBarrowsChests()
	{
		// a Barrows chest gives 35-40 bolt racks
		assertEquals(37.5, Quantities.perDrop(data.boss("barrows"), "Bolt rack"), 1e-9);
		assertEquals(100, Quantities.drops(data.boss("barrows"), "Bolt rack", 3750));
		assertEquals(1, Quantities.drops(data.boss("barrows"), "Bolt rack", 20)); // never below one drop once something was received
	}

	@Test
	public void severalAmountsAreAveragedByHowLikelyEachIs()
	{
		// Amoxliatl's frozen tears: 2-4 at 6 in 10, 5-10 at 3 in 10, 10-20 at 1 in 10
		double each = 0.6 * 3 + 0.3 * 7.5 + 0.1 * 15;
		assertEquals(each, Quantities.perDrop(data.boss("amoxliatl"), "Frozen tear"), 1e-9);
		assertEquals(100, Quantities.drops(data.boss("amoxliatl"), "Frozen tear", (int) Math.round(each * 100)));
	}

	@Test
	public void itemsThatDropOneAtATimeAreNotChanged()
	{
		assertEquals(1, Quantities.perDrop(data.boss("zulrah"), "Tanzanite fang"), 0);
		assertEquals(7, Quantities.drops(data.boss("zulrah"), "Tanzanite fang", 7));
		assertEquals(0, Quantities.drops(data.boss("zulrah"), "Tanzanite fang", 0));
		assertEquals(0, Quantities.drops(data.boss("zulrah"), "Tanzanite fang", -3));
		// an item the boss does not list has no amount at all
		assertEquals(1, Quantities.perDrop(data.boss("zulrah"), "No such item"), 0);
	}
}

package com.dropluckledger.ledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.engine.Data;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class LedgerMergeTest
{
	private final Data data = TestData.get();

	private Ledger ledger()
	{
		return new Ledger(data, () -> 1_700_000_000_000L);
	}

	@Test
	public void aBossTheLedgerLacksComesOverWhole()
	{
		Ledger mine = ledger();
		mine.setKc("zulrah", 100);
		Ledger backup = ledger();
		backup.setKc("vorkath", 250);
		backup.logDrop("vorkath", "Dragonbone necklace", 90, 1, null, Drop.SRC_MANUAL);
		int added = mine.mergeFrom(backup);
		assertEquals(1, added);
		assertEquals(250, mine.kc("vorkath"));
		assertEquals(1, mine.copyOf("vorkath").drops.size());
		assertEquals(100, mine.kc("zulrah"));
	}

	@Test
	public void dropsAreAddedOnceAndKillCountsTakeTheLarger()
	{
		Ledger mine = ledger();
		mine.setKc("zulrah", 100);
		Drop shared = mine.logDrop("zulrah", "Magic fang", 50, 1, null, Drop.SRC_MANUAL);
		Ledger backup = ledger();
		backup.setKc("zulrah", 400);
		backup.replaceWith(mine); // starts from the same drop (same id)
		backup.setKc("zulrah", 400);
		backup.logDrop("zulrah", "Tanzanite fang", 300, 1, null, Drop.SRC_MANUAL);
		int added = mine.mergeFrom(backup);
		assertEquals("only the drop that was not there", 1, added);
		assertEquals(400, mine.kc("zulrah"));
		List<String> items = new ArrayList<>();
		for (Drop d : mine.copyOf("zulrah").drops)
		{
			items.add(d.item);
		}
		assertTrue(items.contains("Magic fang"));
		assertTrue(items.contains("Tanzanite fang"));
		assertEquals(2, items.size());
		// merging the same backup again changes nothing
		assertEquals(0, mine.mergeFrom(backup));
		assertEquals(shared.id, mine.copyOf("zulrah").drops.get(0).id);
	}

	@Test
	public void theBackupIsNotChangedByTheMerge()
	{
		Ledger mine = ledger();
		mine.logDrop("zulrah", "Magic fang", 50, 1, null, Drop.SRC_MANUAL);
		Ledger backup = ledger();
		backup.logDrop("zulrah", "Tanzanite fang", 60, 1, null, Drop.SRC_MANUAL);
		mine.mergeFrom(backup);
		mine.logDrop("zulrah", "Serpentine visage", 70, 1, null, Drop.SRC_MANUAL);
		assertEquals(1, backup.copyOf("zulrah").drops.size());
	}

	@Test
	public void theViewIsRememberedAndSaved()
	{
		Ledger l = ledger();
		List<String> seen = new ArrayList<>();
		l.addListener(id -> seen.add(String.valueOf(id)));
		long rev = l.revision();
		long bossRev = l.revision("zulrah");
		l.setView("zulrah", "table", "new");
		assertEquals("zulrah", l.prefs().sel);
		assertEquals("table", l.prefs().tab);
		assertEquals("new", l.prefs().scope);
		assertTrue("saved", l.revision() > rev);
		assertEquals("no figure depends on it", bossRev, l.revision("zulrah"));
		assertEquals(1, seen.size());
		l.setView("zulrah", "table", "new");
		assertEquals("unchanged: nothing to save", 1, seen.size());
	}
}

package com.dropluckledger.ledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.dropluckledger.TestData;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Luck;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;
