	private static final class MemStore implements LedgerStore
	{
		String text;
		int writes;
		boolean quarantined;
		boolean failWrites;
		final CompletableFuture<Void> firstWrite = new CompletableFuture<>();

		@Override
		public String read()
		{
			return text;
		}

		@Override
		public void write(String json) throws IOException
		{
			if (failWrites)
			{
				throw new IOException("disk full");
			}
			text = json;
			writes++;
			firstWrite.complete(null);
		}

		@Override
		public void quarantine()
		{
			quarantined = true;
			text = null;
		}
	}

	@Test
	public void saverWritesAfterTheLastChange() throws Exception
	{
		Ledger l = ledger();
		ScheduledExecutorService ex = Executors.newSingleThreadScheduledExecutor();
		try
		{
			LedgerSaver saver = new LedgerSaver(l, gson, ex, 50);
			l.addListener(saver);
			MemStore store = new MemStore();
			saver.setStore(store);
			for (int i = 1; i <= 20; i++)
			{
				l.setKc("zulrah", i);
			}
			assertEquals(0, store.writes);
			store.firstWrite.get(3, TimeUnit.SECONDS);
			assertEquals(1, store.writes); // twenty changes, one write
			assertTrue(store.text.contains("\"kc\":20"));
			// nothing changed: flush does nothing
			saver.flushNow();
			assertEquals(1, store.writes);
			// flush writes straight away
			l.setKc("zulrah", 30);
			saver.flushNow();
			assertEquals(2, store.writes);
			assertTrue(store.text.contains("\"kc\":30"));
			// a failing disk is retried at the next change and does not throw
			store.failWrites = true;
			l.setKc("zulrah", 31);
			saver.flushNow();
			assertEquals(2, store.writes);
			store.failWrites = false;
			l.setKc("zulrah", 32);
			saver.flushNow();
			assertEquals(3, store.writes);
			assertTrue(store.text.contains("\"kc\":32"));
		}
		finally
		{
			ex.shutdownNow();
		}
	}

	@Test
	public void switchingAccountsSavesTheFirstBeforeLoadingTheSecond() throws Exception
	{
		Ledger l = ledger();
		ScheduledExecutorService ex = Executors.newSingleThreadScheduledExecutor();
		try
		{
			LedgerSaver saver = new LedgerSaver(l, gson, ex, 60_000);
			l.addListener(saver);
			MemStore a = new MemStore();
			MemStore b = new MemStore();
			b.text = LedgerCodec.toJson(gson, otherLedger(77));
			saver.setStore(a);
			l.setKc("zulrah", 11);
			// switch: flush a, detach, load b, attach b
			saver.setStore(null);
			assertTrue(a.text.contains("\"kc\":11"));
			assertTrue(saver.loadInto(b));
			saver.setStore(b);
			assertEquals(77, l.kc("zulrah"));
			assertEquals(0, b.writes); // loading did not rewrite the file
			l.setKc("zulrah", 78);
			saver.flushNow();
			assertTrue(b.text.contains("\"kc\":78"));
			assertTrue(a.text.contains("\"kc\":11"));
		}
		finally
		{
			ex.shutdownNow();
		}
	}

	private Ledger otherLedger(int kc)
	{
		Ledger o = ledger();
		o.setKc("zulrah", kc);
		return o;
	}

	@Test
	public void unreadableFileIsSetAsideNotOverwritten() throws Exception
	{
		Ledger l = ledger();
		ScheduledExecutorService ex = Executors.newSingleThreadScheduledExecutor();
		try
		{
			LedgerSaver saver = new LedgerSaver(l, gson, ex, 10);
			MemStore s = new MemStore();
			s.text = "{ this is not json";
			assertFalse(saver.loadInto(s));
			assertTrue(s.quarantined);
			assertTrue(l.activeBosses().isEmpty());
		}
		finally
		{
			ex.shutdownNow();
		}
	}
}

package com.dropluckledger.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.capture.KcMessages;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Ledger;
import org.junit.Test;

public class DropMessagesTest
{
	private static String plain(String s)
	{
		return KcMessages.stripTags(s);
	}

	@Test
	public void firstCopyAfterManyKills()
	{
		Ledger l = new Ledger(TestData.get());
		l.setKc("vorkath", 1234);
		l.logDrop("vorkath", "Skeletal visage", 1234, 1, null, "live");
		BossState s = l.copyOf("vorkath");
		assertEquals("Logged Skeletal visage at Vorkath kill 1,234 (the first one, after 1,233 kills).", plain(DropMessages.build(TestData.get(), "vorkath", s, "Skeletal visage", 1234)));
	}

	@Test
	public void laterCopyShowsKillsSinceTheLastOne()
	{
		Ledger l = new Ledger(TestData.get());
		l.setKc("vorkath", 900);
		l.logDrop("vorkath", "Dragonbone necklace", 500, 1, null, "live");
		l.logDrop("vorkath", "Dragonbone necklace", 900, 1, null, "live");
		String m = plain(DropMessages.build(TestData.get(), "vorkath", l.copyOf("vorkath"), "Dragonbone necklace", 900));
		assertEquals("Logged Dragonbone necklace at Vorkath kill 900 (400 kills since the last one).", m);
	}

	@Test
	public void backToBackIsOneKill()
	{
		Ledger l = new Ledger(TestData.get());
		l.logDrop("vorkath", "Vorki", 9, 1, null, "live");
		l.logDrop("vorkath", "Vorki", 10, 1, null, "live");
		assertTrue(plain(DropMessages.build(TestData.get(), "vorkath", l.copyOf("vorkath"), "Vorki", 10)).contains("(1 kill since the last one)"));
	}

	@Test
	public void saysNothingAboutTheStreakWhenAnImportedCopyHasNoKillNumber()
	{
		Ledger l = new Ledger(TestData.get());
		l.addOwned("vorkath", "Skeletal visage", 1);
		l.logDrop("vorkath", "Skeletal visage", 77, 1, null, "live");
		assertEquals("Logged Skeletal visage at Vorkath kill 77.", plain(DropMessages.build(TestData.get(), "vorkath", l.copyOf("vorkath"), "Skeletal visage", 77)));
	}

	@Test
	public void firstKillHasNoStreak()
	{
		Ledger l = new Ledger(TestData.get());
		l.logDrop("vorkath", "Vorki", 1, 1, null, "live");
		assertEquals("Logged Vorki at Vorkath kill 1.", plain(DropMessages.build(TestData.get(), "vorkath", l.copyOf("vorkath"), "Vorki", 1)));
	}

	@Test
	public void unknownBossFallsBackToItsId()
	{
		Ledger l = new Ledger(TestData.get());
		String m = plain(DropMessages.build(TestData.get(), "nobody", new BossState(), "Thing", 5));
		assertTrue(m, m.contains("at nobody kill 5"));
	}
}

package com.dropluckledger.plugin;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import net.runelite.api.Skill;
import net.runelite.client.util.Filepath;

/**
 * The game and RuneLite as the plugin sees them, with everything the tests need to set up or look at as plain fields.
 * Work meant for the client thread simply runs at once, on the caller's thread.
 */
public final class FakeGame implements Game
{
	// the player
	public boolean loggedIn;
	public long accountHash = -1L;
	public boolean standardWorld = true;
	public String playerName = "Tester";
	public int tick = 1000;
	public final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
	public final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);

	// the screen
	public final Map<Integer, Node> widgets = new HashMap<>();

	// items
	public final Map<Integer, String> names = new HashMap<>();
	/**
	 * Ids that are noted copies of another item (the scan skips them).
	 */
	public final Map<Integer, Integer> notes = new HashMap<>();
	public final List<ItemRef> tradeable = new ArrayList<>();
	public int lookups;
	public int searches;
	/**
	 * What was asked of the picture lookups.
	 */
	public final List<Runnable> pictureCallbacks = new CopyOnWriteArrayList<>();

	// what other RuneLite plugins saved: group -> key -> text
	public boolean hasProfile = true;
	public final Map<String, Map<String, String>> saved = new LinkedHashMap<>();

	// what the plugin did
	public final List<String> chat = new CopyOnWriteArrayList<>();

	// the answers the player gives to the file dialogs
	public Filepath fileToSave;
	public Filepath fileToOpen;

	public void logIn(long hash)
	{
		accountHash = hash;
		loggedIn = true;
	}

	public void logOut()
	{
		accountHash = -1L;
		loggedIn = false;
	}

	public FakeGame addItem(int id, String name)
	{
		names.put(id, name);
		return this;
	}

	public FakeGame addTradeable(int id, String name)
	{
		names.put(id, name);
		tradeable.add(new ItemRef(id, name));
		return this;
	}

	public FakeGame save(String group, String key, String value)
	{
		saved.computeIfAbsent(group, g -> new LinkedHashMap<>()).put(key, value);
		return this;
	}

	// ------------------------------------------------------------------ the player

	@Override
	public long accountHash()
	{
		return accountHash;
	}

	@Override
	public boolean isLoggedIn()
	{
		return loggedIn;
	}

	@Override
	public boolean isStandardWorld()
	{
		return standardWorld;
	}

	@Override
	public String playerName()
	{
		return loggedIn ? playerName : null;
	}

	@Override
	public int tickCount()
	{
		return tick;
	}

	@Override
	public int realLevel(Skill skill)
	{
		return levels.getOrDefault(skill, 1);
	}

	@Override
	public int experience(Skill skill)
	{
		return xp.getOrDefault(skill, 0);
	}

	// ------------------------------------------------------------------ the screen

	@Override
	public Node widget(int componentId)
	{
		return widgets.get(componentId);
	}

	// ------------------------------------------------------------------ items

	@Override
	public ItemInfo item(int id)
	{
		lookups++;
		return new ItemInfo(names.getOrDefault(id, "null"), notes.containsKey(id), false);
	}

	@Override
	public int canonicalItemId(int id)
	{
		return id;
	}

	@Override
	public List<ItemRef> searchItems(String text)
	{
		searches++;
		String q = text.toLowerCase(Locale.ROOT);
		List<ItemRef> out = new ArrayList<>();
		for (ItemRef r : tradeable)
		{
			if (r.name.toLowerCase(Locale.ROOT).contains(q))
			{
				out.add(r);
			}
		}
		return out;
	}

	@Override
	public BufferedImage itemImage(int id, Runnable whenLoaded)
	{
		pictureCallbacks.add(whenLoaded);
		return new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
	}

	// ------------------------------------------------------------------ what other RuneLite plugins saved

	@Override
	public List<String> savedKeys(String group, String keyPrefix)
	{
		List<String> out = new ArrayList<>();
		if (hasProfile)
		{
			for (String k : saved.getOrDefault(group, new LinkedHashMap<>()).keySet())
			{
				if (k.startsWith(keyPrefix))
				{
					out.add(k);
				}
			}
		}
		return out;
	}

	@Override
	public Integer savedInt(String group, String key)
	{
		String v = savedText(group, key);
		return v == null || v.isEmpty() ? null : Integer.valueOf(v);
	}

	@Override
	public String savedText(String group, String key)
	{
		return hasProfile ? saved.getOrDefault(group, new LinkedHashMap<>()).get(key) : null;
	}

	// ------------------------------------------------------------------ chat, threads and files

	@Override
	public void gameMessage(String runeLiteFormattedMessage)
	{
		chat.add(runeLiteFormattedMessage);
	}

	@Override
	public void invoke(Runnable task)
	{
		task.run();
	}

	@Override
	public void invokeLater(Runnable task)
	{
		task.run();
	}

	@Override
	public Filepath chooseFileToSave(Component parent, String title, String fileName, String description, String extension)
	{
		return fileToSave;
	}

	@Override
	public Filepath chooseFileToOpen(Component parent, String title, String description, String extension)
	{
		return fileToOpen;
	}
}

package com.dropluckledger.plugin;

import java.util.Arrays;
import java.util.List;

/**
 * A piece of the game's interface with the fields the readers look at.
 */
public final class FakeNode implements Game.Node
{
	public String text = "";
	public int opacity;
	public int itemId = -1;
	public int itemQuantity;
	public List<Game.Node> children;

	public static FakeNode text(String text)
	{
		FakeNode n = new FakeNode();
		n.text = text;
		return n;
	}

	public static FakeNode item(int id, int qty, boolean owned)
	{
		FakeNode n = new FakeNode();
		n.itemId = id;
		n.itemQuantity = qty;
		n.opacity = owned ? 0 : 175;
		return n;
	}

	public static FakeNode withChildren(Game.Node... children)
	{
		FakeNode n = new FakeNode();
		n.children = Arrays.asList(children);
		return n;
	}

	@Override
	public String text()
	{
		return text;
	}

	@Override
	public List<Game.Node> children()
	{
		return children;
	}

	@Override
	public Game.Node child(int index)
	{
		return children == null || index < 0 || index >= children.size() ? null : children.get(index);
	}

	@Override
	public int itemId()
	{
		return itemId;
	}

	@Override
	public int itemQuantity()
	{
		return itemQuantity;
	}

	@Override
	public int opacity()
	{
		return opacity;
	}
}

package com.dropluckledger.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.dropluckledger.TestData;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.ledger.LedgerCodec;
import com.dropluckledger.ledger.LedgerSaver;
import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class FileStoreTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private Filepath dir;

	@Before
	public void setUp() throws IOException
	{
		dir = Filepath.Unchecked.getRooted(tmp.getRoot().toPath()).joinSegment("plugin-data").rooted();
	}

	private File[] files()
	{
		File[] f = new File(tmp.getRoot(), "plugin-data").listFiles();
		return f == null ? new File[0] : f;
	}

	@Test
	public void missingFileReadsAsNull() throws IOException
	{
		assertNull(new FileStore(dir, "ledger-1.json").read());
	}

	@Test
	public void writeCreatesFolderAndReadsBack() throws IOException
	{
		FileStore s = new FileStore(dir, "ledger-1.json");
		s.write("{\"a\":\"ünï\"}");
		assertEquals("{\"a\":\"ünï\"}", s.read());
		assertEquals(1, files().length);
	}

	@Test
	public void overwriteLeavesNoTemporaryFile() throws IOException
	{
		FileStore s = new FileStore(dir, "ledger-1.json");
		s.write("one");
		s.write("two");
		s.write("three");
		assertEquals("three", s.read());
		for (File f : files())
		{
			assertFalse(f.getName(), f.getName().endsWith(".tmp"));
		}
	}

	@Test
	public void keepsTheEarlierSessionsFileOnceAsBackup() throws IOException
	{
		new FileStore(dir, "ledger-1.json").write("last session");
		FileStore s = new FileStore(dir, "ledger-1.json");
		s.write("this session, first save");
		s.write("this session, second save");
		assertEquals("last session", new String(Files.readAllBytes(new File(tmp.getRoot(), "plugin-data/ledger-1.json.bak").toPath()), StandardCharsets.UTF_8));
		assertEquals("this session, second save", s.read());
	}

	@Test
	public void quarantineSetsTheFileAside() throws IOException
	{
		FileStore s = new FileStore(dir, "ledger-1.json");
		s.write("garbage");
		s.quarantine();
		assertNull(s.read());
		boolean found = false;
		for (File f : files())
		{
			found |= f.getName().startsWith("ledger-1.json.unreadable-");
		}
		assertTrue(found);
		s.quarantine(); // nothing left to set aside: no error
	}

	@Test
	public void ledgerNamesPassTheNameChecks() throws IOException
	{
		for (long hash : new long[]{0L, 123456789012345L, -5L, Long.MIN_VALUE, Long.MAX_VALUE})
		{
			FileStore s = new FileStore(dir, FileStore.ledgerName(hash));
			s.write("x");
			assertEquals("x", s.read());
		}
	}

	@Test
	public void cannotLeaveItsFolder() throws IOException
	{
		try
		{
			new FileStore(dir, "../escape.json").write("x");
			fail("a name with a path in it must be refused");
		}
		catch (IllegalArgumentException expected)
		{
			// refused by Filepath
		}
		assertFalse(new File(tmp.getRoot(), "escape.json").exists());
	}

	@Test
	public void refusesAHugeFile() throws IOException
	{
		File big = new File(tmp.getRoot(), "plugin-data");
		assertTrue(big.mkdirs());
		File f = new File(big, "ledger-9.json");
		try (java.io.RandomAccessFile r = new java.io.RandomAccessFile(f, "rw"))
		{
			r.setLength(FileStore.MAX_BYTES + 1);
		}
		try
		{
			new FileStore(dir, "ledger-9.json").read();
			fail("too large");
		}
		catch (IOException expected)
		{
			// refused
		}
	}

	@Test
	public void saverRoundTripThroughTheStore() throws Exception
	{
		ScheduledExecutorService ex = Executors.newSingleThreadScheduledExecutor();
		try
		{
			Gson gson = new Gson();
			Ledger a = new Ledger(TestData.get());
			LedgerSaver saver = new LedgerSaver(a, gson, ex, 10);
			a.addListener(saver);
			FileStore store = new FileStore(dir, FileStore.ledgerName(42));
			saver.setStore(store);
			a.setKc("zulrah", 321);
			a.logDrop("zulrah", "Tanzanite fang", 300, 1, null, "live");
			saver.flushNow();

			Ledger b = new Ledger(TestData.get());
			LedgerSaver saver2 = new LedgerSaver(b, gson, ex, 10);
			assertTrue(saver2.loadInto(new FileStore(dir, FileStore.ledgerName(42))));
			assertEquals(321, b.kc("zulrah"));
			assertEquals(1, b.copyOf("zulrah").copies("Tanzanite fang"));
			// a different account has its own file
			Ledger c = new Ledger(TestData.get());
			assertTrue(new LedgerSaver(c, gson, ex, 10).loadInto(new FileStore(dir, FileStore.ledgerName(43))));
			assertEquals(0, c.kc("zulrah"));
		}
		finally
		{
			ex.shutdownNow();
		}
	}

	@Test
	public void exportAndImportATextFile() throws IOException
	{
		Filepath f = Filepath.Unchecked.getRooted(new File(tmp.getRoot(), "backup.json").toPath());
		FileStore.writeText(f, "{\"app\":\"x\"}");
		assertEquals("{\"app\":\"x\"}", FileStore.readText(f));
		FileStore.writeText(f, "{}");
		assertEquals("{}", FileStore.readText(f));
	}

	@Test
	public void codecErrorsSurfaceAsFormatException() throws IOException
	{
		try
		{
			LedgerCodec.fromJson(TestData.get(), "not json at all");
			fail();
		}
		catch (LedgerCodec.FormatException expected)
		{
			// as the import code expects
		}
	}
}

package com.dropluckledger.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import java.util.Map;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Before;
import org.junit.Test;

public class GameReaderTest
{
	private FakeGame game;

	@Before
	public void setUp()
	{
		game = new FakeGame().addItem(12922, "Tanzanite fang").addItem(12927, "Magic fang").addItem(13200, "Pet snakeling");
	}

	private void killLog(String title, String[] names, String[] kills)
	{
		game.widgets.put(InterfaceID.KillLog.INTERFACE_TITLE, FakeNode.text(title));
		Game.Node[] n = new Game.Node[names.length];
		Game.Node[] k = new Game.Node[kills.length];
		for (int i = 0; i < names.length; i++)
		{
			n[i] = FakeNode.text(names[i]);
			k[i] = FakeNode.text(kills[i]);
		}
		game.widgets.put(InterfaceID.KillLog.NAME, FakeNode.withChildren(n));
		game.widgets.put(InterfaceID.KillLog.KILL, FakeNode.withChildren(k));
	}

	@Test
	public void readsTheBossKillLog()
	{
		killLog("Boss Kill Log", new String[]{"Zulrah:", "Chambers of Xeric: Challenge Mode", "<col=ff9040>Vorkath"}, new String[]{"1,234", "56", "7"});
		Map<String, Integer> kills = GameReader.killLog(game);
		assertNotNull(kills);
		assertEquals(3, kills.size());
		assertEquals(1234, (int) kills.get("Zulrah"));
		assertEquals(56, (int) kills.get("Chambers of Xeric Challenge Mode"));
		assertEquals(7, (int) kills.get("Vorkath"));
	}

	@Test
	public void ignoresOtherLogsAndRowsThatAreNotCounts()
	{
		killLog("Slayer Kill Log", new String[]{"Zulrah"}, new String[]{"5"});
		assertNull(GameReader.killLog(game));
		killLog("Boss Kill Log", new String[]{"Zulrah", "Header", "Vorkath"}, new String[]{"5", "", "0"});
		Map<String, Integer> kills = GameReader.killLog(game);
		assertEquals(1, kills.size());
		assertEquals(5, (int) kills.get("Zulrah"));
	}

	@Test
	public void nothingOnScreenGivesNull()
	{
		assertNull(GameReader.killLog(game));
		assertNull(GameReader.collectionPage(game));
		assertNull(GameReader.adventureLogOwner(game));
	}

	@Test
	public void killLogStillFillingInGivesNull()
	{
		game.widgets.put(InterfaceID.KillLog.INTERFACE_TITLE, FakeNode.text("Boss Kill Log"));
		game.widgets.put(InterfaceID.KillLog.NAME, new FakeNode());
		game.widgets.put(InterfaceID.KillLog.KILL, new FakeNode());
		assertNull(GameReader.killLog(game));
	}

	@Test
	public void readsACollectionLogPage()
	{
		game.widgets.put(InterfaceID.Collection.HEADER_TEXT, FakeNode.withChildren(FakeNode.text("<col=ff9040>Zulrah</col>"), FakeNode.text("3/12")));
		game.widgets.put(InterfaceID.Collection.ITEMS_CONTENTS, FakeNode.withChildren(
			FakeNode.item(12922, 2, true),
			FakeNode.item(12927, 0, false),
			FakeNode.item(13200, 1, true),
			FakeNode.item(99999, 1, true), // unknown to the item list
			FakeNode.item(-1, 0, false)));
		GameReader.LogPage page = GameReader.collectionPage(game);
		assertNotNull(page);
		assertEquals("Zulrah", page.title);
		assertEquals(2, page.items.size());
		assertEquals(2, (int) page.items.get("Tanzanite fang"));
		assertEquals(1, (int) page.items.get("Pet snakeling"));
		// ids of every item on the page, owned or not
		assertEquals(3, page.ids.size());
		assertEquals(12927, (int) page.ids.get("Magic fang"));
	}

	@Test
	public void ownedItemWithNoQuantityCountsAsOne()
	{
		game.widgets.put(InterfaceID.Collection.HEADER_TEXT, FakeNode.withChildren(FakeNode.text("Zulrah")));
		game.widgets.put(InterfaceID.Collection.ITEMS_CONTENTS, FakeNode.withChildren(FakeNode.item(12922, 0, true)));
		assertEquals(1, (int) GameReader.collectionPage(game).items.get("Tanzanite fang"));
	}

	@Test
	public void adventureLogOwnerFromEitherInterface()
	{
		game.widgets.put(InterfaceID.MenuNew.TITLE, FakeNode.withChildren(null, FakeNode.text("<col=ffffff>The Exploits of Someone Else</col>")));
		assertEquals("Someone Else", GameReader.adventureLogOwner(game));
		game.widgets.clear();
		game.widgets.put(InterfaceID.Menu.LJ_LAYER2, FakeNode.text("The Exploits of Tester"));
		assertEquals("Tester", GameReader.adventureLogOwner(game));
		game.widgets.clear();
		game.widgets.put(InterfaceID.MenuNew.TITLE, FakeNode.text("Quest List"));
		assertNull(GameReader.adventureLogOwner(game));
	}
}

package com.dropluckledger.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.history.HistoryInput;
import com.dropluckledger.history.HistoryPlanner;
import com.dropluckledger.ledger.Ledger;
import com.google.gson.Gson;
import org.junit.Before;
import org.junit.Test;

public class HistorySourcesTest
{
	private final BossIndex index = new BossIndex(TestData.get());
	private final Gson gson = new Gson();
	private FakeGame game;
	private Ledger ledger;

	@Before
	public void setUp()
	{
		game = new FakeGame()
			.addItem(12922, "Tanzanite fang")
			.addItem(12927, "Magic fang")
			.addItem(995, "Coins")
			.addItem(22106, "Vorkath's head");
		ledger = new Ledger(TestData.get());
	}

	private HistoryInput collect()
	{
		return HistorySources.collect(ledger, game, gson, index);
	}

	private static int kc(HistoryInput in, String label)
	{
		return in.kc.getOrDefault(label, 0);
	}

	@Test
	public void readsTheKillCountsChatCommandsSaved()
	{
		game.save("killcount", "zulrah", "1500").save("killcount", "chambers of xeric challenge mode", "42").save("killcount", "k'ril tsutsaroth", "300");
		HistoryInput in = collect();
		assertEquals(1500, kc(in, "zulrah"));
		assertEquals(42, kc(in, "chambers of xeric challenge mode"));
		assertTrue(in.sources.contains(HistorySources.SRC_KC));
		HistoryPlanner.Plan plan = new HistoryPlanner(ledger, index).plan(in);
		assertEquals(3, plan.kc.size());
		assertTrue(plan.kcSkipped.isEmpty());
	}

	@Test
	public void ignoresZeroAndMissingCounts()
	{
		game.save("killcount", "zulrah", "0");
		assertTrue(collect().isEmpty());
	}

	@Test
	public void noProfileMeansNothingToRead()
	{
		game.hasProfile = false;
		game.save("killcount", "zulrah", "5");
		assertTrue(collect().isEmpty());
	}

	@Test
	public void readsLootTrackerTotals()
	{
		game.save("loottracker", "drops_NPC_Zulrah",
			"{\"type\":\"NPC\",\"name\":\"Zulrah\",\"kills\":800,\"first\":\"2025-01-01T00:00:00Z\",\"last\":\"2026-09-01T00:00:00Z\",\"drops\":[12922,2,12927,1,995,50000]}");
		HistoryInput in = collect();
		assertEquals(800, kc(in, "Zulrah"));
		assertEquals(3, in.owned.size());
		HistoryPlanner.Plan plan = new HistoryPlanner(ledger, index).plan(in);
		assertEquals(800, plan.kc.get(0).to);
		int fangs = 0;
		for (HistoryPlanner.ItemRow r : plan.items)
		{
			if (r.item.equals("Tanzanite fang"))
			{
				fangs = r.add;
				assertEquals("zulrah", r.bossId);
			}
		}
		assertEquals(2, fangs);
		assertTrue(plan.itemsMissing.contains("Coins") || plan.items.stream().noneMatch(r -> r.item.equals("Coins")));
	}

	@Test
	public void eventLootAndOtherRecordTypes()
	{
		game.save("loottracker", "drops_EVENT_Chambers of Xeric Challenge Mode",
			"{\"type\":\"EVENT\",\"name\":\"Chambers of Xeric Challenge Mode\",\"kills\":10,\"drops\":[]}");
		game.save("loottracker", "drops_PLAYER_Someone", "{\"type\":\"PLAYER\",\"name\":\"Someone\",\"kills\":3,\"drops\":[12922,1]}");
		game.save("loottracker", "drops_NPC_Man", "{\"type\":\"NPC\",\"name\":\"Man\",\"kills\":99,\"drops\":[12922,1]}");
		HistoryInput in = collect();
		assertEquals(10, kc(in, "Chambers of Xeric Challenge Mode"));
		assertEquals(1, in.kc.size());
		assertTrue(in.owned.isEmpty());
	}

	@Test
	public void lootNamesThatAreNotKillCountLabelsUseTheBossLabel()
	{
		// the Loot Tracker calls the Grotesque Guardians "Dusk"; the kill count message calls them something else
		game.save("loottracker", "drops_NPC_Dusk", "{\"type\":\"NPC\",\"name\":\"Dusk\",\"kills\":25,\"drops\":[]}");
		HistoryInput in = collect();
		HistoryPlanner.Plan plan = new HistoryPlanner(ledger, index).plan(in);
		assertEquals(1, plan.kc.size());
		assertEquals("grotesque-guardians", plan.kc.get(0).bossId);
		assertEquals(25, plan.kc.get(0).to);
		assertTrue(plan.kcSkipped.toString(), plan.kcSkipped.isEmpty());
	}

	@Test
	public void brokenRecordsAreSkipped()
	{
		game.save("loottracker", "drops_NPC_Zulrah", "{not json");
		game.save("loottracker", "drops_NPC_Vorkath", "[1,2,3]");
		game.save("loottracker", "drops_NPC_Nex", "{\"type\":\"NPC\",\"name\":\"Nex\"}");
		game.save("loottracker", "drops_NPC_Kraken", "");
		assertTrue(collect().isEmpty());
	}

	@Test
	public void screenReadingsComeFromTheLedger()
	{
		ledger.updateHistory(h ->
		{
			h.kc.put("Zulrah", 700);
			java.util.Map<String, Integer> page = new java.util.LinkedHashMap<>();
			page.put("Tanzanite fang", 1);
			h.log.put("Zulrah", page);
		});
		HistoryInput in = collect();
		assertEquals(700, kc(in, "Zulrah"));
		assertEquals(1, in.owned.size());
		assertTrue(in.sources.contains(HistorySources.SRC_KILL_LOG));
		assertTrue(in.sources.contains(HistorySources.SRC_COLLECTION));
	}

	@Test
	public void sourcesAgreeAndTheLargestCountWins()
	{
		game.save("killcount", "zulrah", "1500");
		game.save("loottracker", "drops_NPC_Zulrah", "{\"type\":\"NPC\",\"name\":\"Zulrah\",\"kills\":400,\"drops\":[12922,1]}");
		ledger.updateHistory(h -> h.kc.put("Zulrah", 1490));
		HistoryPlanner.Plan plan = new HistoryPlanner(ledger, index).plan(collect());
		assertEquals(1500, plan.kc.get(0).to);
	}

	@Test
	public void runningItAfterImportingAddsNothing()
	{
		game.save("killcount", "zulrah", "1500");
		game.save("loottracker", "drops_NPC_Zulrah", "{\"type\":\"NPC\",\"name\":\"Zulrah\",\"kills\":1500,\"drops\":[12922,2]}");
		HistoryPlanner planner = new HistoryPlanner(ledger, index);
		HistoryPlanner.Plan first = planner.plan(collect());
		assertFalse(first.isEmpty());
		planner.apply(first);
		assertEquals(1500, ledger.kc("zulrah"));
		assertEquals(2, ledger.copyOf("zulrah").copies("Tanzanite fang"));
		assertTrue(planner.plan(collect()).isEmpty());
	}
}

package com.dropluckledger.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

public class ItemIconsTest
{
	private FakeGame game;
	private ItemIcons icons;

	@Before
	public void setUp()
	{
		game = new FakeGame();
		icons = new ItemIcons(game);
	}

	@Test
	public void learnedIdsAreFoundIgnoringCaseAndPunctuation()
	{
		icons.learn("Pet snakeling", 12921);
		assertEquals(12921, icons.id("Pet Snakeling"));
		assertEquals(12921, icons.id("pet snakeling!"));
		assertTrue(icons.isDirty());
	}

	@Test
	public void searchesTradeableItemsForAnExactName()
	{
		game.addTradeable(12922, "Tanzanite fang").addTradeable(12923, "Tanzanite fang (uncharged)").addTradeable(555, "Tanzanite mutagen");
		assertEquals(12922, icons.id("tanzanite FANG"));
		assertEquals(0, icons.id("Tanzanite"));
		assertNotNull(icons.image("Tanzanite fang", () -> { }));
		assertNull(icons.image("Not an item", () -> { }));
	}

	@Test
	public void asksTheSearchOnlyOncePerName()
	{
		for (int i = 0; i < 5; i++)
		{
			assertEquals(0, icons.id("Pet Zilyana"));
		}
		assertEquals(1, game.searches);
	}

	@Test
	public void snapshotAndRestoreRoundTrip()
	{
		icons.learn("Vorki", 21992);
		icons.learn("Dragonbone necklace", 22111);
		Map<String, Integer> saved = icons.snapshot();
		assertFalse(icons.isDirty());
		assertEquals(2, saved.size());
		ItemIcons again = new ItemIcons(new FakeGame());
		again.restore(saved, 777L);
		assertEquals(21992, again.id("Vorki"));
		assertEquals(777L, again.scannedAt());
		assertFalse(again.isDirty());
		Map<String, Integer> junk = new HashMap<>();
		junk.put("bad", -3);
		junk.put(null, 4);
		again.restore(junk, 1L);
		assertEquals(0, again.id("bad"));
	}

	@Test
	public void scanFindsPetsAndStopsWhenEverythingIsFound()
	{
		game.addItem(10, "Cabbage").addItem(250, "Vorki").addItem(251, "Vorki").addItem(900, "Pet snakeling");
		game.notes.put(249, 5); // a noted copy of Vorki before the real one: skipped
		game.names.put(249, "Vorki");
		icons.startScan(Arrays.asList("Vorki", "Pet snakeling", "Nothing here"));
		assertTrue(icons.isScanning());
		int ticks = 0;
		boolean done = false;
		while (!done)
		{
			done = icons.scanTick(5000L + ticks);
			ticks++;
			assertTrue("scan should end", ticks < 1000);
		}
		assertFalse(icons.isScanning());
		assertEquals(250, icons.id("Vorki")); // not the noted 249, not the later 251
		assertEquals(900, icons.id("Pet snakeling"));
		assertEquals(0, icons.id("Nothing here"));
		assertTrue(icons.scannedAt() >= 5000L);
		// 100 ids per tick, up to the limit, because one name never turns up
		assertEquals(ItemIcons.SCAN_LIMIT / ItemIcons.SCAN_PER_TICK, ticks);
	}

	@Test
	public void scanStopsEarlyWhenAllNamesAreFound()
	{
		game.addItem(30, "Vorki");
		icons.startScan(Arrays.asList("Vorki"));
		assertTrue(icons.scanTick(1L));
		assertEquals(30, icons.id("Vorki"));
		assertEquals(1L, icons.scannedAt());
	}

	@Test
	public void scanOfNamesAlreadyKnownDoesNothing()
	{
		icons.learn("Vorki", 30);
		icons.startScan(Arrays.asList("Vorki"));
		assertFalse(icons.isScanning());
		assertFalse(icons.scanTick(1L));
	}

	@Test
	public void secondStartWhileScanningIsIgnored()
	{
		icons.startScan(Arrays.asList("A thing"));
		icons.scanTick(1L);
		icons.startScan(Arrays.asList("Another thing"));
		assertTrue(icons.isScanning());
	}
}

package com.dropluckledger.ui;

