package com.dropluckledger.ui;

import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JComponent;

/**
 * Stands in for the panel's windows: records what was asked and answers as the test says.
 */
final class FakeDialogs implements Dialogs
{
	final List<String> asked = new ArrayList<>();
	final List<String> messages = new ArrayList<>();
	boolean formAnswer = true;
	boolean confirmAnswer = true;
	int chooseAnswer = 0;
	/**
	 * Runs on a form before the "player" closes it, to fill it in.
	 */
	Consumer<JComponent> fill = f ->
	{
	};
	JComponent lastForm;
	String lastTitle;

	@Override
	public boolean form(Component parent, String title, JComponent form, String ok)
	{
		asked.add("form:" + title);
		lastForm = form;
		lastTitle = title;
		fill.accept(form);
		return formAnswer;
	}

	@Override
	public boolean confirm(Component parent, String title, String message, String yes)
	{
		asked.add("confirm:" + title);
		messages.add(message);
		return confirmAnswer;
	}

	@Override
	public int choose(Component parent, String title, String message, String... options)
	{
		asked.add("choose:" + title);
		messages.add(message);
		return chooseAnswer;
	}

	@Override
	public void note(Component parent, String title, String message)
	{
		asked.add("note:" + title);
		messages.add(message);
	}

	String last()
	{
		return messages.isEmpty() ? "" : messages.get(messages.size() - 1);
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.history.HistoryPlanner;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.plugin.TrackingState;
import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * Stands in for the plugin.
 */
final class FakeHost implements LedgerPanel.Host
{
	volatile TrackingState state = TrackingState.TRACKING;
	HistoryPlanner.Plan plan = new HistoryPlanner.Plan();
	Ledger backupToImport;
	int planRequests;
	int exports;
	int imports;
	final List<Ledger> replaced = new ArrayList<>();

	@Override
	public TrackingState state()
	{
		return state;
	}

	@Override
	public void planHistory(Consumer<HistoryPlanner.Plan> then)
	{
		planRequests++;
		then.accept(plan);
	}

	@Override
	public void exportBackup(Component parent)
	{
		exports++;
	}

	@Override
	public void importBackup(Component parent, Consumer<Ledger> confirm)
	{
		imports++;
		if (backupToImport != null)
		{
			confirm.accept(backupToImport);
		}
	}

	@Override
	public void replaceLedger(Ledger backup)
	{
		replaced.add(backup);
	}
}

package com.dropluckledger.ui;

import static org.junit.Assert.assertEquals;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The formatting must print what the web app prints.  The expected texts were produced by the web app's own functions.
 */
public class FmtTest
{
	private static JsonObject fixture;

	@BeforeClass
	public static void load() throws IOException
	{
		try (InputStream in = FmtTest.class.getResourceAsStream("/fmt.json"))
		{
			fixture = new JsonParser().parse(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
		}
	}

	private static double number(JsonElement e)
	{
		if (e.getAsJsonPrimitive().isString())
		{
			assertEquals("inf", e.getAsString());
			return Double.POSITIVE_INFINITY;
		}
		return e.getAsDouble();
	}

	@Test
	public void numbersMatchTheWebApp()
	{
		JsonArray rows = fixture.getAsJsonArray("fmt");
		for (JsonElement r : rows)
		{
			JsonArray row = r.getAsJsonArray();
			double in = number(row.get(0));
			assertEquals("fmt(" + in + ")", row.get(1).getAsString(), Fmt.num(in));
		}
	}

	@Test
	public void percentagesMatchTheWebApp()
	{
		JsonArray rows = fixture.getAsJsonArray("pct");
		for (JsonElement r : rows)
		{
			JsonArray row = r.getAsJsonArray();
			JsonElement in = row.get(0);
			Double p;
			if (in.getAsJsonPrimitive().isString())
			{
				p = "nan".equals(in.getAsString()) ? Double.NaN : null;
			}
			else
			{
				p = in.getAsDouble();
			}
			assertEquals("pctStr(" + in + ")", row.get(1).getAsString(), Fmt.pct(p));
		}
	}

	@Test
	public void ratesMatchTheWebApp()
	{
		JsonArray rows = fixture.getAsJsonArray("rate");
		for (JsonElement r : rows)
		{
			JsonArray row = r.getAsJsonArray();
			JsonElement in = row.get(0);
			double p = in.getAsJsonPrimitive().isString() ? 0 : in.getAsDouble();
			assertEquals("rateStr(" + in + ")", row.get(1).getAsString(), Fmt.rate(p));
		}
	}

	@Test
	public void ordinalsMatchTheWebApp()
	{
		JsonArray rows = fixture.getAsJsonArray("ord");
		for (JsonElement r : rows)
		{
			JsonArray row = r.getAsJsonArray();
			double in = row.get(0).getAsDouble();
			assertEquals("ord(" + in + ")", row.get(1).getAsString(), Fmt.ord(in));
		}
	}

	@Test
	public void expectedCopiesUseTwoDecimalsUnderTen()
	{
		assertEquals("0.42", Fmt.expected(0.4213));
		assertEquals("9.99", Fmt.expected(9.994));
		assertEquals("12.3", Fmt.expected(12.34));
	}
}

