		assertEquals(1, fx.host.exports);
	}

	private Ledger backup()
	{
		Ledger b = new Ledger(fx.data, () -> 9L);
		b.setKc("vorkath", 50);
		b.logDrop("vorkath", "Dragonbone necklace", 20, 1, null, Drop.SRC_MANUAL);
